function updateAircraftPresetButtonsUI() {
    AIRCRAFT_PRESET_SLOT_ORDER.forEach(slotId => {
        const preset = getAircraftPreset(slotId);
        const aircraftClass = getAircraftClassOption(preset.aircraftClass);
        const tagLabels = (preset.aircraftTags || [])
            .map(tagId => AIRCRAFT_TAG_OPTIONS.find(option => option.id === tagId)?.label)
            .filter(Boolean);
        const summary = [
            preset.name,
            aircraftClass.label,
            `${preset.tas} TAS`,
            `${String(preset.gph).padStart(2, '0')} GPH`,
            `${preset.pax} Sitze`,
            `${preset.maxPayloadKg} kg Zuladung`,
            ...tagLabels
        ].join(' · ');
        document.querySelectorAll(`.btn-preset[data-aircraft-slot="${slotId}"]`).forEach(btn => {
            btn.textContent = preset.name;
            btn.title = `${summary} · Rechtsklick/Langdruck: bearbeiten`;
            btn.setAttribute('aria-label', `${preset.name} auswählen. Rechtsklick oder Langdruck zum Bearbeiten.`);
        });
        document.querySelectorAll(`.audio-btn[data-aircraft-slot="${slotId}"]`).forEach(btn => {
            const led = btn.querySelector('.audio-led');
            btn.textContent = preset.name;
            if (led) btn.appendChild(led);
            btn.title = `${summary} · Rechtsklick/Langdruck: bearbeiten`;
            btn.setAttribute('aria-label', `${preset.name} auswählen. Rechtsklick oder Langdruck zum Bearbeiten.`);
        });
    });
    if (typeof updateOpsAircraftSwitches === 'function') updateOpsAircraftSwitches();
    updateNavComAircraftButtons();
}
window.updateAircraftPresetButtonsUI = updateAircraftPresetButtonsUI;

function selectAircraftPresetSlotFromSettings(slotId) {
    if (!AIRCRAFT_PRESET_SLOT_ORDER.includes(slotId)) slotId = 'C172';
    activeAircraftPresetSettingsSlot = slotId;
    window.activeAircraftPresetSettingsSlot = slotId;
    const preset = getAircraftPreset(slotId);
    const slotSelect = document.getElementById('aircraftPresetSlot');
    const nameInput = document.getElementById('aircraftPresetName');
    const tasInput = document.getElementById('aircraftPresetTas');
    const gphInput = document.getElementById('aircraftPresetGph');
    const paxInput = document.getElementById('aircraftPresetPax');
    const payloadInput = document.getElementById('aircraftPresetMaxPayload');
    const classSelect = document.getElementById('aircraftPresetClass');
    if (slotSelect && slotSelect.value !== slotId) slotSelect.value = slotId;
    if (nameInput) nameInput.value = preset.name;
    if (tasInput) tasInput.value = String(preset.tas);
    if (gphInput) gphInput.value = String(preset.gph);
    if (paxInput) paxInput.value = String(preset.pax);
    if (payloadInput) payloadInput.value = String(preset.maxPayloadKg);
    if (classSelect) classSelect.value = preset.aircraftClass;
    const activeTags = new Set(preset.aircraftTags || []);
    document.querySelectorAll('[data-aircraft-settings-tag]').forEach(input => {
        input.checked = activeTags.has(input.value);
    });
    updateBoardingPresetEditorUI(preset.boarding);
    setAircraftPresetStatus(`${getAircraftPresetSlotLabel(slotId)} geladen`, '#9aa3ad');
}
window.selectAircraftPresetSlotFromSettings = selectAircraftPresetSlotFromSettings;

function commitAircraftPresetUpdate(slotId, candidate, options = {}) {
    const resolvedSlot = AIRCRAFT_PRESET_SLOT_ORDER.includes(slotId) ? slotId : 'C172';
    const next = normalizeAircraftPreset(resolvedSlot, candidate);
    aircraftPresets[resolvedSlot] = next;
    saveAircraftPresets();
    updateAircraftPresetButtonsUI();
    if (options.selectSettingsSlot !== false) selectAircraftPresetSlotFromSettings(resolvedSlot);
    if (selectedAC === resolvedSlot) applyPreset(next.tas, next.gph, next.pax, resolvedSlot);
    setAircraftPresetStatus(options.statusText || `${getAircraftPresetSlotLabel(resolvedSlot)} gespeichert`, '#4caf50');
    scheduleAircraftPresetCloudSync();
    return next;
}

function saveAircraftPresetFromSettings() {
    const slotId = AIRCRAFT_PRESET_SLOT_ORDER.includes(activeAircraftPresetSettingsSlot) ? activeAircraftPresetSettingsSlot : 'C172';
    const defaults = AIRCRAFT_PRESET_DEFAULTS[slotId] || AIRCRAFT_PRESET_DEFAULTS['C172'];
    const nameInput = document.getElementById('aircraftPresetName');
    const tasInput = document.getElementById('aircraftPresetTas');
    const gphInput = document.getElementById('aircraftPresetGph');
    const paxInput = document.getElementById('aircraftPresetPax');
    const payloadInput = document.getElementById('aircraftPresetMaxPayload');
    const classSelect = document.getElementById('aircraftPresetClass');
    const settingsTagInputs = Array.from(document.querySelectorAll('[data-aircraft-settings-tag]'));
    const aircraftTags = settingsTagInputs.length
        ? settingsTagInputs.filter(input => input.checked).map(input => input.value)
        : getAircraftPreset(slotId).aircraftTags;

    const candidate = {
        name: nameInput?.value ?? defaults.name,
        tas: tasInput?.value ?? defaults.tas,
        gph: gphInput?.value ?? defaults.gph,
        pax: paxInput?.value ?? defaults.pax,
        maxPayloadKg: payloadInput?.value ?? getAircraftPreset(slotId).maxPayloadKg,
        aircraftClass: classSelect?.value ?? getAircraftPreset(slotId).aircraftClass,
        aircraftTags,
        boarding: getAircraftPreset(slotId).boarding
    };
    commitAircraftPresetUpdate(slotId, candidate);
}
window.saveAircraftPresetFromSettings = saveAircraftPresetFromSettings;

function populateAircraftPresetEditor(slotId) {
    const preset = getAircraftPreset(slotId);
    const slotLabel = document.getElementById('aircraftPresetEditorSlotLabel');
    const nameInput = document.getElementById('aircraftPresetEditorName');
    const tasInput = document.getElementById('aircraftPresetEditorTas');
    const gphInput = document.getElementById('aircraftPresetEditorGph');
    const paxInput = document.getElementById('aircraftPresetEditorPax');
    const payloadInput = document.getElementById('aircraftPresetEditorMaxPayload');
    if (slotLabel) slotLabel.textContent = `${getAircraftPresetSlotLabel(slotId)} · ${preset.name}`;
    if (nameInput) nameInput.value = preset.name;
    if (tasInput) tasInput.value = String(preset.tas);
    if (gphInput) gphInput.value = String(preset.gph);
    if (paxInput) paxInput.value = String(preset.pax);
    if (payloadInput) payloadInput.value = String(preset.maxPayloadKg);
    document.querySelectorAll('input[name="aircraftPresetEditorClass"]').forEach(input => {
        input.checked = input.value === preset.aircraftClass;
    });
    const activeTags = new Set(preset.aircraftTags || []);
    document.querySelectorAll('[data-aircraft-editor-tag]').forEach(input => {
        input.checked = activeTags.has(input.value);
    });
}

function openAircraftPresetEditor(slotId, event = null, sourceControl = null) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const resolvedSlot = AIRCRAFT_PRESET_SLOT_ORDER.includes(slotId) ? slotId : 'C172';
    const backdrop = document.getElementById('aircraftPresetEditorBackdrop');
    const dialog = document.getElementById('aircraftPresetEditorDialog');
    if (!backdrop || !dialog) return;
    if (typeof closeSettingsHelp === 'function') closeSettingsHelp();
    if (!document.getElementById('airportTypePickerBackdrop')?.hidden) window.gaAirportTypes?.close?.();
    activeAircraftPresetEditorSlot = resolvedSlot;
    aircraftPresetEditorReturnFocus = sourceControl || event?.currentTarget || document.activeElement;
    populateAircraftPresetEditor(resolvedSlot);
    backdrop.hidden = false;
    dialog.setAttribute('aria-hidden', 'false');
    document.body.classList.add('aircraft-preset-editor-open');
    requestAnimationFrame(() => document.getElementById('aircraftPresetEditorName')?.focus?.({ preventScroll: true }));
}
window.openAircraftPresetEditor = openAircraftPresetEditor;

function closeAircraftPresetEditor(event = null, options = {}) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const backdrop = document.getElementById('aircraftPresetEditorBackdrop');
    const dialog = document.getElementById('aircraftPresetEditorDialog');
    if (!backdrop || !dialog) return;
    backdrop.hidden = true;
    dialog.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('aircraft-preset-editor-open');
    activeAircraftPresetEditorSlot = null;
    const returnFocus = aircraftPresetEditorReturnFocus;
    aircraftPresetEditorReturnFocus = null;
    if (options.restoreFocus !== false) returnFocus?.focus?.({ preventScroll: true });
}
window.closeAircraftPresetEditor = closeAircraftPresetEditor;

function saveAircraftPresetFromEditor(event = null) {
    event?.preventDefault?.();
    const slotId = AIRCRAFT_PRESET_SLOT_ORDER.includes(activeAircraftPresetEditorSlot)
        ? activeAircraftPresetEditorSlot
        : 'C172';
    const current = getAircraftPreset(slotId);
    const selectedClass = document.querySelector('input[name="aircraftPresetEditorClass"]:checked')?.value;
    const aircraftTags = Array.from(document.querySelectorAll('[data-aircraft-editor-tag]:checked'))
        .map(input => input.value);
    const next = commitAircraftPresetUpdate(slotId, {
        name: document.getElementById('aircraftPresetEditorName')?.value ?? current.name,
        tas: document.getElementById('aircraftPresetEditorTas')?.value ?? current.tas,
        gph: document.getElementById('aircraftPresetEditorGph')?.value ?? current.gph,
        pax: document.getElementById('aircraftPresetEditorPax')?.value ?? current.pax,
        maxPayloadKg: document.getElementById('aircraftPresetEditorMaxPayload')?.value ?? current.maxPayloadKg,
        aircraftClass: selectedClass ?? current.aircraftClass,
        aircraftTags,
        boarding: current.boarding
    });
    setAircraftPresetStatus(`${getAircraftPresetSlotLabel(slotId)} · ${next.name} gespeichert`, '#4caf50');
    closeAircraftPresetEditor(null, { restoreFocus: true });
    return false;
}
window.saveAircraftPresetFromEditor = saveAircraftPresetFromEditor;

function initAircraftPresetInteractions() {
    document.querySelectorAll('[data-aircraft-slot]').forEach(control => {
        if (control.dataset.aircraftPresetEditorBound === '1') return;
        control.dataset.aircraftPresetEditorBound = '1';
        control.setAttribute('aria-haspopup', 'dialog');
        if (control.tagName !== 'BUTTON') {
            control.setAttribute('role', 'button');
            if (!control.hasAttribute('tabindex')) control.tabIndex = 0;
        }
        control.setAttribute('draggable', 'false');

        let pressTimer = null;
        let startX = 0;
        let startY = 0;
        const cancelPress = () => {
            clearTimeout(pressTimer);
            pressTimer = null;
            control.classList.remove('aircraft-preset-longpress-active');
        };
        control.addEventListener('pointerdown', event => {
            if (event.button !== 0 || event.isPrimary === false) return;
            cancelPress();
            startX = event.clientX;
            startY = event.clientY;
            control.classList.add('aircraft-preset-longpress-active');
            pressTimer = setTimeout(() => {
                pressTimer = null;
                control.classList.remove('aircraft-preset-longpress-active');
                try { window.getSelection?.()?.removeAllRanges?.(); } catch (_) {}
                control.dataset.aircraftPresetSuppressClickUntil = String(Date.now() + 1200);
                openAircraftPresetEditor(control.dataset.aircraftSlot, event, control);
            }, 650);
        });
        control.addEventListener('pointermove', event => {
            if (Math.hypot(event.clientX - startX, event.clientY - startY) > 12) cancelPress();
        });
        ['pointerup', 'pointercancel', 'pointerleave', 'blur'].forEach(type => {
            control.addEventListener(type, cancelPress);
        });
        control.addEventListener('click', event => {
            const suppressUntil = Number(control.dataset.aircraftPresetSuppressClickUntil || 0);
            if (suppressUntil <= Date.now()) return;
            delete control.dataset.aircraftPresetSuppressClickUntil;
            event.preventDefault();
            event.stopImmediatePropagation();
        }, true);
        control.addEventListener('contextmenu', event => {
            cancelPress();
            try { window.getSelection?.()?.removeAllRanges?.(); } catch (_) {}
            openAircraftPresetEditor(control.dataset.aircraftSlot, event);
        });
        control.addEventListener('selectstart', event => event.preventDefault());
        control.addEventListener('dragstart', event => event.preventDefault());
        control.addEventListener('keydown', event => {
            if (event.key === 'ContextMenu' || (event.shiftKey && event.key === 'F10')) {
                openAircraftPresetEditor(control.dataset.aircraftSlot, event);
            }
        });
    });

    const backdrop = document.getElementById('aircraftPresetEditorBackdrop');
    if (backdrop && backdrop.dataset.aircraftPresetBound !== '1') {
        backdrop.addEventListener('click', event => {
            if (event.target === backdrop) closeAircraftPresetEditor(event);
        });
        backdrop.dataset.aircraftPresetBound = '1';
    }
    if (document.documentElement.dataset.aircraftPresetKeyBound !== '1') {
        document.addEventListener('keydown', event => {
            if (event.key === 'Escape' && !document.getElementById('aircraftPresetEditorBackdrop')?.hidden) {
                closeAircraftPresetEditor(event);
            }
        });
        document.documentElement.dataset.aircraftPresetKeyBound = '1';
    }
}
window.initAircraftPresetInteractions = initAircraftPresetInteractions;

function applyAircraftPresetSlot(slotId) {
    const preset = getAircraftPreset(slotId);
    applyPreset(preset.tas, preset.gph, preset.pax, slotId);
}
window.applyAircraftPresetSlot = applyAircraftPresetSlot;

function clampMainPerfSetting(value, min, max, step = 1, fallback = min) {
    let n = parseInt(value, 10);
    if (!Number.isFinite(n)) n = fallback;
    n = Math.max(min, Math.min(max, n));
    if (step > 1) n = Math.round(n / step) * step;
    return Math.max(min, Math.min(max, n));
}

function persistMainPerformanceSetting(type, value) {
    const key = MAIN_PERF_SETTING_KEYS[type];
    if (!key) return;
    localStorage.setItem(key, String(value));
}
window.persistMainPerformanceSetting = persistMainPerformanceSetting;

function _selectHasOptionValue(selectEl, value) {
    if (!selectEl || value === null || value === undefined) return false;
    const next = String(value);
    return Array.from(selectEl.options || []).some(opt => opt.value === next);
}

function syncMissionParameterControl(selectId, value, options = {}) {
    const selectEl = document.getElementById(selectId);
    if (!selectEl) return null;
    const next = _selectHasOptionValue(selectEl, value)
        ? String(value)
        : (selectEl.value || selectEl.options?.[0]?.value || '');
    if (!next) return null;

    selectEl.value = next;
    const radioId = MISSION_PARAMETER_RADIO_IDS[selectId];
    if (radioId) syncToNavCom(radioId, next);

    if (options.persist && MISSION_PARAMETER_SETTING_KEYS[selectId]) {
        localStorage.setItem(MISSION_PARAMETER_SETTING_KEYS[selectId], next);
    }
    return next;
}
window.syncMissionParameterControl = syncMissionParameterControl;

function persistMissionParameterSetting(selectId, value) {
    syncMissionParameterControl(selectId, value, { persist: true });
}
window.persistMissionParameterSetting = persistMissionParameterSetting;

function applyPersistedMissionParameterSettings() {
    Object.keys(MISSION_PARAMETER_SETTING_KEYS).forEach(selectId => {
        const stored = localStorage.getItem(MISSION_PARAMETER_SETTING_KEYS[selectId]);
        if (stored !== null) syncMissionParameterControl(selectId, stored);
    });
}

function applyPersistedMainPerformanceSettings() {
    const tas = clampMainPerfSetting(localStorage.getItem(MAIN_PERF_SETTING_KEYS.tas), 80, 300, 5, 115);
    const gph = clampMainPerfSetting(localStorage.getItem(MAIN_PERF_SETTING_KEYS.gph), 0, 80, 1, 9);
    const alt = clampMainPerfSetting(localStorage.getItem(MAIN_PERF_SETTING_KEYS.alt), 1500, 13500, 100, 4500);
    const rate = clampMainPerfSetting(localStorage.getItem(MAIN_PERF_SETTING_KEYS.rate), 200, 1500, 50, 500);
    const seats = clampMainPerfSetting(localStorage.getItem(MAIN_PERF_SETTING_KEYS.maxSeats), 1, 6, 1, 4);
    const aircraft = localStorage.getItem(MAIN_PERF_SETTING_KEYS.aircraft);

    const tasSlider = document.getElementById('tasSlider');
    const gphSlider = document.getElementById('gphSlider');
    const altSlider = document.getElementById('altSlider');
    const rateSlider = document.getElementById('rateSlider');
    const maxSeatsEl = document.getElementById('maxSeats');
    const altMapInput = document.getElementById('altMapInput');
    const rateMapInput = document.getElementById('rateMapInput');

    if (tasSlider) tasSlider.value = tas;
    if (gphSlider) gphSlider.value = gph;
    if (altSlider) altSlider.value = alt;
    if (rateSlider) rateSlider.value = rate;
    if (maxSeatsEl) maxSeatsEl.value = seats;
    if (altMapInput) altMapInput.textContent = alt;
    if (rateMapInput) rateMapInput.textContent = rate;
    if (Number.isFinite(rate)) {
        vpClimbRate = rate;
        vpDescentRate = rate;
    }
    if (AIRCRAFT_PRESET_SLOT_ORDER.includes(aircraft)) {
        selectedAC = aircraft;
        window.selectedAC = selectedAC;
    }
    updateAircraftPresetButtonsUI();
    selectAircraftPresetSlotFromSettings(selectedAC);
}

document.addEventListener('DOMContentLoaded', () => {
    // Erkennt, wenn der Nutzer an einem klassischen Slider zieht
    document.querySelectorAll('input[type="range"]').forEach(slider => {
        slider.addEventListener('mousedown', () => window.vpUIInteractionActive = true);
        slider.addEventListener('touchstart', () => window.vpUIInteractionActive = true, {passive: true});
        const onEnd = () => {
            window.vpUIInteractionActive = false;
            if (slider.id === 'altSlider' || slider.id === 'rateSlider') {
                if (typeof renderAirspaceWarningsList === 'function') renderAirspaceWarningsList();
                if (typeof vpDrawClouds === 'function' && document.getElementById('verticalProfileCanvas')) {
                    renderMapProfile(); renderVerticalProfile('verticalProfileCanvas');
                }
            }
        };
        slider.addEventListener('mouseup', onEnd);
        slider.addEventListener('touchend', onEnd);
        slider.addEventListener('touchcancel', onEnd); // Verhindert Einfrieren beim Scrollen
    });
});

/* =========================================================
   1. THEME TOGGLE & NOTIZEN TOGGLE
   ========================================================= */
function changeThemeFromSlider(val) {
    const v = parseInt(val);
    if (v === 0) setTheme('classic');
    else if (v === 1) setTheme('retro');
    else if (v === 2) setTheme('navcom');
    else if (v === 3) setTheme('ops1940');
    else if (v === 4) setTheme('win95');
}

const APP_UI_SCALE_STORAGE_KEY = 'ga_ui_scale_percent';
const APP_UI_SCALE_DEFAULT = 100;
const APP_UI_SCALE_MIN = 30;
const APP_UI_SCALE_MAX = 150;
const APP_UI_SCALE_STEP = 5;
let appUiScaleMapInvalidateTimer = null;

function clampAppUiScalePercent(value) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return APP_UI_SCALE_DEFAULT;
    const stepped = Math.round(numeric / APP_UI_SCALE_STEP) * APP_UI_SCALE_STEP;
    return Math.min(APP_UI_SCALE_MAX, Math.max(APP_UI_SCALE_MIN, stepped));
}

function getSavedAppUiScalePercent() {
    try {
        const raw = localStorage.getItem(APP_UI_SCALE_STORAGE_KEY);
        return clampAppUiScalePercent(raw || APP_UI_SCALE_DEFAULT);
    } catch (_) {
        return APP_UI_SCALE_DEFAULT;
    }
}

function updateAppUiScaleControl(percent) {
    const normalized = clampAppUiScalePercent(percent);
    const scale = normalized / 100;
    const control = document.querySelector('.ui-scale-control');
    const value = document.getElementById('uiScaleValue');
    const resetBtn = document.querySelector('.ui-scale-reset-btn');
    const minusBtn = document.getElementById('uiScaleMinusBtn');
    const plusBtn = document.getElementById('uiScalePlusBtn');
    if (control) control.style.zoom = normalized === APP_UI_SCALE_DEFAULT ? '' : String(1 / scale);
    if (value) value.textContent = `${normalized}%`;
    if (resetBtn) resetBtn.disabled = normalized === APP_UI_SCALE_DEFAULT;
    if (minusBtn) minusBtn.disabled = normalized <= APP_UI_SCALE_MIN;
    if (plusBtn) plusBtn.disabled = normalized >= APP_UI_SCALE_MAX;
}

function invalidateMapAfterAppUiScale() {
    if (appUiScaleMapInvalidateTimer) {
        clearTimeout(appUiScaleMapInvalidateTimer);
        appUiScaleMapInvalidateTimer = null;
    }
    appUiScaleMapInvalidateTimer = setTimeout(() => {
        appUiScaleMapInvalidateTimer = null;
        try {
            if (typeof map !== 'undefined' && map && typeof map.invalidateSize === 'function') {
                map.invalidateSize({ pan: false });
            }
        } catch (_) {}
    }, 140);
}

function applyAppUiScale(value = getSavedAppUiScalePercent(), persist = true) {
    const percent = clampAppUiScalePercent(value);
    const scale = percent / 100;
    if (document.body) {
        document.body.style.zoom = percent === APP_UI_SCALE_DEFAULT ? '' : String(scale);
        document.body.classList.toggle('app-ui-scaled', percent !== APP_UI_SCALE_DEFAULT);
    }
    document.documentElement.style.setProperty('--ga-ui-scale', String(scale));
    document.documentElement.dataset.uiScale = String(percent);
    if (persist) {
        try {
            if (percent === APP_UI_SCALE_DEFAULT) localStorage.removeItem(APP_UI_SCALE_STORAGE_KEY);
            else localStorage.setItem(APP_UI_SCALE_STORAGE_KEY, String(percent));
        } catch (_) {}
    }
    updateAppUiScaleControl(percent);
    invalidateMapAfterAppUiScale();
    return percent;
}

function setAppUiScaleFromSlider(value) {
    return applyAppUiScale(value, true);
}

function getCurrentAppUiScalePercent() {
    const fromDataset = Number(document.documentElement?.dataset?.uiScale);
    if (Number.isFinite(fromDataset)) return clampAppUiScalePercent(fromDataset);
    return getSavedAppUiScalePercent();
}

function adjustAppUiScale(delta) {
    const stepDelta = Number.isFinite(Number(delta)) ? Number(delta) : 0;
    return applyAppUiScale(getCurrentAppUiScalePercent() + stepDelta, true);
}

function resetAppUiScale() {
    return applyAppUiScale(APP_UI_SCALE_DEFAULT, true);
}

window.applyAppUiScale = applyAppUiScale;
window.setAppUiScaleFromSlider = setAppUiScaleFromSlider;
window.adjustAppUiScale = adjustAppUiScale;
window.resetAppUiScale = resetAppUiScale;

const NAVCOM_RACK_V2_STORAGE_KEY = 'ga_navcom_rack_v2';

function isNavcomRackV2Enabled() {
    return localStorage.getItem(NAVCOM_RACK_V2_STORAGE_KEY) === 'true';
}

function updateNavcomRackV2ButtonUi() {
    const enabled = isNavcomRackV2Enabled();
    const btn = document.getElementById('btnNavcomRackV2');
    if (!btn) return;
    btn.textContent = enabled ? 'NavCom V2 An' : 'NavCom V2 Aus';
    btn.style.background = enabled ? '#173a2a' : '#222832';
    btn.style.borderColor = enabled ? '#55b982' : '#5d6470';
    btn.style.color = enabled ? '#d9ffe7' : '#d6dde8';
}

function applyNavcomRackV2State() {
    const enabled = isNavcomRackV2Enabled();
    document.body.classList.toggle('navcom-rack-v2', enabled);
    updateNavcomRackV2ButtonUi();
}

function toggleNavcomRackV2(forceState) {
    const enabled = typeof forceState === 'boolean' ? forceState : !isNavcomRackV2Enabled();
    localStorage.setItem(NAVCOM_RACK_V2_STORAGE_KEY, enabled ? 'true' : 'false');
    if (enabled && !document.body.classList.contains('theme-navcom')) {
        setTheme('navcom');
    } else {
        applyNavcomRackV2State();
    }
    const indicator = document.getElementById('searchIndicator');
    if (indicator) indicator.innerText = enabled
        ? 'Debug: NavCom Rack V2 aktiv.'
        : 'Debug: NavCom Legacy aktiv.';
    return enabled;
}

window.isNavcomRackV2Enabled = isNavcomRackV2Enabled;
window.toggleNavcomRackV2 = toggleNavcomRackV2;
window.updateNavcomRackV2ButtonUi = updateNavcomRackV2ButtonUi;

function isWin95DesktopMode() {
    if (!document.body || !document.body.classList.contains('theme-win95')) return false;
    return true;
}

function isWin95MobileWindowMode() {
    return !!(window.matchMedia && window.matchMedia('(max-width: 899px)').matches);
}

function canFloatWin95Windows() {
    return isWin95DesktopMode() && !isWin95MobileWindowMode();
}

window.isWin95MobileWindowMode = isWin95MobileWindowMode;
window.canFloatWin95Windows = canFloatWin95Windows;

const WIN95_MAIN_CLOSED_STORAGE_KEY = 'ga_win95_main_closed';
const WIN95_MAIN_MINIMIZED_STORAGE_KEY = 'ga_win95_main_minimized';
const WIN95_WINDOW_DRAG_THRESHOLD = 4;
const WIN95_WINDOW_MIN_SIZES = {
    mapTableOverlay: { width: 520, height: 340 },
    pinboardOverlay: { width: 420, height: 320 },
    default: { width: 320, height: 240 }
};
let win95WindowDragState = null;
let win95WindowResizeState = null;
let win95SuppressSettingsToggleClick = false;
let win95LastPointerDragStartAt = 0;
let win95LastPointerResizeStartAt = 0;

function isWin95MainClosedPreference() {
    try {
        return localStorage.getItem(WIN95_MAIN_CLOSED_STORAGE_KEY) === 'true';
    } catch (_) {
        return false;
    }
}

function isWin95MainMinimizedPreference() {
    try {
        return localStorage.getItem(WIN95_MAIN_MINIMIZED_STORAGE_KEY) === 'true';
    } catch (_) {
        return false;
    }
}

function applyWin95MainClosedState() {
    const closed = document.body?.classList.contains('theme-win95') && isWin95MainClosedPreference();
    const minimized = document.body?.classList.contains('theme-win95') && !closed && isWin95MainMinimizedPreference();
    document.body?.classList.toggle('win95-main-closed', !!closed);
    document.body?.classList.toggle('win95-main-minimized', !!minimized);
    if (closed || minimized) setWin95DesktopTaskActive(null);
    return { closed, minimized };
}

function setWin95MainClosed(closed, persist = true) {
    if (closed) setSettingsPanelOpen(false, true);
    if (persist) {
        try {
            localStorage.setItem(WIN95_MAIN_CLOSED_STORAGE_KEY, closed ? 'true' : 'false');
            localStorage.setItem(WIN95_MAIN_MINIMIZED_STORAGE_KEY, 'false');
        } catch (_) {}
    }
    applyWin95MainClosedState();
    if (!closed) setWin95DesktopTaskActive(GA_VIEW_MAIN);
}

function setWin95MainMinimized(minimized, persist = true) {
    if (minimized) setSettingsPanelOpen(false, true);
    if (persist) {
        try {
            localStorage.setItem(WIN95_MAIN_CLOSED_STORAGE_KEY, 'false');
            localStorage.setItem(WIN95_MAIN_MINIMIZED_STORAGE_KEY, minimized ? 'true' : 'false');
        } catch (_) {}
    }
    applyWin95MainClosedState();
    if (!minimized) setWin95DesktopTaskActive(GA_VIEW_MAIN);
}

function closeWin95MainMenu() {
    setWin95MainClosed(true, true);
}

function minimizeWin95MainMenu() {
    setWin95MainMinimized(true, true);
}

function getWin95WindowViewportBounds() {
    const margin = 8;
    const taskbarHeight = document.querySelector('.win95-taskbar')?.getBoundingClientRect?.().height || 0;
    const bottomReserve = isWin95DesktopMode() && taskbarHeight ? Math.round(taskbarHeight) + 2 : margin;
    return {
        minLeft: margin,
        minTop: margin,
        maxRight: Math.max(margin, window.innerWidth - margin),
        maxBottom: Math.max(margin, window.innerHeight - bottomReserve),
        margin
    };
}

function getWin95WindowMinSize(element, bounds = getWin95WindowViewportBounds()) {
    const baseSize = WIN95_WINDOW_MIN_SIZES[element?.id] || WIN95_WINDOW_MIN_SIZES.default;
    return {
        width: Math.min(baseSize.width, Math.max(220, bounds.maxRight - bounds.minLeft)),
        height: Math.min(baseSize.height, Math.max(180, bounds.maxBottom - bounds.minTop))
    };
}

function clampWin95WindowDragPosition(left, top, rect) {
    const bounds = getWin95WindowViewportBounds();
    const minVisible = 48;
    const margin = bounds.margin;
    const viewportWidth = bounds.maxRight - bounds.minLeft;
    const viewportHeight = bounds.maxBottom - bounds.minTop;
    const fitsWidth = rect.width <= viewportWidth;
    const fitsHeight = rect.height <= viewportHeight;
    const minLeft = fitsWidth ? bounds.minLeft : bounds.minLeft - Math.max(0, rect.width - minVisible);
    const maxLeft = fitsWidth ? Math.max(bounds.minLeft, bounds.maxRight - rect.width) : Math.max(bounds.minLeft, window.innerWidth - minVisible);
    const maxTop = fitsHeight ? Math.max(bounds.minTop, bounds.maxBottom - rect.height) : Math.max(bounds.minTop, window.innerHeight - minVisible);
    return {
        left: Math.min(maxLeft, Math.max(minLeft, left)),
        top: Math.min(maxTop, Math.max(bounds.minTop, top))
    };
}

function resetWin95WindowDragStyle(element) {
    if (!element) return;
    element.style.position = '';
    element.style.left = '';
    element.style.top = '';
    element.style.right = '';
    element.style.bottom = '';
    element.style.width = '';
    element.style.height = '';
    element.style.margin = '';
    element.style.transform = '';
}

function resetWin95WindowDragPositions() {
    resetWin95WindowDragStyle(document.querySelector('.container'));
    resetWin95WindowDragStyle(document.querySelector('.settings-shell'));
    resetWin95WindowDragStyle(document.getElementById('mapTableOverlay'));
    resetWin95WindowDragStyle(document.getElementById('pinboardOverlay'));
}

function syncWin95ResponsiveWindowMode() {
    const mobile = isWin95DesktopMode() && isWin95MobileWindowMode();
    document.body?.classList.toggle('win95-mobile-window-mode', !!mobile);
    if (!mobile) return;
    if (win95WindowDragState) endWin95WindowDrag({ pointerId: win95WindowDragState.pointerId });
    if (win95WindowResizeState) endWin95WindowResize({ pointerId: win95WindowResizeState.pointerId });
    resetWin95WindowDragPositions();
}

function win95OverlayTaskForElement(element) {
    if (!element) return null;
    if (element.id === 'mapTableOverlay') return 'map';
    if (element.id === 'pinboardOverlay') return 'pinboard';
    return null;
}

function win95OverlayElementForTask(task) {
    const view = String(task || '').toLowerCase();
    if (view === 'map') return document.getElementById('mapTableOverlay');
    if (view === 'pinboard') return document.getElementById('pinboardOverlay');
    return null;
}

function focusWin95OverlayWindow(taskOrElement) {
    if (!isWin95DesktopMode()) return;
    const overlay = typeof taskOrElement === 'string' ? win95OverlayElementForTask(taskOrElement) : taskOrElement;
    if (!overlay || !overlay.classList.contains('active')) return;
    const task = win95OverlayTaskForElement(overlay);
    document.querySelectorAll('.pinboard-overlay.win95-window-focused').forEach(item => {
        if (item !== overlay) item.classList.remove('win95-window-focused');
    });
    overlay.classList.add('win95-window-focused');
    if (task) setWin95DesktopTaskActive(task);
}

function toggleWin95OverlayWindow(task) {
    const view = String(task || '').toLowerCase();
    if (view === 'map' && typeof toggleMapTable === 'function') {
        document.body.classList.remove('map-is-fullscreen');
        document.documentElement.classList.remove('map-is-fullscreen');
        toggleMapTable(true);
        return;
    }
    if (view === 'pinboard' && typeof togglePinboard === 'function') {
        togglePinboard(true);
    }
}

function focusNextWin95OverlayWindow() {
    if (!isWin95DesktopMode()) return;
    const nextOverlay = document.querySelector('.pinboard-overlay.active');
    if (nextOverlay) {
        focusWin95OverlayWindow(nextOverlay);
    } else if (typeof window.persistMainViewFromOverlays === 'function') {
        window.persistMainViewFromOverlays();
    }
}

function closeWin95OverlayWindow(task, event) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const overlay = win95OverlayElementForTask(task);
    if (overlay?.classList.contains('active')) {
        toggleWin95OverlayWindow(task);
        overlay.classList.remove('win95-window-focused');
        focusNextWin95OverlayWindow();
    }
}

function minimizeWin95OverlayWindow(task, event) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    closeWin95OverlayWindow(task, event);
}

function scheduleWin95WindowLayoutRefresh(element, reason = 'win95-window-resize') {
    if (!element || element.id !== 'mapTableOverlay' || !element.classList.contains('active')) return;
    if (typeof window.gaScheduleRouteMapLayoutRefresh === 'function') {
        window.gaScheduleRouteMapLayoutRefresh(reason, { fitRoute: false, preserveView: true });
    } else if (typeof map !== 'undefined' && map && typeof map.invalidateSize === 'function') {
        map.invalidateSize({ pan: false });
    }
}

function getWin95WindowDragPoint(event) {
    const touch = event?.touches?.[0] || event?.changedTouches?.[0];
    if (touch && Number.isFinite(touch.clientX) && Number.isFinite(touch.clientY)) {
        return { clientX: touch.clientX, clientY: touch.clientY };
    }
    if (Number.isFinite(event?.clientX) && Number.isFinite(event?.clientY)) {
        return { clientX: event.clientX, clientY: event.clientY };
    }
    return null;
}

function getWin95WindowDragInputType(event) {
    if (String(event?.type || '').startsWith('touch')) return 'touch';
    if (String(event?.type || '').startsWith('mouse')) return 'mouse';
    return 'pointer';
}

function endWin95WindowDrag(event) {
    const state = win95WindowDragState;
    if (!state) return;
    if (state.inputType === 'pointer' && event?.pointerId != null && state.pointerId != null && event.pointerId !== state.pointerId) return;

    document.removeEventListener('pointermove', handleWin95WindowDragMove, true);
    document.removeEventListener('pointerup', endWin95WindowDrag, true);
    document.removeEventListener('pointercancel', endWin95WindowDrag, true);
    document.removeEventListener('mousemove', handleWin95WindowDragMove, true);
    document.removeEventListener('mouseup', endWin95WindowDrag, true);
    document.removeEventListener('touchmove', handleWin95WindowDragMove, true);
    document.removeEventListener('touchend', endWin95WindowDrag, true);
    document.removeEventListener('touchcancel', endWin95WindowDrag, true);
    document.body?.classList.remove('win95-window-dragging');
    try {
        if (state.pointerId != null) state.handle?.releasePointerCapture?.(state.pointerId);
    } catch (_) {}

    if (state.suppressSettingsClick && state.moved) {
        win95SuppressSettingsToggleClick = true;
        window.setTimeout(() => {
            win95SuppressSettingsToggleClick = false;
        }, 0);
    }
    win95WindowDragState = null;
}

function endWin95WindowResize(event) {
    const state = win95WindowResizeState;
    if (!state) return;
    if (state.inputType === 'pointer' && event?.pointerId != null && state.pointerId != null && event.pointerId !== state.pointerId) return;

    document.removeEventListener('pointermove', handleWin95WindowResizeMove, true);
    document.removeEventListener('pointerup', endWin95WindowResize, true);
    document.removeEventListener('pointercancel', endWin95WindowResize, true);
    document.removeEventListener('mousemove', handleWin95WindowResizeMove, true);
    document.removeEventListener('mouseup', endWin95WindowResize, true);
    document.removeEventListener('touchmove', handleWin95WindowResizeMove, true);
    document.removeEventListener('touchend', endWin95WindowResize, true);
    document.removeEventListener('touchcancel', endWin95WindowResize, true);
    document.body?.classList.remove('win95-window-resizing');
    try {
        if (state.pointerId != null) state.handle?.releasePointerCapture?.(state.pointerId);
    } catch (_) {}
    scheduleWin95WindowLayoutRefresh(state.windowEl, 'win95-window-resize-end');
    win95WindowResizeState = null;
}

function handleWin95WindowDragMove(event) {
    const state = win95WindowDragState;
    if (!state) return;
    if (state.inputType === 'pointer' && event.pointerId != null && state.pointerId != null && event.pointerId !== state.pointerId) return;
    const point = getWin95WindowDragPoint(event);
    if (!point) return;
    const deltaX = point.clientX - state.startX;
    const deltaY = point.clientY - state.startY;
    if (!state.moved && Math.hypot(deltaX, deltaY) >= WIN95_WINDOW_DRAG_THRESHOLD) {
        state.moved = true;
    }
    const pos = clampWin95WindowDragPosition(
        point.clientX - state.offsetX,
        point.clientY - state.offsetY,
        state.rect
    );
    state.windowEl.style.setProperty('left', `${Math.round(pos.left)}px`, 'important');
    state.windowEl.style.setProperty('top', `${Math.round(pos.top)}px`, 'important');
    event.preventDefault();
}

function clampWin95ResizeRect(state, point) {
    const bounds = getWin95WindowViewportBounds();
    const minSize = state.minSize;
    const edge = state.edge;
    let left = state.startRect.left;
    let top = state.startRect.top;
    let right = state.startRect.right;
    let bottom = state.startRect.bottom;

    if (edge.includes('e')) right = point.clientX;
    if (edge.includes('s')) bottom = point.clientY;
    if (edge.includes('w')) left = point.clientX;
    if (edge.includes('n')) top = point.clientY;

    if (edge.includes('w')) {
        left = Math.max(bounds.minLeft, Math.min(left, state.startRect.right - minSize.width));
    } else if (edge.includes('e')) {
        right = Math.min(bounds.maxRight, Math.max(right, state.startRect.left + minSize.width));
    }

    if (edge.includes('n')) {
        top = Math.max(bounds.minTop, Math.min(top, state.startRect.bottom - minSize.height));
    } else if (edge.includes('s')) {
        bottom = Math.min(bounds.maxBottom, Math.max(bottom, state.startRect.top + minSize.height));
    }

    let width = Math.max(minSize.width, right - left);
    let height = Math.max(minSize.height, bottom - top);

    if (left + width > bounds.maxRight) width = Math.max(minSize.width, bounds.maxRight - left);
    if (top + height > bounds.maxBottom) height = Math.max(minSize.height, bounds.maxBottom - top);

    return { left, top, width, height };
}

function applyWin95WindowRect(element, rect) {
    element.style.position = 'fixed';
    element.style.setProperty('left', `${Math.round(rect.left)}px`, 'important');
    element.style.setProperty('top', `${Math.round(rect.top)}px`, 'important');
    element.style.setProperty('width', `${Math.round(rect.width)}px`, 'important');
    element.style.setProperty('height', `${Math.round(rect.height)}px`, 'important');
    element.style.right = 'auto';
    element.style.bottom = 'auto';
    element.style.margin = '0';
    element.style.transform = 'none';
}

function handleWin95WindowResizeMove(event) {
    const state = win95WindowResizeState;
    if (!state) return;
    if (state.inputType === 'pointer' && event.pointerId != null && state.pointerId != null && event.pointerId !== state.pointerId) return;
    const point = getWin95WindowDragPoint(event);
    if (!point) return;
    const deltaX = point.clientX - state.startX;
    const deltaY = point.clientY - state.startY;
    if (!state.moved && Math.hypot(deltaX, deltaY) >= WIN95_WINDOW_DRAG_THRESHOLD) {
        state.moved = true;
    }
    applyWin95WindowRect(state.windowEl, clampWin95ResizeRect(state, point));
    event.preventDefault();
}

function beginWin95WindowDrag(event, windowEl, options = {}) {
    if (!canFloatWin95Windows() || !windowEl) return false;
    if (event.button != null && event.button !== 0) return false;
    if (options.requireSettingsWindow && !document.body.classList.contains('win95-settings-window-open')) return false;
    const point = getWin95WindowDragPoint(event);
    if (!point) return false;
    if (win95WindowDragState) endWin95WindowDrag({ pointerId: win95WindowDragState.pointerId });
    if (win95WindowResizeState) endWin95WindowResize({ pointerId: win95WindowResizeState.pointerId });

    const rect = windowEl.getBoundingClientRect();
    const pos = clampWin95WindowDragPosition(rect.left, rect.top, rect);
    windowEl.style.position = 'fixed';
    windowEl.style.setProperty('left', `${Math.round(pos.left)}px`, 'important');
    windowEl.style.setProperty('top', `${Math.round(pos.top)}px`, 'important');
    windowEl.style.right = 'auto';
    windowEl.style.bottom = 'auto';
    windowEl.style.margin = '0';
    windowEl.style.transform = 'none';

    win95WindowDragState = {
        pointerId: event.pointerId ?? null,
        inputType: getWin95WindowDragInputType(event),
        handle: event.currentTarget,
        windowEl,
        startX: point.clientX,
        startY: point.clientY,
        offsetX: point.clientX - pos.left,
        offsetY: point.clientY - pos.top,
        rect: { width: rect.width, height: rect.height },
        moved: false,
        suppressSettingsClick: !!options.suppressSettingsClick
    };

    document.body.classList.add('win95-window-dragging');
    try {
        if (event.pointerId != null) event.currentTarget?.setPointerCapture?.(event.pointerId);
    } catch (_) {}
    document.addEventListener('pointermove', handleWin95WindowDragMove, true);
    document.addEventListener('pointerup', endWin95WindowDrag, true);
    document.addEventListener('pointercancel', endWin95WindowDrag, true);
    document.addEventListener('mousemove', handleWin95WindowDragMove, true);
    document.addEventListener('mouseup', endWin95WindowDrag, true);
    document.addEventListener('touchmove', handleWin95WindowDragMove, { capture: true, passive: false });
    document.addEventListener('touchend', endWin95WindowDrag, true);
    document.addEventListener('touchcancel', endWin95WindowDrag, true);
    event.preventDefault?.();
    return true;
}

function beginWin95WindowResize(event, handle) {
    if (!canFloatWin95Windows() || !handle) return false;
    if (event.button != null && event.button !== 0) return false;
    const windowEl = document.getElementById(handle.dataset.win95ResizeTarget || '');
    const edge = String(handle.dataset.win95ResizeEdge || '').toLowerCase();
    if (!windowEl?.classList.contains('active') || !/^[nsew]{1,2}$/.test(edge)) return false;
    const point = getWin95WindowDragPoint(event);
    if (!point) return false;
    if (win95WindowDragState) endWin95WindowDrag({ pointerId: win95WindowDragState.pointerId });
    if (win95WindowResizeState) endWin95WindowResize({ pointerId: win95WindowResizeState.pointerId });

    focusWin95OverlayWindow(windowEl);
    const rect = windowEl.getBoundingClientRect();
    const bounds = getWin95WindowViewportBounds();
    const minSize = getWin95WindowMinSize(windowEl, bounds);
    const startRect = {
        left: Math.round(rect.left),
        top: Math.round(rect.top),
        right: Math.round(rect.right),
        bottom: Math.round(rect.bottom),
        width: Math.round(rect.width),
        height: Math.round(rect.height)
    };
    applyWin95WindowRect(windowEl, startRect);

    win95WindowResizeState = {
        pointerId: event.pointerId ?? null,
        inputType: getWin95WindowDragInputType(event),
        handle,
        windowEl,
        edge,
        minSize,
        startX: point.clientX,
        startY: point.clientY,
        startRect,
        moved: false
    };

    document.body.classList.add('win95-window-resizing');
    try {
        if (event.pointerId != null) handle.setPointerCapture?.(event.pointerId);
    } catch (_) {}
    document.addEventListener('pointermove', handleWin95WindowResizeMove, true);
    document.addEventListener('pointerup', endWin95WindowResize, true);
    document.addEventListener('pointercancel', endWin95WindowResize, true);
    document.addEventListener('mousemove', handleWin95WindowResizeMove, true);
    document.addEventListener('mouseup', endWin95WindowResize, true);
    document.addEventListener('touchmove', handleWin95WindowResizeMove, { capture: true, passive: false });
    document.addEventListener('touchend', endWin95WindowResize, true);
    document.addEventListener('touchcancel', endWin95WindowResize, true);
    event.preventDefault?.();
    event.stopPropagation?.();
    return true;
}

function bindWin95WindowDragHandle(handle, resolveWindow, options = {}) {
    if (!handle) return;
    const startDrag = (event) => {
        if (event.type === 'mousedown' && Date.now() - win95LastPointerDragStartAt < 400) return;
        const windowEl = typeof resolveWindow === 'function' ? resolveWindow(event, handle) : resolveWindow;
        const dragOptions = typeof options === 'function' ? options(event, handle) : options;
        const started = beginWin95WindowDrag(event, windowEl, dragOptions || {});
        if (started && event.type === 'pointerdown') win95LastPointerDragStartAt = Date.now();
    };
    handle.addEventListener('pointerdown', startDrag);
    handle.addEventListener('mousedown', startDrag);
    handle.addEventListener('touchstart', startDrag, { passive: false });
}

function bindWin95WindowResizeHandle(handle) {
    if (!handle) return;
    const startResize = (event) => {
        if (event.type === 'mousedown' && Date.now() - win95LastPointerResizeStartAt < 400) return;
        const started = beginWin95WindowResize(event, handle);
        if (started && event.type === 'pointerdown') win95LastPointerResizeStartAt = Date.now();
    };
    handle.addEventListener('pointerdown', startResize);
    handle.addEventListener('mousedown', startResize);
    handle.addEventListener('touchstart', startResize, { passive: false });
}

function initWin95WindowDragging() {
    if (window.__gaWin95WindowDraggingInstalled) return;
    window.__gaWin95WindowDraggingInstalled = true;

    const mainHandle = document.getElementById('win95MainDragbar');
    if (mainHandle) {
        bindWin95WindowDragHandle(mainHandle, () => {
            if (document.body.classList.contains('win95-main-closed') || document.body.classList.contains('win95-main-minimized')) return;
            return document.querySelector('.container');
        });
    }

    const settingsHandle = document.getElementById('settingsToggleBtn');
    if (settingsHandle) {
        bindWin95WindowDragHandle(settingsHandle, () => document.querySelector('.settings-shell'), {
            requireSettingsWindow: true,
            suppressSettingsClick: true
        });
    }

    document.querySelectorAll('.win95-overlay-dragbar[data-win95-drag-target]').forEach((handle) => {
        bindWin95WindowDragHandle(handle, () => {
            const overlay = document.getElementById(handle.dataset.win95DragTarget || '');
            if (!overlay?.classList.contains('active')) return null;
            focusWin95OverlayWindow(overlay);
            return overlay;
        });
    });

    document.querySelectorAll('.win95-window-resize-handle[data-win95-resize-target]').forEach(bindWin95WindowResizeHandle);

    document.querySelectorAll('.pinboard-overlay').forEach((overlay) => {
        overlay.addEventListener('pointerdown', () => {
            if (overlay.classList.contains('active')) focusWin95OverlayWindow(overlay);
        }, true);
    });
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        initWin95WindowDragging();
        syncWin95ResponsiveWindowMode();
    }, { once: true });
} else {
    initWin95WindowDragging();
    syncWin95ResponsiveWindowMode();
}

window.addEventListener('resize', syncWin95ResponsiveWindowMode, { passive: true });
window.addEventListener('orientationchange', syncWin95ResponsiveWindowMode, { passive: true });

function setSettingsPanelOpen(open, persist = true) {
    const shell = document.querySelector('.settings-shell');
    const panel = document.getElementById('settingsPanel');
    const btn = document.getElementById('settingsToggleBtn');
    const chevron = document.getElementById('settingsToggleChevron');
    if (!shell || !panel) return;
    shell.classList.toggle('is-open', !!open);
    document.body.classList.toggle('win95-settings-window-open', !!open && isWin95DesktopMode());
    if (open && isWin95DesktopMode()) {
        setWin95DesktopTaskActive('settings');
    } else if (!open && typeof window.persistMainViewFromOverlays === 'function') {
        window.persistMainViewFromOverlays();
    }
    if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (chevron) chevron.innerText = '▾';
    if (persist) localStorage.setItem('ga_settings_open', open ? 'true' : 'false');
}

function toggleSettingsPanel() {
    if (win95SuppressSettingsToggleClick) {
        win95SuppressSettingsToggleClick = false;
        return;
    }
    const shell = document.querySelector('.settings-shell');
    if (isWin95DesktopMode() && shell?.classList.contains('is-open')) return;
    setSettingsPanelOpen(!(shell && shell.classList.contains('is-open')));
}

function closeWin95SettingsWindow(event) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    setSettingsPanelOpen(false, true);
}

function minimizeWin95SettingsWindow(event) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    setSettingsPanelOpen(false, true);
}

function openWin95DesktopApp(target) {
    const app = String(target || '').toLowerCase();
    if (app === 'map') {
        setSettingsPanelOpen(false, true);
        const mapOpen = !!document.getElementById('mapTableOverlay')?.classList.contains('active');
        if (!mapOpen && typeof toggleMapTable === 'function') toggleMapTable();
        saveLastMainView(GA_VIEW_MAP);
        if (isWin95DesktopMode()) focusWin95OverlayWindow(GA_VIEW_MAP);
        else setWin95DesktopTaskActive(GA_VIEW_MAP);
        return;
    }
    if (app === 'pinboard') {
        setSettingsPanelOpen(false, true);
        const pinboardOpen = !!document.getElementById('pinboardOverlay')?.classList.contains('active');
        if (!pinboardOpen && typeof togglePinboard === 'function') togglePinboard();
        saveLastMainView(GA_VIEW_PINBOARD);
        if (isWin95DesktopMode()) focusWin95OverlayWindow(GA_VIEW_PINBOARD);
        else setWin95DesktopTaskActive(GA_VIEW_PINBOARD);
        return;
    }
    if (app === 'settings') {
        setSettingsPanelOpen(true);
        setWin95DesktopTaskActive('settings');
        return;
    }

    const pinboardOpen = !!document.getElementById('pinboardOverlay')?.classList.contains('active');
    const mapOpen = !!document.getElementById('mapTableOverlay')?.classList.contains('active');
    if (pinboardOpen && typeof togglePinboard === 'function') togglePinboard();
    if (mapOpen && typeof toggleMapTable === 'function') toggleMapTable();
    setWin95MainClosed(false, true);
    setSettingsPanelOpen(false, true);
    saveLastMainView(GA_VIEW_MAIN);
    setWin95DesktopTaskActive(GA_VIEW_MAIN);
    window.scrollTo(0, 0);
}

window.openWin95DesktopApp = openWin95DesktopApp;
window.closeWin95MainMenu = closeWin95MainMenu;
window.minimizeWin95MainMenu = minimizeWin95MainMenu;
window.closeWin95SettingsWindow = closeWin95SettingsWindow;
window.minimizeWin95SettingsWindow = minimizeWin95SettingsWindow;
window.focusWin95OverlayWindow = focusWin95OverlayWindow;
window.closeWin95OverlayWindow = closeWin95OverlayWindow;
window.minimizeWin95OverlayWindow = minimizeWin95OverlayWindow;

