const POI_TILE_INFRA_ENDPOINTS = [
    './obstacles/infra-tiles/{latI}/{lonI}.json.gz',
    './obstacles/infra-tiles/{latI}/{lonI}.json'
];
if (POI_TILE_WORKER_ENABLED) {
    POI_TILE_POI_ENDPOINTS.push('https://ga-proxy.einherjer.workers.dev/api/obstacles/tile');
    POI_TILE_CORE_ENDPOINTS.push('https://ga-proxy.einherjer.workers.dev/api/obstacles/tile');
    POI_TILE_INFRA_ENDPOINTS.push('https://ga-proxy.einherjer.workers.dev/api/obstacles/tile');
}
const POI_TILE_LEGACY_ENDPOINTS = [
    'https://ga-proxy.einherjer.workers.dev/api/obstacles/tile'
];
const _poiTileMemCache = new Map();

function _poiDebugState() {
    if (!window.gaPoiTileDebug || typeof window.gaPoiTileDebug !== 'object') {
        window.gaPoiTileDebug = {
            requests: 0,
            hits: 0,
            cacheHits: 0,
            splitHits: 0,
            legacyHits: 0,
            fallbackHits: 0,
            misses: 0,
            errors: 0,
            lastSource: '',
            localPoiSplitHits: 0,
            localCoreSplitHits: 0,
            localInfraSplitHits: 0,
            workerPoiSplitHits: 0,
            workerCoreSplitHits: 0,
            workerInfraSplitHits: 0,
            cacheMissSources: 0
        };
    }
    window.gaPoiTileDebug.cacheEntries = _poiTileMemCache.size;
    return window.gaPoiTileDebug;
}

function _poiDebugMarkSource(src = '') {
    const dbg = _poiDebugState();
    dbg.lastSource = String(src || '');
}

function _poiDebugBumpSourceCounter(src = '') {
    const dbg = _poiDebugState();
    const s = String(src || '').toLowerCase();
    if (s === 'local-poi-split') dbg.localPoiSplitHits = Number(dbg.localPoiSplitHits || 0) + 1;
    else if (s === 'local-core-split') dbg.localCoreSplitHits = Number(dbg.localCoreSplitHits || 0) + 1;
    else if (s === 'local-infra-split') dbg.localInfraSplitHits = Number(dbg.localInfraSplitHits || 0) + 1;
    else if (s === 'worker-poi-split') dbg.workerPoiSplitHits = Number(dbg.workerPoiSplitHits || 0) + 1;
    else if (s === 'worker-core-split') dbg.workerCoreSplitHits = Number(dbg.workerCoreSplitHits || 0) + 1;
    else if (s === 'worker-infra-split') dbg.workerInfraSplitHits = Number(dbg.workerInfraSplitHits || 0) + 1;
    else if (s === 'split-only-miss') dbg.cacheMissSources = Number(dbg.cacheMissSources || 0) + 1;
}

function _poiTrackTileCoverage(tileKey, src = 'poi-unknown') {
    try {
        const cfg = (window.vpObsTileConfig && typeof window.vpObsTileConfig === 'object') ? window.vpObsTileConfig : null;
        const storageKey = String(cfg?.storageKey || 'ga_obs_tile_cov_v1');
        const now = Date.now();
        let list = [];
        try {
            const raw = localStorage.getItem(storageKey);
            const parsed = JSON.parse(raw || '[]');
            list = Array.isArray(parsed) ? parsed : [];
        } catch (_) {
            list = [];
        }
        const idx = list.findIndex(e => e && e.k === tileKey);
        const next = {
            k: tileKey,
            ts: now,
            usedTs: now,
            src: String(src || 'poi-unknown')
        };
        if (idx >= 0) list[idx] = { ...(list[idx] || {}), ...next };
        else list.push(next);
        if (list.length > 2200) list = list.slice(list.length - 2200);
        localStorage.setItem(storageKey, JSON.stringify(list));
        if (typeof window.vpNotifyObsTileCoverageChanged === 'function') window.vpNotifyObsTileCoverageChanged();
    } catch (_) {}
}

function _poiTileKey(lat, lon) {
    const latI = Math.floor((Number(lat) + 90) / POI_TILE_STEP_LAT);
    const lonI = Math.floor((Number(lon) + 180) / POI_TILE_STEP_LON);
    return `${latI}|${lonI}`;
}

function _poiTileBoundsFromKey(key) {
    const [latI, lonI] = String(key || '').split('|').map(Number);
    if (!Number.isFinite(latI) || !Number.isFinite(lonI)) return null;
    const south = (latI * POI_TILE_STEP_LAT) - 90;
    const west = (lonI * POI_TILE_STEP_LON) - 180;
    return {
        latI,
        lonI,
        south,
        west,
        north: south + POI_TILE_STEP_LAT,
        east: west + POI_TILE_STEP_LON
    };
}

function _poiCollectTileKeysAround(lat, lon, radiusNm) {
    const out = [];
    const center = _poiTileKey(lat, lon);
    const [cLatI, cLonI] = center.split('|').map(Number);
    const span = Math.max(1, Math.ceil(Number(radiusNm || 25) / POI_TILE_EDGE_NM) + 1);
    for (let dy = -span; dy <= span; dy++) {
        for (let dx = -span; dx <= span; dx++) {
            out.push(`${cLatI + dy}|${cLonI + dx}`);
        }
    }
    return out.slice(0, POI_TILE_MAX_KEYS);
}

function _poiCollectNearestTileKeysAround(lat, lon, radiusNm, maxKeys = POI_TILE_MAX_KEYS) {
    const center = _poiTileKey(lat, lon);
    const [cLatI, cLonI] = center.split('|').map(Number);
    const span = Math.max(1, Math.ceil(Number(radiusNm || 25) / POI_TILE_EDGE_NM) + 1);
    const rows = [];
    for (let dy = -span; dy <= span; dy++) {
        for (let dx = -span; dx <= span; dx++) {
            const key = `${cLatI + dy}|${cLonI + dx}`;
            const b = _poiTileBoundsFromKey(key);
            const centerLat = b ? (Number(b.south) + Number(b.north)) / 2 : Number(lat);
            const centerLon = b ? (Number(b.west) + Number(b.east)) / 2 : Number(lon);
            let dist = Math.abs(dx) + Math.abs(dy);
            try {
                const nav = calcNav(Number(lat), Number(lon), centerLat, centerLon);
                if (Number.isFinite(Number(nav?.dist))) dist = Number(nav.dist);
            } catch (_) {}
            rows.push({ key, dist, grid: Math.abs(dx) + Math.abs(dy) });
        }
    }
    return rows
        .sort((a, b) => a.dist - b.dist || a.grid - b.grid || a.key.localeCompare(b.key))
        .map(row => row.key)
        .slice(0, Math.max(1, Math.min(POI_TILE_MAX_KEYS, Number(maxKeys) || POI_TILE_MAX_KEYS)));
}

function _poiNormalizeFeatureName(raw, fallbackCategory = 'poi') {
    const n = String(raw || '').trim();
    if (n) return n;
    const c = String(fallbackCategory || 'poi').toLowerCase();
    if (c === 'dam') return 'Staudamm/Talsperre';
    if (c === 'water') return 'Gewässer';
    if (c === 'telecom') return 'Funkmast/Funkturm';
    if (c === 'rail') return 'Bahntrasse/Bahninfrastruktur';
    if (c === 'road') return 'Straßen-/Verkehrsknoten';
    if (c === 'mountain') return 'Berg-/Talgebiet';
    if (c === 'castle') return 'Burg/Schloss';
    if (c === 'industry') return 'Industrieanlage';
    if (c === 'city') return 'Stadtgebiet';
    if (c === 'bridge') return 'Brücke/Viadukt';
    if (c === 'infrastructure') return 'Infrastrukturkorridor';
    return 'POI';
}

function _poiRailFallbackName(railwayTag = '') {
    const tag = String(railwayTag || '').toLowerCase();
    if (['station', 'halt'].includes(tag)) return 'Bahnhof/Haltepunkt';
    if (tag === 'signal_box') return 'Stellwerk';
    if (tag === 'switch') return 'Weiche';
    if (tag === 'signal') return 'Bahnsignal';
    if (['level_crossing', 'crossing'].includes(tag)) return 'Bahnübergang';
    if (tag === 'junction') return 'Bahnknoten';
    if (tag) return 'Bahninfrastruktur';
    return 'Bahntrasse/Bahninfrastruktur';
}

function _poiInfraFallbackName(tags = {}, fallbackCategory = 'infrastructure') {
    const t = tags || {};
    const infraType = String(t.infra_type || t.cluster_type || '').toLowerCase();
    const railway = String(t.railway || '').toLowerCase();
    if (infraType === 'solar') return 'Solarpark';
    if (infraType === 'wind') return 'Windpark';
    if (infraType === 'construction' || String(t.landuse || '').toLowerCase() === 'construction' || t.construction) return 'Baustellenbereich';
    if (infraType === 'public_building') return 'Öffentliches Gebäude';
    if (infraType === 'fuel' || String(t.amenity || '').toLowerCase() === 'fuel') return 'Tankstelle';
    if (infraType === 'energy_plant') return 'Energieanlage';
    if (infraType === 'energy_storage') return 'Batterie-/Speicheranlage';
    if (infraType === 'pipeline' || t.pipeline) return 'Pipeline-/Leitungsstation';
    if (infraType === 'marine_infra') return 'Hafen-/Schleusenanlage';
    if (infraType === 'perimeter_security') return 'Perimeter-/Zaunbereich';
    if (infraType === 'water_utility') return 'Wasser-/Abwasseranlage';
    if (infraType === 'water_tank' || String(t.man_made || '').toLowerCase() === 'water_tower') return 'Wassertank';
    if (infraType === 'storage_tank' || String(t.man_made || '').toLowerCase() === 'storage_tank') return 'Lagertank';
    if (infraType === 'waste' || ['recycling', 'waste_disposal', 'waste_transfer_station'].includes(String(t.amenity || '').toLowerCase())) return 'Entsorgungsanlage';
    if (infraType === 'quarry' || String(t.landuse || '').toLowerCase() === 'quarry') return 'Steinbruch/Kieswerk';
    if (infraType === 'flood_protection' || ['dyke', 'embankment'].includes(String(t.man_made || '').toLowerCase())) return 'Hochwasserschutzbauwerk';
    if (infraType === 'traffic_protection' || String(t.tunnel || '').trim() || ['noise_barrier', 'retaining_wall'].includes(String(t.barrier || '').toLowerCase())) return 'Verkehrsschutzbauwerk';
    if (infraType === 'power_station') return 'Umspannwerk/Technikstation';
    if (infraType === 'power_grid') return 'Netztrassenabschnitt';
    if (infraType === 'telecom') return 'Funkmast/Funkturm';
    if (infraType === 'industrial') return 'Industrieareal';
    if (infraType === 'rail' || railway) return _poiRailFallbackName(railway);
    if (infraType === 'road' || t.highway) return 'Straßen-/Verkehrsabschnitt';
    if (infraType === 'bridge' || t.bridge) return 'Brücke/Viadukt';
    const cat = String(fallbackCategory || '').toLowerCase();
    if (cat === 'industry') return 'Technische Anlage';
    return '';
}

function _poiIsGenericFallbackName(name) {
    const n = normalizeMissionText(name || '');
    return (
        n === 'poi' ||
        n === 'zielgebiet' ||
        n === 'staudamm talsperre' ||
        n === 'gewasser' ||
        n === 'gewaesser' ||
        n === 'berg talgebiet' ||
        n === 'funkmast funkturm windrad' ||
        n === 'funkmast funkturm' ||
        n === 'bahntrasse bahninfrastruktur' ||
        n === 'industrieanlage' ||
        n === 'strassen verkehrsknoten' ||
        n === 'infrastrukturkorridor' ||
        n === 'stadtgebiet' ||
        n === 'burg schloss'
    );
}

function _poiIsSettlementOnlyFeature(feature) {
    const t = feature?.tags || {};
    const name = String(feature?.name || '').trim();
    const placeKind = String(t.place || '').toLowerCase();
    const isPlacePoint = ['city', 'town', 'village', 'suburb', 'hamlet', 'locality', 'neighbourhood', 'quarter'].includes(placeKind);
    if (!isPlacePoint) return false;
    const hasInfraTags = (
        !!t.highway ||
        !!t.railway ||
        ['line', 'minor_line', 'cable', 'tower', 'pole', 'substation', 'plant', 'generator', 'transformer'].includes(String(t.power || '').toLowerCase()) ||
        ['bridge', 'tower', 'mast'].includes(String(t.man_made || '').toLowerCase()) ||
        ['dam', 'weir'].includes(String(t.waterway || '').toLowerCase()) ||
        ['road', 'rail', 'power', 'hydro'].includes(String(t.layer || '').toLowerCase())
    );
    if (hasInfraTags) return false;
    // Extra Guard: City-like names without infra tags should not satisfy road/infra selection.
    return classifyPOITitleCategory(name) === 'city';
}

function _poiIsHumanMemorialFeature(feature) {
    const t = feature?.tags || {};
    const historic = String(t.historic || '').toLowerCase();
    const tourism = String(t.tourism || '').toLowerCase();
    const amenity = String(t.amenity || '').toLowerCase();
    const natural = String(t.natural || '').toLowerCase();
    const landuse = String(t.landuse || '').toLowerCase();
    const hasNatureSurface = ['wood', 'heath', 'water'].includes(natural) || ['forest', 'meadow', 'grassland', 'farmland', 'orchard', 'vineyard'].includes(landuse);
    if (hasNatureSurface) return false;
    if (historic === 'memorial' || historic === 'monument') return true;
    if (tourism === 'artwork' || amenity === 'grave_yard') return true;
    return _looksLikePersonForstName(feature?.name || '');
}

function _poiIsNumericLikeName(name) {
    const s = String(name || '').trim();
    if (!s) return false;
    const compact = s.replace(/\s+/g, '');
    return /^[0-9]+([a-z])?$/i.test(compact);
}

function _poiIsCodeLikeName(name) {
    const s = String(name || '').trim();
    if (!s) return false;
    // kurze technische IDs wie "M 401", "5200/30", "P259", "26 W6"
    if (/^[A-Z]?\s*\d{1,5}(?:[\/.-]\d{1,5})?$/i.test(s)) return true;
    if (/^\d{1,4}\s*[A-Z]\d{0,3}$/i.test(s)) return true;
    if (/^[A-Z]{1,3}\s*\d{1,4}$/i.test(s)) return true;
    return false;
}

function _poiLooksJunctionLabel(name) {
    const s = String(name || '').trim();
    if (!s) return false;
    if (s.includes(' / ')) return true;
    if (/^\s*[A-ZÄÖÜ][a-zäöüß.-]+\s*\/\s*[A-ZÄÖÜ][a-zäöüß.-]+\s*$/i.test(s)) return true;
    return false;
}

function _poiFeatureFromTileNode(node, src = 'tile') {
    const lat = Number(node?.lat);
    const lon = Number(node?.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    return {
        lat,
        lon,
        name: String(node?.name || node?.n || '').trim(),
        sourceKind: String(node?.sourceKind || src),
        fetchSource: String(node?.fetchSource || ''),
        rawType: String(node?.type || '').toLowerCase(),
        tags: {
            layer: String(node?.layer || '').toLowerCase(),
            highway: String(node?.highway || '').toLowerCase(),
            waterway: String(node?.waterway || '').toLowerCase(),
            water: String(node?.water || '').toLowerCase(),
            natural: String(node?.natural || '').toLowerCase(),
            landuse: String(node?.landuse || '').toLowerCase(),
            power: String(node?.power || '').toLowerCase(),
            railway: String(node?.railway || '').toLowerCase(),
            man_made: String(node?.man_made || '').toLowerCase(),
            tourism: String(node?.tourism || '').toLowerCase(),
            historic: String(node?.historic || '').toLowerCase(),
            amenity: String(node?.amenity || '').toLowerCase(),
            leisure: String(node?.leisure || '').toLowerCase(),
            boundary: String(node?.boundary || '').toLowerCase(),
            access: String(node?.access || '').toLowerCase(),
            place: String(node?.place || '').toLowerCase(),
            obstacle_type: String(node?.obstacle_type || node?.type || '').toLowerCase(),
            generator_source: String(node?.generator_source || node?.['generator:source'] || '').toLowerCase(),
            plant_source: String(node?.plant_source || node?.['plant:source'] || '').toLowerCase(),
            generator_method: String(node?.generator_method || node?.['generator:method'] || '').toLowerCase(),
            plant_method: String(node?.plant_method || node?.['plant:method'] || '').toLowerCase(),
            substation: String(node?.substation || '').toLowerCase(),
            transformer: String(node?.transformer || '').toLowerCase(),
            location: String(node?.location || '').toLowerCase(),
            utility: String(node?.utility || '').toLowerCase(),
            building: String(node?.building || '').toLowerCase(),
            building_use: String(node?.building_use || node?.['building:use'] || '').toLowerCase(),
            construction: String(node?.construction || '').toLowerCase(),
            content: String(node?.content || '').toLowerCase(),
            healthcare: String(node?.healthcare || '').toLowerCase(),
            office: String(node?.office || '').toLowerCase(),
            shop: String(node?.shop || '').toLowerCase(),
            public_transport: String(node?.public_transport || '').toLowerCase(),
            emergency: String(node?.emergency || '').toLowerCase(),
            barrier: String(node?.barrier || '').toLowerCase(),
            tunnel: String(node?.tunnel || '').toLowerCase(),
            pipeline: String(node?.pipeline || '').toLowerCase(),
            substance: String(node?.substance || '').toLowerCase(),
            monitoring: String(node?.monitoring || '').toLowerCase(),
            monitoring_water_level: String(node?.monitoring_water_level || node?.['monitoring:water_level'] || '').toLowerCase(),
            lock_tag: String(node?.lock_tag || node?.lock || '').toLowerCase(),
            embankment: String(node?.embankment || '').toLowerCase(),
            recycling_type: String(node?.recycling_type || '').toLowerCase(),
            voltage: String(node?.voltage || ''),
            operator: String(node?.operator || ''),
            ref: String(node?.ref || ''),
            bridge: String(node?.bridge || '').toLowerCase(),
            infra_cluster: !!node?.infra_cluster,
            cluster_type: String(node?.cluster_type || '').toLowerCase(),
            cluster_count: Number(node?.cluster_count || 0),
            cluster_radius_nm: Number(node?.cluster_radius_nm || 0),
            cluster_sample_names: String(node?.cluster_sample_names || ''),
            infra_enriched: !!node?.infra_enriched,
            infra_type: String(node?.infra_type || '').toLowerCase()
        }
    };
}

function _poiFeatureSourcePriority(feature = {}) {
    const source = String(feature?.sourceKind || '').toLowerCase();
    if (source === 'infra') return 4;
    if (source === 'poi') return 3;
    if (source === 'lin') return 2;
    if (source === 'obs') return 1;
    return 0;
}

function _poiFeatureDedupeKey(feature = {}) {
    const lat = Number(feature?.lat);
    const lon = Number(feature?.lon);
    const t = feature?.tags || {};
    const name = normalizeMissionText(feature?.name || '').replace(/\s+/g, ' ').trim();
    const type = String(
        t.infra_type ||
        t.obstacle_type ||
        t.highway ||
        t.railway ||
        t.waterway ||
        t.water ||
        t.power ||
        t.man_made ||
        t.natural ||
        t.landuse ||
        feature?.rawType ||
        'poi'
    ).toLowerCase();
    const ref = String(t.ref || '').toLowerCase();
    const operator = normalizeMissionText(t.operator || '').replace(/\s+/g, ' ').trim();
    const identity = name || [type, ref, operator].filter(Boolean).join('|') || type;
    return `${lat.toFixed(5)}|${lon.toFixed(5)}|${identity}|${type}`;
}

function _poiMergePreferredFeature(existing = null, incoming = null) {
    if (!existing) return incoming;
    if (!incoming) return existing;
    const oldPriority = _poiFeatureSourcePriority(existing);
    const newPriority = _poiFeatureSourcePriority(incoming);
    const oldName = String(existing?.name || '').trim();
    const newName = String(incoming?.name || '').trim();
    const preferIncoming = (
        newPriority > oldPriority ||
        (newPriority === oldPriority && !oldName && !!newName)
    );
    const primary = preferIncoming ? incoming : existing;
    const secondary = preferIncoming ? existing : incoming;
    return {
        ...secondary,
        ...primary,
        name: String(primary?.name || secondary?.name || '').trim(),
        fetchSource: String(primary?.fetchSource || secondary?.fetchSource || ''),
        tags: {
            ...(secondary?.tags || {}),
            ...(primary?.tags || {})
        }
    };
}

function _poiParseTilePayload(payload) {
    const out = [];
    if (!payload || typeof payload !== 'object') return out;
    const coreObj = (payload.core && typeof payload.core === 'object') ? payload.core : null;
    const poiObj = (payload.poi && typeof payload.poi === 'object' && Array.isArray(payload.poi.poi))
        ? payload.poi
        : null;
    const infraObj = (payload.infra && typeof payload.infra === 'object' && Array.isArray(payload.infra.poi))
        ? payload.infra
        : null;
    const obs = Array.isArray(payload.obs) ? payload.obs : (Array.isArray(coreObj?.obs) ? coreObj.obs : []);
    const lin = Array.isArray(payload.lin) ? payload.lin : (Array.isArray(coreObj?.lin) ? coreObj.lin : []);
    const poi = Array.isArray(payload.poi) ? payload.poi : (Array.isArray(poiObj?.poi) ? poiObj.poi : []);
    const infra = Array.isArray(infraObj?.poi) ? infraObj.poi : [];
    const infraClusters = Array.isArray(infraObj?.clusters) ? infraObj.clusters : [];

    for (const e of obs) {
        const f = _poiFeatureFromTileNode({
            ...e,
            sourceKind: 'obs',
            layer: 'obs',
            man_made: (String(e?.type || '').toLowerCase().includes('mast') || String(e?.type || '').toLowerCase().includes('tower')) ? 'tower' : '',
            power: String(e?.type || '').toLowerCase().includes('power') ? 'tower' : ''
        }, 'obs');
        if (f) out.push(f);
    }
    for (const e of lin) {
        const legacyType = String(e?.type || '').toLowerCase();
        const isRoadLike = ['highway', 'motorway', 'motorway_link', 'trunk', 'trunk_link', 'primary', 'primary_link', 'secondary', 'secondary_link', 'tertiary', 'tertiary_link', 'residential', 'service'].includes(legacyType);
        const isHydroLike = ['river', 'stream', 'canal', 'ditch', 'drain', 'water', 'lake', 'reservoir', 'dam', 'weir'].includes(legacyType);
        const isRailLike = ['railway', 'rail', 'tram', 'light_rail', 'subway'].includes(legacyType);
        const isPowerLike = ['power', 'powerline', 'power_line', 'line', 'minor_line', 'cable'].includes(legacyType);
        const layer = String(e?.layer || '').toLowerCase() || (
            isRoadLike ? 'road' :
            isHydroLike ? 'hydro' :
            isRailLike ? 'rail' :
            isPowerLike ? 'power' : ''
        );
        const f = _poiFeatureFromTileNode({
            ...e,
            sourceKind: 'lin',
            layer,
            highway: isRoadLike ? (String(e?.highway || '').toLowerCase() || legacyType) : String(e?.highway || '').toLowerCase(),
            waterway: isHydroLike
                ? (String(e?.waterway || '').toLowerCase() || (['dam', 'weir'].includes(legacyType) ? legacyType : (['river', 'stream', 'canal', 'ditch', 'drain'].includes(legacyType) ? legacyType : '')))
                : String(e?.waterway || '').toLowerCase(),
            water: isHydroLike
                ? (String(e?.water || '').toLowerCase() || (['lake', 'reservoir'].includes(legacyType) ? legacyType : ''))
                : String(e?.water || '').toLowerCase(),
            natural: isHydroLike
                ? (String(e?.natural || '').toLowerCase() || (['water', 'lake', 'reservoir'].includes(legacyType) ? 'water' : ''))
                : String(e?.natural || '').toLowerCase(),
            power: isPowerLike
                ? (String(e?.power || '').toLowerCase() || (legacyType === 'power' ? 'line' : legacyType))
                : String(e?.power || '').toLowerCase(),
            railway: isRailLike ? (String(e?.railway || '').toLowerCase() || legacyType) : String(e?.railway || '').toLowerCase(),
            man_made: (legacyType === 'bridge')
                ? (String(e?.man_made || '').toLowerCase() || 'bridge')
                : String(e?.man_made || '').toLowerCase()
        }, 'lin');
        if (f) out.push(f);
    }
    for (const e of poi) {
        const f = _poiFeatureFromTileNode({ ...e, sourceKind: 'poi', layer: 'poi' }, 'poi');
        if (f) out.push(f);
    }
    for (const e of infra) {
        const f = _poiFeatureFromTileNode({ ...e, sourceKind: 'infra', layer: 'infra', infra_enriched: true }, 'infra');
        if (f) out.push(f);
    }
    for (const e of infraClusters) {
        const f = _poiFeatureFromTileNode({ ...e, sourceKind: 'infra', layer: 'infra', infra_enriched: true, infra_cluster: true }, 'infra');
        if (f) out.push(f);
    }
    return out;
}

async function _poiReadTilePayload(url, res) {
    const isGz = String(url || '').toLowerCase().endsWith('.gz');
    if (!isGz) return await res.json();

    // Manche Hosts liefern *.json.gz ohne Content-Encoding-Header.
    // In dem Fall den Body explizit entpacken.
    const enc = String(res.headers.get('content-encoding') || '').toLowerCase();
    if (enc.includes('gzip')) return await res.json();

    if (typeof DecompressionStream !== 'undefined' && res.body) {
        const ds = new DecompressionStream('gzip');
        return await new Response(res.body.pipeThrough(ds)).json();
    }

    // Fallback (falls Browser kein DecompressionStream hat): normal versuchen.
    return await res.json();
}

function _poiFeatureMatchesCategory(feature, category) {
    const cat = String(category || '').toLowerCase();
    if (!cat || cat === 'all') return true;
    const t = feature?.tags || {};
    const rawType = String(feature?.rawType || '').toLowerCase();
    const n = normalizeMissionText(feature?.name || '');
    const infraType = String(t.infra_type || '').toLowerCase();
    const obstacleType = String(t.obstacle_type || '').toLowerCase();
    const energySource = String(
        t['plant:source'] ||
        t['generator:source'] ||
        t.plant_source ||
        t.generator_source ||
        t['plant:method'] ||
        t['generator:method'] ||
        t.plant_method ||
        t.generator_method ||
        t.source ||
        ''
    ).toLowerCase();
    const energyNameHint = (
        _hasWordToken(n, 'windpark') ||
        _hasWordToken(n, 'windkraft') ||
        _hasWordToken(n, 'windturbine') ||
        _hasWordToken(n, 'windrad') ||
        _hasWordToken(n, 'solarpark') ||
        _hasWordToken(n, 'solaranlage') ||
        _hasWordToken(n, 'photovoltaik') ||
        _hasWordToken(n, 'photovoltaic') ||
        _hasWordToken(n, 'pv')
    );
    const isEnergyPlant = (
        ['solar', 'wind', 'energy_plant', 'energy_storage', 'power_station', 'power_grid', 'industrial', 'power'].includes(infraType) ||
        (infraType === 'hydro' && (!!t.power || /(hydro|water)/.test(energySource))) ||
        ['plant', 'generator', 'storage'].includes(t.power) ||
        ['windmill', 'solar_panel'].includes(t.man_made) ||
        energyNameHint ||
        /(wind|solar|photovoltaic|photovoltaik|pv|battery|biogas|biomass|gas|geothermal)/.test(energySource)
    );
    const lockTagPositive = !!String(t.lock_tag || '').trim() && !/^(no|false|0)$/i.test(String(t.lock_tag || '').trim());
    const marineNameHint = (
        _hasWordToken(n, 'hafen') ||
        _hasWordToken(n, 'marina') ||
        _hasWordToken(n, 'sportboothafen') ||
        _hasWordToken(n, 'schleuse') ||
        _hasWordToken(n, 'anleger') ||
        _hasWordToken(n, 'anlegestelle') ||
        _hasWordToken(n, 'kai') ||
        _hasWordToken(n, 'pier') ||
        _hasWordToken(n, 'dock')
    );
    const isMarineInfra = (
        infraType === 'marine_infra' ||
        t.amenity === 'ferry_terminal' ||
        t.leisure === 'marina' ||
        ['pier', 'dock', 'quay', 'jetty'].includes(t.man_made) ||
        ['dock', 'lock_gate'].includes(t.waterway) ||
        lockTagPositive ||
        marineNameHint
    );
    const perimeterNameHint = (
        _hasWordToken(n, 'zaun') ||
        _hasWordToken(n, 'tor') ||
        _hasWordToken(n, 'zugang') ||
        _hasWordToken(n, 'perimeter') ||
        _hasWordToken(n, 'wildzaun') ||
        _hasWordToken(n, 'schutzzaun')
    );
    const isPerimeterSecurity = (
        infraType === 'perimeter_security' ||
        ['fence', 'gate'].includes(t.barrier) ||
        perimeterNameHint
    );
    const isNatureReserve = (
        t.leisure === 'nature_reserve' ||
        ['protected_area', 'national_park'].includes(t.boundary) ||
        _hasWordToken(n, 'naturschutzgebiet') ||
        _hasWordToken(n, 'schutzgebiet')
    );
    const isWildlifeArea = (
        t.tourism === 'zoo' ||
        t.leisure === 'wildlife_park' ||
        _hasWordToken(n, 'wildpark') ||
        _hasWordToken(n, 'wildgehege') ||
        _hasWordToken(n, 'tierpark')
    );

    const isWater = (
        ['river', 'stream', 'canal', 'dam', 'weir'].includes(t.waterway) ||
        t.natural === 'water' ||
        ['lake', 'reservoir', 'pond', 'basin'].includes(t.water) ||
        ['reservoir', 'basin'].includes(t.landuse) ||
        t.layer === 'hydro' ||
        infraType === 'hydro' ||
        isMarineInfra
    );
    const damNameStrong = (
        _hasWordToken(n, 'talsperre') ||
        _hasWordToken(n, 'staudamm') ||
        _hasWordToken(n, 'stausee') ||
        _hasWordToken(n, 'sperrmauer') ||
        _hasWordToken(n, 'reservoir')
    );
    const isDam = (
        ['dam', 'weir'].includes(t.waterway) ||
        t.landuse === 'reservoir' ||
        t.water === 'reservoir' ||
        (damNameStrong && !t.highway)
    );
    const isRoad = (
        !!t.highway ||
        t.layer === 'road' ||
        rawType === 'highway' ||
        infraType === 'road'
    );
    const isSettlementOnly = _poiIsSettlementOnlyFeature(feature);
    const isRail = (
        !!t.railway ||
        t.layer === 'rail' ||
        infraType === 'rail' ||
        rawType === 'railway' ||
        _hasWordToken(n, 'bahn') ||
        _hasWordToken(n, 'bahnhof') ||
        _hasWordToken(n, 'haltepunkt') ||
        _hasWordToken(n, 'stellwerk') ||
        _hasWordToken(n, 'weiche') ||
        _hasWordToken(n, 'bahnsignal') ||
        _hasWordToken(n, 'bahnuebergang') ||
        _hasWordToken(n, 'bahnübergang') ||
        _hasWordToken(n, 'bahnwaerterhaus') ||
        _hasWordToken(n, 'bahnwärterhaus') ||
        _hasWordToken(n, 'bahnwarterhaus') ||
        _hasWordToken(n, 'waerterhaus') ||
        _hasWordToken(n, 'wärterhaus') ||
        _hasWordToken(n, 'warterhaus') ||
        /bahnwarter|bahnwaerter|warterhaus|waerterhaus/.test(n) ||
        _hasWordToken(n, 'gleis') ||
        _hasWordToken(n, 'schiene') ||
        _hasWordToken(n, 'rail') ||
        _hasWordToken(n, 'railway')
    );
    const isTransportCorridor = (
        isRoad ||
        isRail ||
        infraType === 'power_grid' ||
        ['line', 'minor_line', 'cable'].includes(t.power) ||
        t.layer === 'road' ||
        t.layer === 'rail'
    );
    const isHumanMemorial = _poiIsHumanMemorialFeature(feature);
    const isTelecom = (
        !(
            t.highway === 'speed_camera' ||
            t.amenity === 'speed_camera' ||
            t.man_made === 'surveillance' ||
            ['signal', 'switch', 'level_crossing'].includes(t.railway)
        ) && (
        ['tower', 'mast', 'communications_tower'].includes(t.man_made) ||
        ['tower', 'pole'].includes(t.power) ||
        rawType.includes('mast') ||
        rawType.includes('tower') ||
        _hasWordToken(n, 'funkmast') ||
        _hasWordToken(n, 'sendemast') ||
        _hasWordToken(n, 'funkturm') ||
        _hasWordToken(n, 'fernsehturm') ||
        _hasWordToken(n, 'mobilfunk') ||
        _hasWordToken(n, 'telekom')
        )
    );
    const isBridge = (
        infraType === 'bridge' ||
        (!!t.bridge && t.bridge !== 'no') ||
        t.man_made === 'bridge' ||
        _hasWordToken(n, 'bruecke') ||
        _hasWordToken(n, 'brucke') ||
        _hasWordToken(n, 'bridge') ||
        _hasWordToken(n, 'viadukt')
    );
    const isMountain = (
        ['peak', 'valley', 'cliff', 'ridge', 'saddle', 'rock', 'cave_entrance', 'hill'].includes(t.natural) ||
        (
            !isTransportCorridor && (
                _hasWordToken(n, 'berg') ||
                _hasWordToken(n, 'gipfel') ||
                _hasWordToken(n, 'tal') ||
                _hasWordToken(n, 'schlucht') ||
                _hasWordToken(n, 'fels') ||
                _hasWordToken(n, 'felsen') ||
                _hasWordToken(n, 'klippe') ||
                _hasWordToken(n, 'klamm') ||
                _hasWordToken(n, 'hohle')
            )
        )
    );
    const isForest = (
        !isTransportCorridor && !isSettlementOnly && (
            t.natural === 'wood' ||
            t.landuse === 'forest' ||
            isNatureReserve ||
            isWildlifeArea ||
            _hasWordToken(n, 'wald') ||
            _hasWordToken(n, 'forst') ||
            _hasWordToken(n, 'forest')
        )
    );
    const isCastle = (
        ['castle', 'ruins', 'fort', 'monument'].includes(t.historic) ||
        (!isTransportCorridor && t.tourism === 'attraction' && (_hasWordToken(n, 'burg') || _hasWordToken(n, 'schloss'))) ||
        (!isTransportCorridor && (_hasWordToken(n, 'burg') || _hasWordToken(n, 'schloss')))
    );
    const isCity = ['city', 'town', 'village', 'suburb'].includes(t.place);
    const isIndustry = (
        ['industrial', 'quarry', 'brownfield', 'commercial', 'construction', 'depot', 'landfill', 'retail'].includes(t.landuse) ||
        ['industrial', 'solar', 'wind', 'energy_plant', 'energy_storage', 'power_station', 'power_grid', 'power', 'fuel', 'water_utility', 'water_tank', 'storage_tank', 'waste', 'quarry', 'pipeline'].includes(infraType) ||
        (infraType === 'hydro' && (!!t.power || /(hydro|water)/.test(energySource))) ||
        ['substation', 'plant', 'generator', 'storage', 'transformer'].includes(t.power) ||
        ['gasometer', 'pipeline', 'pumping_station', 'water_works', 'wastewater_plant', 'works', 'storage_tank', 'water_tower', 'silo', 'chimney'].includes(t.man_made) ||
        ['fuel', 'recycling', 'waste_disposal', 'wastewater_plant', 'waste_transfer_station', 'water_works'].includes(t.amenity) ||
        ['fuel', 'car_repair'].includes(t.shop) ||
        ['gas', 'heating', 'pipeline', 'sewerage', 'wastewater', 'water'].includes(t.utility) ||
        ['gas', 'hot_water', 'oil', 'sewage', 'steam', 'wastewater', 'water'].includes(t.substance) ||
        isEnergyPlant ||
        _hasWordToken(n, 'baustelle') ||
        _hasWordToken(n, 'tankstelle') ||
        _hasWordToken(n, 'pipeline') ||
        _hasWordToken(n, 'pumpwerk') ||
        _hasWordToken(n, 'recycling') ||
        _hasWordToken(n, 'deponie') ||
        _hasWordToken(n, 'steinbruch') ||
        _hasWordToken(n, 'umspannwerk') ||
        _hasWordToken(n, 'wasserwerk') ||
        _hasWordToken(n, 'klaerwerk') ||
        _hasWordToken(n, 'klärwerk') ||
        _hasWordToken(n, 'kraftwerk') ||
        _hasWordToken(n, 'heizkraftwerk') ||
        _hasWordToken(n, 'industrie') ||
        _hasWordToken(n, 'werk') ||
        _hasWordToken(n, 'fabrik') ||
        _hasWordToken(n, 'anlage')
    );
    const isInfrastructure = (
        isRoad ||
        isRail ||
        isTelecom ||
        isIndustry ||
        isBridge ||
        isMarineInfra ||
        isPerimeterSecurity ||
        !!infraType ||
        ['line', 'minor_line', 'cable'].includes(t.power) ||
        _hasWordToken(n, 'strom') ||
        _hasWordToken(n, 'hochspannung') ||
        _hasWordToken(n, 'freileitung')
    );
    const isFire = (
        !isHumanMemorial && (
            isMountain ||
            (!isTransportCorridor && (_hasWordToken(n, 'wald') || _hasWordToken(n, 'forst'))) ||
            t.natural === 'wood' ||
            t.natural === 'heath'
        )
    );

    if (cat === 'water') return isWater;
    if (cat === 'dam') return isDam;
    if (cat === 'road') return isRoad && !isSettlementOnly;
    if (cat === 'rail') return isRail;
    if (cat === 'telecom') return isTelecom;
    if (cat === 'bridge') return isBridge;
    if (cat === 'mountain') return isMountain;
    if (cat === 'forest') return isForest;
    if (cat === 'castle') return isCastle;
    if (cat === 'city') return isCity;
    if (cat === 'industry') return isIndustry;
    if (cat === 'infrastructure') return isInfrastructure && !isSettlementOnly;
    if (cat === 'sar_corridor') return (isRoad || isRail || isBridge || isWater || isInfrastructure);
    if (cat === 'fire') return isFire;
    return false;
}

function _poiInferCategoryFromFeature(feature) {
    const t = feature?.tags || {};
    const infraType = String(t.infra_type || '').toLowerCase();
    if (infraType === 'bridge') return 'bridge';
    if (infraType === 'road') return 'road';
    if (infraType === 'rail' || infraType === 'power_grid' || infraType === 'power') return 'infrastructure';
    if ([
        'construction', 'energy_plant', 'energy_storage', 'pipeline',
        'public_building', 'fuel', 'water_utility', 'water_tank',
        'storage_tank', 'waste', 'quarry', 'flood_protection',
        'traffic_protection', 'telecom', 'marine_infra', 'perimeter_security'
    ].includes(infraType)) return 'infrastructure';
    if (infraType === 'hydro') {
        const energySource = String(t.generator_source || t.plant_source || t.generator_method || t.plant_method || '').toLowerCase();
        if (t.power || /(hydro|water)/.test(energySource)) return 'industry';
        if (['dam', 'weir'].includes(String(t.waterway || '').toLowerCase())) return 'dam';
        return 'water';
    }
    if (['solar', 'wind', 'power_station', 'industrial'].includes(infraType)) return 'industry';
    const placeKind = String(t.place || '').toLowerCase();
    const placeOnly = (
        ['city', 'town', 'village', 'suburb', 'hamlet', 'locality', 'neighbourhood', 'quarter'].includes(placeKind) &&
        !t.highway &&
        !t.railway &&
        !t.waterway &&
        !t.water &&
        t.natural !== 'water' &&
        !['reservoir', 'basin'].includes(String(t.landuse || '').toLowerCase()) &&
        !t.power &&
        !t.man_made
    );
    if (placeOnly) return 'city';
    if (_poiIsSettlementOnlyFeature(feature)) return 'city';
    const order = ['dam', 'water', 'telecom', 'bridge', 'road', 'castle', 'mountain', 'forest', 'industry', 'city', 'infrastructure', 'fire'];
    for (const cat of order) {
        if (_poiFeatureMatchesCategory(feature, cat)) return cat;
    }
    return classifyPOITitleCategory(feature?.name || '');
}

function _poiLooksTechnicalCodeName(name) {
    const s = String(name || '').trim();
    if (!s) return false;
    if (_poiIsCodeLikeName(s) || _poiIsNumericLikeName(s)) return true;
    const compact = s.replace(/\s+/g, '');
    if (compact.length >= 8 && /[0-9]/.test(compact) && /[A-Z]/i.test(compact) && /[;:_/-]/.test(compact)) return true;
    if (/^[A-Z0-9;:_/-]{8,}$/i.test(compact) && (compact.match(/\d/g) || []).length >= 3) return true;
    return false;
}

function _poiRoadInspectionValue(tags = {}, name = '') {
    const t = tags || {};
    const highway = String(t.highway || '').toLowerCase();
    const ref = String(t.ref || '').trim();
    const n = normalizeMissionText(name || '');
    if (['motorway', 'motorway_link', 'trunk', 'trunk_link', 'primary', 'primary_link', 'secondary', 'secondary_link'].includes(highway)) return 'high';
    if (/^(A|B|L|K)\s?\d{1,4}\b/i.test(ref) || /\b(?:autobahn|bundesstrasse|bundesstraße|landesstrasse|landesstraße|kreisstrasse|kreisstraße)\b/i.test(String(name || ''))) return 'high';
    if (t.bridge && t.bridge !== 'no') return 'high';
    if (['tunnel', 'viaduct', 'bridge'].includes(String(t.man_made || '').toLowerCase())) return 'high';
    if (_hasWordToken(n, 'bruecke') || _hasWordToken(n, 'brucke') || _hasWordToken(n, 'viadukt') || _hasWordToken(n, 'tunnel') || _hasWordToken(n, 'kreuz') || _hasWordToken(n, 'dreieck')) return 'high';
    if (['tertiary', 'tertiary_link'].includes(highway)) return 'medium';
    if (['residential', 'service', 'track', 'path', 'footway', 'cycleway', 'living_street', 'unclassified'].includes(highway)) return 'low';
    return highway ? 'medium' : 'low';
}

function _poiCandidateInfraSubtype(candidate = {}) {
    const tags = candidate?.tags || {};
    const n = normalizeMissionText(candidate?.n || candidate?.name || '');
    const infraType = String(tags.infra_type || '').toLowerCase();
    const clusterType = String(tags.cluster_type || '').toLowerCase();
    const power = String(tags.power || '').toLowerCase();
    const energy = String(tags.generator_source || tags.plant_source || tags.generator_method || tags.plant_method || '').toLowerCase();
    if ([
        'solar', 'wind', 'hydro', 'power_grid', 'power_station',
        'energy_plant', 'energy_storage', 'industrial', 'construction',
        'pipeline', 'public_building', 'fuel', 'water_utility', 'water_tank',
        'storage_tank', 'waste', 'quarry', 'flood_protection',
        'traffic_protection', 'telecom', 'marine_infra', 'perimeter_security'
    ].includes(clusterType)) return clusterType;
    const lockTagPositive = !!String(tags.lock_tag || '').trim() && !/^(no|false|0)$/i.test(String(tags.lock_tag || '').trim());
    if (
        infraType === 'marine_infra' ||
        clusterType === 'marine_infra' ||
        String(tags.amenity || '').toLowerCase() === 'ferry_terminal' ||
        String(tags.leisure || '').toLowerCase() === 'marina' ||
        ['pier', 'dock', 'quay', 'jetty'].includes(String(tags.man_made || '').toLowerCase()) ||
        ['dock', 'lock_gate'].includes(String(tags.waterway || '').toLowerCase()) ||
        lockTagPositive ||
        _hasWordToken(n, 'hafen') ||
        _hasWordToken(n, 'marina') ||
        _hasWordToken(n, 'sportboothafen') ||
        _hasWordToken(n, 'schleuse') ||
        _hasWordToken(n, 'anleger') ||
        _hasWordToken(n, 'anlegestelle') ||
        _hasWordToken(n, 'kai') ||
        _hasWordToken(n, 'pier') ||
        _hasWordToken(n, 'dock')
    ) return 'marine_infra';
    if (
        infraType === 'perimeter_security' ||
        clusterType === 'perimeter_security' ||
        ['fence', 'gate'].includes(String(tags.barrier || '').toLowerCase()) ||
        _hasWordToken(n, 'zaun') ||
        _hasWordToken(n, 'tor') ||
        _hasWordToken(n, 'perimeter') ||
        _hasWordToken(n, 'wildzaun') ||
        _hasWordToken(n, 'schutzzaun')
    ) return 'perimeter_security';
    if (infraType === 'solar' || energy.includes('solar') || _hasWordToken(n, 'solarpark') || _hasWordToken(n, 'photovoltaik') || _hasWordToken(n, 'pv')) return 'solar';
    if (infraType === 'wind' || energy.includes('wind') || _hasWordToken(n, 'windpark') || _hasWordToken(n, 'windkraft') || _hasWordToken(n, 'windrad')) return 'wind';
    if (infraType === 'energy_storage' || power === 'storage' || /(battery|storage)/.test(energy)) return 'energy_storage';
    if (infraType === 'hydro' || /(hydro|water)/.test(energy) || ['dam', 'weir'].includes(String(tags.waterway || '').toLowerCase())) return 'hydro';
    if (infraType === 'energy_plant' || ['plant', 'generator'].includes(power) || /(biogas|biomass|gas|geothermal|oil)/.test(energy)) return 'energy_plant';
    const railway = String(tags.railway || '').toLowerCase();
    if (infraType === 'rail' || railway || candidate.category === 'rail') {
        if (['station', 'halt'].includes(railway) || _hasWordToken(n, 'bahnhof') || _hasWordToken(n, 'haltepunkt')) return 'rail_station';
        if (railway === 'signal_box' || _hasWordToken(n, 'stellwerk') || _hasWordToken(n, 'bahnwaerterhaus') || _hasWordToken(n, 'bahnwärterhaus') || _hasWordToken(n, 'bahnwarterhaus') || _hasWordToken(n, 'waerterhaus') || _hasWordToken(n, 'wärterhaus') || _hasWordToken(n, 'warterhaus') || /bahnwarter|bahnwaerter|warterhaus|waerterhaus/.test(n)) return 'rail_control';
        if (railway === 'switch' || _hasWordToken(n, 'weiche')) return 'rail_switch';
        if (['level_crossing', 'crossing'].includes(railway) || _hasWordToken(n, 'bahnuebergang') || _hasWordToken(n, 'bahnübergang')) return 'rail_crossing';
        if (railway === 'signal' || _hasWordToken(n, 'signal')) return 'rail_signal';
        if (['rail', 'light_rail', 'subway', 'tram', 'narrow_gauge'].includes(railway)) return 'rail_track';
        return 'rail';
    }
    if (infraType === 'bridge' || candidate.category === 'bridge' || tags.bridge === 'yes') return 'bridge';
    if (infraType === 'road' || candidate.category === 'road' || tags.highway) {
        const value = _poiRoadInspectionValue(tags, candidate?.n || candidate?.name || '');
        return value === 'high' ? 'road_major' : (value === 'medium' ? 'road_regional' : 'road_minor');
    }
    if (infraType === 'construction' || String(tags.landuse || '').toLowerCase() === 'construction' || tags.construction) return 'construction';
    if (infraType === 'fuel' || String(tags.amenity || '').toLowerCase() === 'fuel') return 'fuel';
    if (infraType === 'pipeline' || tags.pipeline || String(tags.man_made || '').toLowerCase() === 'pipeline' || ['gas', 'heating', 'pipeline'].includes(String(tags.utility || '').toLowerCase())) return 'pipeline';
    if (
        infraType === 'water_utility' ||
        String(tags.man_made || '').toLowerCase() === 'pumping_station' ||
        ['water_works', 'wastewater_plant'].includes(String(tags.amenity || '').toLowerCase()) ||
        ['water', 'sewerage', 'wastewater'].includes(String(tags.utility || '').toLowerCase()) ||
        String(tags.waterway || '').toLowerCase() === 'lock_gate' ||
        lockTagPositive ||
        tags.monitoring_water_level
    ) return 'water_utility';
    if (infraType === 'water_tank' || String(tags.man_made || '').toLowerCase() === 'water_tower') return 'water_tank';
    if (infraType === 'storage_tank' || String(tags.man_made || '').toLowerCase() === 'storage_tank') return 'storage_tank';
    if (infraType === 'waste' || String(tags.landuse || '').toLowerCase() === 'landfill' || ['recycling', 'waste_disposal', 'waste_transfer_station'].includes(String(tags.amenity || '').toLowerCase())) return 'waste';
    if (infraType === 'quarry' || String(tags.landuse || '').toLowerCase() === 'quarry') return 'quarry';
    if (infraType === 'flood_protection' || ['dyke', 'embankment'].includes(String(tags.man_made || '').toLowerCase()) || tags.embankment) return 'flood_protection';
    if (infraType === 'traffic_protection' || tags.tunnel || ['noise_barrier', 'retaining_wall'].includes(String(tags.barrier || '').toLowerCase())) return 'traffic_protection';
    if (
        infraType === 'public_building' ||
        ['civic', 'hospital', 'public', 'school', 'train_station', 'transportation', 'university'].includes(String(tags.building || '').toLowerCase()) ||
        ['clinic', 'college', 'community_centre', 'courthouse', 'fire_station', 'hospital', 'kindergarten', 'police', 'post_office', 'school', 'townhall', 'university'].includes(String(tags.amenity || '').toLowerCase()) ||
        tags.healthcare ||
        String(tags.office || '').toLowerCase() === 'government'
    ) return 'public_building';
    if (infraType === 'power_grid' || ['line', 'minor_line', 'cable', 'tower', 'pole'].includes(power)) return 'power_grid';
    if (infraType === 'power_station' || ['substation', 'transformer', 'switchgear', 'converter', 'compensator'].includes(power) || tags.substation || tags.transformer) return 'power_station';
    if (infraType === 'industrial' || String(tags.landuse || '').toLowerCase() === 'industrial') return 'industrial';
    if (candidate.category === 'telecom' || ['tower', 'mast', 'communications_tower'].includes(String(tags.man_made || '').toLowerCase())) return 'telecom';
    return infraType || candidate.category || 'infra';
}

function _poiInfraSubtypeHasOwnPickerCategory(subtype = '') {
    const s = String(subtype || '').toLowerCase();
    return (
        s === 'bridge' ||
        s === 'telecom' ||
        s === 'solar' ||
        s === 'wind' ||
        s === 'road' ||
        s.startsWith('road_') ||
        s.startsWith('rail_') ||
        s === 'rail'
    );
}

function _poiCandidateIsRoadInspectionTarget(candidate = {}) {
    const subtype = _poiCandidateInfraSubtype(candidate);
    return (
        subtype === 'road_major' ||
        subtype === 'road_regional' ||
        subtype === 'road' ||
        subtype === 'traffic_protection' ||
        (subtype === 'road_minor' && !!candidate?.hasName)
    );
}

function _poiCandidateIsRailInspectionTarget(candidate = {}) {
    const subtype = _poiCandidateInfraSubtype(candidate);
    const tags = candidate?.tags || {};
    const infraType = String(tags.infra_type || '').toLowerCase();
    return (
        infraType === 'rail' ||
        subtype === 'rail_track' ||
        subtype === 'rail_station' ||
        subtype === 'rail_control' ||
        subtype === 'rail_switch' ||
        subtype === 'rail_crossing' ||
        subtype === 'rail_signal' ||
        subtype === 'rail'
    );
}

function _poiFeatureScore(feature, category) {
    const cat = String(category || 'all').toLowerCase();
    const t = feature?.tags || {};
    const n = normalizeMissionText(feature?.name || '');
    const infraType = String(t.infra_type || '').toLowerCase();
    let score = 0;
    if (cat === 'dam') {
        if (['dam', 'weir'].includes(t.waterway)) score += 8;
        if (t.water === 'reservoir') score += 6;
        if (t.landuse === 'reservoir') score += 5;
        if (_hasWordToken(n, 'talsperre') || _hasWordToken(n, 'staudamm') || _hasWordToken(n, 'stausee') || _hasWordToken(n, 'sperrmauer') || _hasWordToken(n, 'reservoir')) score += 8;
    } else if (cat === 'water') {
        if (['dam', 'weir'].includes(t.waterway)) score += 8;
        if (['lake', 'reservoir', 'pond'].includes(t.water)) score += 9;
        if (['reservoir', 'basin'].includes(t.landuse)) score += 6;
        if (t.natural === 'water') score += 7;
        if (['river', 'stream', 'canal'].includes(t.waterway)) score += 4;
        if (_hasWordToken(n, 'see') || _hasWordToken(n, 'weiher') || _hasWordToken(n, 'teich') || _hasWordToken(n, 'talsperre') || _hasWordToken(n, 'stausee')) score += 6;
        if (_hasWordToken(n, 'karsee') || _hasWordToken(n, 'stausee') || _hasWordToken(n, 'talsperre')) score += 4;
        if (['fire_water_pond', 'suction_point'].includes(String(t.water || '').toLowerCase())) score -= 7;
        if (_hasWordToken(n, 'loeschwasser') || _hasWordToken(n, 'löschwasser')) score -= 5;
        if (!n && t.water === 'pond') score -= 3;
        if (!n && ['reservoir', 'basin'].includes(t.landuse)) score -= 2;
    } else if (cat === 'road') {
        const major = ['motorway', 'motorway_link', 'trunk', 'trunk_link', 'primary', 'primary_link', 'secondary', 'secondary_link'];
        const roadValue = _poiRoadInspectionValue(t, feature?.name || '');
        if (infraType === 'road') score += 10;
        if (major.includes(t.highway)) score += 6;
        if (t.highway) score += 2;
        if (roadValue === 'high') score += 6;
        else if (roadValue === 'medium') score += 2;
        else if (roadValue === 'low') score -= 8;
        if (infraType === 'bridge' || (t.bridge && t.bridge !== 'no')) score -= 12;
        if (t.highway === 'motorway_junction') score -= 5;
        if (_hasWordToken(n, 'stadt') || _hasWordToken(n, 'zentrum') || _hasWordToken(n, 'city')) score -= 4;
        if (String(n || '').includes(' / ')) score -= 3;
    } else if (cat === 'rail') {
        const railTag = String(t.railway || '').toLowerCase();
        const majorRail = ['rail', 'light_rail', 'subway', 'tram', 'narrow_gauge'];
        const facilityRail = ['station', 'halt', 'signal_box', 'switch', 'signal', 'level_crossing', 'crossing', 'junction'];
        if (infraType === 'rail') score += 8;
        if (majorRail.includes(railTag)) score += 7;
        if (facilityRail.includes(railTag)) score += 8;
        if (t.railway) score += 3;
        if (_hasWordToken(n, 'bahnhof') || _hasWordToken(n, 'haltepunkt')) score += 8;
        if (_hasWordToken(n, 'stellwerk') || _hasWordToken(n, 'bahnwaerterhaus') || _hasWordToken(n, 'bahnwärterhaus') || _hasWordToken(n, 'bahnwarterhaus') || _hasWordToken(n, 'warterhaus') || /bahnwarter|bahnwaerter|warterhaus|waerterhaus/.test(n)) score += 8;
        if (_hasWordToken(n, 'weiche') || _hasWordToken(n, 'signal') || _hasWordToken(n, 'bahnuebergang') || _hasWordToken(n, 'bahnübergang')) score += 6;
        if (!n && ['signal', 'switch', 'level_crossing', 'crossing'].includes(railTag)) score -= 1;
    } else if (cat === 'telecom') {
        if (['tower', 'mast'].includes(t.man_made)) score += 7;
        if (t.power === 'tower') score += 4;
        if (t.power === 'pole') score -= 3;
        if (_hasWordToken(n, 'funkmast') || _hasWordToken(n, 'sendemast') || _hasWordToken(n, 'funkturm') || _hasWordToken(n, 'fernsehturm') || _hasWordToken(n, 'mobilfunk')) score += 8;
        if (infraType === 'wind' || String(t.obstacle_type || '').includes('wind') || String(feature?.rawType || '').toLowerCase().includes('wind')) score -= 10;
    } else if (cat === 'infrastructure') {
        const energySourceScore = String(t.generator_source || t.plant_source || t.generator_method || t.plant_method || '').toLowerCase();
        const majorRoad = ['motorway', 'motorway_link', 'trunk', 'trunk_link', 'primary', 'primary_link', 'secondary', 'secondary_link'];
        const majorRail = ['rail', 'light_rail', 'subway', 'tram', 'narrow_gauge'];
        const facilityRail = ['station', 'halt', 'signal_box', 'switch', 'signal', 'level_crossing', 'crossing', 'junction'];
        if (infraType) score += 4;
        if (['power_grid', 'power'].includes(infraType)) score += 6;
        if (['road', 'bridge', 'rail', 'telecom'].includes(infraType)) score -= 3;
        if (['solar', 'wind', 'energy_plant', 'energy_storage', 'power_station', 'industrial'].includes(infraType)) score += 3;
        if (['construction', 'fuel', 'pipeline', 'water_utility', 'water_tank', 'storage_tank', 'waste', 'quarry', 'flood_protection', 'traffic_protection', 'marine_infra', 'perimeter_security'].includes(infraType)) score += 6;
        if (['public_building', 'telecom'].includes(infraType)) score += 4;
        if (infraType === 'hydro') score += 2;
        if (t.infra_cluster) score += 4;
        if (Number(t.cluster_count || 0) >= 3) score += Math.min(4, Math.log2(Number(t.cluster_count || 1)));
        if (majorRoad.includes(t.highway)) score += 6;
        if (t.highway) score += 2;
        if (majorRail.includes(t.railway)) score += 7;
        if (facilityRail.includes(String(t.railway || '').toLowerCase())) score += 6;
        if (t.railway) score += 3;
        if (['line', 'minor_line', 'cable'].includes(t.power)) score += 5;
        if (['tower', 'pole'].includes(t.power)) score += 4;
        if (['substation', 'plant', 'generator', 'storage', 'transformer'].includes(t.power)) score += 5;
        if (infraType === 'rail') score += 3;
        if (infraType === 'power_grid') score += 3;
        if (infraType === 'solar') score -= 2;
        if (infraType === 'solar_roof') score -= 10;
        if (/(solar|photovoltaic|photovoltaik|wind|hydro|water|battery|biomass|biogas|gas|geothermal|storage)/.test(energySourceScore)) score += 6;
        if (String(t.landuse || '').toLowerCase() === 'construction' || t.construction) score += 6;
        if (['landfill', 'quarry'].includes(String(t.landuse || '').toLowerCase())) score += 6;
        if (String(t.amenity || '').toLowerCase() === 'fuel') score += 5;
        if (['ferry_terminal', 'recycling', 'waste_disposal', 'waste_transfer_station', 'water_works', 'wastewater_plant'].includes(String(t.amenity || '').toLowerCase())) score += 5;
        if (['clinic', 'college', 'courthouse', 'fire_station', 'hospital', 'police', 'post_office', 'school', 'townhall', 'university'].includes(String(t.amenity || '').toLowerCase())) score += 3;
        if (['dyke', 'embankment', 'gasometer', 'pipeline', 'pumping_station', 'water_tower', 'storage_tank'].includes(String(t.man_made || '').toLowerCase())) score += 5;
        if (['fence', 'gate', 'noise_barrier', 'retaining_wall'].includes(String(t.barrier || '').toLowerCase())) score += 4;
        if (String(t.leisure || '').toLowerCase() === 'marina') score += 5;
        if (['dock', 'lock_gate'].includes(String(t.waterway || '').toLowerCase())) score += 5;
        if (['pier', 'dock', 'quay', 'jetty'].includes(String(t.man_made || '').toLowerCase())) score += 5;
        if (t.tunnel || t.pipeline || t.monitoring_water_level || t.lock_tag || t.embankment) score += 4;
        if (['gas', 'heating', 'pipeline', 'sewerage', 'wastewater', 'water'].includes(String(t.utility || '').toLowerCase())) score += 4;
        if (t.substation || t.transformer) score += 5;
        if (['tower', 'mast', 'communications_tower', 'bridge'].includes(t.man_made)) score += 4;
        if (!_hasWordToken(n, 'anlage') && !_hasWordToken(n, 'mast') && !_hasWordToken(n, 'werk') && !_hasWordToken(n, 'umspannwerk') && !_hasWordToken(n, 'bahn') && !_hasWordToken(n, 'leitung') && !_hasWordToken(n, 'trasse') && !_hasWordToken(n, 'baustelle') && !_hasWordToken(n, 'dach') && !_hasWordToken(n, 'pv') && !_hasWordToken(n, 'solar') && !_hasWordToken(n, 'tank') && !_hasWordToken(n, 'tankstelle') && !_hasWordToken(n, 'gebaeude') && !_hasWordToken(n, 'gebäude') && !_hasWordToken(n, 'pipeline') && !_hasWordToken(n, 'pump') && !_hasWordToken(n, 'deich') && !_hasWordToken(n, 'tunnel') && !_hasWordToken(n, 'recycling') && !_hasWordToken(n, 'deponie') && !_hasWordToken(n, 'steinbruch') && !_hasWordToken(n, 'hafen') && !_hasWordToken(n, 'schleuse') && !_hasWordToken(n, 'anleger') && !_hasWordToken(n, 'zaun') && !_hasWordToken(n, 'tor')) score -= 2;
    } else if (cat === 'mountain') {
        if (['peak', 'valley', 'cliff', 'ridge', 'saddle', 'rock', 'cave_entrance', 'hill'].includes(t.natural)) score += 6;
        if (_hasWordToken(n, 'fels') || _hasWordToken(n, 'felsen') || _hasWordToken(n, 'klippe') || _hasWordToken(n, 'klamm') || _hasWordToken(n, 'hohle')) score += 5;
    } else if (cat === 'forest') {
        if (t.natural === 'wood') score += 9;
        if (t.landuse === 'forest') score += 9;
        if (String(t.leisure || '').toLowerCase() === 'nature_reserve') score += 8;
        if (['protected_area', 'national_park'].includes(String(t.boundary || '').toLowerCase())) score += 8;
        if (String(t.tourism || '').toLowerCase() === 'zoo') score += 4;
        if (_hasWordToken(n, 'wald')) score += 6;
        if (_hasWordToken(n, 'forst')) score += 5;
        if (_hasWordToken(n, 'naturschutzgebiet') || _hasWordToken(n, 'schutzgebiet') || _hasWordToken(n, 'wildpark') || _hasWordToken(n, 'wildgehege')) score += 7;
        if (_poiIsHumanMemorialFeature(feature)) score -= 12;
        if (['city', 'town', 'suburb', 'neighbourhood', 'quarter'].includes(String(t.place || '').toLowerCase())) score -= 6;
    } else if (cat === 'castle') {
        if (['castle', 'ruins', 'fort', 'monument'].includes(t.historic)) score += 7;
    } else if (cat === 'industry') {
        const energySourceScore = String(t.generator_source || t.plant_source || t.generator_method || t.plant_method || '').toLowerCase();
        if (['solar', 'wind', 'energy_plant', 'energy_storage', 'power_station', 'industrial', 'fuel', 'water_utility', 'water_tank', 'storage_tank', 'waste', 'quarry', 'pipeline'].includes(infraType)) score += 9;
        if (infraType === 'wind') score += 3;
        if (infraType === 'solar' && !_hasWordToken(n, 'solarpark') && !_hasWordToken(n, 'photovoltaik')) score -= 2;
        if (infraType === 'solar_roof') score -= 10;
        if (infraType === 'hydro' && (t.power || /(hydro|water)/.test(energySourceScore))) score += 7;
        if (infraType === 'power_grid') score += 5;
        if (['industrial', 'quarry', 'brownfield', 'commercial', 'construction', 'depot', 'landfill', 'retail'].includes(t.landuse)) score += 6;
        if (['substation', 'plant', 'generator', 'storage', 'transformer'].includes(t.power)) score += 8;
        if (/(solar|photovoltaic|photovoltaik|wind|hydro|water|battery|biomass|biogas|gas|geothermal|storage)/.test(energySourceScore)) score += 7;
        if (t.substation || t.transformer) score += 5;
        if (['gasometer', 'pipeline', 'pumping_station', 'water_works', 'wastewater_plant', 'works', 'storage_tank', 'water_tower', 'silo', 'chimney'].includes(t.man_made)) score += 7;
        if (['fuel', 'recycling', 'waste_disposal', 'wastewater_plant', 'waste_transfer_station', 'water_works'].includes(t.amenity)) score += 7;
        if (['fuel', 'car_repair'].includes(t.shop)) score += 5;
    } else if (cat === 'fire') {
        if (t.natural === 'wood' || t.landuse === 'forest') score += 10;
        if (['heath', 'scrub'].includes(t.natural)) score += 6;
        if (['peak', 'valley', 'cliff', 'ridge'].includes(t.natural)) score += 5;
        if (_hasWordToken(n, 'wald')) score += 5;
        if (_hasWordToken(n, 'forst')) score += 3;
        if (_poiIsHumanMemorialFeature(feature)) score -= 14;
        if (['city', 'town', 'suburb', 'neighbourhood', 'quarter'].includes(String(t.place || '').toLowerCase())) score -= 6;
    }
    if (n) score += 1;
    if (!n && cat === 'infrastructure') score -= 4;
    if (feature?.sourceKind === 'poi') score += 2;
    if (feature?.sourceKind === 'infra' && ['infrastructure', 'industry', 'bridge', 'road', 'rail', 'telecom', 'dam'].includes(cat)) score += 4;
    if (feature?.sourceKind === 'obs') score -= 1;
    return score;
}

function _poiSightseeingInterestScore(item = {}, category = '') {
    const t = item?.tags || {};
    const cat = String(category || item?.category || 'generic').toLowerCase();
    const name = String(item?.n || item?.name || '').trim();
    const n = normalizeMissionText(name);
    const hasUsefulName = !!name && !_poiIsGenericFallbackName(name) && !_poiIsCodeLikeName(name) && !_poiIsNumericLikeName(name);
    const tourism = String(t.tourism || '').toLowerCase();
    const historic = String(t.historic || '').toLowerCase();
    const natural = String(t.natural || '').toLowerCase();
    const manMade = String(t.man_made || '').toLowerCase();
    const railway = String(t.railway || '').toLowerCase();
    const infraType = String(t.infra_type || '').toLowerCase();
    const waterway = String(t.waterway || '').toLowerCase();
    const bridge = String(t.bridge || '').toLowerCase();
    let score = hasUsefulName ? 3 : -4;

    if (tourism === 'viewpoint') score += 14;
    if (tourism === 'attraction') score += 12;
    if (['museum', 'theme_park', 'zoo', 'aquarium'].includes(tourism)) score += 5;
    if (['castle', 'ruins', 'fort', 'monument', 'memorial', 'archaeological_site'].includes(historic)) score += 10;
    if (['peak', 'cliff', 'rock', 'cave_entrance', 'ridge', 'saddle'].includes(natural)) score += 10;
    if (natural === 'hill' || natural === 'valley') score += 5;
    if ((bridge && !/^(no|false|0)$/i.test(bridge)) || manMade === 'bridge' || infraType === 'bridge') score += 9;
    if (waterway === 'dam' || manMade === 'dam' || t.water === 'reservoir' || t.landuse === 'reservoir') score += 8;
    if (['lighthouse', 'tower', 'water_tower'].includes(manMade)) score += 8;
    if (['station', 'halt', 'signal_box'].includes(railway)) score += hasUsefulName ? 8 : 2;
    if (railway === 'narrow_gauge') score += 5;
    if (railway === 'rail' && hasUsefulName) score += 2;

    if (_hasWordToken(n, 'aussicht') || _hasWordToken(n, 'blick') || _hasWordToken(n, 'panorama')) score += 9;
    if (_hasWordToken(n, 'fels') || _hasWordToken(n, 'felsen') || _hasWordToken(n, 'klippe') || _hasWordToken(n, 'klamm') || _hasWordToken(n, 'schlucht') || _hasWordToken(n, 'hohle')) score += 9;
    if (_hasWordToken(n, 'bahnwaerterhaus') || _hasWordToken(n, 'bahnwarterhaus') || _hasWordToken(n, 'waerterhaus') || _hasWordToken(n, 'warterhaus') || _hasWordToken(n, 'stellwerk') || /bahnwarter|bahnwaerter|warterhaus|waerterhaus/.test(n)) score += 11;
    if (_hasWordToken(n, 'bahnhof') || _hasWordToken(n, 'haltepunkt') || _hasWordToken(n, 'viadukt')) score += 7;
    if (_hasWordToken(n, 'bruecke') || _hasWordToken(n, 'brucke') || _hasWordToken(n, 'bridge')) score += 5;
    if (_hasWordToken(n, 'talsperre') || _hasWordToken(n, 'stausee') || _hasWordToken(n, 'staudamm') || _hasWordToken(n, 'sperrmauer')) score += 7;
    if (_hasWordToken(n, 'ruine') || _hasWordToken(n, 'denkmal') || _hasWordToken(n, 'monument')) score += 6;

    if (cat === 'castle') score += 4;
    if (cat === 'mountain') score += 3;
    if (cat === 'bridge' || cat === 'dam') score += 2;
    if (cat === 'rail') score += 1;
    if (cat === 'water' && (hasUsefulName || t.water === 'reservoir' || t.water === 'lake')) score += 1;
    if (cat === 'city' && hasUsefulName) score += 1;

    if (_poiLooksJunctionLabel(name) || _poiLooksTechnicalCodeName(name)) score -= 12;
    if (String(t.highway || '').toLowerCase() === 'motorway_junction') score -= 9;
    if (['signal', 'switch', 'level_crossing', 'crossing'].includes(railway) && !hasUsefulName) score -= 10;
    if (['power_grid', 'power', 'power_station', 'solar_roof', 'solar'].includes(infraType)) score -= 8;
    if (['line', 'minor_line', 'cable', 'tower', 'pole'].includes(String(t.power || '').toLowerCase()) && !/fernsehturm|funkturm|aussicht/.test(n)) score -= 7;
    if (_poiIsGenericFallbackName(name)) score -= 9;
    return score;
}

function _poiSightseeingRequiresInterestCategory(category = '') {
    return ['bridge', 'dam', 'rail', 'road', 'telecom', 'industry', 'infrastructure'].includes(String(category || '').toLowerCase());
}

function _poiFeatureLooksSightseeingAttraction(feature = null) {
    if (!feature || typeof feature !== 'object') return false;
    const t = feature.tags || {};
    const rawName = String(feature.name || t.name || '').trim();
    const n = normalizeMissionText(rawName);
    const tourism = String(t.tourism || '').toLowerCase();
    const historic = String(t.historic || '').toLowerCase();
    const manMade = String(t.man_made || '').toLowerCase();
    if (tourism === 'viewpoint') return true;
    if (rawName && ['attraction', 'museum', 'theme_park', 'zoo', 'aquarium'].includes(tourism)) return true;
    if (rawName && ['castle', 'ruins', 'fort', 'monument', 'memorial', 'archaeological_site'].includes(historic)) return true;
    if (rawName && ['lighthouse', 'tower', 'water_tower'].includes(manMade)) return true;
    return !!(rawName && (
        _hasWordToken(n, 'aussicht') ||
        _hasWordToken(n, 'panorama') ||
        _hasWordToken(n, 'denkmal') ||
        _hasWordToken(n, 'ruine') ||
        _hasWordToken(n, 'museum') ||
        _hasWordToken(n, 'turm')
    ));
}

async function _poiFetchTileFeatures(tileKey, options = null) {
    const includeCore = !!(options && options.includeCore);
    const includeInfra = !!(options && options.includeInfra);
    const allowLegacyFallback = options && Object.prototype.hasOwnProperty.call(options, 'allowLegacyFallback')
        ? !!options.allowLegacyFallback
        : true;
    const now = Date.now();
    const dbg = _poiDebugState();
    const cacheKey = `${tileKey}|${includeCore ? '1' : '0'}|${includeInfra ? '1' : '0'}`;
    const cached = _poiTileMemCache.get(cacheKey);
    if (cached && (now - Number(cached.ts || 0)) <= POI_TILE_CACHE_TTL_MS && Array.isArray(cached.features)) {
        dbg.hits = Number(dbg.hits || 0) + 1;
        dbg.cacheHits = Number(dbg.cacheHits || 0) + 1;
        _poiDebugMarkSource(`cache:${String(cached.source || 'unknown')}`);
        return cached.features;
    }
    const b = _poiTileBoundsFromKey(tileKey);
    if (!b) return [];
    let mergedFeatures = [];
    let tileSourceTag = '';
    // 1) Prefer dedicated split POI tiles.
    for (const endpoint of POI_TILE_POI_ENDPOINTS) {
        try {
            let url = '';
            if (endpoint.includes('{latI}') || endpoint.includes('{lonI}')) {
                url = endpoint
                    .replaceAll('{latI}', encodeURIComponent(String(b.latI)))
                    .replaceAll('{lonI}', encodeURIComponent(String(b.lonI)));
            } else {
                const u = new URL(endpoint);
                u.searchParams.set('layer', 'poi');
                u.searchParams.set('tile', tileKey);
                u.searchParams.set('lat_i', String(b.latI));
                u.searchParams.set('lon_i', String(b.lonI));
                u.searchParams.set('south', b.south.toFixed(5));
                u.searchParams.set('west', b.west.toFixed(5));
                u.searchParams.set('north', b.north.toFixed(5));
                u.searchParams.set('east', b.east.toFixed(5));
                u.searchParams.set('v', '3');
                url = u.toString();
            }
            dbg.requests = Number(dbg.requests || 0) + 1;
            const res = await fetch(url);
            if (!res.ok) continue;
            const payload = await _poiReadTilePayload(url, res);
            let features = _poiParseTilePayload(payload);
            if (features.length) {
                const fetchSource = String((payload && payload.sourceKind) || '').toLowerCase() === 'legacy'
                    ? 'worker-poi-legacy'
                    : (endpoint.includes('{latI}') ? 'local-poi-split' : 'worker-poi-split');
                features = features.map(f => ({ ...f, fetchSource }));
                mergedFeatures = mergedFeatures.concat(features);
                dbg.hits = Number(dbg.hits || 0) + 1;
                dbg.splitHits = Number(dbg.splitHits || 0) + 1;
                tileSourceTag = fetchSource;
                _poiDebugBumpSourceCounter(fetchSource);
                _poiDebugMarkSource(fetchSource);
                break;
            }
        } catch (_) {
            dbg.errors = Number(dbg.errors || 0) + 1;
        }
    }
    if (includeCore) {
        for (const endpoint of POI_TILE_CORE_ENDPOINTS) {
            try {
                let url = '';
                if (endpoint.includes('{latI}') || endpoint.includes('{lonI}')) {
                    url = endpoint
                        .replaceAll('{latI}', encodeURIComponent(String(b.latI)))
                        .replaceAll('{lonI}', encodeURIComponent(String(b.lonI)));
                } else {
                    const u = new URL(endpoint);
                    u.searchParams.set('layer', 'core');
                    u.searchParams.set('tile', tileKey);
                    u.searchParams.set('lat_i', String(b.latI));
                    u.searchParams.set('lon_i', String(b.lonI));
                    u.searchParams.set('south', b.south.toFixed(5));
                    u.searchParams.set('west', b.west.toFixed(5));
                    u.searchParams.set('north', b.north.toFixed(5));
                    u.searchParams.set('east', b.east.toFixed(5));
                    u.searchParams.set('v', '3');
                    url = u.toString();
                }
                dbg.requests = Number(dbg.requests || 0) + 1;
                const res = await fetch(url);
                if (!res.ok) continue;
                const payload = await _poiReadTilePayload(url, res);
                let features = _poiParseTilePayload(payload);
                if (features.length) {
                    const fetchSource = endpoint.includes('{latI}') ? 'local-core-split' : 'worker-core-split';
                    features = features.map(f => ({ ...f, fetchSource }));
                    mergedFeatures = mergedFeatures.concat(features);
                    dbg.hits = Number(dbg.hits || 0) + 1;
                    dbg.splitHits = Number(dbg.splitHits || 0) + 1;
                    if (!tileSourceTag) tileSourceTag = fetchSource;
                    _poiDebugBumpSourceCounter(fetchSource);
                    _poiDebugMarkSource(fetchSource);
                    break;
                }
            } catch (_) {
                dbg.errors = Number(dbg.errors || 0) + 1;
            }
        }
    }
    if (includeInfra) {
        for (const endpoint of POI_TILE_INFRA_ENDPOINTS) {
            try {
                let url = '';
                if (endpoint.includes('{latI}') || endpoint.includes('{lonI}')) {
                    url = endpoint
                        .replaceAll('{latI}', encodeURIComponent(String(b.latI)))
                        .replaceAll('{lonI}', encodeURIComponent(String(b.lonI)));
                } else {
                    const u = new URL(endpoint);
                    u.searchParams.set('layer', 'infra');
                    u.searchParams.set('tile', tileKey);
                    u.searchParams.set('lat_i', String(b.latI));
                    u.searchParams.set('lon_i', String(b.lonI));
                    u.searchParams.set('south', b.south.toFixed(5));
                    u.searchParams.set('west', b.west.toFixed(5));
                    u.searchParams.set('north', b.north.toFixed(5));
                    u.searchParams.set('east', b.east.toFixed(5));
                    u.searchParams.set('v', '3');
                    url = u.toString();
                }
                dbg.requests = Number(dbg.requests || 0) + 1;
                const res = await fetch(url);
                if (!res.ok) continue;
                const payload = await _poiReadTilePayload(url, res);
                let features = _poiParseTilePayload(payload);
                if (features.length) {
                    const fetchSource = endpoint.includes('{latI}') ? 'local-infra-split' : 'worker-infra-split';
                    features = features.map(f => ({ ...f, fetchSource }));
                    mergedFeatures = mergedFeatures.concat(features);
                    dbg.hits = Number(dbg.hits || 0) + 1;
                    dbg.splitHits = Number(dbg.splitHits || 0) + 1;
                    if (!tileSourceTag) tileSourceTag = fetchSource;
                    _poiDebugBumpSourceCounter(fetchSource);
                    _poiDebugMarkSource(fetchSource);
                    break;
                }
            } catch (_) {
                dbg.errors = Number(dbg.errors || 0) + 1;
            }
        }
    }
    if (mergedFeatures.length) {
        const byKey = new Map();
        for (const f of mergedFeatures) {
            const lat = Number(f?.lat);
            const lon = Number(f?.lon);
            if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
            const k = _poiFeatureDedupeKey(f);
            byKey.set(k, _poiMergePreferredFeature(byKey.get(k), f));
        }
        const dedup = Array.from(byKey.values());
        const sourceTag = String(tileSourceTag || dbg.lastSource || 'worker');
        _poiTileMemCache.set(cacheKey, { ts: now, features: dedup, source: sourceTag });
        _poiTrackTileCoverage(tileKey, sourceTag);
        return dedup;
    }
    if (!allowLegacyFallback) {
        dbg.misses = Number(dbg.misses || 0) + 1;
        _poiDebugBumpSourceCounter('split-only-miss');
        _poiDebugMarkSource('split-only-miss');
        _poiTileMemCache.set(cacheKey, { ts: now, features: [], source: 'split-only-miss' });
        return [];
    }
    // 2) Fallback: legacy combined/obstacle tiles.
    for (const endpoint of POI_TILE_LEGACY_ENDPOINTS) {
        try {
            const u = new URL(endpoint);
            u.searchParams.set('tile', tileKey);
            u.searchParams.set('lat_i', String(b.latI));
            u.searchParams.set('lon_i', String(b.lonI));
            u.searchParams.set('south', b.south.toFixed(5));
            u.searchParams.set('west', b.west.toFixed(5));
            u.searchParams.set('north', b.north.toFixed(5));
            u.searchParams.set('east', b.east.toFixed(5));
            u.searchParams.set('v', '2');
            dbg.requests = Number(dbg.requests || 0) + 1;
            const res = await fetch(u.toString());
            if (!res.ok) continue;
            const payload = await _poiReadTilePayload(u.toString(), res);
            const features = _poiParseTilePayload(payload);
            _poiTileMemCache.set(cacheKey, { ts: now, features, source: 'worker-legacy-fallback' });
            if (features.length) {
                dbg.hits = Number(dbg.hits || 0) + 1;
                dbg.legacyHits = Number(dbg.legacyHits || 0) + 1;
                dbg.fallbackHits = Number(dbg.fallbackHits || 0) + 1;
                _poiDebugBumpSourceCounter('worker-poi-legacy');
                _poiDebugMarkSource('worker-legacy-fallback');
                _poiTrackTileCoverage(tileKey, 'worker-legacy-fallback');
            }
            return features;
        } catch (_) {
            dbg.errors = Number(dbg.errors || 0) + 1;
        }
    }
    dbg.misses = Number(dbg.misses || 0) + 1;
    _poiDebugMarkSource('none');
    _poiTileMemCache.set(cacheKey, { ts: now, features: [], source: 'none' });
    return [];
}

function _shouldIncludeCoreForPoiSearch(forcedCategory = null, dispatchProfileId = 'auto') {
    const cat = String(forcedCategory || '').toLowerCase();
    const profile = String(dispatchProfileId || 'auto').toLowerCase();
    if (cat === 'trn') return false;
    if (cat && cat !== 'all') return true;
    if (profile === 'inspection_infra') return true;
    if (profile === 'infra_chain_recon') return true;
    if (profile === 'search_and_rescue' || missionIsSarHeliProfileId(profile)) return true;
    if (profile === 'mapping_survey') return true;
    if (profile === 'fire_watch') return true;
    if (profile === 'tour_guide_knowledge') return true;
    return false;
}

function _shouldIncludeInfraForPoiSearch(forcedCategory = null, dispatchProfileId = 'auto') {
    const cat = String(forcedCategory || '').toLowerCase();
    const profile = String(dispatchProfileId || 'auto').toLowerCase();
    if (profile === 'inspection_infra') return true;
    if (profile === 'infra_chain_recon') return true;
    if (profile === 'mapping_survey') return true;
    if (profile === 'science_geo') return true;
    if (['infrastructure', 'industry', 'bridge', 'road', 'rail', 'telecom', 'dam'].includes(cat)) return true;
    return false;
}

function _poiChainDebugForceValue() {
    let raw = '';
    try { raw = String(localStorage.getItem('ga_debug_force_poi_chain') || '').trim().toLowerCase(); } catch (_) {}
    if (!raw && typeof location !== 'undefined' && location?.search) {
        try {
            const params = new URLSearchParams(location.search);
            raw = String(params.get('poiChain') || params.get('forcePoiChain') || '').trim().toLowerCase();
        } catch (_) {}
    }
    if (!raw || raw === '0' || raw === 'false' || raw === 'off' || raw === 'no') return '';
    if (raw === '1' || raw === 'true' || raw === 'on' || raw === 'auto') return 'auto';
    return raw;
}

function _installPoiChainDebugHelpers() {
    if (typeof window === 'undefined' || window.__gaPoiChainDebugHelpersInstalled) return;
    window.__gaPoiChainDebugHelpersInstalled = true;
    window.getPoiChainDebugForceValue = _poiChainDebugForceValue;
    window.updatePoiChainDebugForceButtonUi = function() {
        const btn = document.getElementById('btnDebugPoiChainForce');
        if (!btn) return;
        const force = _poiChainDebugForceValue();
        const active = !!force;
        btn.textContent = active ? 'POI-Kette Ein' : 'POI-Kette Aus';
        btn.title = active
            ? `POI-Ketten-Dispatch wird beim naechsten passenden POI erzwungen (${force}).`
            : 'POI-Ketten-Dispatch normal, keine Debug-Erzwingung.';
        btn.style.background = active ? '#344a18' : '#262f14';
        btn.style.borderColor = active ? '#95d14a' : '#5c6f2f';
        btn.style.color = active ? '#efffd1' : '#dfff9f';
    };
    window.forcePoiChainDispatch = function(theme = 'auto') {
        const value = String(theme || 'auto').trim().toLowerCase() || 'auto';
        try { localStorage.setItem('ga_debug_force_poi_chain', value); } catch (_) {}
        window.gaPoiChainDebug = { ...(window.gaPoiChainDebug || {}), force: value };
        window.updatePoiChainDebugForceButtonUi();
        return `POI-Chain-Dispatch erzwungen: ${value}`;
    };
    window.clearPoiChainDispatchForce = function() {
        try { localStorage.removeItem('ga_debug_force_poi_chain'); } catch (_) {}
        window.gaPoiChainDebug = { ...(window.gaPoiChainDebug || {}), force: '' };
        window.updatePoiChainDebugForceButtonUi();
        return 'POI-Chain-Dispatch-Force aus';
    };
    window.vpTogglePoiChainDebugForce = function() {
        const current = _poiChainDebugForceValue();
        if (current) {
            try { localStorage.setItem('ga_debug_force_poi_chain', 'off'); } catch (_) {}
            window.gaPoiChainDebug = { ...(window.gaPoiChainDebug || {}), force: '' };
        } else {
            try { localStorage.setItem('ga_debug_force_poi_chain', 'auto'); } catch (_) {}
            window.gaPoiChainDebug = { ...(window.gaPoiChainDebug || {}), force: 'auto' };
        }
        window.updatePoiChainDebugForceButtonUi();
        if (typeof window.vpRefreshWeatherDebugReport === 'function') {
            try { window.vpRefreshWeatherDebugReport(); } catch (_) {}
        }
        const indicator = document.getElementById('searchIndicator');
        if (indicator) indicator.innerText = current
            ? 'Debug: POI-Ketten-Dispatch normal.'
            : 'Debug: POI-Ketten-Dispatch erzwungen.';
        return !current;
    };
    if (document.readyState === 'loading') {
        window.addEventListener('DOMContentLoaded', window.updatePoiChainDebugForceButtonUi);
    } else {
        window.updatePoiChainDebugForceButtonUi();
    }
}
_installPoiChainDebugHelpers();

function compactPoiChainForMission(chain = null, maxPoints = 8) {
    if (!chain || typeof chain !== 'object') return null;
    if (window.missionPoiChain && typeof window.missionPoiChain.compactPoiChain === 'function') {
        return window.missionPoiChain.compactPoiChain(chain, maxPoints);
    }
    const points = Array.isArray(chain.points) ? chain.points.slice(0, maxPoints) : [];
    return {
        schema: chain.schema || 'ga.poiChain.v1',
        kind: chain.kind || 'poi_chain',
        mode: chain.mode || 'progressive_reveal',
        theme: String(chain.theme || ''),
        label: String(chain.label || '').replace(/\s+/g, ' ').trim(),
        guide: chain.guide || null,
        overlay: chain.overlay || null,
        points: points.map((point, idx) => ({
            id: String(point.id || `chain-point-${idx + 1}`).trim(),
            index: Number.isFinite(Number(point.index)) ? Number(point.index) : idx,
            name: String(point.name || '').replace(/\s+/g, ' ').trim(),
            lat: Number.isFinite(Number(point.lat)) ? Math.round(Number(point.lat) * 1e6) / 1e6 : null,
            lon: Number.isFinite(Number(point.lon)) ? Math.round(Number(point.lon) * 1e6) / 1e6 : null,
            category: String(point.category || '').trim(),
            triggerRadiusNm: Number.isFinite(Number(point.triggerRadiusNm)) ? Math.round(Number(point.triggerRadiusNm) * 100) / 100 : 0.45,
            revealState: idx === 0 ? 'visible' : (point.revealState || 'hidden'),
            required: point.required !== false,
            sourceLayer: String(point.sourceLayer || '').trim(),
            sourceTile: String(point.sourceTile || '').trim(),
            score: Number.isFinite(Number(point.score)) ? Math.round(Number(point.score) * 100) / 100 : null,
            orderT: Number.isFinite(Number(point.orderT)) ? Math.round(Number(point.orderT) * 10000) / 10000 : null,
            distCorridorNm: Number.isFinite(Number(point.distCorridorNm)) ? Math.round(Number(point.distCorridorNm) * 1000) / 1000 : null,
            distanceFromPrevNm: Number.isFinite(Number(point.distanceFromPrevNm)) ? Math.round(Number(point.distanceFromPrevNm) * 100) / 100 : 0,
            bearingFromPrevDeg: point.bearingFromPrevDeg === null ? null : Math.round(Number(point.bearingFromPrevDeg || 0)),
            clusterCount: Math.max(1, Number(point.clusterCount || 1)),
            tags: point.tags || {}
        })),
        sequenceRequired: chain.sequenceRequired !== false,
        completionMode: chain.completionMode || 'all_required',
        fallbackAllowed: chain.fallbackAllowed !== false,
        dispatch: chain.dispatch || null
    };
}

function stripPoiChainHiddenFieldsForWriter(chain = null, maxPoints = 8) {
    const compact = compactPoiChainForMission(chain, maxPoints);
    if (!compact || typeof compact !== 'object') return null;
    const { hiddenOutcome, ...safe } = compact;
    const hiddenTagKeys = new Set([
        'finding',
        'findingHint',
        'findingText',
        'paxFindingText',
        'followUp',
        'followUpType',
        'followUpKind',
        'hiddenFromWriter',
        'revealAfter'
    ]);
    safe.points = Array.isArray(compact.points)
        ? compact.points.map(point => {
            const tags = point?.tags && typeof point.tags === 'object' ? { ...point.tags } : {};
            for (const key of hiddenTagKeys) delete tags[key];
            return { ...point, tags };
        })
        : [];
    return safe;
}

function _poiChainDebugCoord(point = null) {
    const lat = Number(point?.lat);
    const lon = Number(point?.lon ?? point?.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    return {
        lat: Math.round(lat * 1e6) / 1e6,
        lon: Math.round(lon * 1e6) / 1e6,
        name: String(point?.name || point?.label || '').replace(/\s+/g, ' ').trim() || undefined
    };
}

function _poiChainDebugTraceSummary(trace = []) {
    const points = Array.isArray(trace) ? trace.map(_poiChainDebugCoord).filter(Boolean) : [];
    return {
        count: points.length,
        first: points.slice(0, 3),
        last: points.slice(-3)
    };
}

function _poiChainDebugRouteSummary(points = []) {
    const route = Array.isArray(points) ? points.map(_poiChainDebugCoord).filter(Boolean) : [];
    return {
        count: route.length,
        points: route.slice(0, 12)
    };
}

function buildPoiChainDebugSummary(missionData = null, contract = null, options = {}) {
    const md = missionData && typeof missionData === 'object' ? missionData : null;
    const c = contract && typeof contract === 'object' ? contract : null;
    const chain = md?.poiChain || c?.poiChain || c?.missionContractV4?.poiChain || c?.missionPlanV2?.poiChain || null;
    if (!chain || typeof chain !== 'object') return null;
    const points = Array.isArray(chain.points) ? chain.points : [];
    const overlay = chain.overlay && typeof chain.overlay === 'object' ? chain.overlay : {};
    let effectiveOverlay = overlay;
    try {
        const runtimeSpec = typeof window.missionPoiChainRuntime?.normalizeSpec === 'function'
            ? window.missionPoiChainRuntime.normalizeSpec(chain)
            : null;
        if (runtimeSpec?.overlay) effectiveOverlay = runtimeSpec.overlay;
    } catch (_) {}
    const guide = chain.guide && typeof chain.guide === 'object' ? chain.guide : {};
    const routeCandidates = [
        options.routeWaypoints,
        md?.missionRouteWaypoints,
        md?.routeWaypoints,
        (typeof window !== 'undefined' ? window._missionRouteWaypoints : null),
        (typeof routeWaypoints !== 'undefined' ? routeWaypoints : null)
    ];
    const activeRoute = routeCandidates.find(candidate => Array.isArray(candidate) && candidate.length) || [];
    return {
        theme: String(chain.theme || ''),
        label: String(chain.label || ''),
        guide: {
            type: String(guide.type || ''),
            name: String(guide.name || guide.namePattern || ''),
            groupKey: String(guide.groupKey || ''),
            guidePointCount: Number(guide.guidePointCount || 0),
            start: _poiChainDebugCoord(guide.start),
            end: _poiChainDebugCoord(guide.end)
        },
        overlay: {
            type: String(overlay.type || ''),
            label: String(overlay.label || ''),
            radiusNm: Number.isFinite(Number(overlay.radiusNm)) ? Math.round(Number(overlay.radiusNm) * 100) / 100 : null,
            widthNm: Number.isFinite(Number(effectiveOverlay.widthNm)) ? Math.round(Number(effectiveOverlay.widthNm) * 100) / 100 : null,
            start: _poiChainDebugCoord(overlay.start),
            end: _poiChainDebugCoord(overlay.end),
            trace: _poiChainDebugTraceSummary(overlay.trace)
        },
        points: points.map((point, idx) => ({
            index: Number.isFinite(Number(point.index)) ? Number(point.index) : idx,
            name: String(point.name || '').replace(/\s+/g, ' ').trim(),
            category: String(point.category || '').trim(),
            lat: Number.isFinite(Number(point.lat)) ? Math.round(Number(point.lat) * 1e6) / 1e6 : null,
            lon: Number.isFinite(Number(point.lon)) ? Math.round(Number(point.lon) * 1e6) / 1e6 : null,
            orderT: Number.isFinite(Number(point.orderT)) ? Math.round(Number(point.orderT) * 10000) / 10000 : null,
            distCorridorNm: Number.isFinite(Number(point.distCorridorNm)) ? Math.round(Number(point.distCorridorNm) * 1000) / 1000 : null,
            distanceFromPrevNm: Number.isFinite(Number(point.distanceFromPrevNm)) ? Math.round(Number(point.distanceFromPrevNm) * 100) / 100 : null,
            bearingFromPrevDeg: Number.isFinite(Number(point.bearingFromPrevDeg)) ? Math.round(Number(point.bearingFromPrevDeg)) : null,
            sourceLayer: String(point.sourceLayer || ''),
            sourceTile: String(point.sourceTile || ''),
            tags: point.tags || {}
        })),
        routeWaypoints: _poiChainDebugRouteSummary(activeRoute),
        dispatch: chain.dispatch || null,
        runtimeDebug: (typeof window !== 'undefined' && window.gaPoiChainDebug) ? window.gaPoiChainDebug.last || null : null
    };
}
window.buildPoiChainDebugSummary = buildPoiChainDebugSummary;

function _poiChainCategoryFromTheme(theme = '') {
    const t = String(theme || '').toLowerCase();
    if (t === 'river_bridge_inspection' || t === 'road_bridge_inspection') return 'bridge';
    if (t === 'road_junction_survey') return 'road';
    if (t === 'rail_chain_inspection') return 'rail';
    if (t === 'power_grid_inspection') return 'infrastructure';
    return 'infrastructure';
}

function _poiChainThemesForDispatch(category = 'all', forceTheme = '') {
    const forced = String(forceTheme || '').toLowerCase();
    const known = ['river_bridge_inspection', 'road_bridge_inspection', 'road_junction_survey', 'rail_chain_inspection', 'power_grid_inspection'];
    if (forced && forced !== 'auto' && known.includes(forced)) return [forced];
    const cat = String(category || 'all').toLowerCase();
    if (cat === 'bridge') return ['river_bridge_inspection', 'road_bridge_inspection'];
    if (cat === 'road') return ['road_bridge_inspection', 'road_junction_survey'];
    if (cat === 'rail') return ['rail_chain_inspection'];
    if (cat === 'infrastructure' || cat === 'industry' || cat === 'all' || cat === 'chain') return known;
    return known;
}

function _poiChainThemeFamily(theme = '') {
    const t = String(theme || '').toLowerCase();
    if (t === 'river_bridge_inspection' || t === 'road_bridge_inspection') return 'bridge';
    if (t === 'road_junction_survey') return 'road';
    if (t === 'rail_chain_inspection') return 'rail';
    if (t === 'power_grid_inspection') return 'power';
    return t || 'chain';
}

function _poiChainDispatchHistoryAnchorKey(context = {}) {
    const lat = Number(context.lat);
    const lon = Number(context.lon);
    return Number.isFinite(lat) && Number.isFinite(lon)
        ? `${Math.round(lat * 10)}_${Math.round(lon * 10)}`
        : 'global';
}

function _poiChainDispatchProspectSignature(prospect = null) {
    const chain = prospect?.chain || {};
    const points = Array.isArray(chain.points) ? chain.points : [];
    const first = points[0] || {};
    const last = points[points.length - 1] || {};
    const loc = point => {
        const lat = Number(point?.lat);
        const lon = Number(point?.lon);
        return Number.isFinite(lat) && Number.isFinite(lon)
            ? `${Math.round(lat * 100)}:${Math.round(lon * 100)}`
            : '';
    };
    const guide = normalizeMissionText(chain?.guide?.name || chain?.label || prospect?.label || '');
    const theme = String(prospect?.theme || chain?.theme || '').toLowerCase();
    return [theme, guide, loc(first), loc(last)].filter(Boolean).join('|') || theme || 'chain';
}

function _poiChainDispatchReadHistory(key = '') {
    try {
        const parsed = JSON.parse(localStorage.getItem(key) || '[]');
        return Array.isArray(parsed) ? parsed.map(x => String(x || '')).filter(Boolean) : [];
    } catch (_) {
        return [];
    }
}

function _poiChainDispatchWriteHistory(key = '', history = [], limit = 12) {
    try {
        const clean = Array.isArray(history) ? history.map(x => String(x || '')).filter(Boolean) : [];
        while (clean.length > Math.max(1, Number(limit) || 12)) clean.shift();
        localStorage.setItem(key, JSON.stringify(clean));
    } catch (_) {}
}

function _selectPoiChainDispatchProspect(prospectRun, context = {}) {
    const prospects = Array.isArray(prospectRun?.prospects)
        ? prospectRun.prospects.filter(prospect => prospect?.chain)
        : [];
    if (!prospects.length) return null;
    const rawForceTheme = String(context.forceTheme || '').toLowerCase();
    const forceTheme = rawForceTheme === 'auto' ? '' : rawForceTheme;
    const category = String(context.category || 'all').toLowerCase();
    const shouldBalance = !forceTheme && (context.force === true || category === 'all' || category === 'chain');
    const bestScore = Number(prospects[0]?.score || 0);
    const scoreFloor = Math.max(bestScore - 10, bestScore * 0.9);
    const scoreBand = prospects.filter(prospect => {
        const score = Number(prospect?.score || 0);
        return Number.isFinite(score) && score >= scoreFloor;
    });
    const anchorKey = _poiChainDispatchHistoryAnchorKey(context);
    const concreteHistoryKey = `ga_poi_chain_dispatch_target_history_${anchorKey}`;
    let concreteHistory = _poiChainDispatchReadHistory(concreteHistoryKey);
    let candidateBand = scoreBand.filter(prospect => !concreteHistory.includes(_poiChainDispatchProspectSignature(prospect)));
    if (!candidateBand.length) {
        candidateBand = scoreBand.length ? scoreBand : prospects;
        concreteHistory = [];
    }
    if (!shouldBalance) {
        const pick = candidateBand[0] || prospects[0];
        concreteHistory.push(_poiChainDispatchProspectSignature(pick));
        _poiChainDispatchWriteHistory(concreteHistoryKey, concreteHistory, 14);
        return pick;
    }

    const families = new Set();
    const band = [];
    for (const prospect of candidateBand) {
        const family = _poiChainThemeFamily(prospect.theme || prospect.chain?.theme);
        if (families.has(family)) continue;
        families.add(family);
        band.push(prospect);
    }
    if (band.length <= 1) {
        const pick = candidateBand[Math.floor(Math.random() * candidateBand.length)] || prospects[0];
        concreteHistory.push(_poiChainDispatchProspectSignature(pick));
        _poiChainDispatchWriteHistory(concreteHistoryKey, concreteHistory, 14);
        return pick;
    }

    const historyKey = `ga_poi_chain_dispatch_family_history_${anchorKey}`;
    let history = _poiChainDispatchReadHistory(historyKey);

    let pool = band.filter(prospect => !history.includes(_poiChainThemeFamily(prospect.theme || prospect.chain?.theme)));
    if (!pool.length) {
        pool = band;
        history = [];
    }
    const pick = pool[Math.floor(Math.random() * pool.length)] || band[0] || prospects[0];
    const family = _poiChainThemeFamily(pick.theme || pick.chain?.theme);
    history.push(family);
    _poiChainDispatchWriteHistory(historyKey, history, Math.max(4, band.length));
    concreteHistory.push(_poiChainDispatchProspectSignature(pick));
    _poiChainDispatchWriteHistory(concreteHistoryKey, concreteHistory, 14);
    return pick;
}

function _poiChainRawValue(feature = null, key = '') {
    const direct = feature?.[key];
    if (direct !== undefined && direct !== null && String(direct).trim()) return String(direct).trim().toLowerCase();
    const tag = feature?.tags?.[key];
    if (tag !== undefined && tag !== null && String(tag).trim()) return String(tag).trim().toLowerCase();
    return '';
}

function _poiChainRawTokens(feature = null) {
    return [
        feature?.name,
        feature?.n,
        feature?.ref,
        feature?.operator,
        feature?.rawType,
        feature?.type,
        feature?.tags?.name,
        feature?.tags?.ref,
        feature?.tags?.operator,
        feature?.tags?.infra_type,
        feature?.tags?.cluster_type,
        feature?.tags?.highway,
        feature?.tags?.railway,
        feature?.tags?.power,
        feature?.tags?.waterway
    ].filter(v => v !== undefined && v !== null && String(v).trim()).join(' ').toLowerCase();
}

function _poiChainFeatureGuideKinds(feature = null) {
    const sourceKind = String(feature?.sourceKind || '').toLowerCase();
    if (sourceKind !== 'lin') return [];
    const layer = _poiChainRawValue(feature, 'layer');
    const highway = _poiChainRawValue(feature, 'highway');
    const railway = _poiChainRawValue(feature, 'railway');
    const power = _poiChainRawValue(feature, 'power');
    const waterway = _poiChainRawValue(feature, 'waterway');
    const water = _poiChainRawValue(feature, 'water');
    const natural = _poiChainRawValue(feature, 'natural');
    const rawType = String(feature?.rawType || feature?.type || '').toLowerCase();
    const kinds = [];
    if (waterway || water === 'river' || natural === 'water' || layer === 'hydro' || ['river', 'stream', 'canal', 'ditch', 'drain', 'water', 'lake', 'reservoir', 'dam', 'weir'].includes(rawType)) kinds.push('waterway');
    if (highway || layer === 'road' || ['highway', 'motorway', 'motorway_link', 'trunk', 'trunk_link', 'primary', 'primary_link', 'secondary', 'secondary_link', 'tertiary', 'tertiary_link', 'residential', 'service', 'road'].includes(rawType)) kinds.push('road');
    if (railway || layer === 'rail' || ['railway', 'rail', 'tram', 'light_rail', 'subway', 'narrow_gauge'].includes(rawType)) kinds.push('rail');
    if (['line', 'minor_line', 'cable', 'powerline', 'power_line'].includes(power) || layer === 'power' || ['power', 'powerline', 'power_line', 'line', 'minor_line', 'cable'].includes(rawType)) kinds.push('power');
    return kinds;
}

function _poiChainFeatureMatchesTheme(feature = null, theme = '') {
    const t = String(theme || '').toLowerCase();
    const sourceKind = String(feature?.sourceKind || '').toLowerCase();
    const guideKinds = _poiChainFeatureGuideKinds(feature);
    if (t === 'river_bridge_inspection' && guideKinds.includes('waterway')) return true;
    if ((t === 'road_bridge_inspection' || t === 'road_junction_survey') && guideKinds.includes('road')) return true;
    if (t === 'rail_chain_inspection' && guideKinds.includes('rail')) return true;
    if (t === 'power_grid_inspection' && guideKinds.includes('power')) return true;
    const infraType = _poiChainRawValue(feature, 'infra_type') || _poiChainRawValue(feature, 'cluster_type');
    const bridge = _poiChainRawValue(feature, 'bridge');
    const manMade = _poiChainRawValue(feature, 'man_made');
    const highway = _poiChainRawValue(feature, 'highway');
    const railway = _poiChainRawValue(feature, 'railway');
    const power = _poiChainRawValue(feature, 'power');
    const substation = _poiChainRawValue(feature, 'substation');
    const tokens = _poiChainRawTokens(feature);
    const isBridge = infraType === 'bridge' || bridge === 'yes' || bridge === 'viaduct' || manMade === 'bridge';
    if ((t === 'river_bridge_inspection' || t === 'road_bridge_inspection') && isBridge) return true;
    const isRoadJunction = highway === 'motorway_junction' || highway === 'trunk_junction' || infraType === 'road_junction' || /\b(motorway_junction|anschlussstelle|kreuz|dreieck)\b/i.test(tokens);
    if (t === 'road_junction_survey' && isRoadJunction) return true;
    const isRail = infraType === 'rail' || infraType === 'railway' || ['station', 'halt', 'signal_box', 'switch', 'level_crossing', 'crossing', 'junction', 'buffer_stop', 'yard', 'rail'].includes(railway);
    if (t === 'rail_chain_inspection' && isRail) return true;
    const isPower = infraType === 'power' || infraType === 'power_grid' || infraType === 'power_station' || ['substation', 'switchgear', 'tower', 'pole', 'line', 'minor_line', 'plant', 'generator'].includes(power) || !!substation || manMade === 'power_tower';
    if (t === 'power_grid_inspection' && isPower) return true;
    return false;
}

function _poiChainFilterDispatchFeatures(rows = [], themes = [], anchor = null, maxRows = POI_CHAIN_MAX_FEATURES_PER_TILE) {
    const themeList = Array.isArray(themes) && themes.length ? themes : _poiChainThemesForDispatch('all', 'auto');
    const filtered = [];
    for (const row of Array.isArray(rows) ? rows : []) {
        if (!row) continue;
        if (!themeList.some(theme => _poiChainFeatureMatchesTheme(row, theme))) continue;
        filtered.push(row);
    }
    if (!anchor || filtered.length <= maxRows) return filtered.slice(0, maxRows);
    return filtered
        .map(row => {
            let dist = 9999;
            try {
                const nav = calcNav(Number(anchor.lat), Number(anchor.lon), Number(row.lat), Number(row.lon));
                if (Number.isFinite(Number(nav?.dist))) dist = Number(nav.dist);
            } catch (_) {}
            return { row, dist };
        })
        .sort((a, b) => a.dist - b.dist)
        .slice(0, Math.max(1, Number(maxRows) || POI_CHAIN_MAX_FEATURES_PER_TILE))
        .map(item => item.row);
}

async function findPoiChainDispatchTarget(lat, lon, minNM, maxNM, dirPref, selectedCategory = 'all', dispatchProfileId = 'auto', searchAnchor = null, options = {}) {
    const chainDebugStartedAt = (typeof performance !== 'undefined' && typeof performance.now === 'function') ? performance.now() : Date.now();
    const chainDebugNow = () => (typeof performance !== 'undefined' && typeof performance.now === 'function') ? performance.now() : Date.now();
    const profile = String(dispatchProfileId || '').toLowerCase();
    const category = String(selectedCategory || 'all').toLowerCase();
    const forceTheme = String(options.forceTheme || _poiChainDebugForceValue() || '').toLowerCase();
    const forced = !!forceTheme || category === 'chain' || options.force === true;
    const supportsChain = profile === 'inspection_infra' || profile === 'infra_chain_recon';
    if (!supportsChain || !forced) return null;
    if (!window.missionPoiChain || typeof window.missionPoiChain.buildPoiChainProspects !== 'function') return null;
    const anchor = (searchAnchor && Number.isFinite(Number(searchAnchor.lat)) && Number.isFinite(Number(searchAnchor.lon)))
        ? {
            lat: Number(searchAnchor.lat),
            lon: Number(searchAnchor.lon),
            localRadiusNm: Math.max(20, Number(searchAnchor.localRadiusNm) || 28)
        }
        : {
            lat: Number(lat),
            lon: Number(lon),
            localRadiusNm: Math.max(22, Math.min(36, Number(maxNM || 40) * 0.6))
        };
    const themes = _poiChainThemesForDispatch(category, forceTheme);
    const tileKeys = _poiCollectNearestTileKeysAround(anchor.lat, anchor.lon, Math.max(18, Math.min(24, Number(anchor.localRadiusNm || 20) + 4)), POI_CHAIN_TILE_MAX_KEYS);
    if (!tileKeys.length) {
        window.gaPoiChainDebug = {
            ...(window.gaPoiChainDebug || {}),
            last: { ok: false, status: 'no_tiles', forced, themes }
        };
        return null;
    }
    const features = [];
    let cursor = 0;
    const workers = [];
    const workerCount = Math.min(2, POI_TILE_FETCH_PARALLEL, tileKeys.length);
    const fetchStartedAt = chainDebugNow();
    for (let i = 0; i < workerCount; i++) {
        workers.push((async () => {
            while (cursor < tileKeys.length && features.length < POI_CHAIN_MAX_FEATURES) {
                const idx = cursor++;
                const key = tileKeys[idx];
                const rows = await _poiFetchTileFeatures(key, { includeCore: true, includeInfra: true, allowLegacyFallback: false });
                if (rows && rows.length) {
                    features.push(..._poiChainFilterDispatchFeatures(rows, themes, anchor));
                    if (features.length > POI_CHAIN_MAX_FEATURES) features.length = POI_CHAIN_MAX_FEATURES;
                }
            }
        })());
    }
    await Promise.all(workers);
    const fetchMs = Math.round((chainDebugNow() - fetchStartedAt) * 10) / 10;
    if (!features.length) {
        window.gaPoiChainDebug = {
            ...(window.gaPoiChainDebug || {}),
            force: forceTheme || '',
            last: {
                ok: false,
                status: 'no_features',
                forced,
                themes,
                tileKeys: tileKeys.length,
                features: 0,
                fetchMs,
                totalMs: Math.round((chainDebugNow() - chainDebugStartedAt) * 10) / 10
            }
        };
        return null;
    }
    const prospectStartedAt = chainDebugNow();
    const prospectRun = window.missionPoiChain.buildPoiChainProspects({
        dispatchStartLat: Number(lat),
        dispatchStartLon: Number(lon),
        minNM,
        maxNM,
        dirPref,
        category: category === 'chain' ? 'all' : category,
        profileId: profile,
        forceTheme: forceTheme && forceTheme !== 'auto' ? forceTheme : '',
        maxGroupsPerTheme: 4,
        stopAfterProspects: 4,
        minPoints: 3,
        maxPoints: 8,
        triggerRadiusNm: 0.5
    }, { features });
    const buildMs = Math.round((chainDebugNow() - prospectStartedAt) * 10) / 10;
    const totalMs = Math.round((chainDebugNow() - chainDebugStartedAt) * 10) / 10;
    if (totalMs > 2500 && typeof window.gaDebugPush === 'function') {
        try {
            window.gaDebugPush('perf-warn', '[POI Chain] Dispatch slow', {
                totalMs,
                fetchMs,
                buildMs,
                tileKeys: tileKeys.length,
                features: features.length,
                themes
            });
        } catch (_) {}
    }
    const best = _selectPoiChainDispatchProspect(prospectRun, {
        category,
        force: options.force === true,
        forceTheme,
        lat,
        lon
    });
    if (!best?.chain) {
        window.gaPoiChainDebug = {
            ...(window.gaPoiChainDebug || {}),
            last: {
                ok: false,
                status: prospectRun?.status || 'no_chain',
                diagnostics: prospectRun?.diagnostics || null,
                themes,
                tileKeys: tileKeys.length,
                features: features.length,
                fetchMs,
                buildMs,
                totalMs,
                forced
            }
        };
        return null;
    }
    const chain = compactPoiChainForMission(best.chain, 8);
    const first = chain?.points?.[0] || null;
    if (!first || !Number.isFinite(Number(first.lat)) || !Number.isFinite(Number(first.lon))) return null;
    const targetName = String(chain.label || first.name || 'Infrastruktur-Kette').trim();
    const targetCategory = _poiChainCategoryFromTheme(chain.theme);
    const out = {
        icao: 'POI',
        n: targetName,
        lat: Number(first.lat),
        lon: Number(first.lon),
        poiCategory: targetCategory,
        poiSource: `POI Chain Dispatch (${chain.theme || 'auto'})`,
        source: 'poi-chain-dispatch',
        missionSubType: 'poi_chain',
        poiChain: chain,
        poiLookup: {
            engine: 'poi-chain-dispatch',
            theme: chain.theme || null,
            guide: chain.guide?.name || chain.guide?.type || null,
            pointCount: chain.points.length,
            source: 'split-tiles',
            debugForced: forced,
            diagnostics: {
                score: best.score,
                group: best.group || null,
                featureCounts: prospectRun?.diagnostics?.featureCounts || null,
                guideScope: best.diagnostics?.guideScope || null,
                guidePoints: best.diagnostics?.guidePoints || 0,
                rawCandidates: best.diagnostics?.rawCandidates || 0,
                selectedPoints: best.diagnostics?.selectedPoints || 0
            }
        }
    };
    window.gaPoiChainDebug = {
        ...(window.gaPoiChainDebug || {}),
        force: forceTheme || '',
        last: {
            ok: true,
            target: targetName,
            category: targetCategory,
            theme: chain.theme,
            points: chain.points.length,
            guide: {
                name: chain.guide?.name || '',
                groupKey: chain.guide?.groupKey || '',
                guidePointCount: chain.guide?.guidePointCount || 0
            },
            overlayTracePoints: Array.isArray(chain.overlay?.trace) ? chain.overlay.trace.length : 0,
            diagnostics: {
                score: best.score,
                guideScope: best.diagnostics?.guideScope || null,
                guidePoints: best.diagnostics?.guidePoints || 0,
                rawCandidates: best.diagnostics?.rawCandidates || 0,
                selectedPoints: best.diagnostics?.selectedPoints || 0
            },
            selectedPoints: Array.isArray(chain.points) ? chain.points.map(point => ({
                index: point.index,
                name: point.name,
                category: point.category,
                lat: point.lat,
                lon: point.lon,
                orderT: point.orderT,
                distCorridorNm: point.distCorridorNm,
                distanceFromPrevNm: point.distanceFromPrevNm
            })) : [],
            score: best.score,
            themes,
            tileKeys: tileKeys.length,
            features: features.length,
            fetchMs,
            buildMs,
            totalMs,
            diagnostics: prospectRun?.diagnostics || null
        }
    };
    return out;
}

async function findTaggedTilePOI(lat, lon, minNM, maxNM, dirPref, forcedCategory = null, dispatchProfileId = 'auto', searchAnchor = null) {
    const forceCat = String(forcedCategory || '').toLowerCase();
    const profileId = String(dispatchProfileId || '').toLowerCase();
    const isKnowledgeGuideProfile = profileId === 'tour_guide_knowledge';
    const isSightseeingProfile = profileId === 'sightseeing_tour';
    const isSarHeliProfile = missionIsSarHeliProfileId(profileId);
    const sarCorridorMode = (profileId === 'search_and_rescue' || isSarHeliProfile) && (!forceCat || forceCat === 'all');
    if (forceCat === 'trn') return null;
    const includeCore = _shouldIncludeCoreForPoiSearch(forceCat, dispatchProfileId);
    const includeInfra = _shouldIncludeInfraForPoiSearch(forceCat, dispatchProfileId);
    const allowLegacyFallback =
        !forceCat ||
        forceCat === 'all' ||
        forceCat === 'telecom' ||
        forceCat === 'infrastructure';
    const dbgStart = { ..._poiDebugState() };
    const anchor = (searchAnchor && Number.isFinite(Number(searchAnchor.lat)) && Number.isFinite(Number(searchAnchor.lon)))
        ? {
            lat: Number(searchAnchor.lat),
            lon: Number(searchAnchor.lon),
            localRadiusNm: Math.max(8, Number(searchAnchor.localRadiusNm) || 20),
            distNm: Number(searchAnchor.distNm || 0),
            bearingDeg: Number(searchAnchor.bearingDeg || 0),
            strategy: String(searchAnchor.strategy || 'ring-quadrant-anchor')
        }
        : {
            lat: Number(lat),
            lon: Number(lon),
            localRadiusNm: Math.max(18, Math.min(26, Number(maxNM || 40) * 0.45)),
            distNm: 0,
            bearingDeg: 0,
            strategy: 'route-centered'
        };
    const tileKeys = _poiCollectTileKeysAround(anchor.lat, anchor.lon, Math.max(anchor.localRadiusNm + 4, 18));
    if (!tileKeys.length) return null;

    const features = [];
    let cursor = 0;
    const workers = [];
    const workerCount = Math.min(POI_TILE_FETCH_PARALLEL, tileKeys.length);
    for (let i = 0; i < workerCount; i++) {
        workers.push((async () => {
            while (cursor < tileKeys.length) {
                const idx = cursor++;
                const key = tileKeys[idx];
                const rows = await _poiFetchTileFeatures(key, { includeCore, includeInfra, allowLegacyFallback });
                if (rows && rows.length) features.push(...rows);
            }
        })());
    }
    await Promise.all(workers);
    if (!features.length) return null;

    const candidates = [];
    const seen = new Set();
    for (const f of features) {
        const flat = Number(f?.lat);
        const flon = Number(f?.lon);
        if (!Number.isFinite(flat) || !Number.isFinite(flon)) continue;
        const navStart = calcNav(lat, lon, flat, flon);
        if (!Number.isFinite(navStart?.dist)) continue;
        if (navStart.dist < Number(minNM || 0) || navStart.dist > Number(maxNM || 9999)) continue;
        if (!checkBearing(navStart.brng, dirPref)) continue;
        const navAnchor = calcNav(anchor.lat, anchor.lon, flat, flon);
        if (!Number.isFinite(navAnchor?.dist) || navAnchor.dist > Number(anchor.localRadiusNm || 20)) continue;

        const inferredCat = _poiInferCategoryFromFeature(f);
        const wantedCat = (!forceCat || forceCat === 'all') ? inferredCat : forceCat;
        const sightseeingAttractionMatch = isSightseeingProfile
            && forceCat === 'city'
            && _poiFeatureLooksSightseeingAttraction(f);
        if (forceCat && forceCat !== 'all' && !_poiFeatureMatchesCategory(f, forceCat) && !sightseeingAttractionMatch) continue;
        if (sarCorridorMode && !_poiFeatureMatchesCategory(f, 'sar_corridor')) continue;

        const rawName = String(f?.name || '').trim();
        const tf = f?.tags || {};
        const railTag = String(tf.railway || '').toLowerCase();
        const isSarLikeProfile = (profileId === 'search_and_rescue' || isSarHeliProfile);
        const isInfraOpsProfile = (profileId === 'inspection_infra' || profileId === 'infra_chain_recon' || profileId === 'mapping_survey');
        if (String(tf.infra_type || '').toLowerCase() === 'solar_roof' && (isInfraOpsProfile || forceCat === 'infrastructure' || forceCat === 'industry')) {
            continue;
        }
        let infraFallbackName = '';
        let name = _poiNormalizeFeatureName(rawName, wantedCat);
        if (!rawName && isInfraOpsProfile && (wantedCat === 'infrastructure' || wantedCat === 'industry' || forceCat === 'infrastructure' || forceCat === 'industry')) {
            infraFallbackName = _poiInfraFallbackName(tf, wantedCat);
            if (infraFallbackName) name = infraFallbackName;
        }
        if (!rawName && railTag && (wantedCat === 'rail' || forceCat === 'rail' || forceCat === 'infrastructure')) {
            name = _poiRailFallbackName(railTag);
        }
        const hasName = !!rawName || !!infraFallbackName;
        const isRailOpPoint = ['signal', 'switch', 'level_crossing', 'crossing'].includes(railTag);

        if (forceCat === 'dam' && !hasName && String(f?.sourceKind || '') === 'lin') continue;
        if (forceCat === 'road' && _poiIsSettlementOnlyFeature(f)) continue;
        if (forceCat === 'road' && !isSarLikeProfile) {
            if (!hasName) continue;
            if (String(f?.sourceKind || '') === 'poi' && !String(tf.highway || '').trim()) continue;
            if (String(tf.highway || '').toLowerCase() === 'motorway_junction') continue;
            if (_poiLooksJunctionLabel(name)) continue;
            if (_poiLooksTechnicalCodeName(name)) continue;
        }
        if (forceCat === 'infrastructure' && !hasName) {
            const strongInfra = (
                !!tf.infra_type ||
                !!tf.highway ||
                !!tf.railway ||
                ['line', 'minor_line', 'cable', 'tower', 'pole', 'storage', 'substation', 'plant', 'generator', 'transformer'].includes(String(tf.power || '').toLowerCase()) ||
                ['tower', 'mast', 'communications_tower', 'bridge', 'dyke', 'embankment', 'gasometer', 'pipeline', 'pumping_station', 'storage_tank', 'water_tower'].includes(String(tf.man_made || '').toLowerCase()) ||
                ['fuel', 'clinic', 'fire_station', 'hospital', 'police', 'post_office', 'recycling', 'school', 'townhall', 'university', 'waste_disposal', 'waste_transfer_station', 'water_works', 'wastewater_plant'].includes(String(tf.amenity || '').toLowerCase()) ||
                ['construction', 'depot', 'industrial', 'commercial', 'landfill', 'quarry', 'retail'].includes(String(tf.landuse || '').toLowerCase()) ||
                ['construction', 'civic', 'hospital', 'public', 'school', 'train_station', 'transportation', 'university'].includes(String(tf.building || '').toLowerCase()) ||
                ['noise_barrier', 'retaining_wall'].includes(String(tf.barrier || '').toLowerCase()) ||
                !!tf.tunnel ||
                !!tf.pipeline ||
                !!tf.monitoring_water_level ||
                !!tf.lock_tag ||
                !!tf.embankment ||
                !!tf.infra_cluster
            );
            if (!strongInfra) continue;
        }
        if (forceCat === 'infrastructure' && !isSarLikeProfile && !isInfraOpsProfile) {
            if (!hasName) continue;
            if (String(tf.highway || '').toLowerCase() === 'motorway_junction') continue;
            if (_poiLooksJunctionLabel(name)) continue;
            if (_poiIsCodeLikeName(name)) continue;
        }
        if (forceCat === 'rail' && !isSarLikeProfile && !isInfraOpsProfile) {
            if (isRailOpPoint && !hasName) continue;
            if (_poiIsNumericLikeName(name)) continue;
            if (_poiLooksTechnicalCodeName(name)) continue;
        }
        if (forceCat === 'telecom' && !isSarLikeProfile) {
            if (!hasName) continue;
            if (_poiIsNumericLikeName(name)) continue;
            if (_poiLooksTechnicalCodeName(name)) continue;
            if (String(tf.infra_type || '').toLowerCase() === 'wind') continue;
        }
        const dedupeKey = `${wantedCat}|${name.toLowerCase()}|${flat.toFixed(4)}|${flon.toFixed(4)}`;
        if (seen.has(dedupeKey)) continue;
        seen.add(dedupeKey);
        if (isKnowledgeGuideProfile) {
            if (!hasName || _poiIsGenericFallbackName(name)) continue;
            if (_poiIsCodeLikeName(name) || _poiIsNumericLikeName(name) || _poiLooksJunctionLabel(name)) continue;
        }

        const baseScore = _poiFeatureScore(f, wantedCat);
        const sightseeingInterest = isSightseeingProfile
            ? _poiSightseeingInterestScore({ n: name, name, tags: tf, category: wantedCat }, wantedCat)
            : 0;
        if (isSightseeingProfile && _poiSightseeingRequiresInterestCategory(wantedCat) && sightseeingInterest < 8) continue;
        const distMin = Number(minNM || 0);
        const distMax = Number(maxNM || 9999);
        const distMid = (distMin + distMax) / 2;
        const distHalf = Math.max(4, (distMax - distMin) / 2);
        const bandDeviation = Math.abs(Number(navStart.dist || 0) - distMid);
        const bandBonus = Math.max(-1.5, 2.5 - ((bandDeviation / distHalf) * 3.5));
        const distPenalty = (Math.min(80, Number(navAnchor.dist || 0)) * 0.30) + (Math.min(120, Number(navStart.dist || 0)) * 0.03);
        const nameBonus = hasName ? 2.0 : -1.5;
        const unnamedInfraPenalty = (forceCat === 'infrastructure' && !hasName) ? 7 : 0;
        const unnamedTelecomPenalty = (forceCat === 'telecom' && !hasName) ? 5 : 0;
        const isRailPointOp = isRailOpPoint;
        const railOpPenalty = (
            forceCat === 'rail' &&
            isRailPointOp &&
            profileId !== 'search_and_rescue' &&
            !isSarHeliProfile &&
            profileId !== 'inspection_infra' &&
            profileId !== 'infra_chain_recon' &&
            profileId !== 'mapping_survey'
        ) ? 7 : 0;
        const sightseeingBonus = isSightseeingProfile ? Math.max(-10, Math.min(18, sightseeingInterest)) : 0;
        const rank = baseScore + nameBonus + bandBonus + sightseeingBonus - distPenalty - unnamedInfraPenalty - unnamedTelecomPenalty - railOpPenalty;
        candidates.push({
            n: name,
            lat: flat,
            lon: flon,
            dist: navStart.dist,
            brng: navStart.brng,
            anchorDistNm: navAnchor.dist,
            category: wantedCat,
            score: baseScore,
            rank,
            sightseeingInterest,
            hasName,
            tags: tf && typeof tf === 'object' ? { ...tf } : {},
            fetchSource: String(f?.fetchSource || ''),
            featureSourceKind: String(f?.sourceKind || ''),
            featureLayer: String(f?.tags?.layer || '')
        });
    }
    if (!candidates.length) return null;

    // Wenn genug benannte Ziele vorhanden sind, bevorzugen wir diese strikt.
    // Das reduziert generische Ziele wie "Gewässer"/"Wasserreservoir", die später
    // häufig zu unpräzisen Story-Ortsnamen führen.
    let scoredCandidates = candidates;
    const namedCandidates = candidates.filter(c => !!c.hasName && !_poiIsGenericFallbackName(c.n));
    const forceStrictNamed = !!forceCat && forceCat !== 'all';
    if (forceStrictNamed && namedCandidates.length >= 3) {
        scoredCandidates = namedCandidates;
    }
    if (forceCat === 'infrastructure') {
        const namedInfra = scoredCandidates.filter(c => !!c.hasName && !_poiIsGenericFallbackName(c.n));
        if (namedInfra.length >= 1) scoredCandidates = namedInfra;
        const broadInfra = scoredCandidates.filter(c => !_poiInfraSubtypeHasOwnPickerCategory(_poiCandidateInfraSubtype(c)));
        if (broadInfra.length >= 6) scoredCandidates = broadInfra;
    }
    if (forceCat === 'telecom') {
        const namedTelecom = scoredCandidates.filter(c => !!c.hasName && !_poiIsGenericFallbackName(c.n));
        if (namedTelecom.length >= 1) scoredCandidates = namedTelecom;
    }
    if (forceCat === 'road' && profileId !== 'search_and_rescue' && !isSarHeliProfile) {
        const namedRoad = scoredCandidates.filter(c => !!c.hasName && !_poiIsGenericFallbackName(c.n) && !_poiLooksJunctionLabel(c.n));
        if (namedRoad.length >= 2) scoredCandidates = namedRoad;
        const roadFocused = scoredCandidates.filter(c => _poiCandidateIsRoadInspectionTarget(c));
        if (roadFocused.length >= 3) scoredCandidates = roadFocused;
    }
    if (forceCat === 'rail' && profileId !== 'search_and_rescue' && !isSarHeliProfile) {
        if (profileId !== 'inspection_infra' && profileId !== 'infra_chain_recon' && profileId !== 'mapping_survey') {
            const namedRail = scoredCandidates.filter(c => !!c.hasName && !_poiIsGenericFallbackName(c.n) && !_poiIsNumericLikeName(c.n));
            if (namedRail.length >= 2) scoredCandidates = namedRail;
        }
        const railFocused = scoredCandidates.filter(c => _poiCandidateIsRailInspectionTarget(c));
        if (railFocused.length >= 4) scoredCandidates = railFocused;
    }
    if (isKnowledgeGuideProfile) {
        const educationalNamed = scoredCandidates.filter(c => !!c.hasName && !_poiIsGenericFallbackName(c.n) && !_poiIsCodeLikeName(c.n) && !_poiIsNumericLikeName(c.n));
        if (educationalNamed.length >= 1) scoredCandidates = educationalNamed;
    }
    if (!scoredCandidates.length) return null;

    let pool = scoredCandidates;
    if (!forceCat || forceCat === 'all') {
        if (!isKnowledgeGuideProfile) {
            const balanced = pickBalancedByCategory(pool, p => p.category || 'generic', 'ga_poi_tag_cat');
            const targetCat = balanced?.category || pool[0]?.category || 'generic';
            pool = pool.filter(p => p.category === targetCat);
        }
    }
    pool.sort((a, b) => (b.rank - a.rank) || (b.score - a.score) || (a.dist - b.dist));
    pool = _poiMaybeRotateInfraSubtypePool(pool, forceCat, profileId);
    const topRaw = pool.slice(0, Math.min(12, pool.length));
    const top = (['infrastructure', 'telecom', 'industry', 'road', 'rail'].includes(String(forceCat || '').toLowerCase()))
        ? _poiLimitPerCluster(topRaw, 2)
        : topRaw;
    let knowledgeGateResult = null;
    let knowledgeGateShortlist = null;
    let pick = isKnowledgeGuideProfile
        ? null
        : (_pickPoiCandidateWithHistory(top, (top[0]?.category || forceCat || 'generic'), 12, anchor) || top[0] || pool[0]);
    if (isKnowledgeGuideProfile) {
        knowledgeGateShortlist = _poiKnowledgeBalancedShortlist(pool, {
            maxCandidates: POI_KNOWLEDGE_AUTO_MAX_CANDIDATES
        });
        knowledgeGateResult = await _poiKnowledgePickAcceptedCandidate(knowledgeGateShortlist.shortlist, {
            budgetMs: POI_KNOWLEDGE_AUTO_BUDGET_MS
        });
        if (!knowledgeGateResult?.pick) return null;
        pick = knowledgeGateResult.pick;
    }
    const usedCat = String((pick && pick.category) || forceCat || 'generic').toLowerCase();
    const dbgBeforeFinalMark = { ..._poiDebugState() };
    _poiDebugMarkSource(String(pick?.fetchSource || '').trim() || String(dbgBeforeFinalMark.lastSource || ''));
    const dbgEnd = { ..._poiDebugState() };
    const selectedFetchSource = String(pick?.fetchSource || '');
    let sourceLabel = `Hosted POI Tiles (split, tagged:${usedCat})`;
    if (selectedFetchSource.includes('infra')) {
        sourceLabel = selectedFetchSource.startsWith('local-')
            ? `Local Infra Tiles (split, tagged:${usedCat})`
            : `Hosted Infra Tiles (worker split, tagged:${usedCat})`;
    } else if (selectedFetchSource.startsWith('local-')) {
        sourceLabel = `Local POI Tiles (split, tagged:${usedCat})`;
    } else if (selectedFetchSource.includes('legacy')) {
        sourceLabel = `Hosted POI Tiles (legacy fallback, tagged:${usedCat})`;
    } else if (selectedFetchSource.startsWith('worker-')) {
        sourceLabel = `Hosted POI Tiles (worker split, tagged:${usedCat})`;
    }
    const lookupDebug = {
        includeCore,
        includeInfra,
        allowLegacyFallback,
        anchorStrategy: anchor.strategy,
        anchorDistNm: Number(anchor.distNm || 0),
        anchorBearingDeg: Number(anchor.bearingDeg || 0),
        anchorRadiusNm: Number(anchor.localRadiusNm || 0),
        anchorLat: Number(anchor.lat || 0),
        anchorLon: Number(anchor.lon || 0),
        tileKeys: tileKeys.length,
        features: features.length,
        candidates: candidates.length,
        requestsDelta: Math.max(0, Number(dbgEnd.requests || 0) - Number(dbgStart.requests || 0)),
        hitsDelta: Math.max(0, Number(dbgEnd.hits || 0) - Number(dbgStart.hits || 0)),
        splitHitsDelta: Math.max(0, Number(dbgEnd.splitHits || 0) - Number(dbgStart.splitHits || 0)),
        legacyHitsDelta: Math.max(0, Number(dbgEnd.legacyHits || 0) - Number(dbgStart.legacyHits || 0)),
        fallbackHitsDelta: Math.max(0, Number(dbgEnd.fallbackHits || 0) - Number(dbgStart.fallbackHits || 0)),
        errorsDelta: Math.max(0, Number(dbgEnd.errors || 0) - Number(dbgStart.errors || 0)),
        lastSource: String(dbgEnd.lastSource || ''),
        selectedFetchSource: selectedFetchSource || 'n/a',
        localPoiSplitHits: Number(dbgEnd.localPoiSplitHits || 0),
        localCoreSplitHits: Number(dbgEnd.localCoreSplitHits || 0),
        localInfraSplitHits: Number(dbgEnd.localInfraSplitHits || 0),
        workerPoiSplitHits: Number(dbgEnd.workerPoiSplitHits || 0),
        workerCoreSplitHits: Number(dbgEnd.workerCoreSplitHits || 0),
        workerInfraSplitHits: Number(dbgEnd.workerInfraSplitHits || 0),
        cacheEntries: Number(dbgEnd.cacheEntries || 0)
    };
    return {
        icao: 'POI',
        n: pick.n,
        lat: pick.lat,
        lon: pick.lon,
        poiCategory: usedCat,
        poiSource: sourceLabel,
        knowledgeContext: pick.knowledgeContext || null,
        poiLookup: {
            engine: 'hosted-poi-tiles',
            featureSourceKind: String(pick?.featureSourceKind || ''),
            featureLayer: String(pick?.featureLayer || ''),
            selectedDistNm: Number(pick?.dist || 0),
            selectedAnchorDistNm: Number(pick?.anchorDistNm || 0),
            selectedBrgDeg: Number(pick?.brng || 0),
            selectedHasName: !!pick?.hasName,
            selectedSightseeingInterest: Number(pick?.sightseeingInterest || 0),
            selectedInfraType: String(pick?.tags?.infra_type || ''),
            selectedTags: pick?.tags && typeof pick.tags === 'object' ? Object.fromEntries(
                Object.entries(pick.tags)
                    .filter(([k, v]) => k && v !== undefined && v !== null && String(v).length <= 80)
                    .slice(0, 18)
            ) : null,
            knowledgeGate: isKnowledgeGuideProfile ? {
                status: String(knowledgeGateResult?.status || 'n/a'),
                stopReason: String(knowledgeGateResult?.stopReason || ''),
                elapsedMs: Number(knowledgeGateResult?.elapsedMs || 0),
                eligible: Number(knowledgeGateShortlist?.eligibleCount || 0),
                rejected: Number(knowledgeGateShortlist?.rejected?.length || 0),
                shortlist: (knowledgeGateShortlist?.shortlist || []).map(c => ({
                    name: c.n,
                    category: c.category || 'generic',
                    bucket: c.knowledgeBucket || 'generic'
                })),
                evaluated: (knowledgeGateResult?.evaluated || []).slice(0, 4)
            } : null,
            knowledgeTitle: String(pick?.knowledgeContext?.title || ''),
            knowledgeStatus: String(pick?.knowledgeContext?.status || ''),
            knowledgeScore: Number(pick?.knowledgeContext?.score || 0),
            knowledgeFacts: Number(pick?.knowledgeContext?.selectedFacts || 0),
            knowledgeWarnings: Array.isArray(pick?.knowledgeContext?.warnings) ? pick.knowledgeContext.warnings.slice(0, 5) : [],
            ...lookupDebug
        }
    };
}

function _isDamLikeNominatimItem(item) {
    if (!item) return false;
    const hay = normalizeMissionText([
        item.name,
        item.display_name,
        item.class,
        item.category,
        item.type,
        item.addresstype
    ].filter(Boolean).join(' '));
    if (
        _hasWordToken(hay, 'staudamm') ||
        _hasWordToken(hay, 'talsperre') ||
        _hasWordToken(hay, 'stausee') ||
        _hasWordToken(hay, 'sperrmauer') ||
        _hasWordToken(hay, 'reservoir') ||
        _hasWordToken(hay, 'damm') ||
        _hasWordToken(hay, 'dam') ||
        _hasWordToken(hay, 'wehr')
    ) return true;
    const cls = String(item.class || item.category || '').toLowerCase();
    const type = String(item.type || '').toLowerCase();
    return (
        (cls === 'waterway' && (type === 'dam' || type === 'weir')) ||
        (cls === 'landuse' && type === 'reservoir') ||
        (cls === 'water' && (type === 'dam' || type === 'reservoir'))
    );
}

async function findNominatimDamPOI(lat, lon) {
    const vb = _buildViewBoxAround(lat, lon, 18);
    const queries = ['staudamm', 'talsperre', 'stausee', 'reservoir', 'dam', 'wehr'];
    const seen = new Set();
    const candidates = [];

    for (const q of queries) {
        try {
            const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&limit=20&bounded=1&q=${encodeURIComponent(q)}&viewbox=${encodeURIComponent(`${vb.west},${vb.north},${vb.east},${vb.south}`)}`;
            const res = await fetch(url);
            if (!res.ok) continue;
            const list = await res.json();
            if (!Array.isArray(list)) continue;
            for (const it of list) {
                const key = `${it.osm_type || '?'}:${it.osm_id || '?'}:${it.lat || '?'}:${it.lon || '?'}`;
                if (seen.has(key)) continue;
                seen.add(key);
                if (!_isDamLikeNominatimItem(it)) continue;
                const ilat = Number(it.lat);
                const ilon = Number(it.lon);
                if (!Number.isFinite(ilat) || !Number.isFinite(ilon)) continue;
                const dNm = calcNav(lat, lon, ilat, ilon).dist;
                if (!Number.isFinite(dNm) || dNm > 18.5) continue;
                const name = String(it.name || it.display_name || '').split(',')[0].trim();
                candidates.push({
                    n: name || 'Staudamm/Talsperre',
                    lat: ilat,
                    lon: ilon,
                    dNm,
                    importance: Number(it.importance || 0)
                });
            }
        } catch (_) {}
    }

    if (candidates.length === 0) return null;
    candidates.sort((a, b) => (a.dNm - b.dNm) || (b.importance - a.importance));
    const pick = candidates[0];
    return { icao: 'POI', n: pick.n, lat: pick.lat, lon: pick.lon, poiCategory: 'dam', poiSource: 'Nominatim (dam typed)' };
}

function _parseWktPoint(wkt) {
    const m = String(wkt || '').match(/Point\(\s*([-\d.]+)\s+([-\d.]+)\s*\)/i);
    if (!m) return null;
    const lon = Number(m[1]);
    const lat = Number(m[2]);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    return { lat, lon };
}

function _wikidataTypeQidsForPoiCategory(category = '') {
    const cat = String(category || '').toLowerCase();
    if (cat === 'water') {
        // reservoir, lake, river, sea, dam
        return ['Q131681', 'Q23397', 'Q4022', 'Q165', 'Q12323'];
    }
    if (cat === 'mountain') {
        // mountain, valley, mountain pass, mountain range
        return ['Q8502', 'Q39816', 'Q133056', 'Q46831'];
    }
    if (cat === 'castle') {
        // castle, fortress, ruins
        return ['Q23413', 'Q1785071', 'Q839954'];
    }
    if (cat === 'dam') {
        // dam, reservoir
        return ['Q12323', 'Q131681'];
    }
    if (cat === 'bridge') {
        // bridge, viaduct
        return ['Q12280', 'Q181348'];
    }
    if (cat === 'telecom') {
        // tower, telecommunications tower
        return ['Q12518', 'Q11166728'];
    }
    if (cat === 'industry') {
        // industrial facility, factory, power station
        return ['Q16686448', 'Q83405', 'Q159719'];
    }
    return [];
}

const _poiEducationalContextCache = new Map();
const POI_KNOWLEDGE_CONTEXT_ACCEPT_SCORE = 70;
const POI_KNOWLEDGE_CONTEXT_REVIEW_SCORE = 55;
const POI_KNOWLEDGE_AUTO_MAX_CANDIDATES = 3;
const POI_KNOWLEDGE_AUTO_BUDGET_MS = 2500;
const POI_KNOWLEDGE_WIKI_TIMEOUT_MS = 2200;
const POI_KNOWLEDGE_WIKI_EXTRACT_CHARS = 7200;
const POI_KNOWLEDGE_CORE_FACT_LIMIT = 10;
const POI_KNOWLEDGE_EXTRA_FACT_LIMIT = 20;
const POI_KNOWLEDGE_429_COOLDOWN_MS = 60 * 1000;
const POI_SIGHTSEEING_KNOWLEDGE_BUDGET_MS = 2200;
const APT_SIGHTSEEING_KNOWLEDGE_BUDGET_MS = 2800;
const APT_SIGHTSEEING_LANDMARK_LIMIT = 5;
let _poiKnowledgeWikiCooldownUntil = 0;
const _aptSightseeingKnowledgeCache = new Map();

function _poiKnowledgeNormalizeKey(value) {
    return String(value || '')
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/ß/g, 'ss')
        .replace(/[^a-z0-9]+/g, '');
}

function _poiKnowledgeTitleMatch(a, b) {
    const aa = _poiKnowledgeNormalizeKey(a);
    const bb = _poiKnowledgeNormalizeKey(b);
    return !!(aa && bb && (aa.includes(bb) || bb.includes(aa)));
}

function _poiKnowledgeDistanceKm(lat1, lon1, lat2, lon2) {
    if (![lat1, lon1, lat2, lon2].every(Number.isFinite)) return null;
    const radiusKm = 6371;
    const toRad = value => value * Math.PI / 180;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat / 2) ** 2
        + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
    return 2 * radiusKm * Math.asin(Math.sqrt(a));
}

function _isUsefulWikiExtract(text) {
    const raw = String(text || '').replace(/\s+/g, ' ').trim();
    if (!raw) return false;
    if (raw.length < 140) return false;
    if (/(keine regionalen wikipedia-daten gefunden|artikel konnte nicht|wiki-daten konnten nicht geladen|nicht abrufbar)/i.test(raw)) return false;
    return true;
}

function _poiKnowledgeCleanWikiText(value) {
    return String(value || '')
        .replace(/\[\d+\]/g, '')
        .replace(/==+\s*[^=]+\s*==+/g, '. ')
        .replace(/\s+/g, ' ')
        .trim();
}

function _poiKnowledgeProtectSentenceDots(text) {
    return String(text || '')
        .replace(/\b(\d{1,2})\.\s+(Januar|Februar|März|Maerz|April|Mai|Juni|Juli|August|September|Oktober|November|Dezember)\b/g, '$1<DOT> $2')
        .replace(/\b(St)\.\s+(?=[A-ZÄÖÜ])/g, '$1<DOT> ')
        .replace(/\b(z)\.\s*(B)\./gi, '$1<DOT> $2<DOT>');
}

function _poiKnowledgeSplitFacts(text) {
    const cleaned = _poiKnowledgeProtectSentenceDots(_poiKnowledgeCleanWikiText(text));
    if (!cleaned) return [];
    return cleaned
        .split(/(?<=[.!?])\s+(?=[A-ZÄÖÜ0-9])/)
        .map(s => s.replace(/<DOT>/g, '.').trim())
        .map(s => s.replace(/^(Freizeit|Geografie|Geschichte|Technische Daten|Nutzung|Beschreibung|Bauwerk)\s+/i, '').trim())
        .filter(s => s.length >= 45)
        .filter(s => !/^(siehe auch|literatur|weblinks|einzelnachweise|normdaten)\b/i.test(s))
        .filter(s => !/\b(ISBN|Systemdruck|Verlag|Literatur|Weblinks|Einzelnachweise|Normdaten|Auflage|Hrsg\.)\b/i.test(s))
        .filter(s => !/^(januar|februar|märz|maerz|april|mai|juni|juli|august|september|oktober|november|dezember)\b/i.test(s))
        .filter(s => !/begriffsklärung|liste von|steht für|kann bedeuten/i.test(s));
}

function _poiKnowledgeFactTopics(sentence) {
    const text = String(sentence || '').toLowerCase();
    const topics = [];
    if (/\b(erbaut|gebaut|bauzeit|in betrieb|eröffnet|eroeffnet|errichtet|jahrhundert|gründ|gruend|stillgelegt|unesco|denkmal|geschichte|histor)/.test(text)) topics.push('history');
    if (/\b(liegt|lage|befindet|mündet|muendet|fluss|tal|region|landkreis|stadt|gemeinde|ufer|zufluss|abfluss|ortsteil)/.test(text)) topics.push('location');
    if (/\b(meter|kilometer|km|mio|million|höhe|hoehe|länge|laenge|fläche|flaeche|volumen|einwohner|kapazität|kapazitaet|spannweite|stau|kronen|speicher)/.test(text)) topics.push('metrics');
    if (/\b(dient|nutzung|versorgt|freizeit|tourismus|seg|surf|baden|rad|spazier|stadion|veranstaltung|museum|naherholung|aussichtsplattform)/.test(text)) topics.push('use');
    if (/\b(architekt|stil|bauwerk|kirche|dom|brücke|bruecke|turm|damm|anlage|industr|konstruktion|bogen|stahl|beton|mauer|viadukt)/.test(text)) topics.push('structure');
    if (/\b(natur|schutzgebiet|wald|landschaft|see|fluss|park|ökolog|oekolog|vogel|lebensraum|schwarzwald|ufer)/.test(text)) topics.push('nature');
    return topics.length ? [...new Set(topics)] : ['general'];
}

function _poiKnowledgePickFacts(text, maxFacts = POI_KNOWLEDGE_CORE_FACT_LIMIT, maxExtraFacts = POI_KNOWLEDGE_EXTRA_FACT_LIMIT) {
    const candidates = _poiKnowledgeSplitFacts(text).map(sentence => ({
        source: 'extract',
        topic: _poiKnowledgeFactTopics(sentence)[0],
        topics: _poiKnowledgeFactTopics(sentence),
        text: sentence
    }));
    const selected = [];
    const topicCount = new Map();
    const selectedKeys = new Set();
    for (const fact of candidates) {
        const topic = fact.topic || 'general';
        const current = topicCount.get(topic) || 0;
        if (current >= 2) continue;
        selected.push(fact);
        selectedKeys.add(fact.text);
        topicCount.set(topic, current + 1);
        if (selected.length >= maxFacts) break;
    }
    for (const fact of candidates) {
        if (selected.length >= maxFacts) break;
        if (selectedKeys.has(fact.text)) continue;
        selected.push(fact);
        selectedKeys.add(fact.text);
    }
    const extra = [];
    const extraLimit = Math.max(0, Math.min(40, Math.round(Number(maxExtraFacts) || 0)));
    for (const fact of candidates) {
        if (extra.length >= extraLimit) break;
        if (selectedKeys.has(fact.text)) continue;
        extra.push(fact);
        selectedKeys.add(fact.text);
    }
    return {
        candidates,
        selected,
        extra,
        topics: [...new Set(selected.flatMap(fact => fact.topics || [fact.topic || 'general']))].sort()
    };
}

function _poiKnowledgeCategoryProfile(category = '') {
    const value = String(category || '').toLowerCase();
    return {
        raw: value,
        isLinear: /water|lake|river|fluss|see|canal/.test(value),
        isCity: /city|town|village|settlement|ort/.test(value),
        isTechnical: /bridge|dam|tower|telecom|industry|stadium|religious|monument/.test(value),
        isCompactInfrastructure: /bridge|dam|tower|telecom/.test(value),
        isSupportedKnowledgeType: /city|town|village|settlement|ort|castle|historic|water|lake|river|canal|bridge|dam|tower|telecom|industry|stadium|religious|monument|nature|mountain/.test(value)
    };
}

function _poiKnowledgeIsGenericLinearTitle(title) {
    const key = _poiKnowledgeNormalizeKey(title);
    return [
        'bach',
        'baggersee',
        'feuerloschteich',
        'feuerloeschteich',
        'gewasser',
        'gewaesser',
        'weiher',
        'teich',
        'loschteich',
        'loeschteich',
        'loschwasserteich',
        'loeschwasserteich',
        'see',
        'fluss',
        'kanal',
        'graben',
        'quelle',
        'regenruckhaltebecken',
        'regenrueckhaltebecken',
        'reservoir',
        'ruckhaltebecken',
        'rueckhaltebecken',
        'wasserbecken',
        'wasserreservoir',
        'stausee'
    ].includes(key);
}

function _poiKnowledgeGenericTypeArticleReason(title, category = '') {
    const key = _poiKnowledgeNormalizeKey(title);
    if (!key) return '';
    const cat = String(category || '').toLowerCase();
    const genericWaterTypes = new Set([
        'baggersee',
        'feuerloschteich',
        'feuerloeschteich',
        'gewasser',
        'gewaesser',
        'loschteich',
        'loeschteich',
        'loschwasserteich',
        'loeschwasserteich',
        'regenruckhaltebecken',
        'regenrueckhaltebecken',
        'ruckhaltebecken',
        'rueckhaltebecken',
        'wasserbecken',
        'wasserreservoir'
    ]);
    if (/water|lake|river|canal|dam/.test(cat) && genericWaterTypes.has(key)) {
        return 'generic_type_article_without_coordinate';
    }
    return '';
}

function _poiKnowledgeHasLinearEvidence(extract) {
    const text = _poiKnowledgeNormalizeKey(extract);
    return /fluss|strom|see|stausee|talsperre|gewaesser|gewasser|zufluss|abfluss|quelle|muendung|mundung|laenge|lange|seelaenge|speicherraum|uferort|einzugsgebiet/.test(text);
}

function _poiKnowledgeCooldownRemainingMs() {
    return Math.max(0, Number(_poiKnowledgeWikiCooldownUntil || 0) - Date.now());
}

function _poiKnowledgeRateLimitedContext(title = '') {
    return {
        ok: false,
        status: 'rate_limited',
        rateLimited: true,
        title: String(title || '').trim(),
        extract: '',
        warnings: ['wiki_rate_limit_cooldown'],
        retryAfterMs: _poiKnowledgeCooldownRemainingMs()
    };
}

function _poiKnowledgeApplyRateLimitCooldown(response) {
    const retryAfterSec = Number(response?.headers?.get?.('retry-after') || 0);
    const waitMs = retryAfterSec > 0
        ? Math.max(15000, Math.min(POI_KNOWLEDGE_429_COOLDOWN_MS, retryAfterSec * 1000))
        : POI_KNOWLEDGE_429_COOLDOWN_MS;
    _poiKnowledgeWikiCooldownUntil = Math.max(_poiKnowledgeWikiCooldownUntil || 0, Date.now() + waitMs);
    return waitMs;
}

async function _poiKnowledgeFetchJson(url, timeoutMs = POI_KNOWLEDGE_WIKI_TIMEOUT_MS) {
    const controller = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    let timer = null;
    if (controller && Number.isFinite(Number(timeoutMs)) && Number(timeoutMs) > 0) {
        timer = setTimeout(() => {
            try { controller.abort(); } catch (_) {}
        }, Math.max(500, Number(timeoutMs)));
    }
    try {
        const res = await fetch(url, controller ? { signal: controller.signal } : undefined);
        return res;
    } finally {
        if (timer) clearTimeout(timer);
    }
}

async function _fetchWikiExtractByTitle(title, options = {}) {
    const t = String(title || '').trim();
    if (!t) return null;
    if (_poiKnowledgeCooldownRemainingMs() > 0) return _poiKnowledgeRateLimitedContext(t);
    try {
        const params = new URLSearchParams({
            action: 'query',
            redirects: '1',
            prop: 'extracts|coordinates|pageprops|pageimages|info',
            inprop: 'url',
            explaintext: '1',
            exchars: String(POI_KNOWLEDGE_WIKI_EXTRACT_CHARS),
            exsectionformat: 'plain',
            piprop: 'thumbnail',
            pithumbsize: '600',
            titles: t,
            format: 'json',
            origin: '*'
        });
        const extRes = await _poiKnowledgeFetchJson(`https://de.wikipedia.org/w/api.php?${params.toString()}`, options.timeoutMs || POI_KNOWLEDGE_WIKI_TIMEOUT_MS);
        if (extRes.status === 429) {
            const retryAfterMs = _poiKnowledgeApplyRateLimitCooldown(extRes);
            return { ..._poiKnowledgeRateLimitedContext(t), retryAfterMs };
        }
        if (!extRes.ok) return null;
        const extData = await extRes.json();
        const pages = Object.values(extData?.query?.pages || {});
        const page = pages.find(p => p && p.missing === undefined && String(p.pageid || '') !== '-1') || null;
        if (!page) return null;
        const redirects = Array.isArray(extData?.query?.redirects) ? extData.query.redirects : [];
        const redirect = redirects.find(r => _poiKnowledgeTitleMatch(r?.from, t)) || redirects[0] || null;
        const extract = String(page?.extract || '').trim();
        return {
            title: String(page?.title || t).trim(),
            extract,
            page,
            redirectedTo: redirect?.to || null
        };
    } catch (_) {
        return null;
    }
}

function _poiKnowledgeScoreContext({ queryTitle = '', category = '', lat = null, lon = null, wiki = null } = {}) {
    const page = wiki?.page || null;
    const extract = String(wiki?.extract || page?.extract || '').trim();
    const title = String(wiki?.title || page?.title || queryTitle || '').trim();
    const profile = _poiKnowledgeCategoryProfile(category);
    const facts = _poiKnowledgePickFacts(extract, POI_KNOWLEDGE_CORE_FACT_LIMIT, POI_KNOWLEDGE_EXTRA_FACT_LIMIT);
    const qid = String(page?.pageprops?.wikibase_item || '').trim();
    const thumb = page?.thumbnail?.source || '';
    const coordinate = page?.coordinates?.[0] || null;
    const dist = coordinate && Number.isFinite(Number(lat)) && Number.isFinite(Number(lon))
        ? _poiKnowledgeDistanceKm(Number(lat), Number(lon), Number(coordinate.lat), Number(coordinate.lon))
        : null;
    const exactTitle = _poiKnowledgeTitleMatch(title, queryTitle);
    const reasons = [];
    const warnings = [];
    let score = 0;

    if (extract.length >= 2200) { score += 32; reasons.push('long_extract'); }
    else if (extract.length >= 1200) { score += 26; reasons.push('solid_extract'); }
    else if (extract.length >= 650) { score += 18; reasons.push('medium_extract'); }
    else if (extract.length >= 350) { score += 10; reasons.push('short_but_usable_extract'); }
    else warnings.push('thin_extract');

    if (facts.candidates.length >= 12) { score += 30; reasons.push('many_fact_candidates'); }
    else if (facts.candidates.length >= 8) { score += 24; reasons.push('good_fact_count'); }
    else if (facts.candidates.length >= 6) { score += 18; reasons.push('acceptable_fact_count'); }
    else if (facts.candidates.length >= 4) { score += 10; reasons.push('low_fact_count'); }
    else warnings.push('too_few_facts');

    if (facts.selected.length >= 6) { score += 10; reasons.push('enough_voice_facts'); }
    if (facts.topics.length >= 4) { score += 12; reasons.push('topic_diversity'); }
    else if (facts.topics.length >= 3) score += 8;
    else if (facts.topics.length >= 2) score += 4;
    else warnings.push('low_topic_diversity');

    if (qid) { score += 10; reasons.push('wikidata_qid'); }
    if (thumb) { score += 5; reasons.push('page_image'); }
    if (exactTitle) { score += 12; reasons.push('title_match'); }
    if (wiki?.redirectedTo) {
        reasons.push('redirect_resolved');
        if (!exactTitle && profile.isCity) warnings.push('city_redirect_or_parent_context');
    }

    if (Number.isFinite(dist)) {
        if (profile.isLinear) {
            if (dist < 80) score += 6;
            else warnings.push('linear_feature_coordinate_far_from_target');
        } else if (dist < 1) {
            score += 15;
            reasons.push('coordinate_close');
        } else if (dist < 5) {
            score += 10;
            reasons.push('coordinate_near');
        } else if (dist < 12) {
            score += 3;
            warnings.push('coordinate_loose');
        } else {
            score -= 14;
            warnings.push('coordinate_far');
        }
    } else if (exactTitle && profile.isTechnical) {
        score += 3;
        warnings.push('no_page_coordinate_but_exact_title');
    } else {
        warnings.push('no_page_coordinate');
    }

    if (profile.isCompactInfrastructure && facts.candidates.length >= 4 && /\b(höchste|hoechste|größte|groesste|längste|laengste|meter|mio|million|bauzeit|erbaut|in betrieb|kronen|spannweite)\b/i.test(extract)) {
        score += 12;
        reasons.push('compact_infrastructure_bonus');
    }

    let status = 'reject';
    if (score >= POI_KNOWLEDGE_CONTEXT_ACCEPT_SCORE) status = 'accept';
    else if (score >= POI_KNOWLEDGE_CONTEXT_REVIEW_SCORE) status = 'review';

    if (status === 'accept' && profile.isCity && !exactTitle) {
        status = 'review';
        warnings.push('city_target_shift_requires_review');
    }
    if (!profile.isSupportedKnowledgeType) {
        status = score >= POI_KNOWLEDGE_CONTEXT_REVIEW_SCORE ? 'review' : 'reject';
        warnings.push('unsupported_knowledge_category');
    }
    if (status === 'accept' && profile.isLinear && _poiKnowledgeIsGenericLinearTitle(title)) {
        status = 'reject';
        warnings.push('generic_linear_article_title');
    }
    const genericTypeArticleReason = _poiKnowledgeGenericTypeArticleReason(title, category);
    if (status === 'accept' && !Number.isFinite(dist) && genericTypeArticleReason) {
        status = 'reject';
        warnings.push(genericTypeArticleReason);
    }
    if (status === 'accept' && profile.isLinear && !Number.isFinite(dist) && !_poiKnowledgeHasLinearEvidence(extract)) {
        status = 'review';
        warnings.push('linear_target_without_coordinate_or_water_evidence');
    }
    if (status === 'accept' && facts.selected.length < 5) {
        status = 'review';
        warnings.push('too_few_selected_voice_facts_for_auto_accept');
    }

    return {
        ok: status === 'accept',
        status,
        title,
        extract,
        score,
        category: profile.raw || category || 'generic',
        qid: qid || null,
        sourceUrl: page?.fullurl || null,
        redirectedTo: wiki?.redirectedTo || null,
        exactTitle,
        distanceKm: Number.isFinite(dist) ? Number(dist.toFixed(2)) : null,
        factCandidates: facts.candidates.length,
        selectedFacts: facts.selected.length,
        topics: facts.topics,
        facts: facts.selected.map(fact => ({
            source: fact.source,
            topic: fact.topic,
            text: fact.text
        })),
        extraFacts: facts.extra.map(fact => ({
            source: fact.source,
            topic: fact.topic,
            text: fact.text
        })),
        extraSelectedFacts: facts.extra.length,
        reasons,
        warnings,
        rateLimited: false
    };
}

async function _resolveEducationalPoiContext(title, lat, lon, category = 'generic', options = {}) {
    const t = String(title || '').trim();
    const cat = String(category || 'generic').toLowerCase();
    const latN = Number(lat);
    const lonN = Number(lon);
    if (_poiKnowledgeCooldownRemainingMs() > 0) return _poiKnowledgeRateLimitedContext(t);
    const key = `${t.toLowerCase()}|${cat}|${Number.isFinite(latN) ? latN.toFixed(4) : 'nan'}|${Number.isFinite(lonN) ? lonN.toFixed(4) : 'nan'}`;
    if (_poiEducationalContextCache.has(key)) return _poiEducationalContextCache.get(key);

    const wiki = await _fetchWikiExtractByTitle(t, options);
    if (wiki?.rateLimited) return wiki;
    const out = (wiki && _isUsefulWikiExtract(wiki.extract))
        ? _poiKnowledgeScoreContext({ queryTitle: t, category: cat, lat: latN, lon: lonN, wiki })
        : {
            ok: false,
            status: 'reject',
            title: t,
            extract: '',
            category: cat,
            score: 0,
            factCandidates: 0,
            selectedFacts: 0,
            facts: [],
            reasons: [],
            warnings: ['missing_wikipedia_page'],
            rateLimited: false
        };
    _poiEducationalContextCache.set(key, out);
    return out;
}

function _missionSightseeingAptWikiTitleCandidates(place = '', airportName = '') {
    const rawPlace = String(place || '').replace(/\s+/g, ' ').trim();
    const rawAirport = String(airportName || '').replace(/\s+/g, ' ').trim();
    const candidates = [];
    const push = value => {
        const clean = String(value || '').replace(/\s+/g, ' ').trim();
        if (!clean) return;
        const key = _poiKnowledgeNormalizeKey(clean);
        if (!key || candidates.some(item => _poiKnowledgeNormalizeKey(item) === key)) return;
        candidates.push(clean);
    };
    push(rawPlace);
    if (/\bfreiburg\b/i.test(rawPlace)) {
        push('Freiburg im Breisgau');
    }
    const hyphenBase = rawPlace.replace(/\s*[-–]\s*[^-–]+$/, '').trim();
    if (hyphenBase && hyphenBase !== rawPlace) push(hyphenBase);
    const airportPlace = _missionSightseeingAptPlaceLabel(rawAirport);
    if (airportPlace && airportPlace !== rawPlace) push(airportPlace);
    if (/\bleutkirch\b/i.test(rawPlace) || /\bleutkirch\b/i.test(rawAirport)) {
        push('Leutkirch im Allgäu');
        push('Leutkirch im Allgaeu');
    }
    return candidates.slice(0, 6);
}

function _missionSightseeingAptLandmarkScore(title = '', place = '') {
    const t = normalizeMissionText(title);
    const p = normalizeMissionText(place);
    if (!t) return -999;
    if (/\b(flugplatz|airport|aerodrome|landeplatz|runway|startbahn|iata|icao)\b/.test(t)) return -80;
    if (/\b(liste|begriffsklaerung|begriffsklarung|verwaltungsgemeinschaft|landkreis|wahlkreis|person)\b/.test(t)) return -40;
    let score = 0;
    if (p && t.includes(p)) score += 8;
    if (/\b(altstadt|muenster|munster|dom|kathedrale|kirche|kloster|schloss|burg|ruine|museum|denkmal|theater|rathaus|marktplatz|markt|tor|turm|aussicht|schlossberg|baechle|bächle|park|garten|promenade|see|hafen|bruecke|brücke|schwarzwald|allgaeu|allgäu)\b/.test(t)) score += 35;
    if (/\b(stadt|ort|gemeinde|stadtteil|viertel)\b/.test(t)) score += 8;
    if (/\b(bahnhof|messe|stadion|universitaet|universität|schule|strasse|straße)\b/.test(t)) score -= 6;
    return score;
}

function _missionSightseeingAptLandmarkTopic(title = '') {
    const t = normalizeMissionText(title);
    if (/\b(muenster|munster|dom|kathedrale|kirche|kloster)\b/.test(t)) return 'religious';
    if (/\b(schloss|burg|ruine)\b/.test(t)) return 'castle';
    if (/\b(museum|denkmal|theater|rathaus|marktplatz|altstadt|tor)\b/.test(t)) return 'culture';
    if (/\b(aussicht|berg|schlossberg|turm|park|garten|see|hafen|promenade|schwarzwald|allgaeu|allgäu)\b/.test(t)) return 'landscape';
    return 'landmark';
}

async function _missionSightseeingFetchNearbyWikiLandmarks(lat, lon, place = '', options = {}) {
    const latN = Number(lat);
    const lonN = Number(lon);
    if (!Number.isFinite(latN) || !Number.isFinite(lonN)) return [];
    if (_poiKnowledgeCooldownRemainingMs() > 0) return [];
    try {
        const params = new URLSearchParams({
            action: 'query',
            list: 'geosearch',
            gscoord: `${latN}|${lonN}`,
            gsradius: String(Math.max(2500, Math.min(18000, Number(options.radiusM || 12000)))),
            gslimit: '30',
            format: 'json',
            origin: '*'
        });
        const res = await _poiKnowledgeFetchJson(`https://de.wikipedia.org/w/api.php?${params.toString()}`, options.timeoutMs || POI_KNOWLEDGE_WIKI_TIMEOUT_MS);
        if (res.status === 429) {
            _poiKnowledgeApplyRateLimitCooldown(res);
            return [];
        }
        if (!res.ok) return [];
        const data = await res.json();
        const rows = Array.isArray(data?.query?.geosearch) ? data.query.geosearch : [];
        return rows
            .map(row => {
                const title = String(row?.title || '').replace(/\s+/g, ' ').trim();
                const distM = Number(row?.dist);
                return {
                    title,
                    distanceKm: Number.isFinite(distM) ? Number((distM / 1000).toFixed(1)) : null,
                    topic: _missionSightseeingAptLandmarkTopic(title),
                    score: _missionSightseeingAptLandmarkScore(title, place)
                };
            })
            .filter(item => item.title && item.score > 0)
            .sort((a, b) => (b.score - a.score) || ((a.distanceKm ?? 999) - (b.distanceKm ?? 999)) || a.title.localeCompare(b.title, 'de'))
            .slice(0, APT_SIGHTSEEING_LANDMARK_LIMIT);
    } catch (_) {
        return [];
    }
}

function _missionSightseeingAptLandmarkFacts(place = '', landmarks = []) {
    const names = (Array.isArray(landmarks) ? landmarks : [])
        .map(item => String(item?.title || item || '').replace(/\s+/g, ' ').trim())
        .filter(Boolean)
        .slice(0, APT_SIGHTSEEING_LANDMARK_LIMIT);
    if (!names.length) return [];
    return [{
        source: 'wikipedia_geosearch',
        topic: 'landmark',
        text: `Nahe ${place || 'dem Zielort'} bieten sich ${names.join(', ')} als Sehenswuerdigkeiten fuer den privaten Zielplan nach der Landung an.`
    }];
}

async function resolveAptSightseeingKnowledgeContext(dest = null, options = {}) {
    const d = dest && typeof dest === 'object' ? dest : {};
    const airportName = String(d.n || d.name || d.title || '').replace(/\s+/g, ' ').trim();
    const place = _missionSightseeingAptPlaceLabel(airportName);
    const lat = Number(d.lat);
    const lon = Number(d.lon);
    if (!place || !Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    if (_poiKnowledgeCooldownRemainingMs() > 0) return _poiKnowledgeRateLimitedContext(place);
    const cacheKey = `${_poiKnowledgeNormalizeKey(place)}|${lat.toFixed(3)}|${lon.toFixed(3)}|apt_sightseeing`;
    if (_aptSightseeingKnowledgeCache.has(cacheKey)) return _aptSightseeingKnowledgeCache.get(cacheKey);

    const started = Date.now();
    const budgetMs = Math.max(900, Number(options.budgetMs || APT_SIGHTSEEING_KNOWLEDGE_BUDGET_MS));
    const titles = _missionSightseeingAptWikiTitleCandidates(place, airportName);
    const evaluated = [];
    let cityContext = null;

    for (const title of titles) {
        const remainingMs = budgetMs - (Date.now() - started);
        if (remainingMs < 500) break;
        const ctx = await _resolveEducationalPoiContext(title, lat, lon, 'city', {
            timeoutMs: Math.min(POI_KNOWLEDGE_WIKI_TIMEOUT_MS, Math.max(600, remainingMs))
        });
        evaluated.push({
            title,
            status: String(ctx?.status || 'reject'),
            score: Number(ctx?.score || 0),
            warnings: Array.isArray(ctx?.warnings) ? ctx.warnings.slice(0, 4) : []
        });
        if (ctx?.rateLimited) {
            _aptSightseeingKnowledgeCache.set(cacheKey, ctx);
            return ctx;
        }
        if (ctx?.ok && ctx.status === 'accept') {
            cityContext = ctx;
            break;
        }
        if (!cityContext && ctx && (ctx.status === 'review' || Number(ctx.score || 0) >= POI_KNOWLEDGE_CONTEXT_REVIEW_SCORE)) {
            cityContext = ctx;
        }
    }

    const remainingForLandmarks = budgetMs - (Date.now() - started);
    const landmarks = remainingForLandmarks >= 550
        ? await _missionSightseeingFetchNearbyWikiLandmarks(lat, lon, place, { timeoutMs: Math.min(POI_KNOWLEDGE_WIKI_TIMEOUT_MS, remainingForLandmarks) })
        : [];
    const cityWarnings = Array.isArray(cityContext?.warnings)
        ? cityContext.warnings.map(item => String(item || '').trim()).filter(Boolean)
        : [];
    const cityCoordinateFar = cityWarnings.some(item => /coordinate_far|linear_feature_coordinate_far_from_target/.test(item));
    const cityScore = cityCoordinateFar ? 0 : Number(cityContext?.score || 0);
    const cityFactCandidates = cityCoordinateFar ? 0 : Number(cityContext?.factCandidates || 0);
    const cityTopics = !cityCoordinateFar && Array.isArray(cityContext?.topics) ? cityContext.topics : [];
    const cityReasons = !cityCoordinateFar && Array.isArray(cityContext?.reasons) ? cityContext.reasons : [];
    const landmarkFacts = _missionSightseeingAptLandmarkFacts(place, landmarks);
    const baseFacts = !cityCoordinateFar && Array.isArray(cityContext?.facts) ? cityContext.facts : [];
    const mergedFacts = compactPoiKnowledgeFactListForMission(
        [...landmarkFacts, ...baseFacts],
        POI_KNOWLEDGE_CORE_FACT_LIMIT
    );
    const hasAcceptedCity = !!(cityContext?.ok && cityContext.status === 'accept' && !cityCoordinateFar);
    const fallbackCityStatus = cityCoordinateFar && String(cityContext?.status || '') === 'accept'
        ? 'review'
        : (cityContext?.status || 'reject');
    const out = {
        ...(cityContext && typeof cityContext === 'object' ? cityContext : {}),
        ok: hasAcceptedCity || landmarks.length > 0,
        status: hasAcceptedCity || landmarks.length > 0 ? 'accept' : fallbackCityStatus,
        title: String((cityCoordinateFar ? '' : cityContext?.title) || place).replace(/\s+/g, ' ').trim(),
        category: 'city',
        score: Math.max(cityScore, landmarks.length ? POI_KNOWLEDGE_CONTEXT_ACCEPT_SCORE : 0),
        facts: mergedFacts,
        factCandidates: Math.max(cityFactCandidates, mergedFacts.length),
        selectedFacts: mergedFacts.length,
        topics: Array.from(new Set([
            ...cityTopics,
            ...mergedFacts.map(fact => fact.topic || 'general')
        ])).filter(Boolean).slice(0, 8),
        sightseeingPlace: place,
        sightseeingLandmarks: landmarks.map(item => ({
            title: item.title,
            topic: item.topic,
            distanceKm: item.distanceKm,
            source: 'wikipedia_geosearch'
        })),
        reasons: Array.from(new Set([
            ...cityReasons,
            ...(landmarks.length ? ['apt_sightseeing_landmarks'] : [])
        ])),
        warnings: Array.from(new Set([
            ...((Array.isArray(cityContext?.warnings) ? cityContext.warnings : [])),
            ...(cityCoordinateFar ? ['apt_sightseeing_city_context_coordinate_far_ignored'] : []),
            ...(hasAcceptedCity || landmarks.length ? [] : ['apt_sightseeing_no_wiki_anchor'])
        ])),
        aptSightseeing: true,
        evaluatedTitles: evaluated,
        rateLimited: false
    };
    _aptSightseeingKnowledgeCache.set(cacheKey, out);
    return out;
}

const POI_KNOWLEDGE_GATE_BUCKET_PRIORITY = [
    'city',
    'water',
    'dam',
    'bridge',
    'tower',
    'monument',
    'religious',
    'stadium',
    'industry',
    'castle',
    'mountain',
    'nature'
];

function _poiKnowledgeCandidateBucket(candidate = {}) {
    const cat = String(candidate.cat || candidate.category || '').toLowerCase();
    const name = String(candidate.q || candidate.n || '').toLowerCase();
    const tags = candidate.tags && typeof candidate.tags === 'object' ? candidate.tags : {};
    const tagText = Object.entries(tags)
        .map(([key, value]) => `${key}:${value}`)
        .join(' ')
        .toLowerCase();
    const hay = `${cat} ${name} ${tagText}`;
    const placeHay = `${cat} ${tagText}`;
    const hasPlaceSignal = /city|town|village|settlement|place:city|place:town|place:village/.test(placeHay);
    const normName = normalizeMissionText(name);

    if (/dam|talsperre|staudamm|stausee|sperrmauer|waterway:dam|waterway:weir/.test(hay)) return 'dam';
    if (/bridge|bruecke|brücke|viadukt|man_made:bridge/.test(hay)) return 'bridge';
    if (/tower|turm|telecom|fernsehturm|funkturm|aussichtsturm|man_made:tower|man_made:mast/.test(hay)) return 'tower';
    if (/religious|church|kirche|dom|kathedrale|muenster|münster|amenity:place_of_worship/.test(hay)) return 'religious';
    if (/stadium|stadion|arena|leisure:stadium/.test(hay)) return 'stadium';
    if (/industry|industrial|industrie|werk|huette|hütte|zeche|tagebau|kraftwerk|fabrik|landuse:industrial|man_made:works|power:plant/.test(hay)) return 'industry';
    if (/monument|denkmal|memorial|walhalla|historic:monument|historic:memorial/.test(hay)) return 'monument';
    if (/castle|burg|schloss|fortress|ruine|ruins|historic:castle|historic:ruins/.test(hay)) return 'castle';
    if (
        /river|fluss|lake|canal|water|reservoir|natural:water|water:reservoir|water:lake|landuse:reservoir/.test(hay) ||
        _hasWordToken(normName, 'see') ||
        _hasWordToken(normName, 'teich') ||
        _hasWordToken(normName, 'weiher') ||
        /see$/.test(normName)
    ) return 'water';
    if (hasPlaceSignal) return 'city';
    if (/mountain|berg|gipfel|peak|valley|tal|ridge|natural:peak|natural:valley/.test(hay)) return 'mountain';
    if (/nature|park|wald|forest|schutzgebiet|natural:wood|landuse:forest/.test(hay)) return 'nature';
    if (/city|town|village|settlement|ort|place:city|place:town|place:village/.test(hay)) return 'city';
    return 'generic';
}

function _poiKnowledgeBadNameReason(candidate = {}) {
    const raw = String(candidate.q || candidate.n || '').trim();
    if (!raw) return 'missing_name';
    const key = _poiKnowledgeNormalizeKey(raw);
    const genericNames = new Set([
        'poi',
        'zielgebiet',
        'gewaesser',
        'gewasser',
        'stadtgebiet',
        'berggebiet',
        'talgebiet',
        'infrastruktur',
        'infrastrukturkorridor',
        'strassenverkehrsknoten',
        'brueckeverkehrsbauwerk',
        'funkmastfunkturmwindrad',
        'staudammtalsperre'
    ]);
    if (genericNames.has(key)) return 'generic_name';
    if (_poiKnowledgeIsGenericLinearTitle(raw)) return 'generic_linear_name';
    if (_poiIsCodeLikeName(raw)) return 'code_like_name';
    if (_poiIsNumericLikeName(raw)) return 'numeric_name';
    if (_poiLooksJunctionLabel(raw)) return 'junction_label';
    return '';
}

function _poiKnowledgeBalancedShortlist(candidates = [], options = {}) {
    const maxCandidates = Math.max(1, Math.min(8, Number(options.maxCandidates || POI_KNOWLEDGE_AUTO_MAX_CANDIDATES)));
    const prepared = (Array.isArray(candidates) ? candidates : []).map((candidate, index) => {
        const bucket = _poiKnowledgeCandidateBucket(candidate);
        const badNameReason = _poiKnowledgeBadNameReason(candidate);
        const supported = POI_KNOWLEDGE_GATE_BUCKET_PRIORITY.includes(bucket);
        return {
            ...candidate,
            sourceIndex: Number.isFinite(Number(candidate.sourceIndex)) ? Number(candidate.sourceIndex) : index,
            knowledgeBucket: bucket,
            knowledgeGateRejectedReason: badNameReason || (!supported ? 'unsupported_bucket' : '')
        };
    });
    const eligible = prepared.filter(candidate => !candidate.knowledgeGateRejectedReason);
    const byBucket = new Map();
    for (const candidate of eligible) {
        if (!byBucket.has(candidate.knowledgeBucket)) byBucket.set(candidate.knowledgeBucket, []);
        byBucket.get(candidate.knowledgeBucket).push(candidate);
    }
    for (const list of byBucket.values()) {
        list.sort((a, b) => (
            Number(b.rank || 0) - Number(a.rank || 0)
        ) || (
            Number(a.sourceIndex || 0) - Number(b.sourceIndex || 0)
        ) || String(a.n || '').localeCompare(String(b.n || ''), 'de'));
    }
    const bucketOrder = [
        ...POI_KNOWLEDGE_GATE_BUCKET_PRIORITY.filter(bucket => byBucket.has(bucket)),
        ...[...byBucket.keys()].filter(bucket => !POI_KNOWLEDGE_GATE_BUCKET_PRIORITY.includes(bucket)).sort()
    ];
    const shortlist = [];
    const seen = new Set();
    for (let round = 0; shortlist.length < maxCandidates; round += 1) {
        let added = false;
        for (const bucket of bucketOrder) {
            const candidate = byBucket.get(bucket)?.[round] || null;
            if (!candidate) continue;
            const key = `${_poiKnowledgeNormalizeKey(candidate.n)}|${candidate.knowledgeBucket}`;
            if (seen.has(key)) continue;
            seen.add(key);
            shortlist.push(candidate);
            added = true;
            if (shortlist.length >= maxCandidates) break;
        }
        if (!added) break;
    }
    return {
        prepared,
        eligibleCount: eligible.length,
        rejected: prepared.filter(candidate => candidate.knowledgeGateRejectedReason),
        shortlist
    };
}

async function _poiKnowledgePickAcceptedCandidate(candidates = [], options = {}) {
    const started = Date.now();
    const budgetMs = Math.max(500, Number(options.budgetMs || POI_KNOWLEDGE_AUTO_BUDGET_MS));
    const evaluated = [];
    let stopReason = '';

    for (const candidate of (Array.isArray(candidates) ? candidates : [])) {
        const elapsed = Date.now() - started;
        if (elapsed >= budgetMs) {
            stopReason = 'budget_exhausted_before_candidate';
            break;
        }
        const remainingMs = Math.max(700, budgetMs - elapsed);
        const ctx = await _resolveEducationalPoiContext(
            candidate.n,
            candidate.lat,
            candidate.lon,
            candidate.knowledgeBucket || candidate.category || 'generic',
            { timeoutMs: Math.min(POI_KNOWLEDGE_WIKI_TIMEOUT_MS, remainingMs) }
        );
        evaluated.push({
            name: candidate.n,
            category: candidate.category || 'generic',
            bucket: candidate.knowledgeBucket || 'generic',
            status: String(ctx?.status || 'reject'),
            score: Number(ctx?.score || 0),
            title: String(ctx?.title || ''),
            warnings: Array.isArray(ctx?.warnings) ? ctx.warnings.slice(0, 5) : []
        });
        if (ctx?.rateLimited) {
            return {
                pick: null,
                context: ctx,
                status: 'rate_limited',
                stopReason: 'wiki_429_fail_fast',
                evaluated,
                elapsedMs: Date.now() - started
            };
        }
        if (ctx?.ok && ctx.status === 'accept') {
            return {
                pick: {
                    ...candidate,
                    n: String(ctx.title || candidate.n || '').trim() || candidate.n,
                    category: candidate.category === 'generic' ? (candidate.knowledgeBucket || candidate.category) : candidate.category,
                    knowledgeBucket: candidate.knowledgeBucket || candidate.category || 'generic',
                    knowledgeContext: ctx
                },
                context: ctx,
                status: 'accept',
                stopReason: 'accepted',
                evaluated,
                elapsedMs: Date.now() - started
            };
        }
    }

    if (!stopReason) stopReason = candidates.length ? 'no_accept_in_shortlist' : 'no_supported_candidates';
    return {
        pick: null,
        context: null,
        status: 'no_pick',
        stopReason,
        evaluated,
        elapsedMs: Date.now() - started
    };
}

async function findWikidataTypedPOI(lat, lon, minNM, maxNM, dirPref, forcedCategory) {
    const cat = String(forcedCategory || '').toLowerCase();
    const qids = _wikidataTypeQidsForPoiCategory(cat);
    if (!qids.length) return null;

    const radiusKm = Math.max(5, Math.min(350, Number(maxNM || 50) * 1.852));
    const values = qids.map(q => `wd:${q}`).join(' ');
    const query = `
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?item ?itemLabel ?coord ?distance WHERE {
  VALUES ?wantedType { ${values} }
  ?item wdt:P31/wdt:P279* ?wantedType ;
        wdt:P625 ?coord .
  SERVICE wikibase:around {
    ?item wdt:P625 ?coord .
    bd:serviceParam wikibase:center "Point(${Number(lon)} ${Number(lat)})"^^geo:wktLiteral .
    bd:serviceParam wikibase:radius "${radiusKm}" .
    bd:serviceParam wikibase:distance ?distance .
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "de,en". }
}
ORDER BY ?distance
LIMIT 120
`.trim();

    try {
        const url = `https://query.wikidata.org/sparql?format=json&query=${encodeURIComponent(query)}`;
        const res = await fetch(url, { headers: { 'Accept': 'application/sparql-results+json' } });
        if (!res.ok) return null;
        const data = await res.json();
        const bindings = Array.isArray(data?.results?.bindings) ? data.results.bindings : [];
        if (!bindings.length) return null;

        const candidates = [];
        for (const b of bindings) {
            const label = String(b?.itemLabel?.value || '').trim();
            const parsed = _parseWktPoint(b?.coord?.value || '');
            if (!parsed || !label) continue;
            const nav = calcNav(lat, lon, parsed.lat, parsed.lon);
            if (!Number.isFinite(nav?.dist) || nav.dist < Number(minNM || 0) || nav.dist > Number(maxNM || 9999)) continue;
            if (!checkBearing(nav.brng, dirPref)) continue;
            candidates.push({
                n: label,
                lat: parsed.lat,
                lon: parsed.lon,
                dist: nav.dist
            });
        }
        if (!candidates.length) return null;
        candidates.sort((a, b) => a.dist - b.dist);
        const top = candidates.slice(0, Math.min(6, candidates.length));
        const pick = top[Math.floor(Math.random() * top.length)] || candidates[0];
        return { icao: 'POI', n: pick.n, lat: pick.lat, lon: pick.lon, poiCategory: cat, poiSource: `Wikidata typed (${cat})` };
    } catch (_) {
        return null;
    }
}

async function findWikipediaPOI(lat, lon, minNM, maxNM, dirPref, forcedCategory = null) {
    const scoredKeywords = [
        "bruecke", "brucke", "bridge", "viadukt", "autobahn", "autobahnkreuz", "kreuz", "kreuzung", "dreieck", "strasse", "tunnel", "highway", "motorway", "interstate", "freeway", "interchange",
        "staudamm", "talsperre", "stausee", "sperrmauer", "reservoir", "dam", "wehr",
        "funkturm", "fernsehturm", "sendemast", "funkmast",
        "fluss", "river", "strom", "kanal", "see", "lake", "hafen", "bay", "fjord", "insel", "kueste",
        "burg", "schloss", "dom", "denkmal", "monument", "festung", "kloster",
        "berg", "gipfel", "tal", "schlucht", "wald", "spitze",
        "stadt", "city", "turm", "arena", "stadion", "zentrum"
    ];
    const weakKeywords = ["liste", "begriffsklarung", "jahr", "person", "verwaltungsgemeinschaft", "gemeinde"];
    const scorePOITitle = (title) => {
        const t = normalizeMissionText(title);
        let score = 0;
        for (const kw of scoredKeywords) {
            if (t.includes(kw)) score += 1;
        }
        for (const kw of weakKeywords) {
            if (t.includes(kw)) score -= 1;
        }
        return score;
    };
    const forceCat = String(forcedCategory || '').trim().toLowerCase();
    // Bei expliziter Kategorie bevorzugen wir typisierte Objekt-Datenquellen,
    // damit z.B. "water" echte Gewaesser/Talsperren liefert.
    if (forceCat && forceCat !== 'all' && forceCat !== 'fire' && forceCat !== 'trn') {
        const typedPoi = await findWikidataTypedPOI(lat, lon, minNM, maxNM, dirPref, forceCat);
        if (typedPoi) return typedPoi;
    }
    const dist = Math.floor(Math.random() * (maxNM - minNM + 1)) + minNM;
    let minB = 0, maxB = 360;
    if (dirPref === 'N') { minB = 315; maxB = 405; } else if (dirPref === 'E') { minB = 45; maxB = 135; } else if (dirPref === 'S') { minB = 135; maxB = 225; } else if (dirPref === 'W') { minB = 225; maxB = 315; }
    let bearing = Math.floor(Math.random() * (maxB - minB + 1)) + minB; bearing = bearing % 360;
    const target = getDestinationPoint(lat, lon, dist, bearing);
    if (forceCat === 'dam') {
        const damPoi = await findNominatimDamPOI(target.lat, target.lon);
        if (damPoi) return damPoi;
    }
    const url = `https://de.wikipedia.org/w/api.php?action=query&list=geosearch&gscoord=${target.lat}|${target.lon}&gsradius=10000&gslimit=30&format=json&origin=*`;
    try {
        const res = await fetch(url); const data = await res.json();
        if (data.query && data.query.geosearch && data.query.geosearch.length > 0) {
            const geosearch = data.query.geosearch;
            let poiPool = geosearch;
            if (forceCat && forceCat !== 'all') {
                const forcedPool = geosearch.filter(p => poiTitleMatchesCategory(p.title, forceCat));
                if (forcedPool.length > 0) {
                    poiPool = forcedPool;
                } else {
                    // Kein unpassender Rückfall bei explizitem Category-Picker.
                    return null;
                }
            }
            let bestScore = -999;
            const scoreFn = (forceCat === 'fire') ? scoreFirePOITitle : scorePOITitle;
            for (const p of poiPool) {
                const s = scoreFn(p.title);
                if (s > bestScore) bestScore = s;
            }
            if (bestScore > 0) {
                poiPool = poiPool.filter(p => scoreFn(p.title) === bestScore);
            }
            const balancedPoi = pickBalancedByCategory(poiPool, p => classifyPOITitleCategory(p.title), 'ga_poi_cat');
            const poi = balancedPoi ? balancedPoi.item : poiPool[Math.floor(Math.random() * poiPool.length)];
            return {
                icao: "POI",
                n: poi.title,
                lat: poi.lat,
                lon: poi.lon,
                poiCategory: balancedPoi ? balancedPoi.category : classifyPOITitleCategory(poi.title),
                poiSource: `Wikipedia GeoSearch${forceCat ? ` (forced:${forceCat})` : ''}`
            };
        }
    } catch (e) { }
    return null;
}

function normalizeGermanTargetInfoText(text = '') {
    return String(text || '')
        .replace(/\bFuer\b/g, 'Für')
        .replace(/\bfuer\b/g, 'für')
        .replace(/Luftueberblick/g, 'Luftüberblick')
        .replace(/Ueberblick/g, 'Überblick')
        .replace(/ueber/g, 'über')
        .replace(/zurueck/g, 'zurück')
        .replace(/koennen/g, 'können')
        .replace(/duerfen/g, 'dürfen')
        .replace(/laesst/g, 'lässt')
        .replace(/spaeter/g, 'später')
        .replace(/haengen/g, 'hängen')
        .replace(/geloest/g, 'gelöst')
        .replace(/Primaer/g, 'Primär')
        .replace(/primaer/g, 'primär')
        .replace(/vollstaendig/g, 'vollständig')
        .replace(/Gewaesser/g, 'Gewässer')
        .replace(/gewaesser/g, 'Gewässer')
        .replace(/Wasserflaeche/g, 'Wasserfläche')
        .replace(/wasserflaeche/g, 'Wasserfläche')
        .replace(/Flaechen/g, 'Flächen')
        .replace(/flaechen/g, 'Flächen')
        .replace(/Flaeche/g, 'Fläche')
        .replace(/flaeche/g, 'Fläche')
        .replace(/Strassen/g, 'Straßen')
        .replace(/strassen/g, 'Straßen')
        .replace(/Strasse/g, 'Straße')
        .replace(/strasse/g, 'Straße')
        .replace(/Gelaendekanten/g, 'Geländekanten')
        .replace(/gelaendekanten/g, 'Geländekanten')
        .replace(/Gelaende/g, 'Gelände')
        .replace(/gelaende/g, 'Gelände')
        .replace(/Sedimentbaenke/g, 'Sedimentbänke')
        .replace(/sedimentbaenke/g, 'Sedimentbänke')
        .replace(/Veraenderungen/g, 'Veränderungen')
        .replace(/veraenderungen/g, 'Veränderungen')
        .replace(/Veraenderung/g, 'Veränderung')
        .replace(/veraenderung/g, 'Veränderung');
}

function sanitizeGeneratedPoiTargetInfo(text = '', { maxLen = 760 } = {}) {
    let clean = String(text || '')
        .replace(/```[\s\S]*?```/g, '')
        .replace(/^\s*(?:targetInfo|poiTargetInfo|Ziel-Info|Zielinfo)\s*:\s*/i, '')
        .replace(/\s+/g, ' ')
        .trim();
    if (!clean) return '';
    if (/\b(CONTRACT|DISPATCH_FORM|missionTruth|targetGeoContext|sceneIntent|targetAltFt|targetRadiusNm|targetDwellMin|JSON|Regel|Guardrail)\b/i.test(clean)) {
        return '';
    }
    clean = _cleanupNarrativeArtifacts(clean)
        .replace(/\bZiel-Info\s*:\s*/gi, '')
        .replace(/\s+([,.;:!?])/g, '$1')
        .trim();
    clean = normalizeGermanTargetInfoText(clean);
    const sentences = clean
        .split(/(?<=[.!?])\s+/)
        .map(s => s.trim())
        .filter(Boolean);
    let out = '';
    for (const sentence of sentences.length ? sentences : [clean]) {
        const next = `${out}${out ? ' ' : ''}${sentence}`.trim();
        if (next.length > maxLen && out) break;
        out = next;
        if (out.length >= Math.min(420, maxLen)) break;
    }
    out = out || clean;
    if (out.length > maxLen) out = `${out.slice(0, maxLen - 1).replace(/\s+\S*$/, '')}.`;
    return out.trim();
}

function poiCategoryDisplayLabel(category = '') {
    const key = String(category || '').toLowerCase();
    const labels = {
        bridge: 'Brücke oder Viadukt',
        road: 'Straßen- oder Verkehrsziel',
        dam: 'Staudamm oder Talsperre',
        water: 'Gewässer- oder Uferziel',
        mountain: 'Berg- oder Reliefziel',
        forest: 'Wald- oder Naturziel',
        city: 'Orts- oder Stadtziel',
        castle: 'historisches Bauwerk',
        historic: 'historisches Ziel',
        infrastructure: 'Infrastrukturziel',
        industry: 'Industrie- oder Technikziel',
        telecom: 'Funk- oder Maststandort',
        fire: 'Feuerwacht-Zielgebiet',
        trn: 'Übungsgebiet'
    };
    return labels[key] || (key ? `${key}-Ziel` : 'POI-Ziel');
}

function poiAnchorDisplayLabel(key = '', anchor = null) {
    const raw = String(anchor?.name || key || '').toLowerCase();
    const labels = {
        water: 'Gewässer oder Uferlinie',
        road: 'Straße oder Zufahrt',
        motorway: 'Autobahn oder Schnellstraße',
        rail: 'Bahnlinie',
        railway: 'Bahnlinie',
        meadow: 'offene Fläche',
        field: 'Feld oder offene Fläche',
        forest: 'Waldkante',
        bridge: 'Brücke',
        power: 'Stromtrasse',
        wind: 'Windenergieanlage',
        parking: 'Park- oder Zufahrtsfläche',
        building: 'Gebäude',
        industrial: 'Industriefläche'
    };
    return labels[String(key || '').toLowerCase()]
        || labels[raw]
        || String(anchor?.name || key || '').replace(/[_-]+/g, ' ').trim();
}

function buildPoiOrientationSentence(targetGeoContext = null, missionTruth = null) {
    const anchors = targetGeoContext?.anchors && typeof targetGeoContext.anchors === 'object'
        ? targetGeoContext.anchors
        : {};
    const anchorParts = Object.entries(anchors)
        .filter(([, anchor]) => anchor && anchor.present)
        .map(([key, anchor]) => {
            const label = poiAnchorDisplayLabel(key, anchor);
            if (!label) return '';
            const dist = Number(anchor.distM);
            return Number.isFinite(dist) && dist > 0
                ? `${label} rund ${Math.round(dist)} m entfernt`
                : label;
        })
        .filter(Boolean)
        .slice(0, 3);
    const landmarks = Array.isArray(targetGeoContext?.visualLandmarks)
        ? targetGeoContext.visualLandmarks
            .map(item => String(item?.name || item?.label || item || '').replace(/\s+/g, ' ').trim())
            .filter(Boolean)
            .slice(0, 2)
        : [];
    const cues = Array.isArray(missionTruth?.visibleCues)
        ? missionTruth.visibleCues.map(cue => String(cue || '').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 2)
        : [];
    const parts = Array.from(new Set([...anchorParts, ...landmarks, ...cues])).slice(0, 4);
    if (!parts.length) return '';
    return `Als Orientierung aus der Luft dienen ${_missionPipelineV4JoinNaturalList(parts)}.`;
}

function buildPoiTargetInfoFromMission(missionData = null, options = {}) {
    const md = (missionData && typeof missionData === 'object')
        ? missionData
        : ((typeof currentMissionData !== 'undefined' && currentMissionData) ? currentMissionData : null);
    if (!md || !missionUsesPoiPresentation(md)) return '';

    const explicit = sanitizeGeneratedPoiTargetInfo(
        md.targetInfo || md.poiTargetInfo || md.generatedTargetInfo || '',
        { maxLen: 760 }
    );
    if (explicit) return explicit;

    const contract = md.missionContractV4
        || md.missionPlanV4
        || md._missionPlanV4
        || md.missionContract?.missionContractV4
        || md.missionContract
        || {};
    const plan = md.missionPlanV2?.plan
        || md._missionPlanV2?.plan
        || md.missionContract?.missionPlanV2?.plan
        || contract?.missionPlan?.plan
        || {};
    const frame = contract?.storyFrame && typeof contract.storyFrame === 'object'
        ? contract.storyFrame
        : (plan.storyFrame && typeof plan.storyFrame === 'object' ? plan.storyFrame : {});
    const missionTruth = md.missionTruth || md.missionContract?.missionTruth || contract?.missionTruth || null;
    const targetGeoContext = md.targetGeoContext || md.missionContract?.targetGeoContext || contract?.targetGeoContext || null;
    const targetName = String(
        options.targetName
        || md.poiName
        || md.targetName
        || md.initialTargetName
        || contract?.target?.name
        || contract?.route?.targetName
        || 'Zielgebiet'
    ).replace(/\s+/g, ' ').trim() || 'Zielgebiet';
    const category = String(
        md.poiCategory
        || md.requestedCategory
        || contract?.target?.poiCategory
        || plan.targetCategory
        || ''
    ).toLowerCase();
    const source = String(md.poiSource || contract?.target?.poiSource || '').replace(/\s+/g, ' ').trim();
    const sourceIsInternal = /tile|fallback|internal|obstacles|profile|follow-up|synthetic/i.test(source);
    const categoryLabel = poiCategoryDisplayLabel(category);
    const sentences = [];
    sentences.push(sourceIsInternal
        ? `${targetName} ist in der internen Zieldatenbank als ${categoryLabel} hinterlegt.`
        : `${targetName} ist als ${categoryLabel} hinterlegt.`);

    const subject = _missionPipelineV4StripSentenceEnd(
        frame.subjectDetail
        || frame.keyQuestion
        || plan.keyQuestion
        || plan.primaryObjective
        || ''
    );
    if (subject) {
        sentences.push(`Für diesen Flug steht im Mittelpunkt: ${subject}.`);
    }

    const outcome = _missionPipelineV4StripSentenceEnd(
        frame.soughtOutcome
        || frame.whyNow
        || plan.completionSignal
        || ''
    );
    if (outcome && !sentences.join(' ').toLowerCase().includes(outcome.toLowerCase())) {
        sentences.push(_missionPipelineV4EnsureSentence(outcome));
    }

    const orientation = buildPoiOrientationSentence(targetGeoContext, missionTruth);
    if (orientation) sentences.push(orientation);

    if (sentences.length < 3) {
        const story = String(md.missionStory || md.story || md.mission || '').replace(/\s+/g, ' ').trim();
        const storySentence = story.split(/(?<=[.!?])\s+/).find(s => s && !sentences.join(' ').includes(s));
        if (storySentence) sentences.push(_missionPipelineV4EnsureSentence(storySentence));
    }

    const text = sanitizeGeneratedPoiTargetInfo(sentences.filter(Boolean).slice(0, 4).join(' '), { maxLen: 760 });
    if (text && md && typeof md === 'object') {
        try {
            md.generatedTargetInfo = text;
            if (!md.targetInfo) md.targetInfo = text;
        } catch (_) {}
    }
    return text;
}

function buildAreaDescriptionPoiFallback(lat, lon, elementId, exactTitle = null, icaoCode = null, options = {}) {
    const opts = options && typeof options === 'object' ? options : {};
    if (typeof opts.fallbackText === 'string') return sanitizeGeneratedPoiTargetInfo(opts.fallbackText);
    if (icaoCode && !opts.poiFallback) return '';
    const elementKey = String(elementId || '');
    const isDestinationInfo = opts.poiFallback === true || /wikiDestDescText|dest/i.test(elementKey);
    if (!isDestinationInfo) return '';
    const md = (opts.missionData && typeof opts.missionData === 'object')
        ? opts.missionData
        : ((typeof currentMissionData !== 'undefined' && currentMissionData) ? currentMissionData : null);
    if (!md || !missionUsesPoiPresentation(md)) return '';
    return buildPoiTargetInfoFromMission(md, { targetName: exactTitle || opts.targetName || '' });
}

async function fetchAreaDescription(lat, lon, elementId, exactTitle = null, icaoCode = null, imgContainerId = 'wikiDestImageContainer', imgElId = 'wikiDestImage', options = {}) {
    const imgContainer = document.getElementById(imgContainerId);
    const imgElement = document.getElementById(imgElId);
    const textElement = document.getElementById(elementId);
    if (imgContainer) imgContainer.style.display = 'none';
    if (!textElement) return;
    const applyPoiFallback = () => {
        const fallback = buildAreaDescriptionPoiFallback(lat, lon, elementId, exactTitle, icaoCode, options);
        if (!fallback) return false;
        textElement.innerText = fallback;
        return true;
    };

    try {
        let titleToFetch = exactTitle;
        if (!titleToFetch && icaoCode) titleToFetch = await getWikiTitleForAirport(icaoCode, lat, lon);

        if (!titleToFetch) {
            const geoRes = await fetch(`https://de.wikipedia.org/w/api.php?action=query&list=geosearch&gscoord=${lat}|${lon}&gsradius=10000&gslimit=1&format=json&origin=*`);
            const geoData = await geoRes.json();
            if (geoData?.query?.geosearch?.length > 0) titleToFetch = geoData.query.geosearch[0].title;
            else {
                if (applyPoiFallback()) return;
                textElement.innerText = "Keine regionalen Wikipedia-Daten gefunden.";
                return;
            }
        }

        if (titleToFetch) {
            const extRes = await fetch(`https://de.wikipedia.org/w/api.php?action=query&prop=extracts|pageimages&exintro=true&explaintext=true&exsentences=4&pithumbsize=1200&titles=${encodeURIComponent(titleToFetch)}&format=json&origin=*`);
            const extData = await extRes.json();

            if (extData?.query?.pages) {
                const pageId = Object.keys(extData.query.pages)[0];
                if (pageId !== "-1" && extData.query.pages[pageId].extract) {
                    let prefix = exactTitle ? "" : `Region (${titleToFetch}):\n\n`;
                    textElement.innerText = prefix + extData.query.pages[pageId].extract;

                    const imgUrl = extData.query.pages[pageId].thumbnail?.source;
                    if (imgUrl && imgContainer && imgElement) {
                        imgElement.style.backgroundImage = `url('${imgUrl}')`;
                        imgContainer.style.display = 'block';
                    }
                    return;
                }
            }
        }
        if (applyPoiFallback()) return;
        textElement.innerText = "Der Artikel konnte nicht von Wikipedia abgerufen werden.";
    } catch (e) {
        if (applyPoiFallback()) return;
        textElement.innerText = "Wiki-Daten konnten nicht geladen werden.";
    }
}

function formatOverpassRunwayDetails(data) {
    const elements = Array.isArray(data?.elements) ? data.elements : [];
    const trans = {
        asphalt: 'Asphalt', concrete: 'Beton', grass: 'Gras',
        paved: 'Asphalt', unpaved: 'Unbefestigt', dirt: 'Erde',
        gravel: 'Schotter', sand: 'Sand', water: 'Wasser'
    };
    const seen = new Set();
    const parts = [];
    for (const element of elements) {
        const tags = element?.tags || {};
        const ref = String(tags.ref || tags.name || 'Piste').trim();
        const surfaceRaw = String(tags.surface || '').trim();
        const surface = surfaceRaw ? (trans[surfaceRaw.toLowerCase()] || surfaceRaw) : '';
        const lengthRaw = String(tags.length || '').trim();
        const lengthNumber = Number.parseFloat(lengthRaw.replace(',', '.'));
        const lengthMeters = Number.isFinite(lengthNumber)
            ? (/ft|feet/i.test(lengthRaw) ? lengthNumber * 0.3048 : lengthNumber)
            : null;
        const key = `${ref}|${surface}|${Number.isFinite(lengthMeters) ? Math.round(lengthMeters) : ''}`;
        if (seen.has(key)) continue;
        seen.add(key);
        const details = [];
        if (surface) details.push(surface);
        if (Number.isFinite(lengthMeters)) details.push(`${Math.round(lengthMeters)}m`);
        parts.push(`${ref}${details.length ? ` – ${details.join(' · ')}` : ''}`);
    }
    return parts.slice(0, 8).join('\n');
}

async function lookupRunwayDetails(lat, lon, icaoCode) {
    if (typeof window.gaFetchOpenAipAirportRunwayText === 'function') {
        try {
            const openAipText = await window.gaFetchOpenAipAirportRunwayText(icaoCode, lat, lon);
            if (openAipText) return { status: 'ok', text: openAipText, source: 'openaip-region' };
        } catch (_) {
            // Der OSM-Fallback bleibt unabhängig von einem OpenAIP-Teilausfall.
        }
    }

    const query = `[out:json][timeout:5];nwr["aeroway"="runway"](around:3000,${lat},${lon});out tags;`;
    try {
        const res = await fetchWithTimeout(
            `https://overpass-api.de/api/interpreter?data=${encodeURIComponent(query)}`,
            6500
        );
        if (!res.ok) {
            const error = new Error(`overpass_http_${res.status}`);
            error.status = res.status;
            throw error;
        }
        const data = await res.json();
        const text = formatOverpassRunwayDetails(data);
        return text
            ? { status: 'ok', text, source: 'overpass' }
            : { status: 'empty', text: '', source: 'overpass' };
    } catch (error) {
        return {
            status: 'temporary',
            text: '',
            source: 'overpass',
            error: String(error?.message || error)
        };
    }
}

function renderRunwayDetailsResult(domEl, result, icaoCode) {
    if (!domEl || !result) return;
    const hColor = document.body.classList.contains('theme-retro') ? 'var(--piper-yellow)' : 'var(--warn)';
    let summaryText = '';
    if (result.status === 'ok' && result.text) {
        summaryText = result.text;
        domEl.innerHTML = result.text.replace(/\n/g, '<br>');
        domEl.style.color = hColor;
    } else if (result.status === 'empty') {
        summaryText = 'Keine Pisteninformationen vorhanden';
        domEl.innerText = summaryText;
        domEl.style.color = '#888';
    } else {
        summaryText = 'Pistendaten vorübergehend nicht verfügbar · erneut antippen';
        domEl.innerText = summaryText;
        domEl.style.color = '#b7791f';
    }
    if (icaoCode === currentStartICAO && document.getElementById('wikiDepRwyText')) {
        document.getElementById('wikiDepRwyText').innerHTML = `Pisten:<br>${summaryText.replace(/\n/g, '<br>')}`;
    }
    if (icaoCode === currentDestICAO && document.getElementById('wikiDestRwyText')) {
        document.getElementById('wikiDestRwyText').innerHTML = `Pisten:<br>${summaryText.replace(/\n/g, '<br>')}`;
    }
}

async function fetchRunwayDetails(lat, lon, elementId, icaoCode) {
    let domEl = document.getElementById(elementId);
    if (!domEl) return;
    const normalizedIcao = String(icaoCode || '').trim().toUpperCase();
    const lookupKey = normalizedIcao || `${Number(lat).toFixed(4)},${Number(lon).toFixed(4)}`;

    const cachedText = normalizedIcao ? String(runwayCache[normalizedIcao] || '') : '';
    if (cachedText && cachedText !== 'Keine Daten gefunden') {
        renderRunwayDetailsResult(domEl, { status: 'ok', text: cachedText, source: 'memory' }, normalizedIcao);
        return;
    }

    const emptyCachedAt = Number(runwayEmptyCache.get(lookupKey)) || 0;
    if (emptyCachedAt && (Date.now() - emptyCachedAt) < RUNWAY_EMPTY_CACHE_MS) {
        renderRunwayDetailsResult(domEl, { status: 'empty', text: '', source: 'memory' }, normalizedIcao);
        return;
    }
    if (emptyCachedAt) runwayEmptyCache.delete(lookupKey);
    const temporaryCachedAt = Number(runwayTemporaryCache.get(lookupKey)) || 0;
    if (temporaryCachedAt && (Date.now() - temporaryCachedAt) < RUNWAY_TEMPORARY_RETRY_MS) {
        renderRunwayDetailsResult(domEl, { status: 'temporary', text: '', source: 'memory' }, normalizedIcao);
        return;
    }
    if (temporaryCachedAt) runwayTemporaryCache.delete(lookupKey);

    let request = runwayLookupInflight.get(lookupKey);
    if (!request) {
        request = lookupRunwayDetails(Number(lat), Number(lon), normalizedIcao);
        runwayLookupInflight.set(lookupKey, request);
    }

    let result;
    try {
        result = await request;
    } finally {
        if (runwayLookupInflight.get(lookupKey) === request) runwayLookupInflight.delete(lookupKey);
    }
    if (result?.status === 'ok' && result.text && normalizedIcao) {
        runwayCache[normalizedIcao] = result.text;
        runwayEmptyCache.delete(lookupKey);
        runwayTemporaryCache.delete(lookupKey);
    } else if (result?.status === 'empty') {
        runwayEmptyCache.set(lookupKey, Date.now());
        runwayTemporaryCache.delete(lookupKey);
    } else if (result?.status === 'temporary') {
        runwayTemporaryCache.set(lookupKey, Date.now());
        console.warn('[Runway] Quelle vorübergehend nicht verfügbar:', normalizedIcao || lookupKey, result.error || result.source);
    }
    domEl = document.getElementById(elementId);
    if (!domEl) return;
    renderRunwayDetailsResult(domEl, result, normalizedIcao);
}

const wikiTitleCache = {};

async function getWikiTitleForAirport(icao, lat, lon) {
    if (wikiTitleCache[icao]) return wikiTitleCache[icao];

    try {
        const wdRes = await fetchWithTimeout(`https://de.wikipedia.org/w/api.php?action=query&list=search&srsearch=haswbstatement:P239=${icao}&format=json&origin=*`, 4000);
        const wdData = await wdRes.json();
        if (wdData?.query?.search?.length > 0) {
            wikiTitleCache[icao] = wdData.query.search[0].title;
            return wdData.query.search[0].title;
        }

        const isAirport = (t) => ['flugplatz', 'flughafen', 'airport', 'air base', 'aerodrome', 'segelflug', 'landeplatz', 'fliegerhorst', icao.toLowerCase()].some(kw => t.toLowerCase().includes(kw));

        const geoRes = await fetchWithTimeout(`https://de.wikipedia.org/w/api.php?action=query&list=geosearch&gscoord=${lat}|${lon}&gsradius=10000&gslimit=10&format=json&origin=*`, 4000);
        const geoData = await geoRes.json();
        const geoResults = geoData?.query?.geosearch || [];

        let hit = geoResults.find(r => isAirport(r.title));
        if (hit) {
            wikiTitleCache[icao] = hit.title;
            return hit.title;
        }

        const txtRes = await fetchWithTimeout(`https://de.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(icao + ' Flughafen OR Flugplatz')}&srlimit=5&format=json&origin=*`, 4000);
        const txtData = await txtRes.json();
        const txtResults = txtData?.query?.search || [];

        hit = txtResults.find(r => isAirport(r.title));
        if (hit) {
            wikiTitleCache[icao] = hit.title;
            return hit.title;
        }
    } catch (e) { }
    return null;
}

async function fetchRunwayFromWikipedia(icaoCode, lat, lon) {
    if (!icaoCode) return null;
    try {
        const title = await getWikiTitleForAirport(icaoCode, lat, lon);
        if (!title) return null;

        const r = await fetchWithTimeout(`https://de.wikipedia.org/w/api.php?action=query&prop=revisions&rvprop=content&rvslots=main&titles=${encodeURIComponent(title)}&format=json&origin=*`, 5000);
        const d = await r.json();
        const pages = d?.query?.pages;

        if (pages) {
            const pageId = Object.keys(pages)[0];
            const wikitext = pages[pageId]?.revisions?.[0]?.slots?.main?.['*'];
            if (wikitext) return parseRunwayFromWikitext(wikitext);
        }
    } catch (e) { }
    return null;
}

function parseRunwayFromWikitext(wikitext) {
    const runways = [];
    const commentRegex = new RegExp('<' + '!--[\\s\\S]*?--' + '>', 'g');
    let text = wikitext.replace(commentRegex, '');
    text = text.replace(/<br\s*\/?>/gi, ' ');
    text = text.replace(/&#160;/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&times;/gi, '×');
    text = text.replace(/\[\[([^\]|]+\|)?([^\]]+)\]\]/g, '$2');
    text = text.replace(/<[^>]+>/g, ' ');
    text = text.replace(/\s+/g, ' ');

    const HDG_PATTERN = /\b((?:0?[1-9]|[12]\d|3[0-6])[LRC]?\s*\/\s*(?:0?[1-9]|[12]\d|3[0-6])[LRC]?)\b/g;
    const SURFACES = /\b(asphalt|beton|gras|grass|schotter|gravel|concrete|paved|unpaved|dirt|erde|sand|wasser|water|eis|ice)\b/i;
    const LEN_PATTERN = /(?:(?:länge|length|len)\d*\s*=\s*([1-9][\d.,]*))|(?:([1-9][\d.,]*)\s*(?:m|Meter)\b)|(?:([1-9][\d.,]*)\s*(?:x|×)\s*\d+)/i;

    let matches = [];
    let match;
    while ((match = HDG_PATTERN.exec(text)) !== null) {
        let cleanHdg = match[1].replace(/\s+/g, '');
        let parts = cleanHdg.split('/');
        if (Math.abs(parseInt(parts[0], 10) - parseInt(parts[1], 10)) === 18) {
            matches.push({ hdg: cleanHdg, index: match.index, raw: match[1] });
        }
    }

    for (let i = 0; i < matches.length; i++) {
        const hdg = matches[i].hdg;
        const startIdx = matches[i].index;

        let endIdx = Math.min(startIdx + 200, text.length);
        if (i + 1 < matches.length) {
            if (matches[i + 1].index < endIdx) endIdx = matches[i + 1].index;
        }
        let contextFwd = text.substring(startIdx, endIdx);

        let preStartIdx = Math.max(0, startIdx - 60);
        if (i > 0) {
            const prevEnd = matches[i - 1].index + matches[i - 1].raw.length;
            if (prevEnd > preStartIdx) preStartIdx = prevEnd;
        }
        let contextBwd = text.substring(preStartIdx, startIdx);

        let length = '';
        let surface = '';

        let lenMatch = contextFwd.match(LEN_PATTERN);
        if (!lenMatch) lenMatch = contextBwd.match(LEN_PATTERN);

        let rawLen = lenMatch ? (lenMatch[1] || lenMatch[2] || lenMatch[3]) : null;

        if (!rawLen) {
            let isolatedNum = contextFwd.match(/(?:\||\s|^)([1-9][\d.]{2,3})(?:\s|\||$)/);
            if (!isolatedNum) isolatedNum = contextBwd.match(/(?:\||\s|^)([1-9][\d.]{2,3})(?:\s|\||$)/);
            if (isolatedNum) rawLen = isolatedNum[1];
        }

        if (rawLen) length = rawLen.replace(/[.,]/g, '') + 'm';

        let surfMatch = contextFwd.match(SURFACES);
        if (!surfMatch) surfMatch = contextBwd.match(SURFACES);

        if (surfMatch) surface = surfMatch[1].charAt(0).toUpperCase() + surfMatch[1].slice(1).toLowerCase();

        if (length || surface || matches.length === 1) {
            runways.push([hdg, length, surface].filter(Boolean).join(' · '));
        }
    }

    if (runways.length === 0) return null;

    const uniqueRunways = [...new Set(runways)];
    uniqueRunways.sort((a, b) => b.length - a.length);

    const finalRunways = [];

    for (const rwy of uniqueRunways) {
        const parts = rwy.split(' · ');
        const currentHdg = parts[0];

        const currentSurfMatch = rwy.match(new RegExp(SURFACES.source, 'i'));
        const currentSurf = currentSurfMatch ? currentSurfMatch[1].toLowerCase() : null;

        let isSubsetOrHistory = false;

        for (const existing of finalRunways) {
            const existingParts = existing.split(' · ');
            if (existingParts[0] === currentHdg) {

                let allAttrMatch = true;
                for (let j = 1; j < parts.length; j++) {
                    if (!existing.includes(parts[j])) {
                        allAttrMatch = false;
                        break;
                    }
                }

                if (allAttrMatch) {
                    isSubsetOrHistory = true;
                    break;
                }

                const existingSurfMatch = existing.match(new RegExp(SURFACES.source, 'i'));
                const existingSurf = existingSurfMatch ? existingSurfMatch[1].toLowerCase() : null;

                if (existingSurf === currentSurf || !currentSurf) {
                    isSubsetOrHistory = true;
                    break;
                }
            }
        }

        if (!isSubsetOrHistory) {
            finalRunways.push(rwy);
        }
    }

    return finalRunways.slice(0, 5).join('\n');
}

const _poiTerrainCache = new Map();
const _poiTerrainEnvelopeCache = new Map();
const _missionWxCache = new Map();
const _dwdWbiStationCache = { ts: 0, stations: [] };
const _dwdWbiByStationCache = new Map();

function _isLikelyGermanyLatLon(lat, lon) {
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return false;
    return lat >= 46.0 && lat <= 56.3 && lon >= 5.0 && lon <= 15.8;
}

function _wbiRiskLabel(level) {
    const l = Number(level || 0);
    if (l <= 1) return 'sehr gering';
    if (l === 2) return 'gering';
    if (l === 3) return 'mittel';
    if (l === 4) return 'hoch';
    if (l >= 5) return 'sehr hoch';
    return 'n/a';
}

function _formatWbiDate(yyyymmdd) {
    const s = String(yyyymmdd || '');
    if (!/^\d{8}$/.test(s)) return null;
    return `${s.slice(6, 8)}.${s.slice(4, 6)}.${s.slice(0, 4)}`;
}

function _looksLikeWbiCsvText(txt) {
    const t = String(txt || '').slice(0, 220).toLowerCase();
    return t.includes('stationsindex;') || t.includes('stationsid;') || t.includes(';wbi');
}

async function _fetchTextMaybeGzip(urls = []) {
    const list = Array.isArray(urls) ? urls.filter(Boolean) : [];
    for (const url of list) {
        try {
            const res = await fetch(url);
            if (!res.ok || res.status === 204) continue;
            const buf = await res.arrayBuffer();
            if (!buf || buf.byteLength === 0) continue;

            // Versuch 1: Direkttext (bei Proxy oft bereits entpackt).
            try {
                const direct = new TextDecoder('utf-8', { fatal: false }).decode(buf);
                if (_looksLikeWbiCsvText(direct) || direct.includes('Stationsindex;')) return direct;
            } catch (_) {}

            // Versuch 2: gzip entpacken (Browser mit DecompressionStream).
            if (typeof DecompressionStream !== 'undefined') {
                try {
                    const ds = new DecompressionStream('gzip');
                    const stream = new Blob([buf]).stream().pipeThrough(ds);
                    const unzipped = await new Response(stream).text();
                    if (_looksLikeWbiCsvText(unzipped)) return unzipped;
                } catch (_) {}
            }

            // Versuch 3: Latin-1 Fallback fuer Stationsliste.
            try {
                const latin = new TextDecoder('latin1', { fatal: false }).decode(buf);
                if (_looksLikeWbiCsvText(latin) || latin.includes('Stationsindex;')) return latin;
            } catch (_) {}
        } catch (_) {}
    }
    return null;
}

async function fetchDwdWbiStations() {
    const now = Date.now();
    if (Array.isArray(_dwdWbiStationCache.stations) && _dwdWbiStationCache.stations.length > 50 && (now - _dwdWbiStationCache.ts) < 24 * 3600 * 1000) {
        return _dwdWbiStationCache.stations;
    }
    const src = 'https://opendata.dwd.de/climate_environment/CDC/derived_germany/fire_danger_index/woodland/forecast/historical/derived_germany_fire_danger_index_woodland_forecast_historical_v2-3--0_stations_list.txt';
    const txt = await _fetchTextMaybeGzip([
        src,
        `https://api.codetabs.com/v1/proxy/?quest=${encodeURIComponent(src)}`
    ]);
    if (!txt) return [];
    const lines = txt.replace(/\r/g, '').split('\n').map(s => s.trim()).filter(Boolean);
    const out = [];
    for (const line of lines) {
        if (!/^\d/.test(line)) continue;
        const cols = line.split(';');
        if (cols.length < 6) continue;
        const id = parseInt(String(cols[0] || '').trim(), 10);
        const lat = parseFloat(String(cols[2] || '').trim().replace(',', '.'));
        const lon = parseFloat(String(cols[3] || '').trim().replace(',', '.'));
        if (!Number.isFinite(id) || !Number.isFinite(lat) || !Number.isFinite(lon)) continue;
        out.push({
            id,
            lat,
            lon,
            name: String(cols[4] || '').trim(),
            state: String(cols[5] || '').trim()
        });
    }
    _dwdWbiStationCache.ts = now;
    _dwdWbiStationCache.stations = out;
    return out;
}

function findNearestDwdWbiStation(lat, lon, stations = []) {
    const src = Array.isArray(stations) ? stations : [];
    if (!src.length || !Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    let best = null;
    let bestNm = Infinity;
    for (const st of src) {
        const dNm = calcNav(lat, lon, Number(st.lat), Number(st.lon)).dist;
        if (!Number.isFinite(dNm)) continue;
        if (dNm < bestNm) {
            bestNm = dNm;
            best = st;
        }
    }
    if (!best) return null;
    return { ...best, distanceNm: bestNm };
}

async function fetchDwdWbiForLocation(lat, lon) {
    if (!_isLikelyGermanyLatLon(lat, lon)) return null;
    const stations = await fetchDwdWbiStations();
    const nearest = findNearestDwdWbiStation(lat, lon, stations);
    if (!nearest) return null;
    const stationKey = String(nearest.id);
    if (_dwdWbiByStationCache.has(stationKey)) return _dwdWbiByStationCache.get(stationKey);

    const fileUrl = `https://opendata.dwd.de/climate_environment/CDC/derived_germany/fire_danger_index/woodland/recomputed/recent/derived_germany_fire_danger_index_woodland_recomputed_recent_${nearest.id}_v2-3--0.csv.gz`;
    const txt = await _fetchTextMaybeGzip([
        fileUrl,
        `https://api.codetabs.com/v1/proxy/?quest=${encodeURIComponent(fileUrl)}`
    ]);
    if (!txt) return null;

    const lines = txt.replace(/\r/g, '').split('\n').map(s => s.trim()).filter(Boolean);
    let bestDate = '';
    let bestLevel = null;
    for (const line of lines) {
        if (!/^\d/.test(line)) continue;
        const cols = line.split(';').map(s => String(s || '').trim());
        if (cols.length < 3) continue;
        const dateRaw = cols[1];
        const date8 = dateRaw.slice(0, 8);
        const level = parseInt(cols[2], 10);
        if (!/^\d{8}$/.test(date8) || !Number.isFinite(level)) continue;
        if (date8 >= bestDate) {
            bestDate = date8;
            bestLevel = level;
        }
    }
    if (!bestDate || !Number.isFinite(bestLevel)) return null;

    const out = {
        source: 'DWD WBI',
        stationId: nearest.id,
        stationName: nearest.name || null,
        state: nearest.state || null,
        distanceNm: Math.round(Number(nearest.distanceNm || 0) * 10) / 10,
        level: Math.max(1, Math.min(5, Math.round(bestLevel))),
        label: _wbiRiskLabel(bestLevel),
        date: bestDate,
        dateIso: `${bestDate.slice(0, 4)}-${bestDate.slice(4, 6)}-${bestDate.slice(6, 8)}`
    };
    _dwdWbiByStationCache.set(stationKey, out);
    return out;
}

async function fetchPoiTerrainElevationFt(lat, lon) {
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    const key = `${Number(lat).toFixed(4)},${Number(lon).toFixed(4)}`;
    if (_poiTerrainCache.has(key)) return _poiTerrainCache.get(key);

    let elevFt = null;
    try {
        if (typeof sampleTerrainElevation === 'function') {
            elevFt = await Promise.race([
                sampleTerrainElevation(lat, lon),
                new Promise((_, reject) => setTimeout(() => reject(new Error('terrain-timeout')), 2500))
            ]);
        }
    } catch (e) {}

    if (!Number.isFinite(elevFt)) {
        try {
            const url = `https://api.open-meteo.com/v1/elevation?latitude=${encodeURIComponent(lat)}&longitude=${encodeURIComponent(lon)}`;
            const res = await fetch(url);
            if (res.ok) {
                const data = await res.json();
                if (Array.isArray(data?.elevation) && Number.isFinite(data.elevation[0])) {
                    elevFt = Math.round(data.elevation[0] * 3.28084);
                } else if (Number.isFinite(data?.elevation)) {
                    elevFt = Math.round(data.elevation * 3.28084);
                }
            }
        } catch (e) {}
    }

    const normalized = Number.isFinite(elevFt) ? Math.max(0, Math.round(elevFt)) : null;
    _poiTerrainCache.set(key, normalized);
    return normalized;
}

async function fetchPoiTerrainEnvelopeFt(lat, lon, radiusNm = 1) {
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    const safeRadiusNm = Math.max(0.1, Math.min(5, Number(radiusNm) || 1));
    const key = `${Number(lat).toFixed(4)},${Number(lon).toFixed(4)}|${safeRadiusNm.toFixed(2)}`;
    if (_poiTerrainEnvelopeCache.has(key)) return _poiTerrainEnvelopeCache.get(key);

    let envelope = null;
    try {
        if (typeof sampleTerrainEnvelope === 'function') {
            envelope = await Promise.race([
                sampleTerrainEnvelope(lat, lon, safeRadiusNm),
                new Promise((_, reject) => setTimeout(() => reject(new Error('terrain-envelope-timeout')), 4000))
            ]);
        }
    } catch (e) {}

    if (
        envelope
        && envelope.centerFt !== null
        && envelope.maxFt !== null
        && Number.isFinite(Number(envelope.centerFt))
        && Number.isFinite(Number(envelope.maxFt))
    ) {
        const normalized = {
            centerFt: Math.max(0, Math.round(Number(envelope.centerFt))),
            maxFt: Math.max(0, Math.round(Number(envelope.maxFt))),
            radiusNm: safeRadiusNm,
            zoom: Number.isFinite(Number(envelope.zoom)) ? Math.round(Number(envelope.zoom)) : null,
            sampleCount: Math.max(0, Math.round(Number(envelope.sampleCount) || 0)),
            complete: true,
            source: 'terrarium-area'
        };
        _poiTerrainCache.set(`${Number(lat).toFixed(4)},${Number(lon).toFixed(4)}`, normalized.centerFt);
        _poiTerrainEnvelopeCache.set(key, normalized);
        return normalized;
    }

    const centerFt = await fetchPoiTerrainElevationFt(lat, lon);
    const fallback = centerFt !== null && Number.isFinite(Number(centerFt)) ? {
        centerFt: Math.max(0, Math.round(Number(centerFt))),
        maxFt: null,
        radiusNm: safeRadiusNm,
        zoom: null,
        sampleCount: 1,
        complete: false,
        source: 'target-point-fallback'
    } : null;
    _poiTerrainEnvelopeCache.set(key, fallback);
    return fallback;
}

function _summarizeMissionWeather(wx) {
    if (!wx) return 'Keine aktuellen Wetterdaten verfügbar.';
    const visTxt = Number.isFinite(wx.visKm)
        ? (wx.visKm >= 10 ? 'Sicht >10 km' : `Sicht ${wx.visKm.toFixed(1)} km`)
        : 'Sicht n/a';
    const windTxt = (Number.isFinite(wx.windDeg) && Number.isFinite(wx.windKts))
        ? `Wind ${wx.windDeg}°/${Math.round(wx.windKts)} kt`
        : 'Wind n/a';
    const tempTxt = Number.isFinite(wx.tempC) ? `${Math.round(wx.tempC)}°C` : 'Temp n/a';
    const wxTxt = wx.wxCode ? `WX ${wx.wxCode}` : 'WX NIL';
    const catTxt = wx.fltCat ? `Kategorie ${wx.fltCat}` : 'Kategorie n/a';
    return `${windTxt}, ${visTxt}, ${tempTxt}, ${wxTxt}, ${catTxt}`;
}

function _missionPromptTimeOfDayLabel(date = new Date()) {
    const hour = Number(date?.getHours?.() ?? NaN);
    if (!Number.isFinite(hour)) return 'unbestimmt';
    if (hour < 5) return 'tiefe Nacht';
    if (hour < 8) return 'frueher Morgen';
    if (hour < 11) return 'Vormittag';
    if (hour < 14) return 'Mittag';
    if (hour < 18) return 'Nachmittag';
    if (hour < 21) return 'frueher Abend';
    return 'spaeter Abend';
}

function _missionPromptSeasonLabel(date = new Date()) {
    const month = Number((date?.getMonth?.() ?? NaN)) + 1;
    if (!Number.isFinite(month)) return 'Jahreszeit unbestimmt';
    if (month === 12 || month <= 2) return 'Winter';
    if (month <= 5) return 'Fruehling';
    if (month <= 8) return 'Sommer';
    return 'Herbst';
}

function _missionPromptIsValidTimeZone(tz) {
    const value = String(tz || '').trim();
    if (!value) return false;
    try {
        new Intl.DateTimeFormat('de-DE', { timeZone: value }).format(new Date());
        return true;
    } catch (_) {
        return false;
    }
}

function _missionPromptFormatTemporalParts(date = new Date(), timeZone = null) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
    const optsDate = {
        weekday: 'long',
        day: '2-digit',
        month: 'long',
        year: 'numeric'
    };
    const optsTime = {
        hour: '2-digit',
        minute: '2-digit'
    };
    if (timeZone) {
        optsDate.timeZone = timeZone;
        optsTime.timeZone = timeZone;
    }
    const dateTxt = date.toLocaleDateString('de-DE', optsDate);
    const timeTxt = date.toLocaleTimeString('de-DE', optsTime);
    const refDate = timeZone
        ? new Date(date.toLocaleString('en-US', { timeZone }))
        : date;
    return {
        dateTxt,
        timeTxt,
        tod: _missionPromptTimeOfDayLabel(refDate),
        season: _missionPromptSeasonLabel(refDate)
    };
}

function _missionPromptApproxOffsetHoursFromLon(lon) {
    const n = Number(lon);
    if (!Number.isFinite(n)) return null;
    return Math.max(-12, Math.min(14, Math.round(n / 15)));
}

function _missionPromptTemporalContext(date = new Date(), airport = null) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return 'Datum/Uhrzeit unbestimmt';
    const apt = airport && typeof airport === 'object' ? airport : null;
    const tz = String(apt?.tz || '').trim();
    if (_missionPromptIsValidTimeZone(tz)) {
        const parts = _missionPromptFormatTemporalParts(date, tz);
        if (!parts) return 'Datum/Uhrzeit unbestimmt';
        return `${parts.dateTxt}, ${parts.timeTxt} Uhr (${parts.tod}, ${parts.season}, Ortszeit Startplatz)`;
    }
    const approxOffset = _missionPromptApproxOffsetHoursFromLon(apt?.lon);
    if (Number.isFinite(approxOffset)) {
        const shifted = new Date(date.getTime() + (approxOffset * 60 * 60 * 1000));
        const parts = _missionPromptFormatTemporalParts(shifted, 'UTC');
        const utcLabel = approxOffset >= 0 ? `UTC+${approxOffset}` : `UTC${approxOffset}`;
        if (!parts) return 'Datum/Uhrzeit unbestimmt';
        return `${parts.dateTxt}, ${parts.timeTxt} Uhr (${parts.tod}, ${parts.season}, Startplatz naeherungsweise ${utcLabel})`;
    }
    const parts = _missionPromptFormatTemporalParts(date, null);
    if (!parts) return 'Datum/Uhrzeit unbestimmt';
    return `${parts.dateTxt}, ${parts.timeTxt} Uhr (${parts.tod}, ${parts.season})`;
}

function _looksLikeIcao(icao) {
    return /^[A-Z0-9]{4}$/.test(String(icao || '').trim().toUpperCase());
}

async function fetchMissionWeatherSnapshot(icao, lat, lon) {
    const normIcao = String(icao || '').trim().toUpperCase();
    const key = `${normIcao || 'POI'}_${Number(lat || 0).toFixed(3)}_${Number(lon || 0).toFixed(3)}`;
    if (_missionWxCache.has(key)) return _missionWxCache.get(key);

    let metar = null;
    if (_looksLikeIcao(normIcao)) {
        const arr = await _fetchMetarArrayViaVariants(`https://aviationweather.gov/api/data/metar?ids=${normIcao}&format=json&t=${Date.now()}`, {
            includeCodeTabs: false,
            includeDirect: false,
            retries: 1,
            timeoutMs: 2200
        });
        if (arr && arr[0]) metar = arr[0];
    }
    if (!metar && Number.isFinite(lat) && Number.isFinite(lon)) {
        const latMin = lat - 0.6, latMax = lat + 0.6;
        const lonMin = lon - 0.8, lonMax = lon + 0.8;
        const arr = await _fetchMetarArrayViaVariants(`https://aviationweather.gov/api/data/metar?bbox=${latMin},${lonMin},${latMax},${lonMax}&format=json&t=${Date.now()}`, {
            includeCodeTabs: false,
            includeDirect: false,
            retries: 1,
            timeoutMs: 2200
        });
        if (arr && arr[0]) {
            const cands = arr.filter(m => Number.isFinite(Number(m?.lat)) && Number.isFinite(Number(m?.lon)));
            if (cands.length) {
                let best = cands[0];
                let bestD = calcNav(lat, lon, Number(best.lat), Number(best.lon)).dist;
                for (let i = 1; i < cands.length; i++) {
                    const d = calcNav(lat, lon, Number(cands[i].lat), Number(cands[i].lon)).dist;
                    if (d < bestD) { bestD = d; best = cands[i]; }
                }
                metar = best;
            }
        }
    }

    let out = null;
    if (metar) {
        const raw = typeof metar.rawOb === 'string' ? metar.rawOb : (typeof metar.raw === 'string' ? metar.raw : '');
        let visKm = null;
        if (raw.includes(' 9999 ')) visKm = 10;
        else {
            const vm = raw.match(/\s(\d{4})\s/);
            if (vm && vm[1] !== '0000') visKm = Math.round((parseInt(vm[1], 10) / 1000) * 10) / 10;
        }
        let windDeg = Number.isFinite(Number(metar.wdir)) ? Number(metar.wdir) : null;
        let windKts = Number.isFinite(Number(metar.wspd)) ? Number(metar.wspd) : null;
        const vrb = /VRB\d{2,3}KT/.test(raw || '');
        if (vrb) windDeg = null;
        out = {
            station: String(metar.icaoId || normIcao || '').toUpperCase() || null,
            raw: raw || null,
            windDeg,
            windKts,
            visKm,
            tempC: Number.isFinite(Number(metar.temp)) ? Number(metar.temp) : null,
            wxCode: metar.wxString || null,
            fltCat: metar.fltCat || null
        };
    }

    _missionWxCache.set(key, out);
    return out;
}

function resolvePoiAltitudeTerrainFt(poiTerrainFt = null, poiTerrainMaxFt = null) {
    if (poiTerrainMaxFt !== null && poiTerrainMaxFt !== '' && Number.isFinite(Number(poiTerrainMaxFt))) {
        return Math.max(0, Math.round(Number(poiTerrainMaxFt)));
    }
    if (poiTerrainFt !== null && poiTerrainFt !== '' && Number.isFinite(Number(poiTerrainFt))) {
        return Math.max(0, Math.round(Number(poiTerrainFt)));
    }
    return null;
}

function missionPoiAltitudeToleranceFt(passenger = null) {
    const taskDomain = String(passenger?.taskDomain || '').trim().toLowerCase();
    return /^(fire_watch|search_and_rescue|inspection_infra|infra_chain_recon|mapping_survey)$/.test(taskDomain)
        ? 300
        : 600;
}

function minimumPoiWorkAltitudeFt(terrainFt = null, passenger = null) {
    if (!Number.isFinite(terrainFt)) return 0;
    return Math.round(Number(terrainFt) + 500 + missionPoiAltitudeToleranceFt(passenger));
}

function enforcePoiPassengerAltitudeRule(passenger, isPOI, poiTerrainFt = null, options = null) {
    if (!passenger || typeof passenger !== 'object') return passenger;
    const opts = (options && typeof options === 'object') ? options : {};
    const treatAsPoiTask = !!(isPOI || opts.treatAsPoiTask);
    const defaultTargetAltFt = Math.max(0, Math.round(Number(opts.defaultTargetAltFt) || 0));
    const defaultTargetRadiusNm = Math.max(0, Number(opts.defaultTargetRadiusNm) || 0);
    const defaultTargetDwellMin = Math.max(0, Number(opts.defaultTargetDwellMin) || 0);
    const ROLE_PROFILE_VALUES = new Set([
        'general_passenger_v1',
        'instructor_calm_precise_v1',
        'charter_professional_neutral_v1',
        'technical_inspector_v1',
        'media_observer_v1',
        'science_field_v1',
        'vip_business_v1',
        'club_utility_v1',
        'medical_sensitive_v1',
        'news_reporter_professional_v1',
        'tour_guide_relaxed_v1',
        'tour_guide_learning_v1',
        'historian_storyteller_v1',
        'photogrammetry_precision_v1',
        'cargo_fragile_highcare_v1',
        'rescue_coordination_v1',
        'fire_observer_ops_v1',
        'club_student_v1',
        'bush_pickup_guest_v1',
        'bush_charter_guest_v1',
        'bush_adventure_guest_v1'
    ]);
    const TASK_DOMAIN_VALUES = new Set([
        'general',
        'training',
        'charter',
        'inspection_infra',
        'infra_chain_recon',
        'media_photo',
        'science_bio',
        'science_geo',
        'science_general',
        'club_utility',
        'medical_transfer',
        'news_coverage',
        'private_outing',
        'sightseeing_tour',
        'poi_learning_guide',
        'historian_guided_tour',
        'mapping_survey',
        'cargo_fragile',
        'search_and_rescue',
        'fire_watch',
        'animal_transport',
        'club_training_basic',
        'club_training_advanced',
        'bush_pickup_return',
        'bush_adventure'
    ]);
    const _normRoleProfile = (v, fallback = 'general_passenger_v1') => {
        const s = String(v || '').trim().toLowerCase();
        return ROLE_PROFILE_VALUES.has(s) ? s : fallback;
    };
    const _normTaskDomain = (v, fallback = 'general') => {
        const s = String(v || '').trim().toLowerCase();
        return TASK_DOMAIN_VALUES.has(s) ? s : fallback;
    };
    const _deriveRoleProfileFromRole = (roleRaw, storyRaw) => {
        const hay = `${String(roleRaw || '').toLowerCase()} ${String(storyRaw || '').toLowerCase()}`;
        if (/(fluglehrer|fluglehrerin|instructor|instruktor|checkpilot)/.test(hay)) return 'instructor_calm_precise_v1';
        if (/(notarzt|notaerzt|sanitaet|rettung|mediz|arzt)/.test(hay)) return 'medical_sensitive_v1';
        if (/(report|journal|news|moderator|tv|presse)/.test(hay)) return 'news_reporter_professional_v1';
        if (/(lern-?guide|wissensflug|bildungsflug|faktenflug|kulturguide|museum aus der luft|lerntour)/.test(hay)) return 'tour_guide_learning_v1';
        if (/(tour|reiseleitung|stadtfuehr|guide|sightseeing)/.test(hay)) return 'tour_guide_relaxed_v1';
        if (/(historiker|historikerin|geschichte|denkmal|zeitreise|kultur)/.test(hay)) return 'historian_storyteller_v1';
        if (/(mapping|survey|photogram|lidar|geodaten|vermessung)/.test(hay)) return 'photogrammetry_precision_v1';
        if (/(fragil|zerbrech|praezision|kunstwerk|laborgeraet|stoßempfind)/.test(hay)) return 'cargo_fragile_highcare_v1';
        if (/(sar|search|rescue|rettungseinsatz|suchmuster)/.test(hay)) return 'rescue_coordination_v1';
        if (/(brand|rauch|hotspot|fire watch|waldbrand)/.test(hay)) return 'fire_observer_ops_v1';
        if (/(flugschueler|schueler|student|ausbildung)/.test(hay)) return 'club_student_v1';
        if (/(berater|anwalt|architekt|projektleiter|unternehmer|geschaeft|business|vip)/.test(hay)) return 'vip_business_v1';
        if (/(mechan|wartung|inspekt|techn|vermess|ingenieur|facility|pruef|prüfung|statik)/.test(hay)) return 'technical_inspector_v1';
        if (/(foto|film|medien|report|journal|immobilien)/.test(hay)) return 'media_observer_v1';
        if (/(wissenschaft|forschung|biolog|oekolog|ökolog|geolog|hydrolog|meteorolog|kartograf|analyst|naturschutz|wildwechsel|habitat)/.test(hay)) return 'science_field_v1';
        if (/(verein|stammtisch|hangar|ersatzteil)/.test(hay)) return 'club_utility_v1';
        return 'general_passenger_v1';
    };
    const _deriveTaskDomain = (roleRaw, storyRaw, roleProfileRaw) => {
        const roleProfile = _normRoleProfile(roleProfileRaw, '');
        if (roleProfile === 'instructor_calm_precise_v1') return 'training';
        if (roleProfile === 'charter_professional_neutral_v1') return 'charter';
        if (roleProfile === 'bush_pickup_guest_v1') return 'bush_pickup_return';
        if (roleProfile === 'bush_adventure_guest_v1') return 'bush_adventure';
        if (roleProfile === 'medical_sensitive_v1') return 'medical_transfer';
        if (roleProfile === 'news_reporter_professional_v1') return 'news_coverage';
        if (roleProfile === 'tour_guide_relaxed_v1') return 'sightseeing_tour';
        if (roleProfile === 'tour_guide_learning_v1') return 'poi_learning_guide';
        if (roleProfile === 'historian_storyteller_v1') return 'historian_guided_tour';
        if (roleProfile === 'photogrammetry_precision_v1') return 'mapping_survey';
        if (roleProfile === 'cargo_fragile_highcare_v1') return 'cargo_fragile';
        if (roleProfile === 'rescue_coordination_v1') return 'search_and_rescue';
        if (roleProfile === 'fire_observer_ops_v1') return 'fire_watch';
        if (roleProfile === 'club_student_v1') return 'club_training_basic';
        const hay = `${String(roleRaw || '').toLowerCase()} ${String(storyRaw || '').toLowerCase()}`;
        if (/(notarzt|notaerzt|mediz|sanitaet|blutkonserve|klinik|patient)/.test(hay)) return 'medical_transfer';
        if (/(report|news|presse|tv|journal|moderator)/.test(hay)) return 'news_coverage';
        if (/(\$\s*100|100\s*\$|burger|kaffee|kuchen|flugplatzcaf|wellness|wandern|wanderung|partner|partnerin|freund|freundin|familie|familienbesuch|wochenend|tagesausflug|staedtetrip|städtetrip|spaziergang)/.test(hay)) return 'private_outing';
        if (/(sightseeing|tour|stadtfuehr|ausflug|panorama)/.test(hay)) return 'sightseeing_tour';
        if (/(lern-?guide|wissensflug|bildungsflug|faktenflug|geschichte am ziel|kulturelle einordnung)/.test(hay)) return 'poi_learning_guide';
        if (/(historiker|historikerin|geschichte|zeitreise|denkmal|kulturhistor)/.test(hay)) return 'historian_guided_tour';
        if (/(mapping|survey|photogram|lidar|geodaten|kartier)/.test(hay)) return 'mapping_survey';
        if (/(fragil|zerbrech|praezision|kunstwerk|stoß|stoss|erschuetter)/.test(hay)) return 'cargo_fragile';
        if (/(sar|search|rescue|rettung|suchmuster|vermisst)/.test(hay)) return 'search_and_rescue';
        if (/(brand|rauch|hotspot|waldbrand|feuerwacht)/.test(hay)) return 'fire_watch';
        if (/(^|[^a-zäöüß])(animal|animal_transport|tier|tiertransport|tierschutz|welpen|katze|hund|ziege|reh|hirsch|möwe|moewe|gans|ente|enten|schwan|pferd|wildvogel|auffangstation|tierarzt)(?=$|[^a-zäöüß])/.test(hay)) return 'animal_transport';
        if (/(biolog|oekolog|ökolog|ornitholog|naturschutz|umwelt|schutzgebiet|wildpark|wildwechsel|habitat|besucherlenkung)/.test(hay)) return 'science_bio';
        if (/(geolog|hydrolog|erosion|hangstabil|gestein|sediment|rutsch)/.test(hay)) return 'science_geo';
        if (/(wissenschaft|forschung|meteorolog|kartograf|analyst)/.test(hay)) return 'science_general';
        if (/(kette|korridor|erstbefund|voruntersuchung|luftbildserie).{0,80}(infrastruktur|brueck|bruck|trasse|bahn|strass|strom|netz)|(?:infrastruktur|brueck|bruck|trasse|bahn|strass|strom|netz).{0,80}(kette|korridor|erstbefund|voruntersuchung|luftbildserie)/.test(hay)) return 'infra_chain_recon';
        if (/(inspekt|wartung|techn|vermess|brueck|bruck|autobahn|strass|funk|mast|damm|talsperre|schaden|sturm|stoer|stör|baufortschritt|waermebild|wärmebild|dach|hafen|marina|schleuse|anleger|zaunlinie|perimeter|zugang)/.test(hay)) return 'inspection_infra';
        if (/(foto|film|medien|immobilien|report|journal)/.test(hay)) return 'media_photo';
        if (/(verein|stammtisch|ersatzteil|mechaniker|hangar)/.test(hay)) return 'club_utility';
        return 'general';
    };
    const _normLevel = (v, fallback = 'mittel') => {
        const s = String(v || '').trim().toLowerCase();
        return (s === 'niedrig' || s === 'mittel' || s === 'hoch') ? s : fallback;
    };
    const _normUrgencyPriority = (v, fallback = 'niedrig') => {
        const s = String(v || '').trim().toLowerCase();
        if (s === 'hoch') return 'hoch';
        if (s === 'niedrig' || s === 'mittel' || s === 'normal' || s === 'medium') return 'niedrig';
        return fallback;
    };
    const _deriveStomachSensitivity = (gToleranceRaw) => {
        const gTol = _normLevel(gToleranceRaw, 'mittel');
        if (gTol === 'niedrig') return 'hoch';
        if (gTol === 'hoch') return 'niedrig';
        return 'mittel';
    };
    const normalized = {
        ...passenger,
        roleProfile: _normRoleProfile(
            passenger.roleProfile,
            _deriveRoleProfileFromRole(passenger.role, passenger.storyHint)
        ),
        taskDomain: _normTaskDomain(
            passenger.taskDomain,
            _deriveTaskDomain(passenger.role, passenger.storyHint, passenger.roleProfile)
        ),
        targetAltFt: Number(passenger.targetAltFt) || 0,
        targetRadiusNm: Number(passenger.targetRadiusNm) || 0,
        targetDwellMin: Number(passenger.targetDwellMin) || 0,
        dialectHint: typeof passenger.dialectHint === 'string' ? passenger.dialectHint.trim() : '',
        gTolerance: _normLevel(passenger.gTolerance, 'mittel'),
        bankTolerance: _normLevel(passenger.bankTolerance, 'mittel'),
        cargoSensitivity: _normLevel(passenger.cargoSensitivity, 'mittel'),
        stomachSensitivity: _normLevel(passenger.stomachSensitivity, _deriveStomachSensitivity(passenger.gTolerance)),
        comfortPriority: _normLevel(passenger.comfortPriority, 'mittel'),
        urgencyPriority: _normUrgencyPriority(passenger.urgencyPriority, 'niedrig')
    };

    // A-B Flüge: keine Arbeitsvorgaben am Ziel (nur Komfort/Charakter).
    if (!treatAsPoiTask) {
        normalized.targetAltFt = 0;
        normalized.targetRadiusNm = 0;
        normalized.targetDwellMin = 0;
        return normalized;
    }

    if (normalized.targetAltFt < 0) normalized.targetAltFt = 0;
    if (normalized.targetRadiusNm < 0) normalized.targetRadiusNm = 0;
    if (normalized.targetDwellMin < 0) normalized.targetDwellMin = 0;
    if (normalized.targetDwellMin > 5) normalized.targetDwellMin = 5;

    if (!(normalized.targetAltFt > 0) && defaultTargetAltFt > 0) normalized.targetAltFt = defaultTargetAltFt;
    if (!(normalized.targetRadiusNm > 0) && defaultTargetRadiusNm > 0) normalized.targetRadiusNm = defaultTargetRadiusNm;
    if (!(normalized.targetDwellMin > 0) && defaultTargetDwellMin > 0) normalized.targetDwellMin = defaultTargetDwellMin;

    if (normalized.targetAltFt > 0) {
        const minMslByTerrain = minimumPoiWorkAltitudeFt(poiTerrainFt, normalized);
        const minRequired = Math.max(500, minMslByTerrain);
        if (normalized.targetAltFt < minRequired) normalized.targetAltFt = minRequired;
        normalized.targetAltFt = roundPoiWorkAltitudeFt(normalized.targetAltFt, minRequired);
    }
    if (!normalized.dialectHint) normalized.dialectHint = 'neutral';
    return normalized;
}

function roundPoiWorkAltitudeFt(value = 0, minFt = 0) {
    const n = Number(value);
    if (!Number.isFinite(n) || n <= 0) return 0;
    const min = Number.isFinite(Number(minFt)) ? Math.max(0, Number(minFt)) : 0;
    let rounded = Math.round(Math.max(n, min) / 500) * 500;
    if (rounded < min) rounded += 500;
    return Math.max(500, rounded);
}

