function _missionPrivateOutingBriefingHasRelationConflict(text = '', passenger = {}) {
    const raw = String(text || '').replace(/\s+/g, ' ').trim();
    const normalized = normalizeMissionText(raw);
    const role = normalizeMissionText(passenger?.role || '');
    if (!normalized || !role) return false;
    if (/\b[A-ZÄÖÜ][A-Za-zÄÖÜäöüß-]+\s+[A-ZÄÖÜ][A-Za-zÄÖÜäöüß-]+\s+begleitet\s+dich\s+heute\s+als\b/.test(raw)) return true;
    const saysPartner = /\b(partner|partnerin|paarausflug|paartag|romantisch)\b/.test(normalized);
    const saysSibling = /\b(schwester|bruder|geschwister)\b/.test(normalized);
    const saysFamily = /\b(familie|familienbesuch|familienausflug|familienkontakt)\b/.test(normalized);
    const saysFriend = /\b(freund|freundin|fliegerfreund|fotofreund|wanderfreundin)\b/.test(normalized);
    if (/\b(schwester|bruder|geschwister)\b/.test(role) && saysPartner) return true;
    if (/\b(partner|partnerin)\b/.test(role) && (saysSibling || saysFamily)) return true;
    if (/\b(freund|freundin|fliegerfreund|fotofreund|wanderfreundin)\b/.test(role) && (saysSibling || /\bpartner(?:in)?\b/.test(normalized))) return true;
    if (/\b(familie|familienkontakt)\b/.test(role) && (saysPartner || saysFriend)) return true;
    return false;
}

function _missionPrivateOutingRelationPhrase(passenger = {}) {
    const role = String(passenger?.role || 'Ausflugsgast').replace(/\s+/g, ' ').trim();
    const lower = role.toLowerCase();
    if (!role || lower === 'ausflugsgast') return 'dein Ausflugsgast';
    if (/\b(partnerin|freundin|wanderfreundin|schwester)\b/i.test(role)) return `deine ${role}`;
    if (/\b(partner|freund|bruder|fotofreund|fliegerfreund)\b/i.test(role)) return `dein ${role}`;
    return String(passenger?.gender || '').toLowerCase() === 'female'
        ? `deine ${role}`
        : `dein ${role}`;
}

function _missionPrivateOutingSubjectPhrase(passenger = {}) {
    const paxName = String(passenger?.name || '').replace(/\s+/g, ' ').trim();
    const relation = _missionPrivateOutingRelationPhrase(passenger);
    if (!paxName || /^(gast|passagier|passenger|ausflugsgast)$/i.test(paxName)) {
        return relation && !/ausflugsgast/i.test(relation) ? relation : 'Der Ausflugsgast';
    }
    if (relation && !/ausflugsgast/i.test(relation)) return `${paxName}, ${relation}`;
    return paxName;
}

function _missionPrivateOutingSoftStoryAnchors(passenger = {}) {
    const paxName = String(passenger?.name || '').replace(/\s*\([^)]*\)\s*$/, '').replace(/\s+/g, ' ').trim();
    const firstName = String(paxName.split(/\s+/)[0] || '').trim();
    const hasFirstName = firstName && !/^(gast|passagier|passenger|ausflugsgast)$/i.test(firstName);
    const role = normalizeMissionText(passenger?.role || '');
    const sharedFamily = /\b(schwester|bruder|geschwister|familie|familienkontakt)\b/.test(role);
    const familyCircle = sharedFamily
        ? 'eure Familie'
        : (hasFirstName ? `die Familie von ${firstName}` : 'die Familie am Ziel');
    const familyPickup = sharedFamily
        ? 'einer aus eurer Familie'
        : (hasFirstName ? `ein Verwandter aus der Familie von ${firstName}` : 'ein Verwandter aus der Familie');
    return {
        firstName: hasFirstName ? firstName : '',
        familyCircle,
        familyPickup,
        familyVisit: sharedFamily ? 'eure Familienrunde' : 'der Familienbesuch'
    };
}

