function pickAnimalTransportSceneSpec(text = '') {
    const hay = String(text || '');
    const byText = ANIMAL_TRANSPORT_SCENE_OPTIONS.find(opt => opt.keywords && opt.keywords.test(hay));
    if (byText) return byText;
    return ANIMAL_TRANSPORT_SCENE_OPTIONS.find(opt => opt.label === 'Tiertransportbox')
        || ANIMAL_TRANSPORT_SCENE_OPTIONS.find(opt => opt.visible === false)
        || ANIMAL_TRANSPORT_SCENE_OPTIONS[0];
}

function animalTransportBoxLabel(animalSpec = null) {
    const cargoLabel = String(animalSpec?.cargoLabel || '').trim();
    if (cargoLabel) return cargoLabel;
    const label = String(animalSpec?.label || '').trim();
    if (label && !/transportbox|kiste|material/i.test(label)) return `${label}-Transportbox`;
    return label || 'Tiertransportbox';
}

function getMissionPlanV2Plan(missionPlanV2 = null) {
    if (!missionPlanV2 || typeof missionPlanV2 !== 'object') return null;
    if (String(missionPlanV2.status || '').toLowerCase() !== 'ready') return null;
    const plan = missionPlanV2.plan && typeof missionPlanV2.plan === 'object' ? missionPlanV2.plan : null;
    return plan || null;
}

function compactPoiKnowledgeFactListForMission(sourceFacts = [], maxFacts = 10, seenTexts = new Set()) {
    const limit = Math.max(0, Math.min(40, Math.round(Number(maxFacts) || 0)));
    const out = [];
    for (const fact of (Array.isArray(sourceFacts) ? sourceFacts : [])) {
        if (out.length >= limit) break;
        const clean = {
            source: String(fact?.source || 'wiki').replace(/\s+/g, ' ').trim() || 'wiki',
            topic: String(fact?.topic || 'general').replace(/\s+/g, ' ').trim() || 'general',
            text: String(fact?.text || fact || '').replace(/\s+/g, ' ').trim()
        };
        if (clean.text.length < 24) continue;
        const key = clean.text.toLowerCase();
        if (seenTexts.has(key)) continue;
        seenTexts.add(key);
        out.push(clean);
    }
    return out;
}

function compactPoiKnowledgeContextForMission(context = null, maxFacts = POI_KNOWLEDGE_CORE_FACT_LIMIT, options = {}) {
    if (!context || typeof context !== 'object') return null;
    const seenTexts = new Set();
    const facts = compactPoiKnowledgeFactListForMission(
        context.facts,
        Math.min(12, Math.round(Number(maxFacts) || POI_KNOWLEDGE_CORE_FACT_LIMIT)),
        seenTexts
    );
    const includeExtraFacts = options?.includeExtraFacts === true;
    const extraFacts = includeExtraFacts
        ? compactPoiKnowledgeFactListForMission(
            context.extraFacts,
            Math.min(24, Math.round(Number(options.maxExtraFacts) || POI_KNOWLEDGE_EXTRA_FACT_LIMIT)),
            seenTexts
        )
        : [];
    if (!facts.length && !context.ok && !context.status) return null;
    const num = value => Number.isFinite(Number(value)) ? Number(value) : null;
    const compact = {
        ok: context.ok === true,
        status: String(context.status || '').replace(/\s+/g, ' ').trim() || (context.ok ? 'accept' : 'unknown'),
        title: String(context.title || '').replace(/\s+/g, ' ').trim(),
        category: String(context.category || '').replace(/\s+/g, ' ').trim(),
        score: num(context.score),
        qid: String(context.qid || '').replace(/\s+/g, ' ').trim() || null,
        sourceUrl: String(context.sourceUrl || '').replace(/\s+/g, ' ').trim() || null,
        redirectedTo: String(context.redirectedTo || '').replace(/\s+/g, ' ').trim() || null,
        exactTitle: context.exactTitle === true,
        distanceKm: num(context.distanceKm),
        factCandidates: Number.isFinite(Number(context.factCandidates)) ? Math.round(Number(context.factCandidates)) : facts.length,
        selectedFacts: facts.length,
        topics: Array.isArray(context.topics)
            ? context.topics.map(x => String(x || '').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 8)
            : [],
        facts,
        warnings: Array.isArray(context.warnings)
            ? context.warnings.map(x => String(x || '').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 8)
            : [],
        rateLimited: context.rateLimited === true
    };
    if (context.aptSightseeing === true) compact.aptSightseeing = true;
    if (context.sightseeingPlace) compact.sightseeingPlace = String(context.sightseeingPlace || '').replace(/\s+/g, ' ').trim();
    if (Array.isArray(context.sightseeingLandmarks) && context.sightseeingLandmarks.length) {
        compact.sightseeingLandmarks = context.sightseeingLandmarks
            .map(item => ({
                title: String(item?.title || item || '').replace(/\s+/g, ' ').trim(),
                topic: String(item?.topic || 'landmark').replace(/\s+/g, ' ').trim() || 'landmark',
                distanceKm: Number.isFinite(Number(item?.distanceKm)) ? Number(item.distanceKm) : null,
                source: String(item?.source || 'wikipedia_geosearch').replace(/\s+/g, ' ').trim() || 'wikipedia_geosearch'
            }))
            .filter(item => item.title)
            .slice(0, APT_SIGHTSEEING_LANDMARK_LIMIT);
    }
    if (includeExtraFacts && extraFacts.length) {
        compact.extraFacts = extraFacts;
        compact.extraSelectedFacts = extraFacts.length;
        compact.availableFacts = facts.length + extraFacts.length;
    }
    return compact;
}

function buildPoiKnowledgeBriefingBlock(missionData = null, passenger = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : null;
    const pax = passenger || md?.passenger || md?.missionContract?.passenger || null;
    const taskDomain = String(pax?.taskDomain || md?.missionContract?.taskDomain || '').toLowerCase();
    if (taskDomain !== 'poi_learning_guide') return '';
    const context = md?.knowledgeContext || md?.missionContract?.knowledgeContext || pax?.knowledgeContext || null;
    if (!context || context.status !== 'accept') return '';
    const factCount = Math.max(
        Number.isFinite(Number(context.availableFacts)) ? Math.round(Number(context.availableFacts)) : 0,
        Number.isFinite(Number(context.selectedFacts)) ? Math.round(Number(context.selectedFacts)) : 0,
        Array.isArray(context.facts) ? context.facts.length : 0
    );
    if (factCount <= 0) return '';
    const target = String(context.title || md?.poiName || md?.targetName || 'Zielgebiet').replace(/\s+/g, ' ').trim();
    const paxName = String(pax?.name || 'Der Lern-Guide').replace(/\s+/g, ' ').trim();
    return `Guide-Hinweis: ${paxName} hat gesicherte Ortsfakten zu ${target} vorbereitet. Die Details kommen unterwegs als kurze Guide-Ansagen; das Briefing bleibt beim Rahmen des ruhigen Rundflugs.`;
}

function _missionBriefingCleanRouteLabel(value = '') {
    return String(value || '')
        .replace(/\s+/g, ' ')
        .replace(/^[^A-Za-z0-9ÄÖÜäöüß]+/g, '')
        .trim();
}

function _missionBriefingPublicIcao(value = '') {
    const raw = String(value || '').trim().toUpperCase();
    if (!/^[A-Z0-9]{3,5}$/.test(raw)) return '';
    if (/^(POI|HOSP|SAR|HOME|START|DEST|TARGET)$/.test(raw)) return '';
    return raw;
}

function _missionBriefingRoutePointLabel(icao = '', name = '') {
    return _missionBriefingPublicIcao(icao)
        || _missionBriefingCleanRouteLabel(name);
}

function _missionBriefingFormatDistanceNm(value = null) {
    const nm = Number(value);
    if (!Number.isFinite(nm) || nm <= 0) return '';
    const rounded = nm >= 20 ? Math.round(nm) : Math.round(nm * 10) / 10;
    return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
}

function _missionBriefingRouteWaypointLabels(missionData = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : {};
    const points = Array.isArray(md.routeWaypoints) ? md.routeWaypoints
        : (Array.isArray(md.missionRouteWaypoints) ? md.missionRouteWaypoints : []);
    if (points.length < 2) return [];
    const labels = [];
    for (const point of points) {
        const label = _missionBriefingRoutePointLabel(
            point?.icao,
            point?.name || point?.label || point?.title
        );
        if (!label) continue;
        if (labels[labels.length - 1] !== label) labels.push(label);
    }
    if (labels.length <= 4) return labels;
    return [labels[0], `${labels.length - 2} Wegpunkte`, labels[labels.length - 1]];
}

function buildMissionBriefingRouteInfoLine(missionData = null, options = {}) {
    const md = missionData && typeof missionData === 'object' ? missionData : {};
    const contractRoute = md.missionContractV4?.route
        || md.missionPlanV4?.route
        || md.missionContract?.missionContractV4?.route
        || md.missionContract?.route
        || {};
    let labels = _missionBriefingRouteWaypointLabels(md);
    if (labels.length < 2) {
        const startLabel = _missionBriefingRoutePointLabel(
            md.start || md.startIcao || contractRoute.startIcao || options.startIcao,
            md.startName || contractRoute.startName || options.startName
        );
        const isPoi = !!(md.isPOI || md.poiName || options.isPOI);
        const targetLabel = isPoi
            ? _missionBriefingCleanRouteLabel(md.poiName || md.targetName || contractRoute.targetName || options.targetName || 'Zielgebiet')
            : _missionBriefingRoutePointLabel(
                md.dest || md.initialDest || md.targetIcao || contractRoute.targetIcao || options.destIcao,
                md.targetName || md.initialTargetName || contractRoute.targetName || options.targetName
            );
        if (startLabel && targetLabel && targetLabel !== startLabel) {
            labels = isPoi ? [startLabel, targetLabel, startLabel] : [startLabel, targetLabel];
        }
    }
    const distanceLabel = _missionBriefingFormatDistanceNm(
        md.dist ?? md.initialDist ?? contractRoute.distanceNm ?? options.dist
    );
    if (labels.length >= 2) {
        return `Strecke: ${labels.join(' -> ')}${distanceLabel ? `, ca. ${distanceLabel} NM` : ''}.`;
    }
    if (distanceLabel) return `Entfernung: ca. ${distanceLabel} NM.`;
    return '';
}

function missionBriefingAlreadyHasStructuredRouteInfo(text = '') {
    const raw = String(text || '');
    if (/(^|\n)\s*(?:Strecke|Route|Distanz|Entfernung)\s*:/i.test(raw)) return true;
    const hasRoutePhrase = /\b(?:die\s+route\s+f(?:ü|ue)hrt|von\s+\S.{1,80}?\s+nach\s+\S)/i.test(raw);
    const hasDistance = /\b\d{1,4}(?:[,.]\d+)?\s*(?:NM|Seemeilen)\b/i.test(raw);
    return hasRoutePhrase && hasDistance;
}

function appendMissionBriefingRouteInfo(story = '', missionData = null, options = {}) {
    const base = String(story || '').trim();
    if (missionBriefingAlreadyHasStructuredRouteInfo(base)) return base;
    const routeLine = buildMissionBriefingRouteInfoLine(missionData, options);
    if (!routeLine) return base;
    return `${base}${base ? '\n\n' : ''}${routeLine}`;
}

function sanitizePoiBriefingRuleLeaks(text = '', missionData = null) {
    let out = String(text || '');
    const md = missionData && typeof missionData === 'object' ? missionData : null;
    const isPoi = !!(md?.isPOI || md?.poiName || md?.poiPresentation || missionUsesPoiTaskRecipe(md));
    if (!out || !isPoi || missionIsSarHeliMission(md)) return out;
    const replacement = 'Der Blick bleibt auf das Zielgebiet aus der Luft ausgerichtet; danach geht es zurück zur Basis.';
    out = out.replace(/(?:Denken Sie daran:\s*)?Keine\s+Landung\s+am\s+POI\.?/gi, replacement);
    out = out.replace(/(?:Denken Sie daran:\s*)?Keine\s+Landung\s+am\s+Ziel(?:gebiet)?\.?/gi, replacement);
    out = out.replace(/\s+([,.;:!?])/g, '$1').replace(/\n{3,}/g, '\n\n').trim();
    return out;
}

function buildMissionContract({ isPOI = false, missionType = '', bushSpec = null, requestedProfileId = 'auto', appliedProfileId = 'auto', mission = null, passenger = null, paxText = '', passengerCount = null, plannedPassengerCount = null, party = null, aircraftCapability = null, cargoText = '', category = '', targetSceneOverride = undefined, sceneIntentOverride = undefined, sceneAccepted = true, targetGeoContext = null, missionTruth = null, aptArrivalPlan = null, missionPlanV2 = null, missionPlanV4 = null, missionContractV4 = null, knowledgeContext = null, infraInspectionOutcome = null, poiChain = null } = {}) {
    const normalizedMissionType = normalizeMissionType(missionType || mission?.missionType || passenger?.missionType || '', isPOI);
    const profileGroup = normalizedMissionType === 'bush' ? 'bush' : (normalizedMissionType === 'poi' ? 'poi' : 'apt');
    const profile = getMissionTaskProfile(appliedProfileId, profileGroup) || getMissionTaskProfile('auto', profileGroup);
    const taskDomain = String(passenger?.taskDomain || profile?.taskDomain || 'general').toLowerCase();
    const roleProfile = String(passenger?.roleProfile || profile?.roleProfile || 'general_passenger_v1').toLowerCase();
    const urgencyPriority = (String(passenger?.urgencyPriority || '').toLowerCase() === 'hoch') ? 'hoch' : 'niedrig';
    const title = String(mission?.t || mission?.title || '').trim();
    const story = String(mission?.s || mission?.story || '').trim();
    const rawTargetScene = targetSceneOverride !== undefined ? targetSceneOverride : (mission?.targetScene || passenger?.targetScene || null);
    const targetScene = sanitizeMissionTargetSceneSpec(rawTargetScene, { isPOI, taskDomain, targetGeoContext, missionPlanV2 });
    const sceneIntent = sanitizeMissionSceneIntentSpec(
        sceneIntentOverride !== undefined ? sceneIntentOverride : (mission?.sceneIntent || passenger?.sceneIntent || null),
        { isPOI, taskDomain }
    );
    const summaryBase = normalizedMissionType === 'bush'
        ? 'Bush-Einsatz'
        : (profile?.label || (isPOI ? 'POI-Einsatz' : 'A-B Einsatz'));
    const modeLabel = normalizedMissionType === 'bush' ? 'BUSH' : (isPOI ? 'POI' : 'A-B');
    const summary = `${summaryBase} | ${modeLabel} | cat:${String(category || 'std')}`;
    const constraints = [
        `Rollenkonsistenz: roleProfile=${roleProfile}, taskDomain=${taskDomain}, urgency=${urgencyPriority}`,
        'Kein Themenmix zwischen Auftrag, PAX und Fracht',
        'Alle Folgeansagen bleiben im gleichen Auftragsrahmen'
    ];
    const normalizedBushSpec = (normalizedMissionType === 'bush' || bushSpec || mission?.bush || passenger?.bush)
        ? sanitizeBushMissionSpec(bushSpec || mission?.bush || passenger?.bush || null)
        : null;
    const compactKnowledgeContext = compactPoiKnowledgeContextForMission(
        knowledgeContext || mission?.knowledgeContext || passenger?.knowledgeContext || null,
        10
    );
    return {
        missionType: normalizedMissionType,
        requestedProfileId: String(requestedProfileId || 'auto').toLowerCase(),
        appliedProfileId: String(appliedProfileId || 'auto').toLowerCase(),
        summary,
        taskDomain,
        roleProfile,
        urgencyPriority,
        paxText: String(paxText || ''),
        passengerCount: Math.max(0, Math.min(6, Math.round(Number(passengerCount ?? mission?.passengerCount) || 0))),
        plannedPassengerCount: Math.max(0, Math.min(6, Math.round(Number(plannedPassengerCount ?? mission?.plannedPassengerCount ?? passengerCount ?? mission?.passengerCount) || 0))),
        party: party && typeof party === 'object'
            ? { ...party }
            : (mission?.party && typeof mission.party === 'object' ? { ...mission.party } : null),
        aircraftCapability: aircraftCapability && typeof aircraftCapability === 'object'
            ? { ...aircraftCapability, aircraftTags: [...(aircraftCapability.aircraftTags || [])] }
            : (mission?.aircraftCapability && typeof mission.aircraftCapability === 'object'
                ? { ...mission.aircraftCapability, aircraftTags: [...(mission.aircraftCapability.aircraftTags || [])] }
                : null),
        cargoText: String(cargoText || ''),
        missionTitle: title,
        missionStory: story,
        sceneIntent,
        sceneAccepted: !!sceneAccepted,
        targetGeoContext: targetGeoContext || mission?.targetGeoContext || passenger?.targetGeoContext || null,
        missionTruth: attachAptArrivalPlanToMissionTruth(missionTruth || mission?.missionTruth || passenger?.missionTruth || null, aptArrivalPlan),
        missionPlanV2: missionPlanV2 || mission?._missionPlanV2 || mission?.missionPlanV2 || passenger?.missionPlanV2 || null,
        missionPlanV4: missionPlanV4 || mission?._missionPlanV4 || mission?.missionPlanV4 || passenger?.missionPlanV4 || null,
        missionContractV4: missionContractV4 || mission?._missionContractV4 || mission?.missionContractV4 || passenger?.missionContractV4 || null,
        knowledgeContext: compactKnowledgeContext,
        missionVariety: mission?.missionVariety
            || missionContractV4?.pickupCreativeBrief?.variety
            || missionContractV4?.missionVarietyBrief?.variety
            || missionContractV4?.variety
            || missionPlanV4?.variety
            || missionPlanV2?.variety
            || null,
        aptArrivalPlan: aptArrivalPlan || mission?.aptArrivalPlan || passenger?.aptArrivalPlan || null,
        sarHeli: missionSarHeliSpecFromMission(mission) || null,
        bush: normalizedBushSpec,
        infraInspectionOutcome: infraInspectionOutcome || mission?.infraInspectionOutcome || passenger?.infraInspectionOutcome || null,
        poiChain: compactPoiChainForMission(poiChain || mission?.poiChain || passenger?.poiChain || missionContractV4?.poiChain || missionPlanV2?.poiChain || null, 8),
        targetScene,
        constraints
    };
}

const MISSION_SURVEY_PATTERN_DEFAULTS = {
    altitudeToleranceFt: 300,
    scan: {
        lineCount: 4,
        lineLengthNm: 1.6,
        lineSpacingNm: 0.35,
        crossTrackToleranceNm: 0.10,
        headingToleranceDeg: 35,
        minCoverage: 0.82,
        bins: 24,
        startEndTolerance: 0.18,
        resetGraceSec: 5,
        minGroundSpeedKts: 45
    },
    orbit: {
        radiusNm: 0.55,
        radialToleranceNm: 0.12,
        requiredTurns: 3,
        sectorsPerTurn: 36,
        minTurnCoverage: 0.86,
        resetGraceSec: 5,
        minGroundSpeedKts: 45,
        minTurnSec: 45
    }
};

function missionSurveyPatternTargetPoint(missionData = null, contract = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : {};
    const c = contract && typeof contract === 'object' ? contract : {};
    const truth = md.missionTruth || c.missionTruth || null;
    const main = truth?.mainTarget || null;
    const anchor = truth?.sceneAnchor || null;
    const sources = [
        main,
        anchor,
        { name: md.targetName || md.poiName, lat: md.targetLat, lon: md.targetLon },
        { name: md.poiName, lat: md.dest?.lat, lon: md.dest?.lon }
    ];
    for (const src of sources) {
        const lat = Number(src?.lat);
        const lon = Number(src?.lon ?? src?.lng);
        if (Number.isFinite(lat) && Number.isFinite(lon)) {
            return {
                name: String(src?.name || md.targetName || md.poiName || 'Zielgebiet').trim() || 'Zielgebiet',
                lat,
                lon,
                source: src === main ? 'missionTruth.mainTarget' : (src === anchor ? 'missionTruth.sceneAnchor' : 'missionData')
            };
        }
    }
    return null;
}

function missionSurveyPatternCategory(missionData = null, contract = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : {};
    const c = contract && typeof contract === 'object' ? contract : {};
    const truth = md.missionTruth || c.missionTruth || {};
    return String(
        truth.primaryCategory
        || truth.poiCategory
        || truth.requestedCategory
        || c.category
        || c.poiCategory
        || c.requestedCategory
        || md.poiCategory
        || md.category
        || md.requestedCategory
        || ''
    ).toLowerCase();
}

function missionSurveyPatternTypeForTarget(missionData = null, contract = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : {};
    const c = contract && typeof contract === 'object' ? contract : {};
    const truth = md.missionTruth || c.missionTruth || {};
    const category = missionSurveyPatternCategory(md, c);
    const geometryMode = String(truth.geometryMode || '').toLowerCase();
    if (/^(area|corridor|facility|broad_infrastructure)$/.test(geometryMode)) return 'north_south_scan';
    if (/^(city|town|village|settlement|generic|water|lake|river|canal|forest|mountain|industry|infrastructure|road|rail|dam|fire)$/.test(category)) {
        return 'north_south_scan';
    }
    return 'orbit';
}

function buildMissionSurveyPatternScanLines(center, scan = {}) {
    const lineCount = Math.max(1, Math.min(8, Math.round(Number(scan.lineCount || MISSION_SURVEY_PATTERN_DEFAULTS.scan.lineCount))));
    const lineLengthNm = Math.max(0.4, Math.min(5, Number(scan.lineLengthNm || MISSION_SURVEY_PATTERN_DEFAULTS.scan.lineLengthNm)));
    const lineSpacingNm = Math.max(0.12, Math.min(1.2, Number(scan.lineSpacingNm || MISSION_SURVEY_PATTERN_DEFAULTS.scan.lineSpacingNm)));
    const halfLen = lineLengthNm / 2;
    const mid = (lineCount - 1) / 2;
    const out = [];
    for (let i = 0; i < lineCount; i++) {
        const offsetNm = (i - mid) * lineSpacingNm;
        const base = Math.abs(offsetNm) > 0.0001
            ? getDestinationPoint(center.lat, center.lon, Math.abs(offsetNm), offsetNm >= 0 ? 90 : 270)
            : { ...center };
        const north = getDestinationPoint(base.lat, base.lon, halfLen, 0);
        const south = getDestinationPoint(base.lat, base.lon, halfLen, 180);
        out.push({
            id: `S${i + 1}`,
            label: `Survey-Linie ${i + 1}`,
            start: { lat: Math.round(north.lat * 1000000) / 1000000, lon: Math.round(north.lon * 1000000) / 1000000 },
            end: { lat: Math.round(south.lat * 1000000) / 1000000, lon: Math.round(south.lon * 1000000) / 1000000 }
        });
    }
    return out;
}

function buildMissionSurveyPatternSpec({ missionData = null, missionContract = null, passenger = null } = {}) {
    const md = missionData && typeof missionData === 'object' ? missionData : null;
    const contract = missionContract && typeof missionContract === 'object' ? missionContract : (md?.missionContract || null);
    const pax = passenger && typeof passenger === 'object' ? passenger : (md?.passenger || null);
    const taskDomain = String(pax?.taskDomain || contract?.taskDomain || '').toLowerCase();
    if (taskDomain !== 'mapping_survey') return null;
    const isPoiTask = !!(md?.isPOI || md?.poiName || md?.poiPresentation || missionUsesPoiTaskRecipe(md));
    if (!isPoiTask) return null;
    const target = missionSurveyPatternTargetPoint(md, contract);
    if (!target) return null;
    const type = missionSurveyPatternTypeForTarget(md, contract);
    const category = missionSurveyPatternCategory(md, contract);
    const targetAltFt = Math.max(0, Math.round(Number(pax?.targetAltFt || 0)));
    const center = {
        lat: Math.round(Number(target.lat) * 1000000) / 1000000,
        lon: Math.round(Number(target.lon) * 1000000) / 1000000
    };
    const scan = { ...MISSION_SURVEY_PATTERN_DEFAULTS.scan };
    if (/^(city|town|village|settlement|industry|infrastructure|dam)$/.test(category)) {
        scan.lineCount = 5;
        scan.lineLengthNm = 1.9;
        scan.lineSpacingNm = 0.35;
    } else if (/^(road|rail|river|canal)$/.test(category)) {
        scan.lineCount = 3;
        scan.lineLengthNm = 2.2;
        scan.lineSpacingNm = 0.32;
    } else if (/^(water|lake|forest|mountain|fire)$/.test(category)) {
        scan.lineCount = 4;
        scan.lineLengthNm = 2.0;
        scan.lineSpacingNm = 0.42;
    }
    scan.lines = buildMissionSurveyPatternScanLines(center, scan);
    const orbit = { ...MISSION_SURVEY_PATTERN_DEFAULTS.orbit };
    if (/^(castle|church|religious|monument|stadium|telecom|tower)$/.test(category)) {
        orbit.radiusNm = 0.45;
        orbit.radialToleranceNm = 0.10;
    } else if (category === 'bridge') {
        orbit.radiusNm = 0.50;
        orbit.radialToleranceNm = 0.11;
    }
    return {
        schema: 'ga.surveyPattern.v1',
        enabled: true,
        key: [
            'survey',
            String(md?.missionId || md?.missionKey || md?.targetName || md?.poiName || 'mission').replace(/[^a-zA-Z0-9_-]+/g, '-').slice(0, 48),
            type,
            center.lat.toFixed(5),
            center.lon.toFixed(5)
        ].join(':'),
        taskDomain: 'mapping_survey',
        type,
        label: type === 'orbit' ? 'Survey-Orbit' : 'Nord-Sued-Scan',
        targetLabel: target.name,
        targetSource: target.source,
        category,
        center,
        targetAltFt,
        altitudeToleranceFt: MISSION_SURVEY_PATTERN_DEFAULTS.altitudeToleranceFt,
        scan,
        orbit,
        completion: {
            mode: type === 'orbit' ? 'all_turns' : 'all_lines',
            returnToBaseOnComplete: true
        }
    };
}

function attachMissionSurveyPattern(missionData = null, missionContract = null, passenger = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : null;
    const contract = missionContract && typeof missionContract === 'object' ? missionContract : md?.missionContract || null;
    const spec = buildMissionSurveyPatternSpec({ missionData: md, missionContract: contract, passenger });
    if (!spec) {
        if (md && md.surveyPattern) delete md.surveyPattern;
        if (contract && contract.surveyPattern) delete contract.surveyPattern;
        return null;
    }
    if (md) md.surveyPattern = spec;
    if (contract) contract.surveyPattern = spec;
    return spec;
}

function refreshMissionSurveyOverlaySoon(missionData = null, passenger = null, reason = 'mission') {
    if (typeof window === 'undefined') return false;
    const run = () => {
        if (typeof window.missionSurveyPattern?.refreshOverlay !== 'function') return false;
        try {
            return window.missionSurveyPattern.refreshOverlay(
                missionData || currentMissionData || null,
                passenger || window.activePassenger || null
            );
        } catch (_) {
            return false;
        }
    };
    const first = run();
    if (typeof setTimeout === 'function') {
        [120, 450, 1200].forEach(delay => {
            setTimeout(() => {
                try { run(); } catch (_) {}
            }, delay);
        });
    }
    return first;
}

function refreshMissionPoiChainOverlaySoon(missionData = null, passenger = null, reason = 'mission') {
    if (typeof window === 'undefined') return false;
    const run = () => {
        if (typeof window.missionPoiChainRuntime?.refreshOverlay !== 'function') return false;
        try {
            return window.missionPoiChainRuntime.refreshOverlay(
                missionData || currentMissionData || null,
                passenger || window.activePassenger || null
            );
        } catch (_) {
            return false;
        }
    };
    const first = run();
    if (typeof setTimeout === 'function') {
        [120, 450, 1200, 2400, 4000].forEach(delay => {
            setTimeout(() => {
                try { run(); } catch (_) {}
            }, delay);
        });
    }
    return first;
}
window.buildMissionSurveyPatternSpec = buildMissionSurveyPatternSpec;
window.attachMissionSurveyPattern = attachMissionSurveyPattern;
window.refreshMissionSurveyOverlaySoon = refreshMissionSurveyOverlaySoon;
window.refreshMissionPoiChainOverlaySoon = refreshMissionPoiChainOverlaySoon;

function pickFireWatchExtent(truth, hazardLevel) {
    if (truth !== 'fire') return 'false_alarm';
    const h = Number.isFinite(Number(hazardLevel)) ? Number(hazardLevel) : 3;
    const r = Math.random();
    if (h >= 4) {
        if (r < 0.22) return 'major_fire';
        if (r < 0.58) return 'multi_smoke';
        return 'single_smoke';
    }
    if (h >= 3) {
        if (r < 0.12) return 'major_fire';
        if (r < 0.42) return 'multi_smoke';
        return 'single_smoke';
    }
    if (r < 0.05) return 'major_fire';
    if (r < 0.25) return 'multi_smoke';
    return 'single_smoke';
}

function fireWatchSiteCountForExtent(extent) {
    if (extent === 'major_fire') return 3;
    if (extent === 'multi_smoke') return 2;
    if (extent === 'single_smoke') return 1;
    return 0;
}

function buildFireWatchSmokeSites(dest, altFt, heading, extent) {
    const siteCount = fireWatchSiteCountForExtent(extent);
    if (!siteCount) return [];
    const baseBearing = Number.isFinite(Number(heading)) ? Number(heading) : Math.random() * 360;
    const sites = [];
    for (let i = 0; i < siteCount; i++) {
        const bearing = (baseBearing + 55 + i * 125 + Math.random() * 55) % 360;
        const distM = i === 0 ? Math.random() * 35 : (260 + i * 170 + Math.random() * 160);
        const p = getDestinationPoint(Number(dest.lat), Number(dest.lon), distM / 1852, bearing);
        const denseMajor = extent === 'major_fire';
        sites.push({
            siteId: `smoke-${i + 1}`,
            label: siteCount === 1 ? 'Rauchentwicklung' : `Rauchentwicklung ${i + 1}`,
            objectTitle: 'Chimney_Smoke_V1',
            lat: Number(p.lat),
            lon: Number(p.lon),
            altFt,
            hdg: Math.round((baseBearing + i * 35) % 360),
            count: denseMajor ? 9 : 8,
            radiusM: denseMajor ? 55 : 35
        });
    }
    return sites;
}

function buildFireWatchFireSites(smokeSites, extent, fireConfig = {}) {
    if (!Array.isArray(smokeSites) || smokeSites.length === 0) return [];
    const n = extent === 'major_fire' ? Math.min(2, smokeSites.length) : (extent === 'multi_smoke' ? 1 : 0);
    const ladderTest = fireConfig.testMode === 'offset_ladder' || fireConfig.testMode === 'fire_only_ladder';
    if (!n && !ladderTest) return [];
    const objectTitle = String(fireConfig.objectTitle || 'VO_Fire_R1_40').trim() || 'VO_Fire_R1_40';
    const altOffsetFt = Number.isFinite(Number(fireConfig.altOffsetFt)) ? Math.round(Number(fireConfig.altOffsetFt)) : 0;
    const count = Number.isFinite(Number(fireConfig.count)) ? Math.max(1, Math.min(6, Math.round(Number(fireConfig.count)))) : (extent === 'major_fire' ? 2 : 1);
    const radiusM = Number.isFinite(Number(fireConfig.radiusM)) ? Math.max(0, Math.min(80, Math.round(Number(fireConfig.radiusM)))) : (count > 1 ? 8 : 0);
    if (ladderTest) {
        const base = smokeSites[0];
        const offsets = [80, 40, 0, -40, -80, -120];
        return offsets.map((offset, idx) => {
            const sideM = (idx - (offsets.length - 1) / 2) * 55;
            const p = getDestinationPoint(Number(base.lat), Number(base.lon), Math.abs(sideM) / 1852, sideM >= 0 ? 90 : 270);
            return {
                siteId: `fire-offset-${offset}`,
                smokeSiteId: base.siteId,
                label: `Fire Offset ${offset} ft`,
                objectTitle,
                lat: Number(p.lat),
                lon: Number(p.lon),
                altFt: base.altFt,
                altOffsetFt: offset,
                hdg: base.hdg || 0,
                count: 1,
                radiusM: 0
            };
        });
    }
    return smokeSites.slice(0, n).map((site, idx) => ({
        siteId: `fire-${idx + 1}`,
        smokeSiteId: site.siteId,
        objectTitle,
        lat: site.lat,
        lon: site.lon,
        altFt: site.altFt,
        altOffsetFt,
        hdg: site.hdg || 0,
        count,
        radiusM
    }));
}

function missionAllowsFireWatchScenario({ mission = null, passenger = null } = {}) {
    const taskDomain = String(passenger?.taskDomain || mission?.passenger?.taskDomain || '').toLowerCase();
    const profileId = String(passenger?.roleProfile || mission?.profileId || mission?._appliedProfile || mission?._requestedProfile || '').toLowerCase();
    if (taskDomain === 'fire_watch' || profileId === 'fire_watch') return true;
    if (/(mapping|survey|photogrammetry|sightseeing|tour_guide|cargo|medical|search_and_rescue|rescue|sar)/.test(`${taskDomain} ${profileId}`)) return false;
    const titleStory = normalizeMissionText(`${mission?.t || ''} ${mission?.s || ''}`);
    return /(waldbrand|feuerwacht|rauchfahne|rauchentwicklung|brandherd|brandmeldung|hotspot|fire watch|smoke report)/.test(titleStory);
}

function missionDataAllowsFireWatchScenario(md = null, passenger = null, contract = null) {
    if (!md || typeof md !== 'object') return false;
    return missionAllowsFireWatchScenario({
        passenger: passenger || md?.passenger || contract?.passenger || null,
        mission: {
            t: md?.mission || contract?.missionTitle || contract?.summary || '',
            s: [contract?.missionStory, contract?.summary, md?.poiName, md?.targetName].filter(Boolean).join(' '),
            passenger: passenger || md?.passenger || contract?.passenger || null,
            profileId: contract?.appliedProfileId || contract?.requestedProfileId || md?.appliedProfile || md?.profile || ''
        }
    });
}

function buildFireWatchScenario({ isPOI = false, mission = null, passenger = null, dest = null, poiTerrainFt = null, heading = 0, fireHazard = null } = {}) {
    const isFireMission = isPOI && missionAllowsFireWatchScenario({ mission, passenger });
    if (!isFireMission || !dest || !Number.isFinite(Number(dest.lat)) || !Number.isFinite(Number(dest.lon))) return null;

    const hazardLevel = Number(fireHazard?.level);
    const fireProbability = Number.isFinite(hazardLevel)
        ? Math.max(0.25, Math.min(0.82, 0.18 + hazardLevel * 0.13))
        : 0.55;
    const debugTruthOverride = (typeof window.fireMissionTruthOverride === 'function')
        ? window.fireMissionTruthOverride()
        : null;
    const truth = debugTruthOverride || (Math.random() < fireProbability ? 'fire' : 'false_alarm');
    const debugExtentOverride = (typeof window.fireMissionExtentOverride === 'function')
        ? window.fireMissionExtentOverride()
        : null;
    const extent = (truth === 'fire' && debugExtentOverride && debugExtentOverride !== 'false_alarm')
        ? debugExtentOverride
        : pickFireWatchExtent(truth, hazardLevel);
    const altFt = Number.isFinite(Number(poiTerrainFt))
        ? Math.max(0, Math.round(Number(poiTerrainFt)))
        : Math.max(0, Math.round(Number(dest.elevation ?? currentDestElev ?? currentDepElev ?? 0)));
    const missionId = `fire-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const smokeSites = buildFireWatchSmokeSites(dest, altFt, heading, extent);
    const fireConfig = (typeof window.fireMissionFireOverride === 'function')
        ? (window.fireMissionFireOverride() || {})
        : {};
    const fireSites = buildFireWatchFireSites(smokeSites, extent, fireConfig);
    const fireObjectTitle = String(fireConfig.objectTitle || 'VO_Fire_R1_40').trim() || 'VO_Fire_R1_40';
    const fireAltOffsetFt = Number.isFinite(Number(fireConfig.altOffsetFt)) ? Math.round(Number(fireConfig.altOffsetFt)) : 0;

    return {
        enabled: true,
        type: 'fire_watch',
        missionId,
        truth,
        extent,
        smokeSiteCount: smokeSites.length,
        fireSiteCount: fireSites.length,
        state: 'enroute',
        createdAt: Date.now(),
        debugOverride: [debugTruthOverride || null, debugExtentOverride || null].filter(Boolean).join(',') || null,
        fireProbability: Math.round(fireProbability * 100) / 100,
        paxAwarenessRangeNm: 4,
        confirmRangeNm: 2,
        targetAreaNm: Number(passenger?.targetRadiusNm || 1.5) || 1.5,
        searchDwellSec: Math.max(120, Math.round(Number(passenger?.targetDwellMin || 3) * 60)),
        assessmentDwellSec: 240,
        target: {
            name: String(dest.n || dest.name || 'Zielgebiet'),
            lat: Number(dest.lat),
            lon: Number(dest.lon),
            altFt
        },
        smoke: {
            objectTitle: 'Chimney_Smoke_V1',
            lat: Number(dest.lat),
            lon: Number(dest.lon),
            altFt,
            hdg: Number.isFinite(Number(heading)) ? Math.round(Number(heading)) : 0,
            count: smokeSites[0]?.count || 0,
            radiusM: smokeSites[0]?.radiusM || 0,
            sites: smokeSites,
            spawned: false,
            spawnRequestedAt: 0,
            clearRequestedAt: 0
        },
        fire: {
            enabled: fireSites.length > 0,
            objectTitle: fireObjectTitle,
            altOffsetFt: fireAltOffsetFt,
            count: Number.isFinite(Number(fireConfig.count)) ? Math.round(Number(fireConfig.count)) : null,
            radiusM: Number.isFinite(Number(fireConfig.radiusM)) ? Math.round(Number(fireConfig.radiusM)) : null,
            testMode: fireConfig.testMode || null,
            sites: fireSites
        },
        observations: []
    };
}

function missionMatchesTaskProfile(missionLike, profileId, isPOI = false) {
    const id = String(profileId || 'auto').toLowerCase();
    if (!id || id === 'auto') return true;
    const expectedProfile = getMissionTaskProfile(id, isPOI ? 'poi' : 'apt') || null;
    const t = normalizeMissionText(missionLike?.t || missionLike?.title || '');
    const s = normalizeMissionText(missionLike?.s || missionLike?.story || '');
    const hay = `${t} ${s}`;
    const has = (re) => re.test(hay);
    const conflictsWithProfile = (profile) => {
        if (profile === 'sightseeing_tour') {
            const hardConflict = has(/\bverein|vereins|ersatzteil|pumpe|werkzeug|mechaniker|fracht|kurier|medizin|tierschutz|training|fluglehrer/);
            const softPrivateCue = !isPOI && has(/\bburger|kaffee|kuchen|flugplatzcaf|wellness|wandern|wanderung|familienbesuch/);
            const sightseeingAnchor = has(/\bsightseeing|panorama|rundflug|aussicht|blick|sehenswuerdig|sehenswürdig|landmarke|landmarken|altstadt|ortskern|schloss|museum|fotomotiv|fotomotive|fotos|spaziergang|zielregion/);
            return hardConflict || (softPrivateCue && !sightseeingAnchor);
        }
        if (profile === 'private_outing') {
            const privateCheckText = hay
                .replace(/\b(?:kein|keine|keinen|nicht\s+um\s+einen|nicht\s+als|ohne)\s+(?:rundflug|panorama|ueberflug|überflug|sightseeing|arbeitsauftrag|charter|fracht|medizin|training|reporter|redaktion)\b/g, ' ')
                .replace(/\b(?:kein|keine|keinen|nicht\s+um\s+eine|nicht\s+als|ohne)\s+(?:sightseeing[-\s]?tour|panorama[-\s]?tour|frachtmission|charterlogik|arbeitsmission)\b/g, ' ');
            return /\b(verein|vereins|ersatzteil|pumpe|werkzeug|mechaniker|fracht|kurier|medizin|tierschutz|training|fluglehrer|report|redaktion|sightseeing|panorama|rundflug|ueberflug|überflug)\b/.test(privateCheckText);
        }
        if (profile === 'cargo_fragile') return has(/\bverein|vereins|stammtisch|fly in|sightseeing|panorama|kuchen|burger|wellness|tour|konzert|city\b/);
        if (profile === 'animal_transport') return has(/\bverein|vereins|ersatzteil|pumpe|werkzeug|sightseeing|panorama|training|fluglehrer/);
        if (profile === 'medical_transfer') return has(/\bverein|vereins|sightseeing|panorama|kuchen|burger|tierschutz|tiertransport/);
        if (profile === 'news_coverage') return has(/\bverein|vereins|ersatzteil|pumpe|werkzeug|tierschutz|tiertransport|training|fluglehrer/);
        return false;
    };
    const rp = String(missionLike?.passenger?.roleProfile || '').toLowerCase().trim();
    const td = String(missionLike?.passenger?.taskDomain || '').toLowerCase().trim();
    if (expectedProfile && (rp || td)) {
        const rpOk = !expectedProfile.roleProfile || rp === String(expectedProfile.roleProfile || '').toLowerCase();
        const tdOk = !expectedProfile.taskDomain || td === String(expectedProfile.taskDomain || '').toLowerCase();
        if (rpOk && tdOk && !conflictsWithProfile(id)) return true;
    }

    if (id === 'medical_transfer') {
        return has(/organtransport|medicine emergency|medizin|medical|notfall|blut|plasma|anti serum|klinik|arzt|notarzt|labor kurier/);
    }
    if (id === 'cargo_fragile') {
        return has(/aog|ersatzteil|fracht|transport|kurier|urgent mail|high priority courier|archive transport|art transfer|uhren|flower delivery|labor/);
    }
    if (id === 'animal_transport') {
        return has(/(^|[^a-zäöüß])(animal|tier|tiertransport|tierrettung|tierarzt|hund|hunderettung|welpen|katze|ziege|reh|hirsch|möwe|moewe|gans|ente|enten|schwan|pferd|wildvogel|auffangstation|horse vet)(?=$|[^a-zäöüß])/);
    }
    if (id === 'news_coverage') {
        if (isPOI) return has(/report|redaktion|medien|kamera|dreh|event|fest|besucher|verkehr|stau|baustell|lage|aufhaenger|aufhänger|dokument|live|beobacht|ortsbild|veraender|veränder/);
        return has(/report|medien|kamera|dreh|event|verkehr|stau|city|festival|skydiver/);
    }
    if (id === 'private_outing') {
        const positive = has(/ausflug|burger|kaffee|kuchen|flugplatzcaf|wellness|wandern|wanderung|freund|freundin|familie|partner|partnerin|wochenend|tagesausflug|stadtetrip|städtetrip|spaziergang/);
        const negative = conflictsWithProfile(id) || has(/aog|ersatzteil|organtransport|medicine|notfall|urgent|kurier|fracht|transport|inspekt|vermess|arbeitsauftrag/);
        return positive && !negative;
    }
    if (id === 'sightseeing_tour') {
        const positive = has(/ausflug|stadtetrip|stadttrip|sightseeing|panorama|rundflug|aussicht|blick|sehenswuerdig|sehenswürdig|tour/);
        const negative = has(/aog|ersatzteil|organtransport|medicine|notfall|urgent|kurier|fracht|transport/);
        return positive && !negative && !conflictsWithProfile(id);
    }
    if (id === 'tour_guide_knowledge') {
        const positive = has(/bildungsflug|wissensflug|lernflug|fakten|einordnung|hintergrund|geschichte des ortes|kultur|reiseguide|ortskunde/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall|inspekt|schaden|riss|vermess/);
        return positive && !negative;
    }
    if (id === 'historian_guided_tour') {
        const positive = has(/histor|geschichte|zeitreise|denkmal|kultur|stadtfuehr|stadtfuehrung|stadtchron|ortschron|heimatforsch|ortsarchiv|archiv|ortskern|ortsbild|siedlungsform|alte wege|verkehrsweg|kirchenlage|marktplatzlage|tal|hang|schloss|burg|turm|fluss|berg/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall/);
        return positive && !negative;
    }
    if (id === 'science_bio') {
        const positive = has(/biolog|oekolog|ökolog|naturschutz|umwelt|vegetation|fauna|flora|habitat|gewasser|gewaesser|uferzone|trockenstress|rastbereich|brutbereich|monitoring|schilf|feucht|schutzgebiet|wildpark|wildwechsel|zaunlinie|besucherlenkung/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall/);
        return positive && !negative;
    }
    if (id === 'science_geo') {
        const positive = has(/geolog|geomorph|erosion|relief|hang|sediment|gestein|tal|berg|bruchkante|uferkante|abbruchkante|talform|hangstabil|fliessweg|fließweg|gelaende|gelände/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall/);
        return positive && !negative;
    }
    if (id === 'mapping_survey') {
        return has(/scan|vermess|lidar|photogram|kartier|topo|mess|dokumentation/);
    }
    if (id === 'infra_chain_recon') {
        const positive = has(/kette|korridor|erstbefund|voruntersuchung|luftbildserie|zwischenpunkt|folgepruef|folgeprüf|bodenteam|priorisier/);
        const domain = has(/infrastruktur|brueck|bruck|querung|bauwerk|trasse|bahn|strass|strom|netz|damm|wehr|wasserbau|betreiber/);
        return positive && domain;
    }
    if (id === 'inspection_infra') {
        return has(/inspekt|prüfung|pruef|wartung|schaden|sturm|stör|stoer|baufortschritt|zustand|waermebild|wärmebild|brueck|bruck|viadukt|pfeiler|widerlager|fundament|sperrung|unterfuehr|unterführ|hochstrass|hochstraß|damm|talsperre|industrie|anlage|infrastruktur|trasse|umspannwerk|windpark|windkraft|windrad|solarpark|solaranlage|photovoltaik|modulreihe|wechselrichter|trafopunkt|hafen|marina|schleuse|anleger|zaunlinie|perimeter|tor|zugang/);
    }
    if (id === 'media_photo') {
        const positive = has(/foto|film|kamera|luftbild|aufnahmen|bildserie|shots|establishing|dreh|pr|medien|redaktion|aufmacher|tourismus|ortsmarketing|gemeinde|jubilaeum|jubiläum|immobilien|jahresbericht|firmen|doku/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall/);
        return positive && !negative;
    }
    if (id === 'search_and_rescue') {
        return has(/sar|search|rescue|rettung|vermisst|suchmuster|einsatz|lagebild|polizei support/);
    }
    if (id === 'fire_watch') {
        return has(/brand|rauch|hotspot|feuer|waldbrand|fruhwarn|aufklar/);
    }
    return true;
}

function _pickUniqueTrainingItems(pool, count, used = new Set()) {
    const src = Array.isArray(pool) ? pool.filter(Boolean) : [];
    const shuffled = src
        .filter(item => !used.has(item))
        .sort(() => Math.random() - 0.5);
    const out = [];
    for (const item of shuffled) {
        out.push(item);
        used.add(item);
        if (out.length >= count) break;
    }
    return out;
}

function _isPatternFocusItem(text) {
    const s = String(text || '').toLowerCase();
    return /pattern|platzrunde|touch|go-around|missed|no-flap|engine-out|anflug|landung|final/.test(s);
}

function buildDistributedTrainingPlan(seedMode = 'airwork') {
    const totalCount = 4;
    const requiredCount = 2;
    const preferPattern = String(seedMode || '').toLowerCase() === 'pattern';
    let patternCount = 0;

    if (preferPattern) {
        patternCount = Math.min(totalCount - 1, totalCount >= 4 ? 2 : 1);
    } else if (totalCount >= 3 && Math.random() < 0.55) {
        // Airwork bleibt dominant, aber oft mit einer Landeuebung gemischt.
        patternCount = 1;
    }
    const airworkCount = Math.max(1, totalCount - patternCount);
    const used = new Set();
    const focus = [
        ..._pickUniqueTrainingItems(TRAINING_AIRWORK_ITEMS, airworkCount, used),
        ..._pickUniqueTrainingItems(TRAINING_PATTERN_ITEMS, patternCount, used)
    ];
    const mode = patternCount > 0 ? 'pattern' : 'airwork';
    const trigger = mode === 'pattern' ? 'five_nm_before_landing' : 'half_route';
    const instructorLine = mode === 'pattern'
        ? 'Wir machen erst die Uebungen in der Luft und gehen dann in eine Landeuebung am Platz.'
        : 'Wir bleiben heute beim Airwork: sauber, ruhig und mit klarem Ablauf.';
    return { mode, trigger, focus, instructorLine, requiredCount };
}

function sanitizeTrainingPlan(rawPlan, isTrainingMission) {
    if (!isTrainingMission) return null;
    if (!rawPlan || typeof rawPlan !== 'object') {
        return buildDistributedTrainingPlan('airwork');
    }
    const modeRaw = String(rawPlan.mode || '').toLowerCase();
    const requestedMode = (modeRaw === 'airwork' || modeRaw === 'pattern') ? modeRaw : 'airwork';
    const focusRaw = Array.isArray(rawPlan.focus) ? rawPlan.focus : [];
    let focus = focusRaw
        .map(x => String(x || '').trim())
        .filter(Boolean)
        .slice(0, 4);
    // Trainingsvielfalt erzwingen: insgesamt 2-4 Manoever, oft Airwork + optional 1 Pattern.
    if (focus.length < 2) {
        const fallback = buildDistributedTrainingPlan(requestedMode);
        focus = fallback.focus;
    } else {
        const hasPattern = focus.some(_isPatternFocusItem);
        if (!hasPattern && focus.length >= 3 && requestedMode === 'airwork' && Math.random() < 0.45) {
            const add = _pickUniqueTrainingItems(TRAINING_PATTERN_ITEMS, 1, new Set(focus));
            focus = focus.concat(add).slice(0, 4);
        }
    }
    const mode = focus.some(_isPatternFocusItem) ? 'pattern' : requestedMode;
    const requiredCount = Math.max(1, Math.min(focus.length, Math.round(Number(rawPlan.requiredCount || 2) || 2)));
    const triggerRaw = String(rawPlan.trigger || '').toLowerCase();
    const trigger = (triggerRaw === 'half_route' || triggerRaw === 'five_nm_before_landing')
        ? triggerRaw
        : (mode === 'pattern' ? 'five_nm_before_landing' : 'half_route');
    const instructorLine = String(rawPlan.instructorLine || '').trim().slice(0, 220);
    const instructorFallback = mode === 'pattern'
        ? 'Heute mit gemischtem Programm: Airwork im Uebungsgebiet, dann eine saubere Landeuebung am Platz.'
        : 'Heute konzentrieren wir uns auf Airwork mit ruhigem, sauberem Ablauf.';
    return { mode, trigger, focus, instructorLine: instructorLine || instructorFallback, requiredCount };
}

function resolveMissionPassengerCapacityPlan({
    paxText = '',
    passengerCount = null,
    pickupPassengerCount = null,
    aircraftCapability = null,
    roleLabel = '',
    preserveDash = false
} = {}) {
    const capability = aircraftCapability && typeof aircraftCapability === 'object'
        ? aircraftCapability
        : getMissionAircraftCapabilitySnapshot();
    const capabilityCore = window.aircraftMissionCapabilityCore;
    if (capabilityCore && typeof capabilityCore.resolveMissionPassengerPlan === 'function') {
        return capabilityCore.resolveMissionPassengerPlan({
            paxText,
            passengerCount,
            pickupPassengerCount,
            passengerCapacity: capability.passengerCapacity,
            maxPartySize: 1,
            roleLabel,
            preserveDash
        });
    }
    const match = String(paxText || '').match(/(\d+)\s*PAX/i);
    const requested = passengerCount !== null
        && passengerCount !== undefined
        && passengerCount !== ''
        && Number.isFinite(Number(passengerCount))
        ? Math.max(0, Math.min(6, Math.round(Number(passengerCount))))
        : Math.max(0, Math.min(6, parseInt(match?.[1] || '0', 10) || 0));
    const capacity = Math.max(0, Math.min(6, Math.round(Number(capability.passengerCapacity) || 0)));
    const count = requested > 0 && capacity > 0 ? 1 : 0;
    return {
        passengerCapacity: capacity,
        requestedPassengerCount: requested,
        requestedPickupPassengerCount: 0,
        passengerCount: count,
        pickupPassengerCount: 0,
        plannedPassengerCount: count,
        requiresPassenger: requested > 0,
        blocked: requested > 0 && capacity <= 0,
        deferredPickup: false,
        paxText: count > 0 ? `1 PAX${roleLabel ? ` (${roleLabel})` : ''}` : (preserveDash && /^\s*-\s*$/.test(String(paxText || '')) ? '-' : '0 PAX'),
        party: count > 0 ? { count: 1, kind: 'single', label: roleLabel || 'Passagier' } : null
    };
}

function formatPaxBriefingText(paxText, passenger) {
    const base = String(paxText || '').trim();
    const name = String(passenger?.name || '').trim();
    const role = String(passenger?.role || '').trim();
    if (!base || !name) return base;
    if (/^\s*0\s*PAX\b/i.test(base)) return base;
    if (base.toLowerCase().includes(name.toLowerCase())) return base;
    const m = base.match(/^(.*)\(([^)]*)\)\s*$/);
    if (m) {
        const left = String(m[1] || '').trim();
        const inner = String(m[2] || '').trim();
        const descriptor = role || inner;
        if (!descriptor) return `${left} (${name})`.trim();
        return `${left} (${descriptor}: ${name})`.trim();
    }
    return `${base} (${name})`;
}

function buildBushPickupStoryHint({
    mission = null,
    missionPlanV2 = null,
    missionContractV4 = null,
    targetGeoContext = null,
    dest = null
} = {}) {
    const parts = [];
    const add = (value) => {
        if (Array.isArray(value)) {
            value.forEach(add);
            return;
        }
        if (value && typeof value === 'object') {
            Object.values(value).forEach(add);
            return;
        }
        const text = String(value || '').replace(/\s+/g, ' ').trim();
        if (text) parts.push(text.slice(0, 360));
    };
    const plan = missionPlanV2?.plan && typeof missionPlanV2.plan === 'object' ? missionPlanV2.plan : {};
    const frame = plan.storyFrame && typeof plan.storyFrame === 'object' ? plan.storyFrame : {};
    const contractPlan = missionContractV4?.plan && typeof missionContractV4.plan === 'object' ? missionContractV4.plan : {};
    const contractFrame = missionContractV4?.storyFrame && typeof missionContractV4.storyFrame === 'object'
        ? missionContractV4.storyFrame
        : (contractPlan.storyFrame && typeof contractPlan.storyFrame === 'object' ? contractPlan.storyFrame : {});
    add(dest?.n || dest?.name || dest?.icao);
    add(mission?.t);
    add(mission?.s);
    add(mission?.pax);
    add(plan.primaryObjective);
    add(plan.missionTrigger);
    add(plan.focusSubject);
    add(plan.keyQuestion);
    add(plan.missionStakes);
    add(plan.completionSignal);
    add(plan.localFacts);
    add(plan.weatherHooks);
    add(plan.operationalDetails);
    add(plan.realismBrief);
    add(plan.narrativeHooks);
    add(plan.mustMention);
    add(frame);
    add(contractPlan.primaryObjective);
    add(contractPlan.mustMention);
    add(contractFrame);
    add(targetGeoContext?.summary);
    add(targetGeoContext?.localFacts);
    add(targetGeoContext?.airportDetails);
    return parts.join(' | ').slice(0, 1800);
}

function compactBushPickupStoryExcerpt(text = '', maxLen = 320) {
    const clean = String(text || '')
        .replace(/\s+/g, ' ')
        .trim();
    if (!clean) return '';
    const sentences = clean
        .split(/(?<=[.!?])\s+/)
        .map(s => s.trim())
        .filter(Boolean);
    let out = '';
    for (const sentence of sentences) {
        const next = `${out}${out ? ' ' : ''}${sentence}`.trim();
        if (next.length > maxLen && out) break;
        out = next;
        if (out.length >= Math.min(180, maxLen)) break;
    }
    return (out || clean).slice(0, maxLen).trim();
}

function bushPickupStorySentences(text = '') {
    return String(text || '')
        .replace(/\s+/g, ' ')
        .trim()
        .split(/(?<=[.!?])\s+/)
        .map(s => s.trim())
        .filter(Boolean);
}

function pickBushPickupStorySentence(text = '', pattern = null, maxLen = 260) {
    const sentences = bushPickupStorySentences(text);
    const re = pattern instanceof RegExp ? pattern : null;
    const picked = re ? sentences.find(sentence => re.test(normalizeMissionText(sentence))) : sentences[0];
    return String(picked || '').slice(0, maxLen).trim();
}

function normalizeBushPickupWhyThereText(value = '', targetName = 'dem Zielstrip') {
    const clean = _missionPipelineV4BushPickupDisplayText(value).replace(/\s+/g, ' ').trim();
    if (!clean) return '';
    const parts = clean.split(/\s*;\s*/).map(part => part.trim()).filter(Boolean);
    if (!parts.length) return clean;
    const first = parts[0];
    const firstNorm = normalizeMissionText(first);
    const needsAccessSentence = _missionPipelineV4LooksBushPickupFragmentText(first)
        || /^(?:der\s+)?strip\s+(?:selbst\s+)?(?:ist|liegt|dient|bleibt)\b/.test(firstNorm)
        || /^(treffpunkt|abholpunkt|naechster|nachster|nächster|sicherer|neutraler|kurzer|schnellster|besserer)\b/.test(firstNorm);
    if (!needsAccessSentence) return clean;
    const access = _missionPipelineV4StripSentenceEnd(
        _missionPipelineV4BushPickupAccessSentence(first, targetName)
    ).replace(/[.!?]+$/g, '').trim();
    return [access, ...parts.slice(1)].filter(Boolean).join('; ');
}

function bushPickupRoleContext(role = '', storyText = '') {
    const hay = normalizeMissionText(`${role} ${storyText}`);
    if (/\b(hydrolog|wasserstand|pegel|fluss|river|bach|ufer|sediment)\b/.test(hay)) {
        return {
            equipment: 'Feldmappe, Tablet, Wasserproben und zwei leichten Kisten',
            boarding: 'Die Pegelpunkte sind kontrolliert, die Wasserproben sind beschriftet und die Messdaten liegen im Tablet.',
            departure: 'In der Basis werden Wasserstandsreihen, Proben und Fotos ausgewertet und an die nächste Crew übergeben.',
            returnReason: 'In der Basis gehen Messdaten, Proben und Fotos in die nächste Einsatzplanung.'
        };
    }
    if (/\b(geolog|gestein|fels|hang|erosion|rutsch|kartier|probe|sediment)\b/.test(hay)) {
        return {
            equipment: 'Probenbeuteln, GPS-Notizen, Feldskizzen und einem Messkoffer',
            boarding: 'Die Proben sind beschriftet, die GPS-Punkte sitzen und die Feldskizzen sind trocken verpackt.',
            departure: 'In der Basis werden Proben, Fotos und Kartiernotizen zusammengeführt.',
            returnReason: 'In der Basis gehen Proben, Fotos und Kartiernotizen an das Projektteam.'
        };
    }
    if (/\b(ranger|wildlife|trail|forst|permit|bachlauf|markierung|sperr)\b/.test(hay)) {
        return {
            equipment: 'Rucksack, Markierungsband, Kartenmappe und einer kleinen Rückholkiste',
            boarding: 'Die Markierungen sind gesetzt, die Fotos sind im Tablet und die Notizen für die Rangerstation sind vollständig.',
            departure: 'Die Rangerstation braucht die Sperr- und Zustandsnotizen für die nächste Crewplanung.',
            returnReason: 'In der Basis werden Zustandsnotizen, Fotos und Markierungen für die nächste Crewplanung abgegeben.'
        };
    }
    if (/\b(technik|techniker|inspekt|mechan|wartung|funk|relais|generator|pruef|prüf|maengel|mängel)\b/.test(hay)) {
        return {
            equipment: 'Prüfmappe, Werkzeugtasche, Tablet und zwei leichten Kisten',
            boarding: 'Die Prüfung ist abgeschlossen, die Fotos sind im Tablet und die kleinen Kisten können mit zurück.',
            departure: 'In der Basis gehen Prüfwerte, Mängelliste und Ersatzteilbedarf in die nächste Planung.',
            returnReason: 'In der Basis werden Prüfwerte, Mängelliste und Materialbedarf für den nächsten Einsatz eingetragen.'
        };
    }
    return {
        equipment: 'Feldmappe, Tablet, persönlichem Gepäck und leichter Ausrüstung',
        boarding: 'Die Feldnotizen sind vollständig, die Fotos sind gesichert und die leichte Ausrüstung ist bereit für den Rückflug.',
        departure: 'In der Basis gehen Notizen, Daten und Rückholmaterial in den nächsten Ablauf.',
        returnReason: 'In der Basis werden Notizen, Daten und Rückholmaterial für den nächsten Schritt übergeben.'
    };
}

function buildAiBushPickupStory({
    aiPassenger = null,
    storyText = '',
    fallbackPickupStory = null,
    dest = null,
    start = null
} = {}) {
    const passenger = aiPassenger && typeof aiPassenger === 'object' ? aiPassenger : {};
    const aiStory = passenger.pickupStory && typeof passenger.pickupStory === 'object' ? passenger.pickupStory : {};
    const display = (value = '') => _missionPipelineV4BushPickupDisplayText(String(value || '')).replace(/\s+/g, ' ').trim();
    const role = display(aiStory.role || passenger.role || fallbackPickupStory?.role || 'Pickup-Gast');
    const personName = display(aiStory.personName || passenger.name || fallbackPickupStory?.personName || '');
    const targetName = String(dest?.n || dest?.name || dest?.icao || 'dem Zielstrip').trim();
    const homeName = String(start?.n || start?.name || start?.icao || currentStartICAO || 'dem Heimatplatz').trim();
    const roleContext = bushPickupRoleContext(role, storyText);
    const storyReturn = display(pickBushPickupStorySentence(
        storyText,
        /\b(zurueck|zurück|heim|basis|mccall|auswert|ueberg|überg|bericht|planung|crew|naechst|nächst|handoff|termin|freigabe)\b/,
        280
    ));
    const storyWork = display(pickBushPickupStorySentence(
        storyText,
        /\b(gemess|mess|probe|daten|foto|tablet|karte|skizz|markier|kontroll|geprueft|geprüft|dokument|wartung|feld)\b/,
        320
    ));
    const exactWhere = display(aiStory.exactWhere)
        || `am Striprand bei ${targetName}, neben einem kleinen Geländewagen mit ${roleContext.equipment}`;
    const whyThere = normalizeBushPickupWhyThereText(aiStory.whyThere, targetName)
        || compactBushPickupStoryExcerpt(storyText, 320)
        || normalizeBushPickupWhyThereText(fallbackPickupStory?.whyThere, targetName);
    const returnReason = display(aiStory.returnReason)
        || storyReturn
        || roleContext.returnReason.replace(/\bder Basis\b/g, homeName);
    const boardingCue = display(aiStory.boardingCue)
        || storyWork
        || roleContext.boarding;
    const departureCue = display(aiStory.departureCue)
        || roleContext.departure.replace(/\bder Basis\b/g, homeName);
    const story = {
        personName,
        role,
        exactWhere,
        whyThere,
        returnReason,
        boardingCue,
        departureCue
    };
    return (typeof _sanitizeBushPickupStory === 'function')
        ? _sanitizeBushPickupStory(story)
        : story;
}

function sanitizeBushPickupBriefingWhere(value = '', fallback = 'am Treffpunkt am Zielstrip') {
    let text = String(value || '').replace(/\s+/g, ' ').trim().replace(/[.!?]+$/g, '');
    if (!text) return fallback;
    text = text
        .replace(/^ich\s+(?:warte|stehe|sitze)\s+/i, '')
        .replace(/^ich\s+bin\s+/i, '')
        .replace(/^(?:warte|stehe|sitze)\s+/i, '')
        .replace(/\s+(?:und\s+)?(?:warte|stehe|sitze)?\s*(?:hier\s+)?auf\s+(?:sie|dich|den\s+piloten|meine\s+abholung)\s*$/i, '')
        .replace(/\s+auf\s+(?:sie|dich|den\s+piloten|meine\s+abholung)\s*$/i, '')
        .replace(/\bmein(?:e|en|em|er)?\s+/gi, '')
        .replace(/\s+/g, ' ')
        .trim();
    return text || fallback;
}

function addBushPickupNameToStory(storyText = '', { name = '', role = '', exactWhere = '' } = {}) {
    const story = String(storyText || '').replace(/\s+/g, ' ').trim();
    const personName = String(name || '').trim();
    if (!story || !personName) return story;
    if (story.toLowerCase().includes(personName.toLowerCase())) return story;
    const roleText = String(role || '').trim();
    const where = sanitizeBushPickupBriefingWhere(exactWhere, 'am Treffpunkt am Zielstrip');
    const intro = roleText
        ? `${personName}, ${roleText}, wartet ${where}.`
        : `${personName} wartet ${where}.`;
    return `${intro} ${story}`;
}

function missionHasPassengerByPaxText(paxText) {
    const txt = String(paxText || '').trim();
    if (!txt) return true;
    const m = txt.match(/^\s*(\d+)\s*PAX\b/i);
    if (m) return parseInt(m[1], 10) > 0;
    return !/^\s*0\s*PAX\b/i.test(txt);
}

