function _missionSemanticsV4NormalizeCategory(value = '') {
    const raw = String(value || '').trim().toLowerCase();
    if (!raw) return 'generic';
    if (['bridge', 'water', 'mountain', 'forest', 'fire', 'city', 'castle', 'road', 'cargo'].includes(raw)) return raw;
    if (/cargo|fracht|kurier|sendung|lieferung|transport/.test(raw)) return 'cargo';
    if (/lake|river|shore|dam|reservoir|basin|water/.test(raw)) return 'water';
    if (/fire|brand|rauch|smoke|hotspot/.test(raw)) return 'fire';
    if (/forest|wood|wald|forst/.test(raw)) return 'forest';
    if (/mountain|ridge|summit|terrain|peak|cliff|hill/.test(raw)) return 'mountain';
    if (/road|street|strasse|straße|traffic|junction|intersection|roundabout|kreuzung|zufahrt|parking/.test(raw)) return 'road';
    if (/town|village|city|settlement/.test(raw)) return 'city';
    if (/ruin|fort|castle|schloss|burg/.test(raw)) return 'castle';
    return 'generic';
}

function _missionSemanticsV4IsGenericTargetLabel(label = '') {
    const raw = String(label || '').trim();
    const normalized = normalizeMissionText(raw);
    if (!normalized) return true;
    if (raw.length <= 2) return true;
    return /^(yes|no|unknown|poi|ziel|water|wasser|gewaesser|gewasser|gewaesserbereich|gewasserbereich|ufer|uferbereich|uferlinie|shoreline|water edge|water_edge|ditch|stream|river|terrain|road|track|path|footway|service|parking|building|traffic signals|traffic_signals|crossing|minor line|minor_line|meadow|farmland|grass|grassland|village green|village_green|field|fields|clearing|forest|wood|woods|scrub|heath|orchard|vineyard|wiese|wiesen|acker|feld|felder|lichtung|wald|forst)$/.test(normalized);
}

function _missionSemanticsV4TargetLabelOrFallback(label = '', fallback = 'Ziel') {
    const raw = String(label || '').trim();
    const fallbackText = String(fallback || '').trim();
    if (raw && !_missionSemanticsV4IsGenericTargetLabel(raw)) return raw;
    if (fallbackText) return fallbackText;
    return raw || 'Ziel';
}

function _missionSemanticsV4Build({
    mode = 'apt',
    taskDomain = 'general',
    targetCategory = 'generic',
    requestedCategory = 'all',
    targetName = '',
    missionTruth = null
} = {}) {
    const normalizedMode = normalizeMissionType(mode || '', mode === 'poi');
    const domainKey = String(taskDomain || 'general').trim().toLowerCase() || 'general';
    const categoryKey = _missionSemanticsV4NormalizeCategory(
        missionTruth?.primaryCategory || targetCategory || requestedCategory || 'generic'
    );
    const truthMain = missionTruth?.mainTarget || null;
    const truthMainName = String(truthMain?.name || '').trim();
    const targetLabel = String(targetName || '').trim();
    const primarySubjectLabel = _missionSemanticsV4TargetLabelOrFallback(truthMainName, targetLabel || truthMainName || 'Ziel');
    const primarySubjectType = String(truthMain?.kind || categoryKey || normalizedMode).trim().toLowerCase() || normalizedMode;
    const modeRule = MISSION_SEMANTICS_V4_RULESET.modeRules[normalizedMode] || MISSION_SEMANTICS_V4_RULESET.modeRules.apt;
    const domainRule = MISSION_SEMANTICS_V4_RULESET.domainRules[domainKey] || MISSION_SEMANTICS_V4_RULESET.domainRules.general;
    const categoryRule = MISSION_SEMANTICS_V4_RULESET.categoryRules[categoryKey] || MISSION_SEMANTICS_V4_RULESET.categoryRules.generic;
    const plannerGuardrails = [
        `Primary subject lock: ${primarySubjectLabel} (${primarySubjectType}) bleibt Hauptsubjekt.`,
        `Task-domain lock: ${domainKey} bleibt die Art des Auftrags.`,
        `Kontextrollen: ${MISSION_SEMANTICS_V4_RULESET.contextRoles.join(', ')}.`,
        ...modeRule.planner,
        ...domainRule.planner,
        ...categoryRule.planner
    ];
    const writerGuardrails = [
        `Story, Greeting und sceneIntent muessen ${primarySubjectLabel} als Primaerfokus behalten.`,
        'Kontext darf den Auftrag anreichern, aber nicht umwidmen.',
        ...modeRule.writer,
        ...domainRule.writer,
        ...categoryRule.writer
    ];
    return {
        version: MISSION_SEMANTICS_V4_VERSION,
        focusLock: {
            mode: normalizedMode,
            taskDomain: domainKey,
            targetCategory: categoryKey,
            requestedCategory: String(requestedCategory || '').trim().toLowerCase() || null,
            primarySubjectLabel,
            primarySubjectType,
            contextRoles: [...MISSION_SEMANTICS_V4_RULESET.contextRoles]
        },
        plannerGuardrails,
        writerGuardrails,
        forceSceneNone: !!domainRule.forceSceneNone,
        naturalPriority: !!domainRule.naturalPriority
    };
}

function _missionSemanticsV4SortTexts(values = [], semantics = {}, kind = 'facts') {
    const src = Array.isArray(values) ? values.filter(Boolean).map(v => String(v).trim()).filter(Boolean) : [];
    if (!src.length) return [];
    const task = String(semantics?.focusLock?.taskDomain || '').toLowerCase();
    const category = String(semantics?.focusLock?.targetCategory || '').toLowerCase();
    const subject = String(semantics?.focusLock?.primarySubjectLabel || '').toLowerCase();
    const weightOf = (text) => {
        const hay = normalizeMissionText(text);
        let score = 0;
        if (subject && hay.includes(normalizeMissionText(subject))) score -= 3;
        if (task === 'search_and_rescue' && semantics?.naturalPriority && !['road', 'water'].includes(category)) {
            if (/(wald|forest|hang|gipfel|berg|kuppe|such|perimeter|lichtung|gelaende|terrain|trail|pfad|ridge|nature|offen)/.test(hay)) score -= 2;
            if (/(strasse|straße|road|klinik|power|mast|leitung|park|parking|building|gebaeude|gebäude|rail|bahn)/.test(hay)) score += 2;
        }
        if (category === 'bridge') {
            if (/(brueck|brück|bridge|viadukt|span|pfeiler|widerlager|deck)/.test(hay)) score -= 2;
            if (/(strasse|straße|road|rail|bahn|ufer|water|zufahrt)/.test(hay)) score += 1;
        }
        if (kind === 'avoid' && /drift|umwidm|ersetzen/.test(hay)) score -= 2;
        return score;
    };
    return src
        .map((text, index) => ({ text, index, weight: weightOf(text) }))
        .sort((a, b) => (a.weight - b.weight) || (a.index - b.index))
        .map(entry => entry.text);
}

function _missionPipelineV4PickOne(values = []) {
    const src = Array.isArray(values) ? values.filter(Boolean) : [];
    if (!src.length) return '';
    return String(src[Math.floor(Math.random() * src.length)] || src[0] || '');
}

function _missionPipelineV4PickEntry(values = []) {
    const src = Array.isArray(values) ? values.filter(item => item !== undefined && item !== null) : [];
    if (!src.length) return null;
    return src[Math.floor(Math.random() * src.length)] ?? src[0] ?? null;
}

function _missionPipelineV4BushPickupDisplayText(text = '') {
    return String(text || '')
        .replace(/\bfuer\b/g, 'für')
        .replace(/\bFuer\b/g, 'Für')
        .replace(/\bzurueck\b/g, 'zurück')
        .replace(/\bZurueck\b/g, 'Zurück')
        .replace(/\bRueckflug\b/g, 'Rückflug')
        .replace(/\bRueckkehr\b/g, 'Rückkehr')
        .replace(/\bRueckmeldung\b/g, 'Rückmeldung')
        .replace(/\bRueckhol/g, 'Rückhol')
        .replace(/\bRueckweg\b/g, 'Rückweg')
        .replace(/\bRueckfahrt\b/g, 'Rückfahrt')
        .replace(/\bnaechste\b/g, 'nächste')
        .replace(/\bNaechste\b/g, 'Nächste')
        .replace(/\bnaechster\b/g, 'nächster')
        .replace(/\bNaechster\b/g, 'Nächster')
        .replace(/\bnaechsten\b/g, 'nächsten')
        .replace(/\bNaechsten\b/g, 'Nächsten')
        .replace(/\bGelaende/g, 'Gelände')
        .replace(/\bgelaende/g, 'gelände')
        .replace(/\bGelaendewagen\b/g, 'Geländewagen')
        .replace(/\bgeprueft\b/g, 'geprüft')
        .replace(/\bgepruefte\b/g, 'geprüfte')
        .replace(/\bgeprueften\b/g, 'geprüften')
        .replace(/\bpruefen\b/g, 'prüfen')
        .replace(/\bprueft\b/g, 'prüft')
        .replace(/\bpruefte\b/g, 'prüfte')
        .replace(/\bprueften\b/g, 'prüften')
        .replace(/\bPruef/g, 'Prüf')
        .replace(/\bMaengel/g, 'Mängel')
        .replace(/\bmaengel/g, 'mängel')
        .replace(/\bUebergabe\b/g, 'Übergabe')
        .replace(/\buebergeben\b/g, 'übergeben')
        .replace(/\bueber\b/g, 'über')
        .replace(/\bUeber/g, 'Über')
        .replace(/\bAusruestung\b/g, 'Ausrüstung')
        .replace(/\bausruestung\b/g, 'ausrüstung')
        .replace(/\bdraussen\b/g, 'draußen')
        .replace(/\bDraussen\b/g, 'Draußen')
        .replace(/\bSchluessel/g, 'Schlüssel')
        .replace(/\bgezaehlt\b/g, 'gezählt')
        .replace(/\bzaehlen\b/g, 'zählen')
        .replace(/\bentlueftet\b/g, 'entlüftet')
        .replace(/\bStoer/g, 'Stör')
        .replace(/\bGeraet/g, 'Gerät')
        .replace(/geraet\b/g, 'gerät')
        .replace(/\bHandgeraet/g, 'Handgerät')
        .replace(/\bLuecken\b/g, 'Lücken')
        .replace(/\bluecken\b/g, 'lücken')
        .replace(/Lueck/g, 'Lück')
        .replace(/lueck/g, 'lück')
        .replace(/\bGaeste/g, 'Gäste')
        .replace(/\bgaeste/g, 'gäste')
        .replace(/\bAussen/g, 'Außen')
        .replace(/\bGebaeude/g, 'Gebäude')
        .replace(/\bMassband\b/g, 'Maßband');
}

function _missionPipelineV4BushPickupAccessSentence(reason = '', targetLabel = 'Der Zielstrip') {
    const r = _missionPipelineV4StripSentenceEnd(_missionPipelineV4BushPickupDisplayText(reason || '')).trim();
    const target = String(targetLabel || 'Der Zielstrip').trim() || 'Der Zielstrip';
    if (!r) return `${target} ist der passende Zugangspunkt für den Abschluss der Arbeit draußen.`;
    if (/^(?:der\s+)?strip\s+selbst\s+ist\s+der\s+arbeitsort\b/i.test(r)) {
        return _missionPipelineV4EnsureSentence(`${target} ist selbst der Arbeitsort dieser Prüfung`);
    }
    if (/^(?:der\s+)?strip\s+liegt\s+/i.test(r)) {
        return _missionPipelineV4EnsureSentence(`${target} liegt ${r.replace(/^(?:der\s+)?strip\s+liegt\s+/i, '').trim()}`);
    }
    if (/^(?:der\s+)?strip\s+dient\s+/i.test(r)) {
        return _missionPipelineV4EnsureSentence(`${target} dient ${r.replace(/^(?:der\s+)?strip\s+dient\s+/i, '').trim()}`);
    }
    if (/^(?:der\s+)?strip\s+bleibt\s+/i.test(r)) {
        return _missionPipelineV4EnsureSentence(`${target} bleibt ${r.replace(/^(?:der\s+)?strip\s+bleibt\s+/i, '').trim()}`);
    }
    if (/^der\s+strip\s+ist\s+/i.test(r)) return _missionPipelineV4EnsureSentence(`Der Strip ist ${r.replace(/^der\s+strip\s+ist\s+/i, '').trim()}`);
    if (/^strip\s+ist\s+/i.test(r)) return _missionPipelineV4EnsureSentence(`Der Strip ist ${r.replace(/^strip\s+ist\s+/i, '').trim()}`);
    if (/^treffpunkt\s+/i.test(r)) return _missionPipelineV4EnsureSentence(`Der Treffpunkt liegt ${r.replace(/^treffpunkt\s+/i, '').trim()}`);
    if (/^abholpunkt\s+/i.test(r)) return _missionPipelineV4EnsureSentence(`Der Abholpunkt liegt ${r.replace(/^abholpunkt\s+/i, '').trim()}`);
    if (/^zu\s+fuss\s+waere\b/i.test(normalizeMissionText(r))) return _missionPipelineV4EnsureSentence(r);
    if (/^(kurzer|sicherer|neutraler|naechster|nächster|schnellster|besserer)\b/i.test(r)) {
        return _missionPipelineV4EnsureSentence(`${target} ist dafür als ${_missionPipelineV4LowerFirst(r)} der passende Zugangspunkt`);
    }
    return _missionPipelineV4EnsureSentence(`${target} ist dafür der passende Zugangspunkt: ${_missionPipelineV4LowerFirst(r)}`);
}

function _missionPipelineV4BushPickupCandidateNarrativeDefaults(plan = {}, semantics = {}, resolvedNeeds = {}, options = {}) {
    const brief = options?.pickupCreativeBrief || null;
    const candidates = Array.isArray(brief?.candidateShortlist) ? brief.candidateShortlist : [];
    const candidate = candidates[0] || null;
    if (!candidate || typeof candidate !== 'object') return null;
    const targetLabel = String(plan?.targetLabel || semantics?.focusLock?.primarySubjectLabel || 'dem Zielstrip').trim() || 'dem Zielstrip';
    const homeName = String(options?.homeName || 'der Heimatbasis').trim() || 'der Heimatbasis';
    const role = _missionPipelineV4BushPickupDisplayText(String(candidate.roleIdeas?.[0] || 'Backcountry-Kontakt').trim()) || 'Backcountry-Kontakt';
    const taskA = _missionPipelineV4BushPickupDisplayText(String(candidate.taskIdeas?.[0] || 'die Arbeit vor Ort abgeschlossen').trim());
    const taskB = _missionPipelineV4BushPickupDisplayText(String(candidate.taskIdeas?.[1] || 'die offenen Punkte für die Basis notiert').trim());
    const accessReason = _missionPipelineV4BushPickupDisplayText(String(candidate.accessReasons?.[0] || 'der Zielstrip der passende Abholpunkt ist').trim());
    const returnReason = _missionPipelineV4BushPickupDisplayText(String(candidate.returnDrivers?.[0] || 'die Basis den aktuellen Stand für den nächsten Schritt braucht').trim());
    const objects = Array.isArray(candidate.objectIdeas)
        ? candidate.objectIdeas.slice(0, 3).map(x => _missionPipelineV4BushPickupDisplayText(String(x || '').trim())).filter(Boolean)
        : [];
    const objectText = objects.length ? ` mit ${_missionPipelineV4JoinNaturalList(objects)}` : '';
    const taskText = taskB
        ? `${role} hat vor Ort ${taskA} und ${taskB}.`
        : `${role} hat vor Ort ${taskA}.`;
    const accessText = _missionPipelineV4BushPickupAccessSentence(accessReason, targetLabel);
    return {
        trigger: `${role} wartet am ${targetLabel} nach einem abgeschlossenen Backcountry-Auftrag auf den Rückflug.`,
        focusSubject: `${role}, Arbeit vor Ort und Rückkehr zur Basis`,
        keyQuestion: `Wer am ${targetLabel} wartet, was draußen erledigt wurde und warum der Rückflug nach ${homeName} jetzt der passende Abschluss ist.`,
        stakes: `${returnReason}; der Rückflug bringt Person, Notizen und Ausrüstung wieder in den Basisablauf.`,
        completionSignal: `Nach der Rückkehr nach ${homeName} werden Rückmeldung, Unterlagen oder Material an die zuständige Stelle übergeben.`,
        subjectDetail: `${role} am Striprand bei ${targetLabel}${objectText}`,
        incidentContext: `${taskText} ${accessText}`,
        whyNow: `${returnReason}; der Aufenthalt draußen ist damit abgeschlossen, ohne daraus einen Notfall zu machen.`,
        soughtOutcome: `Wir sollen leer zum Zielstrip fliegen, ${role} am Wartepunkt aufnehmen und die Ergebnisse nach ${homeName} zurückbringen.`
    };
}

function missionSarCanonicalIncidentType(incidentType = '') {
    const raw = String(incidentType || '').trim().toLowerCase();
    return ({
        overdue_person: 'missing_hiker',
        missing_person: 'missing_hiker',
        lost_person: 'missing_hiker',
        hiker_missing: 'missing_hiker',
        fall_injury: 'fallen_climber',
        climbing_accident: 'fallen_climber',
        vehicle_accident: 'vehicle_off_road',
        vehicle_crash: 'vehicle_off_road',
        car_off_road: 'vehicle_off_road',
        road_accident: 'road_collision',
        traffic_accident: 'road_collision',
        intersection_accident: 'road_collision',
        intersection_crash: 'road_collision',
        road_collision: 'road_collision',
        downed_aircraft: 'downed_ultralight',
        aircraft_search: 'downed_ultralight',
        plane_crash: 'downed_ultralight',
        water_rescue: 'missing_kayaker',
        kayak_missing: 'missing_kayaker',
        boat_missing: 'small_boat_overdue'
    })[raw] || raw;
}

function missionSarIncidentCategoryKey(category = '', targetLabel = '') {
    const cat = String(category || '').trim().toLowerCase();
    const target = String(targetLabel || '').trim().toLowerCase();
    if (/water|river|lake|stream|reservoir|canal|harbor|dam/.test(cat)) return 'water';
    if (/road|highway|parking|pass|intersection/.test(cat)) return 'road';
    if (/forest|fire/.test(cat)) return 'forest';
    if (/mountain|viewpoint|peak|trail|hill|cliff|rock|terrain/.test(cat)) return 'mountain';
    if (/(see|lake|fluss|river|ufer|wasser|water|boot|boat|kajak|kayak|hafen|harbor)/.test(target)) return 'water';
    if (/(strasse|straße|road|kreuzung|abzweig|intersection|junction|zufahrt|auffahrt|ausfahrt|pass|parkplatz|parking)/.test(target)) return 'road';
    if (/(wald|forst|forest|lichtung|clearing)/.test(target)) return 'forest';
    if (/(berg|gipfel|hang|ridge|trail|pfad|kletter|cliff|fels)/.test(target)) return 'mountain';
    return 'land';
}

function missionSarIncidentIdsForCategory(category = '', targetLabel = '') {
    const key = missionSarIncidentCategoryKey(category, targetLabel);
    const target = String(targetLabel || '').trim().toLowerCase();
    const matrix = {
        water: ['missing_kayaker', 'angler_missing', 'small_boat_overdue', 'riverside_vehicle_entry'],
        road: ['vehicle_off_road', 'road_collision', 'missing_hiker'],
        forest: ['missing_hiker', 'vehicle_off_road', 'downed_ultralight', 'fallen_climber'],
        mountain: ['missing_hiker', 'fallen_climber', 'downed_ultralight'],
        land: ['missing_hiker', 'fallen_climber', 'downed_ultralight']
    };
    const ids = matrix[key] || matrix.land;
    if (key === 'road' && /(kreuzung|intersection|junction|abzweig|zufahrt|auffahrt|ausfahrt|anschluss)/.test(target)) {
        return ['road_collision', 'vehicle_off_road', 'missing_hiker'];
    }
    return ids.slice();
}
window.missionSarIncidentIdsForCategory = missionSarIncidentIdsForCategory;

function missionSarIncidentFamily(incidentType = '') {
    const id = missionSarCanonicalIncidentType(incidentType);
    return ({
        missing_hiker: 'missing_person',
        fallen_climber: 'injured_person',
        missing_kayaker: 'water_person',
        angler_missing: 'water_person',
        small_boat_overdue: 'watercraft',
        riverside_vehicle_entry: 'vehicle',
        vehicle_off_road: 'vehicle',
        road_collision: 'road_incident',
        downed_ultralight: 'aircraft'
    })[id] || id || 'generic';
}

function missionSarSiteAnalysis(category = '', targetLabel = '', context = {}) {
    const geoContext = context?.geoContext || context?.targetGeoContext || null;
    const missionTruth = context?.missionTruth || null;
    const anchors = geoContext?.anchors && typeof geoContext.anchors === 'object' ? geoContext.anchors : {};
    const visualLandmarks = Array.isArray(geoContext?.visualLandmarks) ? geoContext.visualLandmarks : [];
    const anchorPresent = key => !!anchors[key]?.present;
    const text = normalizeMissionText([
        category,
        targetLabel,
        geoContext?.summary || '',
        ...(Array.isArray(geoContext?.hints) ? geoContext.hints : []),
        ...Object.entries(anchors).map(([key, anchor]) => `${key} ${anchor?.name || ''}`),
        ...visualLandmarks.map(lm => `${lm?.kind || lm?.type || ''} ${lm?.label || ''} ${lm?.name || ''}`),
        missionTruth?.mainTarget?.kind || '',
        missionTruth?.sceneAnchor?.kind || '',
        ...(Array.isArray(missionTruth?.visibleCues) ? missionTruth.visibleCues : [])
    ].join(' '));
    const key = missionSarIncidentCategoryKey(category, targetLabel);
    const hasTrafficNode = anchorPresent('traffic_node') || /(kreisverkehr|roundabout|kreuzung|junction|intersection|traffic signals|ampelkreuzung|verkehrsknoten)/.test(text);
    const hasRoad = key === 'road' || anchorPresent('road') || anchorPresent('parking') || hasTrafficNode || /(strasse|straße|road|rue|route|fahrbahn|verkehr)/.test(text);
    const hasWater = key === 'water' || anchorPresent('water') || /(wasser|ufer|fluss|river|stream|see|lake|l'allaine)/.test(text);
    const hasBridge = anchorPresent('bridge') || /(bruecke|brucke|bridge|pont)/.test(text);
    const hasBuiltUp = anchorPresent('building') || anchorPresent('parking') || /(stadt|city|ort|dorf|village|rue|grand'?rue|building|gebaeude|gebäude|parking|parkplatz)/.test(text);
    const hasTrail = anchorPresent('path') || /(trail|pfad|wander|weg|chemin|path)/.test(text);
    const hasForest = key === 'forest' || anchorPresent('forest') || /(wald|forst|forest|wood)/.test(text);
    const hasTerrain = key === 'mountain' || anchorPresent('terrain') || anchorPresent('viewpoint') || /\b(berg|gipfel|hang|ridge|cliff|fels|mountain|slope)\b/.test(text);
    const hasOpenLand = anchorPresent('meadow') || anchorPresent('farmland');
    const evidence = [];
    const addEvidence = label => { if (label && !evidence.includes(label)) evidence.push(label); };
    if (hasRoad) addEvidence('road_target');
    if (hasTrafficNode) addEvidence('traffic_node');
    if (hasBuiltUp) addEvidence('built_up_context');
    if (hasBridge) addEvidence('bridge_nearby');
    if (hasWater) addEvidence('water_nearby');
    if (hasTrail) addEvidence('path_or_trail');
    if (hasForest) addEvidence('forest_context');
    if (hasTerrain) addEvidence('terrain_context');
    if (hasOpenLand) addEvidence('open_land');

    const incidentScores = {
        missing_hiker: 1,
        fallen_climber: 1,
        missing_kayaker: 1,
        angler_missing: 1,
        small_boat_overdue: 1,
        riverside_vehicle_entry: 1,
        vehicle_off_road: 1,
        road_collision: 1,
        downed_ultralight: 1
    };
    const addScore = (id, amount) => {
        const canonical = missionSarCanonicalIncidentType(id);
        incidentScores[canonical] = Number(incidentScores[canonical] || 0) + Number(amount || 0);
    };
    if (hasRoad) {
        addScore('vehicle_off_road', 1.8);
        addScore('road_collision', 2.2);
        addScore('missing_hiker', -0.4);
    }
    if (hasTrafficNode) {
        addScore('road_collision', 4.0);
        addScore('vehicle_off_road', 0.8);
        addScore('missing_hiker', -1.2);
    }
    if (hasBuiltUp && hasRoad) {
        addScore('road_collision', 1.5);
        addScore('vehicle_off_road', 0.6);
        addScore('missing_hiker', -0.8);
    }
    if (hasRoad && (hasWater || hasBridge)) {
        addScore('vehicle_off_road', 2.0);
        addScore('road_collision', 0.9);
        addScore('riverside_vehicle_entry', 2.2);
    }
    if (hasWater) {
        addScore('missing_kayaker', 1.8);
        addScore('angler_missing', 1.6);
        addScore('small_boat_overdue', 1.8);
    }
    if (hasTrail || hasForest || hasTerrain || hasOpenLand) {
        addScore('missing_hiker', 1.8);
        addScore('fallen_climber', hasTerrain ? 2.0 : 0.7);
        addScore('downed_ultralight', hasOpenLand || hasForest ? 1.2 : 0.5);
    }
    Object.keys(incidentScores).forEach(id => {
        incidentScores[id] = Math.max(0.1, Math.round(Number(incidentScores[id]) * 10) / 10);
    });
    return {
        categoryKey: key,
        evidence,
        incidentScores,
        rule: 'Incident-Auswahl folgt zuerst der Lage-Evidenz am Ziel; Verlauf/History dient nur als Varianz-Tiebreaker.'
    };
}
window.missionSarSiteAnalysis = missionSarSiteAnalysis;

function missionSarIncidentHistoryKeys(category = '', targetLabel = '') {
    const key = missionSarIncidentCategoryKey(category, targetLabel);
    return {
        exact: `ga_sar_incident_history_${key}`,
        family: 'ga_sar_incident_family_history_v1'
    };
}

function missionSarReadIncidentHistory(storageKey = '') {
    try {
        const parsed = JSON.parse(localStorage.getItem(storageKey) || '[]');
        return Array.isArray(parsed) ? parsed.map(x => String(x || '')).filter(Boolean) : [];
    } catch (_) {
        return [];
    }
}

function missionSarWriteIncidentHistory(storageKey = '', values = [], limit = 10) {
    try { localStorage.setItem(storageKey, JSON.stringify(values.slice(-limit))); } catch (_) {}
}

function missionSarIncidentGuidance(category = '', targetLabel = '', context = {}) {
    const overrideAllowedIncidentTypes = Array.isArray(context?.allowedIncidentTypes)
        ? context.allowedIncidentTypes.map(missionSarCanonicalIncidentType).filter(Boolean)
        : [];
    const allowedIncidentTypes = [...new Set(
        (overrideAllowedIncidentTypes.length ? overrideAllowedIncidentTypes : missionSarIncidentIdsForCategory(category, targetLabel))
            .map(missionSarCanonicalIncidentType)
            .filter(Boolean)
    )];
    const allowedFamilies = [...new Set(allowedIncidentTypes.map(missionSarIncidentFamily))];
    const keys = missionSarIncidentHistoryKeys(category, targetLabel);
    const exactHistory = missionSarReadIncidentHistory(keys.exact)
        .map(missionSarCanonicalIncidentType)
        .filter(id => allowedIncidentTypes.includes(id));
    const familyHistory = missionSarReadIncidentHistory(keys.family)
        .filter(family => allowedFamilies.includes(family));
    const recentIncidentLimit = Math.min(2, Math.max(0, allowedIncidentTypes.length - 1));
    const recentFamilyLimit = Math.min(2, Math.max(0, allowedFamilies.length - 1));
    const recentIncidentTypes = recentIncidentLimit ? exactHistory.slice(-recentIncidentLimit) : [];
    const recentFamilies = recentFamilyLimit ? familyHistory.slice(-recentFamilyLimit) : [];
    const siteAnalysis = missionSarSiteAnalysis(category, targetLabel, context);
    const scoredIncidentTypes = allowedIncidentTypes
        .map(id => ({
            id,
            score: Number(siteAnalysis.incidentScores?.[id] || 1),
            family: missionSarIncidentFamily(id)
        }))
        .sort((a, b) => (b.score - a.score) || a.id.localeCompare(b.id));
    const bestScore = Number(scoredIncidentTypes[0]?.score || 1);
    const evidencePreferred = bestScore > 1.2
        ? scoredIncidentTypes.filter(entry => entry.score >= bestScore - 0.8).map(entry => entry.id)
        : allowedIncidentTypes.slice();
    let preferredIncidentTypes = evidencePreferred.filter(id =>
        !recentIncidentTypes.includes(id)
        && !recentFamilies.includes(missionSarIncidentFamily(id))
    );
    if (!preferredIncidentTypes.length) {
        preferredIncidentTypes = evidencePreferred.filter(id => !recentIncidentTypes.includes(id));
    }
    if (!preferredIncidentTypes.length) {
        preferredIncidentTypes = evidencePreferred.filter(id => !recentFamilies.includes(missionSarIncidentFamily(id)));
    }
    if (!preferredIncidentTypes.length) preferredIncidentTypes = evidencePreferred.length ? evidencePreferred.slice() : allowedIncidentTypes.slice();
    return {
        allowedIncidentTypes,
        allowedFamilies,
        siteAnalysis,
        scoredIncidentTypes,
        recentIncidentTypes,
        recentFamilies,
        preferredIncidentTypes,
        rule: 'Waehle einen Incident aus allowedIncidentTypes, der zur Lage-Evidenz in siteAnalysis passt. Missing-Person bleibt erlaubt, aber History darf starke Ziel-Evidenz nicht gegen generische Personensuche ueberstimmen.'
    };
}
window.missionSarIncidentGuidance = missionSarIncidentGuidance;

function missionSarSelectIncidentType(category = '', targetLabel = '', suggestedIncidentType = '', context = {}, options = {}) {
    const guidance = missionSarIncidentGuidance(category, targetLabel, context);
    const uniqueAllowed = guidance.allowedIncidentTypes;
    if (!uniqueAllowed.length) return 'missing_hiker';
    if (uniqueAllowed.length === 1) return uniqueAllowed[0];

    const suggested = missionSarCanonicalIncidentType(suggestedIncidentType);
    if (options?.lockSuggested && suggested && uniqueAllowed.includes(suggested)) return suggested;
    const keys = missionSarIncidentHistoryKeys(category, targetLabel);
    const exactHistory = missionSarReadIncidentHistory(keys.exact);
    const familyHistory = missionSarReadIncidentHistory(keys.family);
    let pool = guidance.preferredIncidentTypes.slice();
    if (suggested && pool.includes(suggested) && Math.random() < 0.35) pool = [suggested, ...pool];

    const selected = pool[Math.floor(Math.random() * pool.length)] || uniqueAllowed[0];
    if (options?.writeHistory !== false) {
        missionSarWriteIncidentHistory(keys.exact, exactHistory.filter(id => uniqueAllowed.includes(id)).concat(selected), Math.max(6, uniqueAllowed.length * 2));
        missionSarWriteIncidentHistory(keys.family, familyHistory.concat(missionSarIncidentFamily(selected)), 10);
    }
    return selected;
}

function missionSarPickIncidentType(category = '', targetLabel = '', suggestedIncidentType = '', context = {}) {
    return missionSarSelectIncidentType(category, targetLabel, suggestedIncidentType, context, { writeHistory: true });
}
window.missionSarPickIncidentType = missionSarPickIncidentType;

