    const paxGender = String(passenger?.gender || '').toLowerCase();
    const paxPronoun = paxGender === 'male' ? 'Er' : (paxGender === 'female' ? 'Sie' : 'Die Person');
    const passengerIntro = paxName ? `Nimm ${paxName} bitte mit.` : '';
