function _missionPipelineV4BuildStoryFrame(plan = {}, semantics = {}, resolvedNeeds = {}, options = {}) {
    const rawFrame = (plan.storyFrame && typeof plan.storyFrame === 'object') ? plan.storyFrame : {};
    const defaults = _missionPipelineV4NarrativeDefaults(plan, semantics, resolvedNeeds, options);
    const taskDomain = String(semantics?.focusLock?.taskDomain || plan?.taskDomain || '').toLowerCase();
    const missionMode = normalizeMissionType(options?.missionType || plan?.missionType || '', !!options?.isPOI);
    const isAptSightseeing = taskDomain === 'sightseeing_tour' && missionMode === 'apt' && !options?.isPOI;
    const useSarDecisionFrame = taskDomain === 'search_and_rescue'
        && !!options?.sarDecision?.incidentType;
    const sarIncidentType = options?.sarDecision?.incidentType || defaults.incidentType || rawFrame.incidentType || '';
    const sarTextUsable = text => !!String(text || '').trim()
        && !_missionPipelineV4LooksEnglish(text)
        && !_missionPipelineV4LooksInternalMissionText(text)
        && !_missionPipelineV4SarTextConflictsIncidentType(text, sarIncidentType)
        && !_missionPipelineV4SarTextConflictsIncidentFamily(text, sarIncidentType)
        && !_missionPipelineV4SarTextLooksUndecided(text);
    const pickSarText = (text = '') => useSarDecisionFrame && !sarTextUsable(text) ? '' : text;
    const pickCleanText = (text = '') => {
        const clean = String(text || '').replace(/\s+/g, ' ').trim();
        if (!clean) return '';
        if (useSarDecisionFrame) return pickSarText(clean);
        if (taskDomain === 'bush_pickup_return' && _missionPipelineV4LooksBushPickupFragmentText(clean)) return '';
        if (isAptSightseeing && /\b(rundflug|panorama-rundflug|panoramaflug|ueberflug|überflug|runde\s+ueber|runde\s+über|rueckkehr|rückkehr|zurueck\s+zum\s+heimat|zurück\s+zum\s+heimat)\b/.test(normalizeMissionText(clean))) return '';
        return _missionPipelineV4NarrativeTextUsable(clean) ? clean : '';
    };
    const frameSource = useSarDecisionFrame
        ? {
            trigger: pickSarText(rawFrame.trigger),
            focusSubject: pickSarText(rawFrame.focusSubject),
            keyQuestion: pickSarText(rawFrame.keyQuestion),
            stakes: pickSarText(rawFrame.stakes),
            completionSignal: pickSarText(rawFrame.completionSignal),
            subjectDetail: pickSarText(rawFrame.subjectDetail),
            incidentContext: pickSarText(rawFrame.incidentContext),
            whyNow: pickSarText(rawFrame.whyNow),
            soughtOutcome: pickSarText(rawFrame.soughtOutcome),
            lastSeenContext: pickSarText(rawFrame.lastSeenContext),
            probableScenario: pickSarText(rawFrame.probableScenario),
            visibleClueCandidates: Array.isArray(rawFrame.visibleClueCandidates)
                ? rawFrame.visibleClueCandidates.filter(sarTextUsable)
                : undefined
        }
        : {
            trigger: pickCleanText(rawFrame.trigger),
            focusSubject: pickCleanText(rawFrame.focusSubject),
            keyQuestion: pickCleanText(rawFrame.keyQuestion),
            stakes: pickCleanText(rawFrame.stakes),
            completionSignal: pickCleanText(rawFrame.completionSignal),
            subjectDetail: pickCleanText(rawFrame.subjectDetail),
            incidentContext: pickCleanText(rawFrame.incidentContext),
            whyNow: pickCleanText(rawFrame.whyNow),
            soughtOutcome: pickCleanText(rawFrame.soughtOutcome),
            incidentType: pickCleanText(rawFrame.incidentType),
            lastSeenContext: pickCleanText(rawFrame.lastSeenContext),
            probableScenario: pickCleanText(rawFrame.probableScenario),
            visibleClueCandidates: Array.isArray(rawFrame.visibleClueCandidates)
                ? _missionPipelineV4FilterNarrativeTexts(rawFrame.visibleClueCandidates)
                : undefined
        };
    const planSource = useSarDecisionFrame
        ? {
            missionTrigger: pickSarText(plan.missionTrigger),
            focusSubject: pickSarText(plan.focusSubject),
            keyQuestion: pickSarText(plan.keyQuestion),
            missionStakes: pickSarText(plan.missionStakes),
            completionSignal: pickSarText(plan.completionSignal)
        }
        : {
            missionTrigger: pickCleanText(plan.missionTrigger),
            focusSubject: pickCleanText(plan.focusSubject),
            keyQuestion: pickCleanText(plan.keyQuestion),
            missionStakes: pickCleanText(plan.missionStakes),
            completionSignal: pickCleanText(plan.completionSignal)
        };
    const frame = {
        trigger: _missionPipelineV3Text(frameSource.trigger || planSource.missionTrigger || defaults.trigger, 220),
        focusSubject: _missionPipelineV3Text(frameSource.focusSubject || planSource.focusSubject || defaults.focusSubject, 140),
        keyQuestion: _missionPipelineV3Text(frameSource.keyQuestion || planSource.keyQuestion || defaults.keyQuestion, 220),
        stakes: _missionPipelineV3Text(frameSource.stakes || planSource.missionStakes || defaults.stakes, 220),
        completionSignal: _missionPipelineV3Text(frameSource.completionSignal || planSource.completionSignal || defaults.completionSignal, 220),
        subjectDetail: _missionPipelineV3Text(frameSource.subjectDetail || defaults.subjectDetail, 180),
        incidentContext: _missionPipelineV3Text(frameSource.incidentContext || defaults.incidentContext, 220),
        whyNow: _missionPipelineV3Text(frameSource.whyNow || defaults.whyNow, 220),
        soughtOutcome: _missionPipelineV3Text(frameSource.soughtOutcome || defaults.soughtOutcome, 220),
        incidentType: _missionPipelineV3Text(frameSource.incidentType || defaults.incidentType || '', 80),
        lastSeenContext: _missionPipelineV3Text(frameSource.lastSeenContext || defaults.lastSeenContext || '', 180),
        probableScenario: _missionPipelineV3Text(frameSource.probableScenario || defaults.probableScenario || '', 180),
        visibleClueCandidates: Array.isArray(frameSource.visibleClueCandidates)
            ? frameSource.visibleClueCandidates.slice(0, 5).map(x => _missionPipelineV3Text(x, 80)).filter(Boolean)
            : (Array.isArray(defaults.visibleClueCandidates)
                ? defaults.visibleClueCandidates.slice(0, 5).map(x => _missionPipelineV3Text(x, 80)).filter(Boolean)
                : [])
    };
    if (taskDomain === 'club_utility') {
        return _missionPipelineV4EnrichClubUtilityStoryFrame(frame, {
            targetLabel: semantics?.focusLock?.primarySubjectLabel || plan?.targetLabel || '',
            cargoText: options?.loadout?.cargoText || plan?.storyFrame?.shipment || plan?.cargo || '',
            selectedProposal: options?.loadout?.selectedMissionProposal || null
        });
    }
    return frame;
}

const BUSH_MISSION_VARIETY_PROFILE_IDS = new Set([
    'bush_supply_strip',
    'bush_charter_strip',
    'bush_scenic_hopper',
    'bush_recon_return',
    'bush_pickup_cargo'
]);

function bushProfileSupportsMissionVariety(profileId = '') {
    return BUSH_MISSION_VARIETY_PROFILE_IDS.has(String(profileId || '').trim().toLowerCase());
}

function _missionPipelineV4CompactVarietyPack(varietyPack = null) {
    if (!varietyPack || typeof varietyPack !== 'object') return null;
    return {
        schema: varietyPack.schema,
        namespace: varietyPack.namespace,
        profileId: varietyPack.profileId,
        contextTags: varietyPack.contextTags,
        selectedIds: varietyPack.selectedIds,
        selectedFamilies: varietyPack.selectedFamilies,
        primaryId: varietyPack.primaryId,
        primaryFamily: varietyPack.primaryFamily,
        recentFamilies: varietyPack.recentFamilies,
        recentPrimaryFamilies: varietyPack.recentPrimaryFamilies,
        recentPrimaryIds: varietyPack.recentPrimaryIds,
        selectionRule: varietyPack.selectionRule,
        storageKey: varietyPack.storageKey
    };
}

