window.buildMissionWriterV5BriefingBrief = _missionWriterV5BuildBriefingBrief;

function buildMissionWriterV5Prompt(contract = {}, context = {}) {
    const briefingBrief = _missionWriterV5BuildBriefingBrief(contract, context);
    const missionBriefForm = briefingBrief.missionBriefForm || _missionWriterV5BuildBriefForm(contract, context);
    const legacyBriefingBrief = { ...briefingBrief };
    delete legacyBriefingBrief.missionBriefForm;
    const promptTaskDomain = String(contract?.profile?.taskDomain || '').trim().toLowerCase();
    const promptNewsIsPoi = promptTaskDomain === 'news_coverage' ? _missionNewsContractIsPoi(contract, context) : false;
    const newsCoveragePromptRule = promptTaskDomain === 'news_coverage'
        ? (promptNewsIsPoi
            ? '\n14. NEWS-COVERAGE POI: Erfinde die konkrete weiche Hintergrundgeschichte selbst. Entscheide dich für einen einzigen journalistischen Kern: Headline, Vorfall, Event, Streitfrage, Initiative oder mediale Dokumentation. Der erste inhaltliche Satz muss sagen, was bei diesem POI berichtenswert ist; "die Redaktion braucht Bilder/einen klaren Ort/einen Rahmen für die Geschichte" ist nur Arbeitsauftrag, keine fertige Story. Der gewählte POI bleibt Ort des Geschehens. Schreibe nicht fragend, welches Standardmotiv dort vorliegen könnte, sondern erzähle die gewählte Situation direkt. Sichtbare Orts- oder Umfeldmerkmale sind nur Rohmaterial; wähle höchstens einen Beleg, statt eine Liste aufzuzählen. Kein Boulevard- oder BILD-Zeitung-Ton; bei Fotoaufträgen eher Fotoreportage, Fotodokumentation oder Fotoauswahl sagen. Story-Felder sind Leitplanken, keine Textbausteine; du musst nicht jede Nebeninformation erwähnen, wenn die Geschichte dadurch besser wird.'
            : '\n14. NEWS-COVERAGE APT: Dies ist ein reiner A-B-Reporterflug zum Zielflugplatz. KEIN Überflug, KEIN Kreisen, KEINE Luftbilder oder Luftarbeit als Missionsziel. Erfinde eine konkrete headline-taugliche Bodenstory am Zielplatz: kurioser Aufreger, Platzgerücht, PR-Gag, Streitfrage, ungewöhnliches Bildmotiv, spontane Aktion oder mediale Dokumentation. Es darf sich anfühlen, als wäre die Geschichte schon im Gang und wir bringen Reporter, Kamera oder Live-Rucksack mitten hinein. Der erste inhaltliche Satz muss die Sache selbst benennen, nicht nur "die Redaktion braucht einen Aufhänger". Nach der Landung beginnt Recherche, Fotoauswahl, Schalte oder Einordnung am Boden. Keine harten Ortsfakten, echten Veranstalternamen oder Termine behaupten.')
        : '';
    const historianPromptRule = promptTaskDomain === 'historian_guided_tour'
        ? '\n14. HISTORIKER: Schreibe eine historische Ortslesart mit einem weichen fachlichen Anlass, nicht eine Checkliste. "Warum heute" bedeutet hier Arbeitsstand oder Weiterverwendung, z.B. Archivnotiz, Infotafel-Entwurf, Führungsvorbereitung oder kurzer Chronikbeitrag; es darf beiläufig sein und muss nicht als eigener Pflichtsatz erscheinen. Wetter ist nur Flugrahmen und darf nicht noch einmal als eigentliche Begründung dienen, wenn es schon genannt wurde. Wähle wenige passende Belege wie Lage, Wege, Ortsbild, Hang/Tal oder Bauwerk; nicht alles aufzählen.'
        : '';
    const privateOutingPromptRule = '';
    const privateOutingDirectPromptRule = promptTaskDomain === 'private_outing'
        ? '\n14. PRIVATE-OUTING: Nutze MISSION_BRIEF_FORM.domainDetails.storyInspiration als Rohmaterial fuer ein direktes, warmes Briefing aus Dispatcher- oder Vereinskollegen-Rolle. Sprich Pilot und Mitflieger natuerlich mit du, ihr oder euch an. Schreibe nicht ueber den Missionstyp, sondern sag konkret, was die beiden vorhaben: wohin sie rollen, was der Hinflug zum Tag beiträgt, was nach dem Parken als Erstes passiert, und warum der Anlass am Ziel den Flug wert macht. MISSION_BRIEF_FORM.domainDetails.storyInspiration.mainStory ist der rote Faden, aber kein Text zum Abschreiben. Wenn mainStory, Fakten oder Anlass nur schwach/generisch wirken, nutze MISSION_BRIEF_FORM.domainDetails.storyInspiration.creativeWildcard als Hauptgeschichte: mach daraus eine charmante private Wildcard wie Familienkaffee, Thermengeruecht, Stadtbummel, Schuhsuche, Spezialitaetenladen, Kuchenlegende, Vereins-Empfehlung oder eine andere weiche Alltagsidee. Aus Café-Stopp, Burger, Picknick, Eis, Frühstück, Abendessen, Fotorunde, Badesee, Museum, Markt, Familienbesuch, Paartag, Zielort als Tapetenwechsel, Strecke als kleiner Reiseflug oder einem anderen plausiblen Privatgrund soll eine zusammenhaengende kleine Geschichte entstehen. Bei Familienbesuch zaehlt nur ein konkreter kleiner Anlass als Hauptgeschichte: Kuchen, Fotoalben, Familienkaffee, gedeckter Tisch, kleine Überraschung oder lange verschobene Runde; Abholung und Route duerfen nur hinfuehren. Du darfst weiche private Alltagsdetails dazuerfinden und Nebeninfos weglassen, wenn der Text dadurch menschlicher klingt; auch eine unbenannte Gastgeberin, Familienabholung, ein alter Freund oder ein Cousin am Ziel ist als weiche Privatrolle erlaubt, wenn sie den Anlass traegt. Wenn Wetter, Licht, Route, Entfernung, Taeler, Alb, Schwarzwald, Sicht oder Temperatur den Flug selbst reizvoll machen, baue sie als erlebte Stimmung in denselben Ablauf ein: nicht als Zusatzinfo, sondern als Teil davon, wie der Flug und der Anlass sich anfühlen. Ziele auf 4-5 natuerliche Saetze, wenn dadurch eine rundere kleine Geschichte entsteht; der Zusatzsatz soll Handlung, Stimmung, Route oder Zielmoment weitertragen und nicht wie eine Checklisten-Info klingen. Bleibe bei einem privaten Flug von Start zu Ziel; erfinde keine harten Ortsfakten, echten Café-Namen, Veranstaltungen, Termine, echten Personennamen oder Wetterwerte, und drehe die Mission nicht in Sightseeing, Charter, Fracht oder Arbeit.'
        : '';
    const clubUtilityPromptRule = promptTaskDomain === 'club_utility'
        ? '\n14. CLUB-UTILITY: Denk dir: "Hier im JSON sind die Daten zum Flug, schreib dem Piloten daraus ein freundliches, kreatives, kollegiales Briefing aus deiner Rolle als Dispatcher." Es soll wie gesprochen klingen, nicht wie ein Formular. Baue eine kleine Hintergrundgeschichte: Was ist am Ziel gerade los, warum können wir unkompliziert helfen, wer oder was kommt mit, und was passiert nach dem Abstellen? Du darfst direkt ansprechen und Du-/Wir-Form nutzen. Die Ladung ist Wahrheit, aber keine sichtbare Inventarliste; fasse sie frei zu einem natürlichen Motiv zusammen und erwähne nur das, was der Geschichte hilft. Route, Wetter, Tagesstimmung oder Pax dürfen die Geschichte tragen, wenn der eigentliche Auftrag klein ist. Keine Semikolons, keine abgehackten Einzelsätze, keine kopierten StoryCore- oder domainDetails-Sätze. Vermeide Baukastenanfänge wie "Heute geht es mit ...", "Nimm [Name] bitte mit", "Die [Zahl] NM führen dich ...", "Am Ziel geht es kurz ...", "Keine anonyme Fracht", "nicht nur eine beliebige Box", "kennt den Ablauf am Boden", "die Sache direkt mit", "müssen heute", "nicht um eine große Logistiknummer", "bergig und waldig genug" oder "saubere VFR-Planung".'
        : '';
    const bushPickupPromptRule = promptTaskDomain === 'bush_pickup_return'
        ? '\n14. BUSH-PICKUP: Schreib so, als würdest du dem Piloten den Auftrag gerade mündlich im Bush-Dispatch erzählen. Sprich ihn direkt mit du an und mache aus genau einer Richtung in pickupCreativeBrief beziehungsweise MISSION_BRIEF_FORM.domainDetails eine kleine Abenteuergeschichte mit Anfang, Szene am Strip und sinnvoller Rückkehr. Name, Rolle, Arbeit draußen, Gegenstände am Wartepunkt und Rückkehrgrund müssen aus derselben Richtung stammen. Der Ablauf bleibt fest: leer hinaus, am Strip landen, genau eine Person aufnehmen, zur Heimatbasis zurück. Du darfst weiche glaubwürdige Wilderness-Details erfinden und Spannung aufbauen, aber keine neuen Ortsnamen, Notfälle, harten Geofakten oder weiteren Personen hinzufügen. Wenn belastbare Wetter- oder Pistenangaben vorhanden sind und ohne Zusatzsatz in die Erzählung passen, darfst du sie als erlebten Flugrahmen verwenden. Wetter ist kein Pflichtpunkt; lieber weglassen als den Erzählfluss mit einem Datenanhang oder einer erzwungenen Wetterbegründung zu belasten. Keine Steckbrieferöffnung nach dem Muster "Name, Rolle, wartet heute", keine Inventarliste, keine Semikolons und keine sichtbare Folge von Formularfeldern. Das story-Feld bleibt Dispatcher-Perspektive; Ich-Sätze des Pickup-Gasts gehören ausschließlich in passenger.greetingText und pickupStory-Voice-Cues.'
        : '';
    return `<INSTRUKTIONEN>
Du bist ein freundlicher, entspannter Flugdienstleiter in einem lokalen Fliegerclub.
Du schreibst einen kurzen Dispatch-Zettel fuer den Piloten, nicht eine Formularantwort.

Arbeitsweise:
1. Nutze MISSION_BRIEF_FORM als ausgefuelltes Missionsformular. Es enthaelt Identitaet, Route, Personen, Story-Kern, Missionsdetails, Fakten, Stil und Qualitaetskompass.
2. Schreibe die Story als 4-6 zusammenhaengende deutsche Saetze, bei sehr einfachen Missionen reichen 3.
3. Die Story soll wie eine kleine Erzaehlung klingen: wer fliegt, warum genau heute, warum dieser Flug Sinn macht, was nach Landung/Rueckkehr passiert.
4. Route, Entfernung, Wetter und Zielplatz sind erwuenschte Realitaetsanker, aber sie duerfen den Text nicht kippen, wenn sie fehlen oder nicht elegant passen.
5. storyCore ist der rote Faden: premise, concreteReason, whyToday, flightValue, targetFocus und successOutcome sollen als Geschichte spuerbar werden, wenn sie vorhanden sind.
6. domainDetails sagt dir, was diese Missionsfamilie besonders macht; formuliere daraus frei, nicht als sichtbares Schema.
7. facts.hardFacts sind die belegten Fakten. Harte Ortsfakten, Landmarken, Baujahre, historische Details oder echte Sehenswuerdigkeiten nur daraus oder aus den Legacy-Feldern targetFacts/storyIngredients verwenden.
8. style.allowedFreedom beschreibt, wo du weiche Farbe ergaenzen darfst. Private Genussgruende duerfen charmant erfunden werden, bleiben aber weiche Privatstory, keine neuen harten Ortsfakten.
9. quality.questions und quality.requiredMeaning sind dein innerer Kompass. Du musst sie nicht einzeln sichtbar abarbeiten.
10. Keine Systemwoerter und keine sichtbaren Feldnamen.
11. Kein Listenstil, keine wechselnden Perspektiven, keine Ich-Form im story-Feld.
12. Passenger, Greeting, Cargo und SceneIntent muessen dieselbe Geschichte stuetzen.
13. Nutze normale deutsche Umlaute.${newsCoveragePromptRule}${historianPromptRule}${privateOutingDirectPromptRule}${clubUtilityPromptRule}${bushPickupPromptRule}

<MISSION_BRIEF_FORM>
${JSON.stringify(missionBriefForm)}
</MISSION_BRIEF_FORM>

<BRIEFING_BRIEF>
${JSON.stringify(legacyBriefingBrief)}
</BRIEFING_BRIEF>

<OUTPUT>
Antworte ausschliesslich als JSON ohne Markdown:
{
  "title": "Kurzer, passender Missionstitel",
  "story": "4-6 natuerliche Saetze als zusammenhaengender Dispatch-Zettel",
  "pax": "z.B. 1 PAX (...) oder 0 PAX",
  "cargo": "z.B. Tagesrucksack (12 lbs)",
  "targetInfo": "Bei POI: 2-3 sachliche Saetze fuer die Ziel-Info-Seite aus belegten Daten; bei A-B leerer String",
  "passenger": {
    "name": "Vollstaendiger Name",
    "role": "Rolle oder Beziehung",
    "gender": "male|female",
    "personality": "3 Adjektive",
    "dialectHint": "neutral oder leicht regional",
    "roleProfile": "${String(contract?.profile?.roleProfile || 'general_passenger_v1')}",
    "taskDomain": "${String(contract?.profile?.taskDomain || 'general')}",
    "gTolerance": "niedrig|mittel|hoch",
    "bankTolerance": "niedrig|mittel|hoch",
    "cargoSensitivity": "niedrig|mittel|hoch",
    "stomachSensitivity": "niedrig|mittel|hoch",
    "comfortPriority": "niedrig|mittel|hoch",
    "urgencyPriority": "niedrig|hoch",
    "targetAltFt": 0,
    "targetRadiusNm": 0,
    "targetDwellMin": 0,
    "greetingText": "Kurze persoenliche Begruessung mit konkretem Bezug zur gleichen Geschichte"
  },
  "sceneIntent": {
    "summary": "Was am Ziel sichtbar sein soll oder warum keine Zielszene noetig ist",
    "environment": "kurzer Umgebungsanker oder leer",
    "visibleIdeas": [],
    "avoid": [],
    "densityHint": "none|sparse|normal|busy",
    "notes": "kurzer Grund"
  }
}
</OUTPUT>`;
}
window.buildMissionWriterV5Prompt = buildMissionWriterV5Prompt;

function _missionPipelineV4StoryKeywords(text = '') {
    const stop = new Set([
        'der', 'die', 'das', 'und', 'oder', 'aber', 'eine', 'einer', 'einem', 'einen', 'eines', 'eines',
        'nach', 'heute', 'damit', 'dass', 'fuer', 'ueber', 'unter', 'ohne', 'nicht', 'mehr', 'noch',
        'wird', 'werden', 'wurde', 'sind', 'sein', 'soll', 'sollen', 'muss', 'muessen', 'jetzt', 'dort',
        'rund', 'bereich', 'ziel', 'einsatz', 'auftrag', 'luft', 'lagebild', 'klaren', 'konkreten'
    ]);
    return normalizeMissionText(text)
        .split(/[^a-z0-9]+/)
        .filter(token => token && token.length >= 4 && !stop.has(token));
}

function _missionPipelineV4StoryFieldCovered(story = '', phrase = '', minHits = 1) {
    const storyText = normalizeMissionText(story);
    const tokens = Array.from(new Set(_missionPipelineV4StoryKeywords(phrase)));
    if (!tokens.length) return false;
    let hits = 0;
    for (const token of tokens) {
        if (storyText.includes(token)) hits += 1;
        if (hits >= minHits) return true;
    }
    return false;
}

function _missionPipelineV4LooksEnglish(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    const englishHits = (normalized.match(/\b(the|with|from|near|last|confirmed|position|reported|wearing|their|group|during|steep|section|climber|ground|teams|immediate|aerial|required|before|light|conditions|confirmation|assessment|accessibility|handover|coordinates|coordination|center|need|needs|retrieve|someone|something|remote|location|specific|operational|context|completed|counting|inventory|weekend|secured|forgotten|special|order|ready|transport|transported|return|flight|logical|step|collected|data|base|processing|planning|pickup|passenger|cargo|departure|destination|prevail|involve|personnel|essential|items|common|operation)\b/g) || []).length;
    const germanHits = (normalized.match(/\b(der|die|das|und|mit|von|bei|nahe|letzte|meldung|sichtung|ortung|funkkontakt|person|fahrzeug|einsatz|leitstelle|bodenkraefte|suchtrupps|rettung|ausruestung|befund|lagebild|wartet|flieg|flug|rueckflug|rückflug|zurueck|zurück|abholung|abholen|aufnehmen|bringen|basis|planung|notizen|unterlagen|auftrag|gelandet|ziel|zielstrip|wetter|sicht|wind)\b/g) || []).length;
    const englishStarts = (normalized.match(/(^|[.!?]\s*)(the|this|that|she|he|they|pickup|return|transport|vfr)\b/g) || []).length;
    return (englishHits >= 4 && englishHits > germanHits)
        || (englishHits >= 3 && englishStarts >= 1 && englishHits >= germanHits);
}

function _missionPipelineV4NarrativeTextUsable(text = '') {
    const clean = String(text || '').replace(/\s+/g, ' ').trim();
    if (!clean) return false;
    return !_missionPipelineV4LooksEnglish(clean) && !_missionPipelineV4LooksInternalMissionText(clean);
}

function _missionPipelineV4LooksBushPickupFragmentText(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    if (/^(strip\s+(selbst\s+)?(ist|liegt|dient|bleibt)|treffpunkt|abholpunkt|naechster|nachster|nächster|sicherer|neutraler|kurzer|schnellster|besserer)\b/.test(normalized)) return true;
    if (/^(der\s+)?strip\s+selbst\s+ist\s+der\s+arbeitsort\b/.test(normalized)) return true;
    if (/\bweil\s+(?:(?:der|die|das)\s+)?(?:strip|treffpunkt|abholpunkt|naechster|nachster|nächster|sicherer|neutraler|kurzer|schnellster|besserer)\b/.test(normalized)) return true;
    if (/\bweil\s+(?:der|die|das)\s+[a-z0-9_-]+\s+(?:selbst\s+)?ist\s+/.test(normalized)) return true;
    if (/\bweil\s+[a-z0-9_-]+\s+ist\s+/.test(normalized)) return true;
    if (/(^|[.!?]\s+)(naechste|nächste|rangerstation|basis|lodge-team|projektleitung|freigabe)[a-z0-9_-]*\s+(crew|braucht|passt|wartet|geht|wird)\b/.test(normalized)) return true;
    return false;
}

function _missionPipelineV4FilterNarrativeTexts(values = []) {
    return (Array.isArray(values) ? values : [])
        .map(value => String(value || '').replace(/\s+/g, ' ').trim())
        .filter(text => text && _missionPipelineV4NarrativeTextUsable(text));
}

function _missionPipelineV4LooksInternalMissionText(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    return /\b(sar[\s_-]*erkundung|unterfokus|storyframe|missiontruth|contract|writer|planner|pipeline|zielkategorie|objectfamil(?:y|ien)?|primaerfokus|passt durch zielkategorie|sichtbare suchhinweise zu diesem sar)\b/.test(normalized);
}

function _missionPipelineV4SarIncidentSignatureRegex(incidentType = '') {
    const id = missionSarCanonicalIncidentType(incidentType);
    return ({
        missing_hiker: /\b(wanderer|wanderin|spaziergaenger|spazierganger|vermisste person|personensuche|orientierungslos|verlaufen)\b/,
        fallen_climber: /\b(kletterer|kletterin|bergsteiger|bergsteigerin|kletter|fels|grat|steig|abgerutscht|absturzkante|geroell|geroll)\b/,
        downed_ultralight: /\b(luftfahrzeug|kleinflugzeug|ultraleichtflugzeug|ultraleicht|ul[\s-]?maschine|echo[\s-]?maschine|flugzeug|mayday|wrack|wrackteil|einschlag|absturz)\b/,
        vehicle_off_road: /\b(von der fahrbahn abgekommen|fahrbahn abgekommen|abseits der strasse|abseits der straße|boeschung|boschung|waldsaum|vermisstes fahrzeug|fahrzeugspuren|reifenspuren|handy[\s-]?ortung)\b/,
        road_collision: /\b(verkehrsunfall|kollision|auffahrunfall|kreuzungsunfall|unfallstelle|mehrere fahrzeuge|mehreren fahrzeugen|fahrzeugkollision|sperrung|rettungsgasse)\b/,
        missing_kayaker: /\b(kajak|kajakfahrer|kajakfahrerin|paddler|paddlerin|paddel|kanu|kenterung|gekentert)\b/,
        angler_missing: /\b(angler|anglerin|angelplatz|angelausruestung|angelausrustung|angelrute|fischerei|fischer)\b/,
        small_boat_overdue: /\b(bootsbesatzung|bootscrew|motorboot|freizeitboot|angelboot|aluboot|ueberfaelliges boot|uberfalliges boot)\b/,
        riverside_vehicle_entry: /\b(fahrzeugeintritt ins wasser|fahrzeug im wasser|pkw im wasser|auto im wasser|fahrzeug.*wasserkontakt|wasserkontakt.*fahrzeug|fahrzeug.*ufer|ufer.*fahrzeug)\b/
    })[id] || null;
}

function _missionPipelineV4SarTextConflictsIncidentType(text = '', incidentType = '') {
    const id = missionSarCanonicalIncidentType(incidentType);
    const normalized = normalizeMissionText(text);
    if (!normalized || !id) return false;
    const own = _missionPipelineV4SarIncidentSignatureRegex(id);
    const known = [
        'missing_hiker',
        'fallen_climber',
        'downed_ultralight',
        'vehicle_off_road',
        'road_collision',
        'missing_kayaker',
        'angler_missing',
        'small_boat_overdue',
        'riverside_vehicle_entry'
    ];
    return known.some(otherId => {
        if (otherId === id) return false;
        const other = _missionPipelineV4SarIncidentSignatureRegex(otherId);
        if (!other || !other.test(normalized)) return false;
        return !own || !own.test(normalized) || /\b(oder|bzw|stattdessen)\b/.test(normalized);
    });
}

function _missionPipelineV4SarTextConflictsIncidentFamily(text = '', incidentType = '') {
    const id = missionSarCanonicalIncidentType(incidentType);
    const normalized = normalizeMissionText(text);
    if (!normalized || !id) return false;
    const has = re => re.test(normalized);
    const aircraftTerms = /\b(luftfahrzeug|kleinflugzeug|ultraleichtflugzeug|ultraleichtflugzeuge|ultraleicht|ul[\s-]?maschine|echo[\s-]?maschine|flugzeug|einschlag|wrackhinweis)\b/;
    const roadCollisionTerms = /\b(verkehrsunfall|kollision|auffahrunfall|kreuzungsunfall|unfallstelle mit|mehrere fahrzeuge|mehreren fahrzeugen|unfallfahrzeug)\b/;
    const offRoadTerms = /\b(von der fahrbahn abgekommen|fahrbahn abgekommen|abseits der strasse|abseits der straße|boeschung|boschung|waldsaum|vermisstes fahrzeug|fahrzeugspuren|reifenspuren)\b/;
    const waterTerms = /\b(kajak|paddel|boot|bootscrew|bootsbesatzung|angler|wasserrettung|uferabschnitt|anlandepunkt)\b/;
    const missingPersonTerms = /\b(wanderer|wanderin|kletterer|kletterin|bergsteiger|bergsteigerin|personensuche|vermisste person|vermisstenmeldung)\b/;
    if (id === 'downed_ultralight') return has(roadCollisionTerms) || has(offRoadTerms) || has(waterTerms) || has(missingPersonTerms);
    if (id === 'road_collision') return has(aircraftTerms) || has(offRoadTerms) || has(waterTerms) || has(missingPersonTerms);
    if (id === 'vehicle_off_road' || id === 'riverside_vehicle_entry') return has(aircraftTerms) || has(roadCollisionTerms);
    if (['missing_hiker', 'fallen_climber'].includes(id)) return has(aircraftTerms) || has(roadCollisionTerms) || has(waterTerms);
    if (['missing_kayaker', 'angler_missing', 'small_boat_overdue'].includes(id)) return has(aircraftTerms) || has(roadCollisionTerms) || has(offRoadTerms);
    return false;
}

function _missionPipelineV4SarTextLooksUndecided(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    const personFamily = /\b(wanderer|wanderin|kletterer|kletterin|bergsteiger|bergsteigerin|personensuche|vermisste person|vermisstenmeldung)\b/;
    const aircraftFamily = /\b(luftfahrzeug|kleinflugzeug|ultraleichtflugzeug|ultraleichtflugzeuge|ultraleicht|ul[\s-]?maschine|echo[\s-]?maschine|flugzeug|wrack|wrackteile|absturzortung)\b/;
    const roadFamily = /\b(verkehrsunfall|kollision|unfallstelle|fahrbahn|fahrzeuge|fahrzeug)\b/;
    const waterFamily = /\b(kajak|boot|bootscrew|bootsbesatzung|angler|wasserrettung|uferhinweis)\b/;
    const families = [personFamily, aircraftFamily, roadFamily, waterFamily].filter(re => re.test(normalized)).length;
    return families >= 2 && /\b(oder|bzw)\b/.test(normalized);
}

function _missionPipelineV4SentenceCount(text = '') {
    return String(text || '')
        .split(/(?<=[.!?])\s+/)
        .map(x => String(x || '').trim())
        .filter(Boolean)
        .length;
}

function _missionPipelineV4CountNeedle(text = '', needle = '') {
    const hay = normalizeMissionText(text);
    const key = normalizeMissionText(needle);
    if (!hay || !key) return 0;
    return hay.split(key).length - 1;
}

function _missionPipelineV4LooksEnumerative(text = '') {
    const s = String(text || '').trim();
    if (!s) return false;
    if (/^([A-ZÄÖÜ][^.!?]{0,80}\.\s*){4,}$/.test(s) && /Wir sollen|Der letzte|Nach dem|Aufgrund|Zuletzt/i.test(s)) return true;
    if (/(^|[.!?]\s*)(Der letzte|Zuletzt|Moegliche Hinweise|Aus der Luft achten wir|Verdeckte |Aufgrund der |Wir uebernehmen )/i.test(s) && _missionPipelineV4SentenceCount(s) >= 5) return true;
    return false;
}

function _missionPipelineV4LooksFragmentedStory(text = '') {
    const s = String(text || '').replace(/\s+/g, ' ').trim();
    if (!s) return false;
    return /[.!?]\s+(einem|einer|einen|eines|mit|bei|nach|wegen|durch|unter)\s+[a-zäöüß][^.!?]{8,}[.!?]/.test(s);
}

function _missionPipelineV4LooksLooseInfraInspectionStory(text = '') {
    const s = String(text || '').replace(/\s+/g, ' ').trim();
    const normalized = normalizeMissionText(s);
    if (!normalized) return false;
    if (/\b(recente|ueberwachungsprotoko|uberwachungsprotoko)\b/.test(normalized)) return true;
    if (/\b(protoko|auffaelligkei|infrastruktu|wasserinfrastruktu|wartungszyk)\./i.test(normalized)) return true;
    const fieldStarts = (s.match(/(^|[.!?]\s+)(Es besteht|Dies könnte|Dies koennte|Die aktuelle|Ein visueller Befund|Rückkehr|Rueckkehr|Nach dem Ueberflug|Nach dem Überflug)\b/g) || []).length;
    if (fieldStarts >= 3) return true;
    const hedgeHits = (normalized.match(/\b(moeglich(?:e|er|en|es|erweise)?|potenziell(?:e|er|en|es)?|genereller\s+verdacht|koennte|koennten|beduerfen\s+koennten|ratsa?m)\b/g) || []).length;
    if (hedgeHits >= 4 && _missionPipelineV4SentenceCount(s) >= 4) return true;
    if (/\bheute\s+pruefen\s+wir\s+an\s+[^.!?]{3,90}\s+(das|die|der)\s+[^.!?]{3,90}\s+als\s+teil\s+der\s+lokalen\b/.test(normalized)) return true;
    if (/\b(das|die|der)\s+[^.!?]{3,90}\s+als\s+teil\s+der\s+lokalen\s+(wasser)?infrastruktur\b[^.!?]*\.\s*\./.test(normalized)) return true;
    return false;
}

function _missionPipelineV4JoinNaturalList(values = []) {
    const src = Array.isArray(values) ? values.map(x => String(x || '').trim()).filter(Boolean) : [];
    if (!src.length) return '';
    if (src.length === 1) return src[0];
    if (src.length === 2) return `${src[0]} und ${src[1]}`;
    return `${src.slice(0, -1).join(', ')} und ${src[src.length - 1]}`;
}

function _missionPipelineV4BushVarietyCandidate(contract = {}) {
    const brief = contract?.missionVarietyBrief && typeof contract.missionVarietyBrief === 'object'
        ? contract.missionVarietyBrief
        : null;
    const candidates = Array.isArray(brief?.candidateShortlist) ? brief.candidateShortlist : [];
    if (!candidates.length) return null;
    const primaryId = String(brief?.variety?.primaryId || '').trim();
    return (primaryId ? candidates.find(c => String(c?.id || '').trim() === primaryId) : null) || candidates[0] || null;
}

function _missionPipelineV4BushVarietyFirst(values = [], fallback = '') {
    return Array.isArray(values) && values.length
        ? String(values[0] || fallback).trim()
        : String(fallback || '').trim();
}

function _missionPipelineV4BushVarietySecond(values = [], fallback = '') {
    return Array.isArray(values) && values.length > 1
        ? String(values[1] || fallback).trim()
        : String(fallback || '').trim();
}

function _missionPipelineV4ContractHomeName(contract = {}, fallback = 'der Basis') {
    const followRoute = contract?.followUpContext?.route && typeof contract.followUpContext.route === 'object'
        ? contract.followUpContext.route
        : null;
    return String(
        followRoute?.homeName
        || followRoute?.returnHomeRef?.name
        || contract?.route?.homeName
        || contract?.route?.startName
        || contract?.route?.startIcao
        || currentStartICAO
        || fallback
    ).trim() || fallback;
}

function _missionPipelineV4ComposeBushVarietyStory(contract = {}) {
    const profileId = String(contract?.profile?.id || '').trim().toLowerCase();
    if (!bushProfileSupportsMissionVariety(profileId)) return '';
    const candidate = _missionPipelineV4BushVarietyCandidate(contract);
    if (!candidate) return '';
    const targetName = String(contract?.target?.name || contract?.route?.targetName || 'dem Zielstrip').trim() || 'dem Zielstrip';
    const homeName = _missionPipelineV4ContractHomeName(contract, 'der Basis');
    const role = _missionPipelineV4BushVarietyFirst(candidate.roleIdeas, 'Backcountry-Kontakt');
    const taskA = _missionPipelineV4BushVarietyFirst(candidate.taskIdeas, 'den Auftrag vor Ort vorbereiten');
    const taskB = _missionPipelineV4BushVarietySecond(candidate.taskIdeas, 'die offenen Punkte dokumentieren');
    const objects = _missionPipelineV4JoinNaturalList(
        Array.isArray(candidate.objectIdeas) ? candidate.objectIdeas.slice(0, 3) : []
    ) || 'leichte Ausruestung';
    const returnReason = _missionPipelineV4EnsureSentence(_missionPipelineV4BushVarietyFirst(candidate.returnDrivers, 'Der naechste Schritt haengt an diesem Flug'));
    const accessReason = _missionPipelineV4EnsureSentence(_missionPipelineV4BushVarietyFirst(candidate.accessReasons, 'Der Zielstrip ist der passende Zugangspunkt'));
    if (profileId === 'bush_supply_strip') {
        return [
            `Wir bringen heute ${objects} nach ${targetName}; am Strip wartet ${role} auf die Uebergabe.`,
            `Die Lieferung wird dort draussen gebraucht, um ${taskA} und ${taskB}.`,
            accessReason,
            `${returnReason} Nach dem Abladen ist der Supply-Auftrag am Ziel abgeschlossen.`
        ].filter(Boolean).join(' ');
    }
    if (profileId === 'bush_charter_strip') {
        return [
            `Heute bringen wir ${role} mit ${objects} nach ${targetName}.`,
            `Nach der Landung beginnt vor Ort der eigentliche Termin: ${taskA} und ${taskB}.`,
            accessReason,
            `${returnReason} Der Charterflug endet mit dem Dropoff am Zielstrip.`
        ].filter(Boolean).join(' ');
    }
    if (profileId === 'bush_scenic_hopper') {
        return [
            `Dieser Bush-Hop nach ${targetName} ist als ruhiger Backcountry-Leg fuer ${role} geplant.`,
            `Nach der Landung beginnt draussen der kleine Tagesplan: ${taskA} und ${taskB}.`,
            `${objects} bleibt als leichtes Kit dabei.`,
            `Die Landung am Zielstrip ist der Abschluss des Fluglegs und der Start des Aufenthalts.`
        ].filter(Boolean).join(' ');
    }
    if (profileId === 'bush_recon_return') {
        return [
            `Heute pruefen wir ${targetName} aus der Luft, ohne dort eine Landung einzuplanen.`,
            `Im Fokus stehen ${taskA} und ${taskB}.`,
            accessReason,
            `${returnReason} Danach bringen wir Befund, Fotos und Notizen zurueck nach ${homeName}.`
        ].filter(Boolean).join(' ');
    }
    if (profileId === 'bush_pickup_cargo') {
        return [
            `Wir fliegen leer nach ${targetName}; dort liegen ${objects} am Striprand zur Rueckholung bereit.`,
            `Vor Ort geht es konkret darum, ${taskA} und ${taskB}.`,
            accessReason,
            `${returnReason} Danach bringen wir die Fracht zurueck nach ${homeName} und laden sie dort aus.`
        ].filter(Boolean).join(' ');
    }
    return '';
}

function _missionPipelineV4StripSentenceEnd(text = '') {
    return String(text || '')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(/\s*[.!?]+$/g, '')
        .trim();
}

function _missionPipelineV4LowerFirst(text = '') {
    const s = String(text || '').trim();
    if (!s) return '';
    return s.charAt(0).toLowerCase() + s.slice(1);
}

function _missionPipelineV4UpperSentenceStart(text = '') {
    return String(text || '').replace(/^(\s*["'„“(]*)([a-zäöü])/u, (_m, prefix, first) => `${prefix}${first.toUpperCase()}`);
}

function _missionPipelineV4BuildSarObjective(frame = {}, semantics = {}) {
    const targetName = String(semantics?.focusLock?.primarySubjectLabel || '').trim() || 'dem Zielgebiet';
    const subject = _missionPipelineV4SarPrimarySubjectText(frame.focusSubject || frame.subjectDetail || 'einer konkreten Suchlage');
    return `Luftsuche bei ${targetName}: ${_missionPipelineV4LowerFirst(subject)}`;
}

function _missionPipelineV4BuildSarRealismBrief(frame = {}, semantics = {}, resolvedNeeds = {}) {
    const targetName = String(semantics?.focusLock?.primarySubjectLabel || '').trim() || 'Das Zielgebiet';
    const cues = Array.isArray(resolvedNeeds?.mission_truth?.visibleCues)
        ? resolvedNeeds.mission_truth.visibleCues.slice(0, 2).map(x => String(x || '').trim()).filter(Boolean)
        : [];
    const cueText = cues.length ? ` mit ${_missionPipelineV4JoinNaturalList(cues)}` : '';
    const subject = _missionPipelineV4SarPrimarySubjectText(frame.focusSubject || frame.subjectDetail || 'Suchhinweisen');
    return `${targetName}${cueText} ist ein plausibler Suchraum fuer ${_missionPipelineV4LowerFirst(subject)}.`;
}

function _missionPipelineV4SarPrimarySubjectText(text = '') {
    const subject = _missionPipelineV4StripSentenceEnd(text || 'eine konkrete Suchlage');
    return subject
        .replace(/\s+oder\s+(frischer|klarer|verwertbarer|eindeutiger|moeglicher|möglicher)?\s*(hinweis|unfallhinweis|wasserhinweis|suchhinweis|einschlaghinweis|uferhinweis|zugriffspunkt|befund).*$/i, '')
        .trim() || subject;
}

function _missionPipelineV4EnsureSentence(text = '', fallback = '') {
    const s = _missionPipelineV4UpperSentenceStart(_missionPipelineV4StripSentenceEnd(text || fallback));
    if (!s) return '';
    return /[.!?]$/.test(s) ? s : `${s}.`;
}

function _missionPipelineV4SentenceParts(text = '') {
    const protectedText = String(text || '')
        .replace(/\bbzw\./gi, m => `${m.slice(0, -1)}__DOT__`)
        .replace(/\bca\./gi, m => `${m.slice(0, -1)}__DOT__`)
        .replace(/\bggf\./gi, m => `${m.slice(0, -1)}__DOT__`)
        .replace(/\bu\.a\./gi, m => m.replace(/\./g, '__DOT__'))
        .replace(/\bd\.h\./gi, m => m.replace(/\./g, '__DOT__'))
        .replace(/\bz\.\s*b\./gi, m => m.replace(/\./g, '__DOT__'));
    return protectedText
        .split(/(?<=[.!?])\s+/)
        .map(part => _missionPipelineV4StripSentenceEnd(part.replace(/__DOT__/g, '.')))
        .filter(Boolean);
}

function _missionPipelineV4LooksLikeCompleteSentence(text = '') {
    const s = _missionPipelineV4StripSentenceEnd(text);
    if (!s) return false;
    if (/^Meldung\b/i.test(s)) return false;
    return /\b(wird|wurde|ist|sind|hat|haben|befindet|fehlt|meldet|melden|sucht|suchen|braucht|brauchen|soll|sollen|muss|muessen|müssen)\b/i.test(s);
}

function _missionPipelineV4SarSubjectSentence(detail = '', fallback = '') {
    const s = _missionPipelineV4StripSentenceEnd(detail || fallback);
    if (!s) return '';
    if (/^(einem|einer|einen|eines)\b/i.test(s)) return `Gesucht wird nach ${_missionPipelineV4LowerFirst(s)}.`;
    if (_missionPipelineV4LooksLikeCompleteSentence(s)) return _missionPipelineV4EnsureSentence(s);
    return `Im Mittelpunkt steht ${_missionPipelineV4LowerFirst(s)}.`;
}

function _missionPipelineV4OutcomeSentence(text = '', fallback = '') {
    let s = _missionPipelineV4StripSentenceEnd(text || fallback);
    if (!s) return '';
    if (_missionPipelineV4LooksLikeCompleteSentence(s)) {
        return _missionPipelineV4EnsureSentence(s);
    }
    return _missionPipelineV4EnsureSentence(`Aus der Luft liefern wir den benoetigten Befund: ${_missionPipelineV4LowerFirst(s)}`);
}

function _missionPipelineV4CompletionSentence(text = '') {
    let s = _missionPipelineV4StripSentenceEnd(text);
    if (!s) return '';
    if (/^(Uebergabe|Übergabe)\b/i.test(s)) {
        return _missionPipelineV4EnsureSentence(`Anschliessend folgt die ${s}`);
    }
    return _missionPipelineV4EnsureSentence(s);
}

function _missionPipelineV4PushUniqueSentence(out = [], sentence = '', minHits = 2) {
    const s = _missionPipelineV4EnsureSentence(sentence);
    if (!s) return;
    const existing = out.join(' ');
    if (existing && _missionPipelineV4StoryFieldCovered(existing, s, minHits)) return;
    out.push(s);
}

function _missionPipelineV4WeatherBitsForBriefing(wx = null) {
    const raw = (wx && typeof wx === 'object' && wx.raw && typeof wx.raw === 'object') ? wx.raw : wx;
    const bits = [];
    const windDeg = Number(raw?.windDeg);
    const windKts = Number(raw?.windKts);
    if (Number.isFinite(windDeg) && Number.isFinite(windKts)) {
        bits.push(`Wind ${Math.round(windDeg)}°/${Math.round(windKts)} kt`);
    } else if (Number.isFinite(windKts)) {
        bits.push(`Wind ${Math.round(windKts)} kt`);
    }
    const visRaw = raw?.visKm;
    const visKm = visRaw === null || visRaw === undefined || visRaw === '' ? NaN : Number(visRaw);
    if (Number.isFinite(visKm) && visKm > 0) bits.push(visKm >= 10 ? 'Sicht >10 km' : `Sicht ${visKm.toFixed(1)} km`);
    const fltCat = String(raw?.fltCat || '').trim().toUpperCase();
    if (fltCat && !bits.some(bit => bit.toUpperCase().includes(fltCat))) bits.push(fltCat);
    const tempC = Number(raw?.tempC);
    if (Number.isFinite(tempC)) bits.push(`${Math.round(tempC)}°C`);
    return bits.slice(0, 4);
}

function _missionPipelineV4BushPickupConditionSentence(contract = {}) {
    const destWeather = contract?.weather?.dest || contract?.weather?.targetPoi || null;
    const depWeather = contract?.weather?.dep || null;
    const bits = _missionPipelineV4WeatherBitsForBriefing(destWeather);
    if (bits.length) {
        return `Am Ziel geben ${bits.join(', ')} den Rahmen vor, trotzdem bleibt es ein echter Bush-Strip: lies Piste, Wind und Randbereich sauber, bevor du zum Wartepunkt rollst.`;
    }
    const depBits = _missionPipelineV4WeatherBitsForBriefing(depWeather).slice(0, 2);
    if (depBits.length) {
        return `Mit ${depBits.join(', ')} am Start wirkt der Leerflug freundlich, doch am Ziel zählt weiterhin der Strip: lies Piste, Wind und Randbereich sauber, bevor du zum Wartepunkt rollst.`;
    }
    return 'Am Ziel wartet ein echter Bush-Strip auf dich: lies Piste, Wind und Randbereich sauber, bevor du zum Wartepunkt rollst.';
}

function _missionPipelineV4BushPickupStoryHasConditionCue(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    const weatherCue = /\b(wind|sicht|vfr|mvfr|ifr|temperatur|wetter|metar|\d+\s*°\s*c)\b/.test(normalized);
    const stripCue = /\b(piste|bahn|landebahn|strip|zielstrip|pistenrand|randbereich|anflug)\b/.test(normalized);
    return weatherCue && stripCue;
}

function _missionPipelineV4EnsureBushPickupConditions(story = '', contract = {}) {
    const base = String(story || '').replace(/\s+/g, ' ').trim();
    const condition = _missionPipelineV4BushPickupConditionSentence(contract);
    if (!base) return condition;
    if (_missionPipelineV4BushPickupStoryHasConditionCue(base)) return base;
    return `${base} ${condition}`.trim();
}

function _missionPipelineV4EscapeRegExp(value = '') {
    return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function _missionPipelineV4EnforceBushPickupNameCandidates(passenger = {}, contract = {}, story = '') {
    const taskDomain = String(contract?.profile?.taskDomain || passenger?.taskDomain || '').trim().toLowerCase();
    const roleProfile = String(contract?.profile?.roleProfile || passenger?.roleProfile || '').trim().toLowerCase();
    const profileId = String(contract?.profile?.id || '').trim().toLowerCase();
    const isBushPickup = taskDomain === 'bush_pickup_return'
        || roleProfile === 'bush_pickup_guest_v1'
        || profileId === 'bush_pickup_strip';
    if (!isBushPickup) return { passenger, story };
    const lockedPassenger = contract?.followUpContext?.lockedPassenger && typeof contract.followUpContext.lockedPassenger === 'object'
        ? contract.followUpContext.lockedPassenger
        : null;
    if (lockedPassenger?.name) {
        const pax = (passenger && typeof passenger === 'object') ? { ...passenger } : {};
        const selectedName = String(lockedPassenger.name || '').trim();
        const selectedRole = String(lockedPassenger.role || pax.role || '').trim();
        const selectedGender = String(lockedPassenger.gender || pax.gender || '').trim().toLowerCase();
        const currentName = String(pax.name || '').replace(/\s*\([^)]*\)\s*$/, '').trim();
        let nextStory = String(story || '').replace(/\s+/g, ' ').trim();
        if (currentName && currentName !== selectedName) {
            nextStory = nextStory.replace(new RegExp(_missionPipelineV4EscapeRegExp(currentName), 'g'), selectedName);
        }
        pax.name = selectedName;
        if (selectedRole) pax.role = selectedRole;
        if (selectedGender === 'female' || selectedGender === 'male') pax.gender = selectedGender;
        if (pax.pickupStory && typeof pax.pickupStory === 'object') {
            pax.pickupStory = {
                ...pax.pickupStory,
                personName: selectedName,
                role: selectedRole || pax.pickupStory.role || pax.role || ''
            };
        }
        return { passenger: pax, story: nextStory || story };
    }
    const candidates = (Array.isArray(contract?.varietyHints?.passengerNameCandidates)
        ? contract.varietyHints.passengerNameCandidates
        : [])
        .map(item => ({
            name: String(item?.name || '').trim(),
            gender: String(item?.gender || '').trim().toLowerCase() === 'female' ? 'female' : 'male'
        }))
        .filter(item => item.name);
    if (!candidates.length) return { passenger, story };
    const pax = (passenger && typeof passenger === 'object') ? { ...passenger } : {};
    const currentName = String(pax.name || '').replace(/\s*\([^)]*\)\s*$/, '').trim();
    const normalizedCurrent = normalizeMissionText(currentName);
    const exactCandidate = normalizedCurrent
        ? candidates.find(item => normalizeMissionText(item.name) === normalizedCurrent)
        : null;
    const currentGender = String(pax.gender || '').trim().toLowerCase();
    const selected = exactCandidate
        || candidates.find(item => item.gender === currentGender)
        || candidates[0];
    if (!selected?.name) return { passenger: pax, story };
    const storyText = String(story || '').replace(/\s+/g, ' ').trim();
    const leadingName = (storyText.match(/^([A-ZÄÖÜ][A-Za-zÄÖÜäöüß'’.-]+(?:\s+[A-ZÄÖÜ][A-Za-zÄÖÜäöüß'’.-]+){1,2})(?=,\s)/) || [])[1] || '';
    const oldName = currentName || leadingName;
    let nextStory = storyText;
    if (oldName && oldName !== selected.name) {
        nextStory = nextStory.replace(new RegExp(_missionPipelineV4EscapeRegExp(oldName), 'g'), selected.name);
    } else if (!oldName && nextStory) {
        nextStory = nextStory.replace(/^([A-ZÄÖÜ][A-Za-zÄÖÜäöüß'’.-]+(?:\s+[A-ZÄÖÜ][A-Za-zÄÖÜäöüß'’.-]+){1,2})(?=,\s)/, selected.name);
    }
    pax.name = selected.name;
    pax.gender = selected.gender;
    if (pax.pickupStory && typeof pax.pickupStory === 'object') {
        pax.pickupStory = { ...pax.pickupStory, personName: selected.name };
    }
    return { passenger: pax, story: nextStory || story };
}

function _missionPipelineV4InfraPassengerHandoff(contract = {}, detail = '') {
    const category = String(contract?.target?.poiCategory || contract?.target?.targetCategory || contract?.profile?.pickerCategory || '').trim().toLowerCase();
    const targetName = String(contract?.target?.name || contract?.route?.targetName || 'dem Ziel').trim() || 'dem Ziel';
    const targetText = normalizeMissionText(targetName);
    const cleanDetail = _missionPipelineV4StripSentenceEnd(detail || contract?.storyFrame?.subjectDetail || '');
    const isWindTarget = /(windpark|windkraft|windrad|windturbine|wind turbine|windenergie|wind farm)/.test(targetText);
    const isSolarTarget = /(solarpark|solaranlage|photovoltaik|photovoltaic|solar farm|(^|[^a-z0-9])pv([^a-z0-9]|$))/.test(targetText);
    const isMarineTarget = /(hafen|marina|sportboothafen|schleuse|anleger|anlegestelle|kai|pier|dock|hafenbecken)/.test(targetText);
    const isPerimeterTarget = /(zaun|zaunlinie|tor|zugang|perimeter|wildzaun|schutzzaun)/.test(targetText);
    const isEnergyTarget = isWindTarget || isSolarTarget || /(umspannwerk|kraftwerk|strom|freileitung|hochspannung|trasse)/.test(targetText);
    const handoff = (() => {
        if (category === 'road') return {
            focus: 'den gemeldeten Abschnitt',
            decision: 'ob Beobachtung reicht oder Streckendienst und Absicherung für den Abschnitt geplant werden sollen'
        };
        if (category === 'bridge') return {
            focus: 'den auffälligen Bauwerksanschluss',
            decision: 'ob eine Bodenprüfung, Beobachtung oder eine gezielte Nachkontrolle vorbereitet werden soll'
        };
        if (category === 'rail') return {
            focus: 'den gemeldeten Abschnitt der Betriebsinfrastruktur',
            decision: 'ob ein Wartungsfenster, eine Trassenrunde oder nur weitere Beobachtung nötig wirkt'
        };
        if (category === 'dam' || category === 'water') return {
            focus: 'den sichtbaren Zustand am Wasserbauwerk',
            decision: 'ob Wasserbau- oder Betriebsteam später einen bestimmten Abschnitt genauer ansehen sollen'
        };
        if (category === 'telecom') return {
            focus: 'den Maststandort',
            decision: 'ob ein Netztechnik-, Zugangsteam- oder Hubsteiger-Einsatz sinnvoll vorbereitet werden sollte'
        };
        if (isWindTarget) return {
            focus: 'den auffälligen Anlagenpunkt',
            decision: 'ob der Wartungstermin wie geplant laufen kann oder ein einzelner Anlagenpunkt vorgezogen werden sollte'
        };
        if (isSolarTarget) return {
            focus: 'den auffälligen Technik- oder Randpunkt',
            decision: 'ob der Betreiber einen Technikpunkt, eine Zaunstelle oder die Zufahrt gezielt nachprüfen muss'
        };
        if (isMarineTarget) return {
            focus: 'den sichtbaren Wasserbau- oder Hafenpunkt',
            decision: 'ob Wasserbau- oder Hafenbetrieb später einen bestimmten Zugang oder Uferabschnitt nachprüfen muss'
        };
        if (isPerimeterTarget) return {
            focus: 'den gemeldeten Perimeterpunkt',
            decision: 'ob der Betreiber den Perimeter nur beobachtet oder ein Vor-Ort-Team an eine konkrete Stelle schickt'
        };
        if (isEnergyTarget) return {
            focus: 'den auffälligen Punkt im Anlagen- oder Trassenbereich',
            decision: 'ob Netzbetrieb oder Technikteam einen bestimmten Punkt gezielt nachprüfen müssen'
        };
        if (category === 'industry' || category === 'infrastructure') return {
            focus: 'den gemeldeten Teilbereich der Betriebsfläche',
            decision: 'ob Beobachtung reicht oder ein Betriebsteam einen Teilbereich nachprüfen muss'
        };
        return {
            focus: 'den konkreten Nachprüfpunkt am Ziel',
            decision: 'ob Beobachtung reicht oder ein gezielter Folgeeinsatz vorbereitet werden muss'
        };
    })();
    return {
        focus: cleanDetail && _missionPipelineV4NarrativeTextUsable(cleanDetail) ? cleanDetail : handoff.focus,
        decision: handoff.decision
    };
}

function _missionPipelineV4BuildInfraNarrativeHandoff(contract = {}) {
    const taskDomain = String(contract?.profile?.taskDomain || '').trim().toLowerCase();
    if (taskDomain !== 'inspection_infra' && taskDomain !== 'infra_chain_recon') return null;
    const targetName = String(contract?.target?.name || contract?.route?.targetName || 'Zielgebiet').trim() || 'Zielgebiet';
    const chain = contract?.poiChain && typeof contract.poiChain === 'object' ? contract.poiChain : null;
    if (taskDomain === 'infra_chain_recon' && Array.isArray(chain?.points) && chain.points.length >= 2) {
        const spine = _missionPipelineV4PoiChainStorySpine(chain);
        const phrase = _missionPipelineV4PoiChainCorridorPhrase(chain, targetName);
        const first = String(chain.points[0]?.name || 'ersten Prüfpunkt').replace(/\s+/g, ' ').trim();
        const last = String(chain.points[chain.points.length - 1]?.name || 'letzten Prüfpunkt').replace(/\s+/g, ' ').trim();
        return {
            schema: 'ga.infraNarrativeHandoff.v1',
            mode: 'chain_recon',
            phrase,
            actor: spine.actor,
            trigger: _missionPipelineV4PoiChainTrigger(chain, phrase),
            focus: spine.scope,
            firstPoint: first,
            lastPoint: last,
            decision: 'welche Punkte unauffällig wirken, welche beobachtet werden sollten und wo später eine gezielte Einzelprüfung lohnt',
            nextStep: 'Bildserie und Kurzbefund gehen nach der Rückkehr an Betreiber oder Technikteam; Details bleiben späteren Einzelobjekt-Missionen oder Bodenteams vorbehalten'
        };
    }
    const handoff = _missionPipelineV4InfraPassengerHandoff(contract);
    return {
        schema: 'ga.infraNarrativeHandoff.v1',
        mode: 'single_infra_inspection',
        focus: handoff.focus,
        decision: handoff.decision,
        nextStep: 'Befund, Fotos und Empfehlung gehen nach dem Überflug an Betreiber oder Technikteam'
    };
}

function _missionPipelineV4InfraPassengerSentence(passenger = {}, contract = {}, detail = '') {
    const taskDomain = String(contract?.profile?.taskDomain || passenger?.taskDomain || '').trim().toLowerCase();
    if (taskDomain !== 'inspection_infra') return '';
    const category = String(contract?.target?.poiCategory || contract?.target?.targetCategory || contract?.profile?.pickerCategory || '').trim().toLowerCase();
    const name = String(passenger?.name || '').replace(/\s*\([^)]*\)\s*$/, '').trim();
    const persona = (() => {
        const nameKey = normalizeMissionText(name);
        if (!nameKey || !Array.isArray(MISSION_ROLE_TASK_PROFILES?.inspection_infra?.personas)) return null;
        return MISSION_ROLE_TASK_PROFILES.inspection_infra.personas
            .find(item => normalizeMissionText(item?.name || '') === nameKey) || null;
    })();
    const rawRole = String(passenger?.role || persona?.role || '').trim();
    const genericRole = !rawRole || /^(begleitperson|passagier|passagierin|gast|pax)$/i.test(rawRole);
    const role = genericRole ? (() => {
        if (category === 'dam' || category === 'water') return 'Wasserbau-Fachperson';
        if (category === 'bridge') return 'Bauwerks-Fachperson';
        if (category === 'rail') return 'Bahn-Infrastrukturfachperson';
        if (category === 'road') return 'Verkehrsbau-Fachperson';
        if (category === 'telecom') return 'Netztechnik-Fachperson';
        if (category === 'industry' || category === 'infrastructure') return 'Infrastruktur-Fachperson';
        return 'Infrastruktur-Fachperson';
    })() : rawRole;
    if (!name && !role) return '';
    const targetName = String(contract?.target?.name || contract?.route?.targetName || 'dem Ziel').trim() || 'dem Ziel';
    const gender = String(passenger?.gender || persona?.gender || '').trim().toLowerCase();
    const pronoun = gender === 'female' ? 'Sie' : (gender === 'male' ? 'Er' : 'Die Fachperson');
    const label = name && role ? `An Bord ist ${name}, ${role}` : (name ? `${name} fliegt als Fachperson mit` : `An Bord ist eine ${role}`);
    const handoff = _missionPipelineV4InfraPassengerHandoff(contract, detail);
    return `${_missionPipelineV4EnsureSentence(label)} ${pronoun} ordnet bei ${targetName} ${handoff.focus} ein und hält fest, ${handoff.decision}.`;
}

function _missionPipelineV4StoryMentionsPassenger(story = '', passenger = {}) {
    const normalized = normalizeMissionText(story);
    if (!normalized) return false;
    const name = normalizeMissionText(String(passenger?.name || '').replace(/\s*\([^)]*\)\s*$/, '').trim());
    const role = normalizeMissionText(passenger?.role || '');
    if (name && normalized.includes(name)) return true;
    if (role && normalized.includes(role)) return true;
    return false;
}

function _missionPipelineV4StoryHasInfraPassengerTask(story = '', passenger = {}) {
    const normalized = normalizeMissionText(story);
    if (!normalized) return false;
    const name = normalizeMissionText(String(passenger?.name || '').replace(/\s*\([^)]*\)\s*$/, '').trim());
    const role = normalizeMissionText(passenger?.role || '');
    const mentionsPassenger = !!((name && normalized.includes(name)) || (role && normalized.includes(role)));
    if (!mentionsPassenger) return false;
    return /\b(prueft|prüft|pruefung|prüfung|kontrolliert|beurteilt|bewertet|dokumentiert|begleitet|grenzt|eingegrenzt|ordnet|achtet|braucht|wartung|bodenpruefung|bodenprüfung|sichtmeldung|erstbefund|befund)\b|geht es fuer|geht es für|geht es fur/i.test(normalized);
}

function _missionPipelineV4DedupeStorySentences(story = '') {
    const parts = _missionPipelineV4SentenceParts(story);
    if (!parts.length) return String(story || '').trim();
    const seen = new Set();
    const out = [];
    for (const part of parts) {
        const key = normalizeMissionText(part);
        if (!key || seen.has(key)) continue;
        seen.add(key);
        out.push(_missionPipelineV4EnsureSentence(part));
    }
    return out.join(' ').trim();
}

function _missionPipelineV4RepairInfraPassengerPronouns(story = '', passenger = {}) {
    const gender = String(passenger?.gender || '').trim().toLowerCase();
    if (gender !== 'female' && gender !== 'male') return String(story || '').trim();
    const expected = gender === 'female' ? 'Sie' : 'Er';
    const wrong = gender === 'female' ? 'Er' : 'Sie';
    const verbPattern = '(beurteilt|bewertet|prüft|prueft|kontrolliert|dokumentiert|begleitet|ordnet|achtet)';
    return String(story || '').replace(new RegExp(`\\b${wrong}\\s+${verbPattern}\\b`, 'g'), `${expected} $1`).trim();
}

function _missionPipelineV4EnsureInfraPassengerStory(story = '', contract = {}, passenger = {}, detail = '') {
    const taskDomain = String(contract?.profile?.taskDomain || passenger?.taskDomain || '').trim().toLowerCase();
    const base = _missionPipelineV4RepairInfraPassengerPronouns(
        _missionPipelineV4DedupeStorySentences(String(story || '').replace(/\s+/g, ' ').trim()),
        passenger
    );
    if (taskDomain !== 'inspection_infra' || !base) return base;
    const paxSentence = _missionPipelineV4InfraPassengerSentence(passenger, contract, detail);
    if (!paxSentence) return base;
    const parts = _missionPipelineV4SentenceParts(base);
    const name = normalizeMissionText(String(passenger?.name || '').replace(/\s*\([^)]*\)\s*$/, '').trim());
    const role = normalizeMissionText(passenger?.role || '');
    const normalized = normalizeMissionText(base);
    const hasName = !!(name && normalized.includes(name));
    const hasRole = !!(role && normalized.includes(role));
    if (hasName && hasRole && _missionPipelineV4StoryHasInfraPassengerTask(base, passenger)) return base;
    if (!hasName && hasRole && _missionPipelineV4StoryHasInfraPassengerTask(base, passenger)) {
        const out = [];
        if (parts.length) out.push(_missionPipelineV4EnsureSentence(parts[0]));
        out.push(_missionPipelineV4EnsureSentence(paxSentence));
        for (const part of parts.slice(1)) out.push(_missionPipelineV4EnsureSentence(part));
        return out.filter(Boolean).join(' ');
    }
    if (hasName && parts.length) {
        const replaceIndex = parts.findIndex(part => normalizeMissionText(part).includes(name));
        if (replaceIndex >= 0) {
            parts[replaceIndex] = paxSentence;
            return parts.map(part => _missionPipelineV4EnsureSentence(part)).filter(Boolean).join(' ');
        }
    }
    if (_missionPipelineV4StoryMentionsPassenger(base, passenger)) return base;
    if (!parts.length) return `${base} ${_missionPipelineV4EnsureSentence(paxSentence)}`.trim();
    const out = [];
    out.push(_missionPipelineV4EnsureSentence(parts[0]));
    out.push(_missionPipelineV4EnsureSentence(paxSentence));
    for (const part of parts.slice(1)) out.push(_missionPipelineV4EnsureSentence(part));
    return out.filter(Boolean).join(' ');
}

