    const generic = String(incident || `heute geht es fuer uns nach ${targetName}`).trim().replace(/[.!?]+$/,'');
    const normalized = generic ? generic.charAt(0).toLowerCase() + generic.slice(1) : `heute geht es fuer uns nach ${targetName}`;
