function missionProposalPoiOptionLine(target = {}, profileId = '') {
    const profile = String(profileId || '').toLowerCase();
    const tags = missionProposalPoiTags(target);
    const infraType = String(target?.poiLookup?.selectedInfraType || tags.infra_type || '').toLowerCase();
    const railway = String(tags.railway || '').toLowerCase();
    const category = String(target?.poiCategory || target?.category || '').toLowerCase();
    const typeLabel = missionProposalPoiTypeLabel(target);
    if (profile === 'sightseeing_tour') {
        if (category === 'castle') return 'Motiv: Bauwerk, Lage und Umgebung als markanter Blickpunkt.';
        if (category === 'mountain') return 'Motiv: Geländeform, Aussicht und Landschaftszusammenhang.';
        if (category === 'water' || category === 'dam') return 'Motiv: Wasserlinie, Ufer und Einbettung in die Landschaft.';
        if (category === 'city') return 'Motiv: Ortsbild, Orientierung und wiedererkennbare Landmarken.';
        if (category === 'bridge') return 'Motiv: Brücke, Tal- oder Flussbezug und klare Fotoperspektive.';
        return 'Motiv: ein konkreter Blickpunkt mit Zeit für Orientierung und Fotos.';
    }
    if (profile === 'inspection_infra') {
        if (infraType === 'telecom') return 'Prüfauftrag: Mast, Standortzugang und unmittelbares Umfeld einordnen.';
        if (railway || infraType === 'rail') return 'Prüfauftrag: relevanten Bahninfrastruktur-Befund dokumentieren.';
        if (infraType === 'bridge' || tags.bridge) return 'Prüfauftrag: Bauwerk, Widerlager, Zufahrten und Unterseite soweit sichtbar erfassen.';
        if (infraType === 'road' || tags.highway) return 'Prüfauftrag: Verkehrsabschnitt, Randbereiche und mögliche Baustellenlage einordnen.';
        if (infraType === 'power_grid') return 'Prüfauftrag: Trasse, Masten und freie Zugänglichkeit aus ruhigen Blickwinkeln prüfen.';
        if (infraType === 'power_station') return 'Prüfauftrag: Anlagenrand, Schaltfeld und Zufahrtsbereich dokumentieren.';
        if (infraType === 'water_utility' || infraType === 'water_tank') return 'Prüfauftrag: Bauwerkszustand, Zugänge und sichtbare Leitungs-/Beckenbereiche prüfen.';
        if (infraType === 'industrial') return 'Prüfauftrag: Anlagenkanten, Zufahrten und sichtbare Wartungspunkte erfassen.';
        return 'Prüfauftrag: Zielbereich, Zugänge und auffällige Veränderungen aus der Luft erfassen.';
    }
    if (profile === 'tour_guide_knowledge') {
        if (category === 'city') return 'Guide-Fokus: Ortsbild, Lage, Nutzung und sichtbare Landmarken verständlich erklären.';
        if (category === 'water' || category === 'dam') return 'Guide-Fokus: Wasserlinie, Ufer, Nutzung und Landschaftszusammenhang einordnen.';
        if (category === 'castle') return 'Guide-Fokus: Bauwerk, Lage und historische Einbettung anschaulich erklären.';
        return 'Guide-Fokus: Ziel, Umgebung und sichtbare Orientierungspunkte knapp und anschaulich einordnen.';
    }
    if (profile === 'historian_guided_tour') {
        if (category === 'castle') return 'Historischer Blick: Bauwerk, Lage, alte Wege und sichtbare Bezüge zur Umgebung.';
        if (category === 'city') return 'Historischer Blick: Ortskern, Siedlungsform, Wegeachsen und Landschaftslage.';
        return 'Historischer Blick: sichtbare Spuren, Lagebezug und frühere Nutzung des Zielraums.';
    }
    if (profile === 'mapping_survey') {
        if (category === 'road' || category === 'rail' || category === 'infrastructure') return 'Survey-Fokus: Korridor, Kanten und Anschlussbereiche mit ruhigen Linien abdecken.';
        if (category === 'bridge' || category === 'dam') return 'Survey-Fokus: Bauwerk und Randbereiche als auswertbare Bildserie erfassen.';
        return 'Survey-Fokus: Zielgeometrie, Überdeckung und reproduzierbare Perspektiven für die Auswertung.';
    }
    if (profile === 'news_coverage') {
        if (category === 'city') return 'Redaktionsfokus: freie lokale News-Geschichte am POI; Ortsbild und Umfeld nur als Bildbelege.';
        if (category === 'road') return 'Redaktionsfokus: freie lokale News-Geschichte am POI; Straße und Zufahrt nur als Bildbelege.';
        return 'Redaktionsfokus: Headline, Vorfall, Event oder mediale Dokumentation aus Ziel und sichtbaren Ankern entwickeln.';
    }
    if (profile === 'media_photo') {
        return 'Bildauftrag: wiedererkennbare Lage, saubere Perspektiven und verwertbare Motive statt Showflug.';
    }
    if (profile === 'fire_watch') {
        return 'Beobachtungsfokus: Rauchfahnen, Hotspot-Hinweise und trockene Vegetationsränder sachlich prüfen.';
    }
    if (profile === 'science_bio') {
        return 'Beobachtungsfokus: Habitatgrenzen, Vegetation, Uferzonen oder Störkanten für spätere Feldarbeit.';
    }
    if (profile === 'science_geo') {
        return 'Geologie-Fokus: Relief, Hangform, Erosionsspuren oder Uferkante aus ruhiger Perspektive lesen.';
    }
    if (typeLabel) return `Auftrag: ${typeLabel} mit ruhigen, nachvollziehbaren Blickwinkeln einordnen.`;
    return 'Auftrag: Zielbereich und Umgebung mit ruhigen, nachvollziehbaren Blickwinkeln einordnen.';
}

function missionProposalFamilyIntro(choices = []) {
    const profile = String(choices?.[0]?.profileId || '').toLowerCase();
    const mode = String(choices?.[0]?.mode || '').toLowerCase();
    if (mode === 'apt') {
        const config = missionProposalAptProfileConfig(profile);
        if (config?.intro) return config.intro;
    }
    const poiConfig = missionProposalPoiProfileConfig(profile);
    if (poiConfig?.intro) return poiConfig.intro;
    return 'Wähle einen der vorbereiteten Aufträge.';
}

function missionProposalTargetKey(target = {}) {
    const name = String(target?.n || target?.name || target?.icao || '').replace(/\s+/g, ' ').trim().toLowerCase();
    const lat = Number(target?.lat);
    const lon = Number(target?.lon ?? target?.lng);
    return `${name}|${Number.isFinite(lat) ? lat.toFixed(4) : ''}|${Number.isFinite(lon) ? lon.toFixed(4) : ''}`;
}

function missionProposalCleanLocationPart(value = '', maxLen = 56) {
    const clean = missionProposalPolishVisibleText(value)
        .replace(/\s*\([^)]*\)\s*$/g, '')
        .replace(/\s+/g, ' ')
        .trim();
    if (!clean) return '';
    if (clean.length <= maxLen) return clean;
    return `${clean.slice(0, Math.max(24, maxLen - 1)).replace(/\s+\S*$/, '').trim()}.`;
}

function missionProposalSameLocationText(a = '', b = '') {
    if (!a || !b) return false;
    const norm = typeof normalizeAirportSearchText === 'function'
        ? normalizeAirportSearchText
        : (value => String(value || '').toLowerCase().replace(/[^a-z0-9äöüß]+/g, ' ').trim());
    const aa = norm(a);
    const bb = norm(b);
    return !!(aa && bb && (aa === bb || aa.includes(bb) || bb.includes(aa)));
}

function missionProposalAirportLocationLabel(airport = {}) {
    const code = normalizeAirportIdent(airport?.icao || '');
    const name = missionProposalCleanLocationPart(airport?.n || airport?.name || '');
    const city = missionProposalCleanLocationPart(airport?.city || '');
    const airportLabel = [code, name && !missionProposalSameLocationText(name, code) ? name : '']
        .filter(Boolean)
        .join(' · ');
    if (city && airportLabel && !missionProposalSameLocationText(city, name)) return `Ziel: ${city} (${airportLabel})`;
    if (airportLabel) return `Ziel: ${airportLabel}`;
    if (city) return `Ziel: ${city}`;
    return '';
}

function missionProposalPoiTagPlaceLabel(target = {}) {
    const tags = missionProposalPoiTags(target);
    const keys = [
        'addr:city',
        'addr:town',
        'addr:village',
        'addr:place',
        'is_in:city',
        'is_in:town',
        'is_in:village',
        'municipality',
        'place_name',
        'is_in'
    ];
    for (const key of keys) {
        const raw = missionProposalCleanLocationPart(tags?.[key] || '', 42);
        if (raw) return raw.split(',')[0].trim();
    }
    return '';
}

function missionProposalNearestAirportReference(target = {}, maxNm = 45) {
    const lat = Number(target?.lat);
    const lon = Number(target?.lon ?? target?.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    const airports = (typeof globalAirports === 'object' && globalAirports) ? globalAirports : null;
    if (!airports) return null;
    let best = null;
    for (const [rawCode, apt] of Object.entries(airports)) {
        if (!apt || typeof apt !== 'object') continue;
        const aptLat = Number(apt.lat);
        const aptLon = Number(apt.lon ?? apt.lng);
        if (!Number.isFinite(aptLat) || !Number.isFinite(aptLon)) continue;
        const nav = calcNav(lat, lon, aptLat, aptLon);
        const dist = Number(nav?.dist);
        if (!Number.isFinite(dist) || dist > maxNm) continue;
        const code = normalizeAirportIdent(apt.icao || rawCode || '');
        const name = missionProposalCleanLocationPart(apt.name || apt.n || '');
        const city = missionProposalCleanLocationPart(apt.city || '');
        const place = city || name || code;
        const score = dist
            + (/large_airport/i.test(String(apt.type || '')) ? 6 : 0)
            - (city ? 1.5 : 0);
        if (!best || score < best.score) {
            best = {
                code,
                name,
                city,
                place,
                distNm: Math.max(1, Math.round(dist)),
                score
            };
        }
    }
    return best;
}

function missionProposalPoiLocationLabel(target = {}, title = '') {
    const tagPlace = missionProposalPoiTagPlaceLabel(target);
    const nearest = missionProposalNearestAirportReference(target);
    const parts = [];
    if (tagPlace && !missionProposalSameLocationText(tagPlace, title)) parts.push(tagPlace);
    if (nearest?.place) {
        const nearPlace = missionProposalCleanLocationPart(nearest.place, 38);
        const detail = [
            nearest.code && !missionProposalSameLocationText(nearest.code, nearPlace) ? nearest.code : '',
            Number.isFinite(Number(nearest.distNm)) ? `${nearest.distNm} NM` : ''
        ].filter(Boolean).join(', ');
        parts.push(`nahe ${nearPlace}${detail ? ` (${detail})` : ''}`);
    }
    if (!parts.length) return '';
    return `Lage: ${parts.slice(0, 2).join(' · ')}`;
}

function missionProposalCompactTarget(target = {}, mode = 'apt') {
    const isPoi = String(mode || '').toLowerCase() === 'poi';
    const lat = Number(target?.lat);
    const lon = Number(target?.lon ?? target?.lng);
    const out = {
        n: String(target?.n || target?.name || target?.icao || (isPoi ? 'POI' : 'Zielplatz')).trim(),
        name: String(target?.name || target?.n || target?.icao || (isPoi ? 'POI' : 'Zielplatz')).trim(),
        lat: Number.isFinite(lat) ? lat : null,
        lon: Number.isFinite(lon) ? lon : null,
        elevation: Number.isFinite(Number(target?.elevation ?? target?.elevFt)) ? Math.round(Number(target?.elevation ?? target?.elevFt)) : null,
        source: String(target?.source || target?.poiSource || 'mission-proposal')
    };
    if (isPoi) {
        out.icao = 'POI';
        out.poiCategory = String(target?.poiCategory || target?.category || 'poi').toLowerCase();
        out.poiSource = String(target?.poiSource || target?.source || 'Mission Proposal');
        if (target?.poiLookup && typeof target.poiLookup === 'object') out.poiLookup = target.poiLookup;
        if (target?.knowledgeContext && typeof target.knowledgeContext === 'object') out.knowledgeContext = target.knowledgeContext;
        if (target?.poiChain && typeof target.poiChain === 'object') out.poiChain = target.poiChain;
    } else {
        out.icao = normalizeAirportIdent(target?.icao || '');
        out.city = target?.city || null;
        out.state = target?.state || null;
        out.country = target?.country || null;
        out.type = target?.type ?? '';
        out.openAipType = Number.isInteger(Number(target?.openAipType))
            ? Number(target.openAipType)
            : (Number.isInteger(Number(target?.type)) ? Number(target.type) : null);
        out.airportTypeCategory = target?.airportTypeCategory || window.gaAirportTypes?.classify?.(target) || '';
        out.icaoCode = airportRealIcao(target);
        out.altIdentifier = target?.altIdentifier || target?.designator || '';
        out.sourceId = target?.sourceId || target?.id || target?._id || '';
        out.ppr = !!target?.ppr;
        out.private = !!target?.private;
        out.winchOnly = !!target?.winchOnly;
        out.iata = target?.iata || '';
        out.faa = target?.faa || target?.localCode || target?.local_code || '';
        out.localCode = target?.localCode || target?.local_code || '';
        out.tz = target?.tz || null;
    }
    return out;
}

function missionProposalDispatchTarget(choice = null) {
    const normalized = normalizeMissionProposalChoice(choice);
    if (!normalized) return null;
    const target = missionProposalCompactTarget(normalized.target || {}, normalized.mode);
    if (!Number.isFinite(Number(target.lat)) || !Number.isFinite(Number(target.lon))) return null;
    if (normalized.mode === 'poi') {
        target.icao = 'POI';
        target.poiCategory = String(normalized.selectedCategory || target.poiCategory || 'poi').toLowerCase();
        target.poiSource = target.poiSource || 'Mission Proposal';
    }
    return target;
}

function compactMissionProposalChoice(choice = null) {
    const normalized = normalizeMissionProposalChoice(choice);
    if (!normalized) return null;
    return {
        id: normalized.id,
        mode: normalized.mode,
        profileId: normalized.profileId,
        selectedCategory: normalized.selectedCategory,
        requestedCategory: normalized.requestedCategory,
        title: normalized.title,
        subtitle: normalized.subtitle,
        description: normalized.description,
        locationLabel: normalized.locationLabel,
        cargoText: normalized.cargoText,
        paxText: normalized.paxText,
        routeLabel: normalized.routeLabel,
        target: missionProposalCompactTarget(normalized.target || {}, normalized.mode)
    };
}

function normalizeMissionProposalChoice(choice = null) {
    if (!choice || typeof choice !== 'object') return null;
    const mode = String(choice.mode || '').toLowerCase();
    if (mode !== 'apt' && mode !== 'poi') return null;
    const target = choice.target && typeof choice.target === 'object' ? choice.target : null;
    if (!target || !Number.isFinite(Number(target.lat)) || !Number.isFinite(Number(target.lon))) return null;
    const profileId = String(choice.profileId || '').trim().toLowerCase();
    if (!profileId) return null;
    return {
        ...choice,
        id: String(choice.id || `proposal-${Date.now()}`).trim(),
        mode,
        profileId,
        selectedCategory: String(choice.selectedCategory || choice.category || (mode === 'poi' ? target.poiCategory : 'all') || 'all').toLowerCase(),
        requestedCategory: String(choice.requestedCategory || choice.selectedCategory || choice.category || 'all').toLowerCase(),
        title: String(choice.title || target.n || target.name || 'Vorschlag').trim(),
        subtitle: String(choice.subtitle || '').trim(),
        description: String(choice.description || '').trim(),
        locationLabel: String(choice.locationLabel || '').trim(),
        cargoText: String(choice.cargoText || '').trim(),
        paxText: String(choice.paxText || '').trim(),
        routeLabel: String(choice.routeLabel || '').trim(),
        storySeed: String(choice.storySeed || '').trim(),
        target
    };
}

function missionProposalSetBriefingControlsEnabled(enabled = true) {
    const opacity = enabled ? '' : '0.35';
    const pointerEvents = enabled ? '' : 'none';
    document.querySelectorAll('.briefing-save-pin, .briefing-pdf-pin, .mission-pin-btn, #missionAcceptPanel button')
        .forEach(el => {
            el.style.opacity = opacity;
            el.style.pointerEvents = pointerEvents;
        });
}

function missionProposalSetMapAttachmentVisible(visible = true) {
    const miniMap = document.getElementById('miniMap');
    if (!miniMap) return;
    const attachment = miniMap.closest ? miniMap.closest('.briefing-photo-attachment') : miniMap.parentElement;
    if (attachment) attachment.style.display = visible ? '' : 'none';
}

function missionProposalRestoreBriefingPresentation() {
    missionProposalSetBriefingControlsEnabled(true);
    missionProposalSetMapAttachmentVisible(true);
}

function missionProposalClearBriefingState() {
    gaMissionProposalPending = null;
    missionProposalRestoreBriefingPresentation();
}

window.cancelMissionProposalSelection = function cancelMissionProposalSelection() {
    missionProposalClearBriefingState();
    const box = document.getElementById('briefingBox');
    if (box) box.style.display = 'none';
    const indicator = document.getElementById('searchIndicator');
    if (indicator) indicator.innerText = 'Vorschlagsauswahl abgebrochen.';
    setMissionGenerationProgress({ visible: false, force: true });
    setDispatchLampState('idle');
};

function missionProposalFormatRoute(start, target, mode = 'apt') {
    const nav = calcNav(Number(start?.lat), Number(start?.lon), Number(target?.lat), Number(target?.lon));
    const legDist = Number(nav?.dist || 0);
    const displayDist = String(mode).toLowerCase() === 'poi' ? Math.round(legDist * 2) : Math.round(legDist);
    const dir = missionProposalDirectionLabel(nav?.brng);
    return {
        nav,
        totalDist: displayDist,
        label: `${displayDist} NM${dir ? ` ${dir}` : ''}`,
        bearingText: Number.isFinite(Number(nav?.brng)) ? `${nav.brng}°` : ''
    };
}

function missionProposalPickCargoItems(cargoPool = [], count = 3) {
    const fallback = [
        'Optische Baugruppe im Schaumcase (24 lbs)',
        'Ming-Vase im Klimakoffer (18 lbs)',
        'Kiste rohe Eier für die Testküche (20 lbs)',
        'Kalibrierter Sensorkoffer (32 lbs)',
        'Archivmappe mit Originaldokumenten (12 lbs)'
    ];
    const explicitPool = (Array.isArray(cargoPool) ? cargoPool : [])
        .map(v => String(v || '').trim())
        .filter(Boolean);
    const pool = explicitPool.length ? explicitPool : fallback;
    const shuffled = pool
        .map(v => ({ v, r: Math.random() }))
        .sort((a, b) => a.r - b.r)
        .map(entry => entry.v);
    const out = [];
    while (out.length < count && shuffled.length) {
        out.push(shuffled[out.length % shuffled.length]);
    }
    return out;
}

async function collectMissionProposalAirportCandidates({ start, minNM, maxNM, dirPref, regionPref, limit = 16 } = {}) {
    if (!start) return [];
    const startCode = normalizeAirportIdent(start.icao || currentStartICAO || '');
    const out = [];
    const seen = new Set();
    const selectedTypes = getSelectedMissionAirportTypeIds();
    const appendCandidate = (apt, fallbackCode = '') => {
        const code = normalizeAirportIdent(fallbackCode || apt?.icao || openAipAirportStableIdent(apt));
        if (!code || code === startCode) return;
        const lat = Number(apt?.lat);
        const lon = Number(apt?.lon);
        if (!Number.isFinite(lat) || !Number.isFinite(lon)) return;
        if (!_airportMatchesRegionPref({ ...apt, icao: code }, regionPref)) return;
        if (!missionAirportMatchesTypeFilter(apt, selectedTypes)) return;
        const stableKey = String(apt?.sourceId || code).toUpperCase();
        if (seen.has(stableKey)) return;
        const nav = calcNav(Number(start.lat), Number(start.lon), lat, lon);
        if (!Number.isFinite(Number(nav?.dist))) return;
        if (nav.dist < minNM || nav.dist > maxNM) return;
        if (!checkBearing(nav.brng, dirPref)) return;
        const record = buildAirportDispatchRecord(code, apt);
        record._proposalNav = nav;
        record._proposalScore = Math.random()
            + (['ga', 'glider', 'ultralight', 'water', 'strips'].includes(record.airportTypeCategory) ? 0.25 : 0)
            - (/large_airport/i.test(String(record.type || '')) ? 0.2 : 0);
        seen.add(stableKey);
        out.push(record);
    };

    const hostedAirports = await fetchOpenAipDispatchAirports(
        Number(start.lat),
        Number(start.lon),
        Math.max(Number(maxNM) || 0, 90),
        regionPref
    );
    hostedAirports.forEach(apt => appendCandidate(apt));

    if (out.length < Math.max(3, Number(limit) || 16)) {
        await loadGlobalAirports();
        for (const [icao, apt] of Object.entries(globalAirports || {})) {
            appendCandidate(apt, icao);
        }
    }
    return out
        .sort((a, b) => b._proposalScore - a._proposalScore)
        .slice(0, Math.max(0, Number(limit) || 16));
}

function missionProposalAddCandidate(out, seen, candidate, start, mode = 'poi', category = 'all') {
    if (!candidate || typeof candidate !== 'object') return false;
    const lat = Number(candidate.lat);
    const lon = Number(candidate.lon ?? candidate.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return false;
    const key = missionProposalTargetKey(candidate);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    const nav = calcNav(Number(start?.lat), Number(start?.lon), lat, lon);
    out.push({
        ...candidate,
        lat,
        lon,
        icao: mode === 'poi' ? 'POI' : normalizeAirportIdent(candidate.icao || ''),
        poiCategory: mode === 'poi' ? String(candidate.poiCategory || category || 'poi').toLowerCase() : candidate.poiCategory,
        _proposalNav: nav
    });
    return true;
}

function missionProposalAppendUniquePoiCandidates(out, seen, candidates = [], limit = 3) {
    if (!Array.isArray(out) || !seen) return;
    for (const candidate of Array.isArray(candidates) ? candidates : []) {
        if (!candidate || typeof candidate !== 'object') continue;
        const key = missionProposalTargetKey(candidate);
        if (!key || seen.has(key)) continue;
        seen.add(key);
        out.push(candidate);
        if (out.length >= limit) break;
    }
}

function missionProposalPoiCategoryMix(profileId = '', selectedCategory = 'all', requestedCategory = 'all', count = 3) {
    const profile = String(profileId || '').toLowerCase();
    const selected = String(selectedCategory || 'all').toLowerCase();
    const requested = String(requestedCategory || selected || 'all').toLowerCase();
    if (requested && requested !== 'all' && requested !== 'chain') {
        return [selected && selected !== 'all' ? selected : requested];
    }
    const overrides = {
        inspection_infra: ['bridge', 'rail', 'industry', 'road', 'dam', 'telecom', 'infrastructure'],
        mapping_survey: ['industry', 'rail', 'road', 'bridge', 'dam', 'infrastructure'],
        sightseeing_tour: ['castle', 'mountain', 'water', 'city', 'bridge', 'dam', 'rail'],
        tour_guide_knowledge: ['city', 'water', 'castle', 'mountain', 'bridge', 'dam', 'industry', 'telecom'],
        historian_guided_tour: ['castle', 'city'],
        media_photo: ['city', 'castle', 'industry', 'road'],
        news_coverage: ['city', 'road', 'industry'],
        science_bio: ['water', 'forest', 'mountain'],
        science_geo: ['mountain', 'dam', 'water']
    };
    const policy = Array.isArray(overrides[profile]) && overrides[profile].length
        ? overrides[profile]
        : missionTaskPoiCategoryPolicy(profile);
    const base = (Array.isArray(policy) && policy.length ? policy : [selected])
        .map(cat => String(cat || '').toLowerCase())
        .filter(cat => cat && cat !== 'all' && cat !== 'chain' && cat !== 'trn');
    const out = [];
    const push = cat => {
        const clean = String(cat || '').toLowerCase();
        if (!clean || out.includes(clean)) return;
        out.push(clean);
    };
    if (selected && selected !== 'all' && selected !== 'chain') push(selected);
    missionProposalShuffleItems(base.filter(cat => cat !== selected)).forEach(push);
    if (!out.length) push(selected === 'chain' ? 'infrastructure' : selected || 'all');
    return out.slice(0, Math.max(1, Number(count) || 3));
}

async function collectMissionProposalPoiCandidates({
    start,
    searchMin,
    searchMax,
    dirPref,
    selectedPoiCategory,
    dispatchProfileId,
    limit = 3,
    ensureAlive = null
} = {}) {
    const out = [];
    const seen = new Set();
    const requested = String(selectedPoiCategory || 'all').toLowerCase();
    const searchCategory = requested === 'chain' ? 'infrastructure' : requested;
    for (let i = 0; out.length < limit && i < 6; i++) {
        const anchor = buildPoiRingSearchAnchor(start.lat, start.lon, searchMin, searchMax, dirPref, 20);
        try {
            const tagged = await findTaggedTilePOI(start.lat, start.lon, searchMin, searchMax, dirPref, searchCategory, dispatchProfileId, anchor);
            if (typeof ensureAlive === 'function') ensureAlive();
            missionProposalAddCandidate(out, seen, tagged, start, 'poi', searchCategory);
        } catch (err) {
            console.warn('[Mission Proposal] Tagged POI candidate failed', err);
        }
    }
    for (let i = 0; out.length < limit && i < 5; i++) {
        try {
            const wiki = await findWikipediaPOI(start.lat, start.lon, searchMin, searchMax, dirPref, searchCategory);
            if (typeof ensureAlive === 'function') ensureAlive();
            missionProposalAddCandidate(out, seen, wiki, start, 'poi', searchCategory);
        } catch (err) {
            console.warn('[Mission Proposal] Wiki POI candidate failed', err);
        }
    }
    if (out.length < limit && typeof fallbackPOIs !== 'undefined' && Array.isArray(fallbackPOIs)) {
        fallbackPOIs
            .map(p => {
                const nav = calcNav(start.lat, start.lon, p.lat, p.lon);
                return { ...p, _proposalNav: nav };
            })
            .filter(p => Number.isFinite(Number(p._proposalNav?.dist))
                && p._proposalNav.dist >= searchMin
                && p._proposalNav.dist <= searchMax
                && checkBearing(p._proposalNav.brng, dirPref)
                && (searchCategory === 'all' || poiTitleMatchesCategory(p.n, searchCategory)))
            .sort(() => Math.random() - 0.5)
            .some(p => {
                missionProposalAddCandidate(out, seen, p, start, 'poi', searchCategory);
                return out.length >= limit;
            });
    }
    return out.slice(0, limit);
}

